public async Task<int> CountMboxMessagesAsync(string mboxFilePath, IProgress<MboxParsingProgress>? progress = null)
    {
        return await Task.Run(() =>
        {
            if (!File.Exists(mboxFilePath))
            {
                throw new FileNotFoundException($"MBOX file not found: {mboxFilePath}");
            }

            var fileInfo = new FileInfo(mboxFilePath);
            var fileSizeInMB = fileInfo.Length / 1024.0 / 1024.0;

            progress?.Report(new MboxParsingProgress 
            { 
                Message = $"Counting messages in MBOX file ({fileSizeInMB:F2} MB)", 
                MessageCount = 0,
                FileSizeMB = fileSizeInMB
            });

            using var stream = File.OpenRead(mboxFilePath);
            var parser = new MimeParser(stream, MimeFormat.Mbox);

            int messageCount = 0;
            while (!parser.IsEndOfStream)
            {
                var message = parser.ParseMessage();
                if (message != null)
                {
                    messageCount++;
                    if (messageCount % 100 == 0)
                    {
                        progress?.Report(new MboxParsingProgress 
                        { 
                            Message = $"Counted {messageCount} messages...", 
                            MessageCount = messageCount,
                            FileSizeMB = fileSizeInMB
                        });
                    }
                }
            }

            progress?.Report(new MboxParsingProgress 
            { 
                Message = $"Finished counting. Total messages: {messageCount}", 
                MessageCount = messageCount,
                FileSizeMB = fileSizeInMB,
                IsCompleted = true
            });

            return messageCount;
        });
    }

def load_user_list(self, file_path):
        """从文件加载用户列表"""
        try:
            with open(file_path, 'r', encoding='utf-8') as f:
                if file_path.endswith('.json'):
                    return json.load(f)
                else:
                    # 假设是文本文件，每行一个UID
                    return [line.strip() for line in f if line.strip()]
        except Exception as e:
            print(f"加载用户列表失败: {e}")
            return []

def get_uid_from_url(weibo_url):
    """从微博链接中提取UID"""
    try:
        # 处理不同格式的微博链接
        if 'weibo.com/u/' in weibo_url:
            # https://weibo.com/u/1234567890
            uid = weibo_url.split('/u/')[1].split('?')[0].split('/')[0]
            return uid
        elif 'weibo.com/' in weibo_url and '/u/' not in weibo_url:
            # https://weibo.com/username 需要进一步解析
            return get_uid_from_username_url(weibo_url)
        elif 'm.weibo.cn/u/' in weibo_url:
            # https://m.weibo.cn/u/1234567890
            uid = weibo_url.split('/u/')[1].split('?')[0].split('/')[0]
            return uid
        else:
            print("不支持的链接格式")
            return None
    except Exception as e:
        print(f"解析链接失败: {e}")
        return None

def get_uid_from_username_url(weibo_url):
    """从用户名链接获取UID"""
    try:
        headers = {
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36'
        }

        response = requests.get(weibo_url, headers=headers, allow_redirects=True)

        # 查找UID
        uid_pattern = r'"oid":"(\d+)"'
        match = re.search(uid_pattern, response.text)
        if match:
            return match.group(1)

        # 尝试其他模式
        uid_pattern2 = r'CONFIG\[\'oid\'\]=\'(\d+)\''
        match2 = re.search(uid_pattern2, response.text)
        if match2:
            return match2.group(1)

        # 从重定向URL中获取
        if '/u/' in response.url:
            return get_uid_from_url(response.url)

        print("无法从页面中提取UID")
        return None

    except Exception as e:
        print(f"请求失败: {e}")
        return None

def save_to_csv(self, data, filename):
        """保存数据到CSV文件"""
        try:
            df = pd.DataFrame(data)
            df.to_csv(filename, index=False, encoding='utf-8-sig')
            self.logger.info(f"数据已保存到 {filename}")
        except Exception as e:
            self.logger.error(f"保存CSV文件失败: {e}")

def save_to_json(self, data, filename):
        """保存数据到JSON文件"""
        try:
            with open(filename, 'w', encoding='utf-8') as f:
                json.dump(data, f, ensure_ascii=False, indent=2)
            self.logger.info(f"数据已保存到 {filename}")
        except Exception as e:
            self.logger.error(f"保存JSON文件失败: {e}")

def __init__(self, headless=True):
        self.setup_logging()
        self.setup_driver(headless)

def to_html(self, include_details: bool = False) -> str:
        """Convert the entry to HTML format

        Args:
            include_details: Whether to include the details section with metadata
        """
        html_content = []

        # Photo name as H2
        html_content.append(f'<h2>{html.escape(self.filename)}</h2>')

        # Details section as H3 (only if include_details is True)
        if include_details:
            html_content.append('<h3>Details</h3>')
            html_content.append('<ul>')

            # Add metadata items to list
            if self.filepath:
                html_content.append(f'<li><strong>File Path:</strong> {html.escape(self.filepath)}</li>')

            if self.photo_date:
                html_content.append(f'<li><strong>Photo Date:</strong> {html.escape(self.photo_date)}</li>')

            if self.location:
                html_content.append(f'<li><strong>Location:</strong> {html.escape(self.location)}</li>')

            if self.camera:
                html_content.append(f'<li><strong>Camera:</strong> {html.escape(self.camera)}</li>')

            if self.settings:
                html_content.append(f'<li><strong>Settings:</strong> {html.escape(self.settings)}</li>')

            if self.model:
                html_content.append(f'<li><strong>Model:</strong> {html.escape(self.model)}</li>')

            if self.prompt_style:
                html_content.append(f'<li><strong>Prompt Style:</strong> {html.escape(self.prompt_style)}</li>')

            if self.timestamp:
                html_content.append(f'<li><strong>Generated:</strong> {html.escape(self.timestamp)}</li>')

            html_content.append('</ul>')

        # Description as H4
        html_content.append('<h4>Description</h4>')

        if self.description:
            # Convert line breaks to HTML and escape content
            description_html = html.escape(self.description).replace('\n', '<br>\n')
            html_content.append(f'<p>{description_html}</p>')
        else:
            html_content.append('<p><em>No description available</em></p>')

        return '\n'.join(html_content)

def __init__(self, input_file: Path):
        self.input_file = input_file
        self.entries: List[DescriptionEntry] = []

def _parse_section(self, section: str) -> Optional[DescriptionEntry]:
        """Parse a single section into a DescriptionEntry"""
        entry = DescriptionEntry()
        lines = section.split('\n')

        description_started = False
        description_lines = []

        for line in lines:
            line = line.strip()
            if not line:
                continue

            # Check if we've reached the description
            if line.startswith('Description:'):
                description_started = True
                desc_text = line[12:].strip()  # Remove 'Description: '
                if desc_text:
                    description_lines.append(desc_text)
                continue

            # If we're in description mode, collect all remaining lines
            if description_started:
                if line.startswith('Timestamp:'):
                    # End of description, parse timestamp
                    entry.timestamp = line[10:].strip()
                    break
                else:
                    description_lines.append(line)
                continue

            # Parse metadata fields
            if line.startswith('File:'):
                entry.filename = line[5:].strip()
            elif line.startswith('Path:'):
                entry.filepath = line[5:].strip()
            elif line.startswith('Photo Date:'):
                entry.photo_date = line[11:].strip()
            elif line.startswith('Location:'):
                entry.location = line[9:].strip()
            elif line.startswith('Camera:'):
                entry.camera = line[7:].strip()
            elif line.startswith('Settings:'):
                entry.settings = line[9:].strip()
            elif line.startswith('Model:'):
                entry.model = line[6:].strip()
            elif line.startswith('Prompt Style:'):
                entry.prompt_style = line[13:].strip()
            elif line.startswith('Timestamp:'):
                entry.timestamp = line[10:].strip()

        # Join description lines
        entry.description = '\n'.join(description_lines).strip()

        return entry

