def get_prompt(self) -> str:
        """
        Get the prompt based on the selected style

        Returns:
            Prompt string
        """
        prompt_variations = self.config.get('prompt_variations', {})

        if self.prompt_style in prompt_variations:
            return prompt_variations[self.prompt_style]
        else:
            # Fallback to default prompt_template
            return self.config.get('prompt_template', 
                                 "Describe this image in detail, including the main subjects, setting, colors, and composition.")

def is_supported_image(self, file_path: Path) -> bool:
        """Check if the file is a supported image format"""
        return file_path.suffix.lower() in self.supported_formats

def encode_image_to_base64(self, image_path: Path) -> str:
        """
        Encode image to base64 string with optimization

        Args:
            image_path: Path to the image file

        Returns:
            Base64 encoded string of the image
        """
        try:
            # Try optimized approach first
            if self.enable_compression:
                optimized_bytes = self.optimize_image(image_path)
                if optimized_bytes:
                    return base64.b64encode(optimized_bytes).decode('utf-8')

            # Fallback to original method
            with open(image_path, 'rb') as image_file:
                return base64.b64encode(image_file.read()).decode('utf-8')

        except Exception as e:
            logger.error(f"Error encoding image {image_path}: {e}")
            return None

def extract_metadata(self, image_path: Path) -> Dict[str, Any]:
        """
        Extract EXIF metadata from an image file

        Args:
            image_path: Path to the image file

        Returns:
            Dictionary containing extracted metadata
        """
        metadata = {}

        try:
            # Check if metadata extraction is enabled
            if not self.config.get('processing_options', {}).get('extract_metadata', False):
                return metadata

            with Image.open(image_path) as img:
                # Use getexif() instead of _getexif() (modern method)
                exif_data = img.getexif()

                if exif_data:
                    # Convert EXIF data to human-readable format
                    exif_dict = {}
                    for tag_id, value in exif_data.items():
                        tag = TAGS.get(tag_id, tag_id)
                        exif_dict[tag] = value

                    # Extract all available metadata
                    datetime_info = self._extract_datetime(exif_dict)
                    if datetime_info:
                        metadata['datetime'] = datetime_info

                    location_info = self._extract_location(exif_dict)
                    if location_info:
                        metadata['location'] = location_info

                    camera_info = self._extract_camera_info(exif_dict)
                    if camera_info:
                        metadata['camera'] = camera_info

                    technical_info = self._extract_technical_info(exif_dict)
                    if technical_info:
                        metadata['technical'] = technical_info

        except Exception as e:
            logger.debug(f"Error extracting metadata from {image_path}: {e}")

        return metadata

def _extract_datetime(self, exif_data: dict) -> Optional[str]:
        """Extract date and time from EXIF data"""
        try:
            # Try different datetime fields
            datetime_fields = ['DateTime', 'DateTimeOriginal', 'DateTimeDigitized']

            for field in datetime_fields:
                if field in exif_data:
                    dt_str = exif_data[field]
                    if dt_str:
                        # Parse and format the datetime
                        try:
                            dt = datetime.strptime(dt_str, '%Y:%m:%d %H:%M:%S')
                            return dt.strftime('%Y-%m-%d %H:%M:%S')
                        except ValueError:
                            # Try alternative format
                            try:
                                dt = datetime.strptime(dt_str, '%Y-%m-%d %H:%M:%S')
                                return dt.strftime('%Y-%m-%d %H:%M:%S')
                            except ValueError:
                                logger.debug(f"Could not parse datetime format: {dt_str}")
                                continue
        except Exception as e:
            logger.debug(f"Error extracting datetime: {e}")

        return None

def _extract_location(self, exif_data: dict) -> Optional[Dict[str, Any]]:
        """Extract GPS location from EXIF data"""
        try:
            gps_info = exif_data.get('GPSInfo')
            if not gps_info:
                return None

            # Convert GPS info to readable format
            gps_dict = {}
            for tag_id, value in gps_info.items():
                tag = GPSTAGS.get(tag_id, tag_id)
                gps_dict[tag] = value

            location = {}

            # Extract latitude
            if 'GPSLatitude' in gps_dict and 'GPSLatitudeRef' in gps_dict:
                lat = self._convert_gps_coordinate(gps_dict['GPSLatitude'])
                if gps_dict['GPSLatitudeRef'] == 'S':
                    lat = -lat
                location['latitude'] = lat

            # Extract longitude
            if 'GPSLongitude' in gps_dict and 'GPSLongitudeRef' in gps_dict:
                lon = self._convert_gps_coordinate(gps_dict['GPSLongitude'])
                if gps_dict['GPSLongitudeRef'] == 'W':
                    lon = -lon
                location['longitude'] = lon

            # Extract altitude
            if 'GPSAltitude' in gps_dict:
                altitude = float(gps_dict['GPSAltitude'])
                if 'GPSAltitudeRef' in gps_dict and gps_dict['GPSAltitudeRef'] == 1:
                    altitude = -altitude
                location['altitude'] = altitude

            return location if location else None

        except Exception as e:
            logger.debug(f"Error extracting location: {e}")

        return None

def _extract_camera_info(self, exif_data: dict) -> Optional[Dict[str, str]]:
        """Extract camera information from EXIF data"""
        try:
            camera_info = {}

            # Camera make and model
            if 'Make' in exif_data:
                camera_info['make'] = exif_data['Make']
            if 'Model' in exif_data:
                camera_info['model'] = exif_data['Model']

            # Lens information
            if 'LensModel' in exif_data:
                camera_info['lens'] = exif_data['LensModel']

            return camera_info if camera_info else None

        except Exception as e:
            logger.debug(f"Error extracting camera info: {e}")

        return None

def _extract_technical_info(self, exif_data: dict) -> Optional[Dict[str, Any]]:
        """Extract technical camera settings from EXIF data"""
        try:
            technical_info = {}

            # ISO
            if 'ISOSpeedRatings' in exif_data:
                technical_info['iso'] = exif_data['ISOSpeedRatings']
            elif 'ISO' in exif_data:
                technical_info['iso'] = exif_data['ISO']

            # Aperture
            if 'FNumber' in exif_data:
                f_number = exif_data['FNumber']
                if isinstance(f_number, tuple) and len(f_number) == 2:
                    f_value = f_number[0] / f_number[1]
                    technical_info['aperture'] = f"f/{f_value:.1f}"
                else:
                    technical_info['aperture'] = f"f/{f_number}"

            # Shutter speed
            if 'ExposureTime' in exif_data:
                exposure_time = exif_data['ExposureTime']
                if isinstance(exposure_time, tuple) and len(exposure_time) == 2:
                    if exposure_time[0] == 1:
                        technical_info['shutter_speed'] = f"1/{exposure_time[1]}s"
                    else:
                        technical_info['shutter_speed'] = f"{exposure_time[0]/exposure_time[1]}s"
                else:
                    technical_info['shutter_speed'] = f"{exposure_time}s"

            # Focal length
            if 'FocalLength' in exif_data:
                focal_length = exif_data['FocalLength']
                if isinstance(focal_length, tuple) and len(focal_length) == 2:
                    fl_value = focal_length[0] / focal_length[1]
                    technical_info['focal_length'] = f"{fl_value:.0f}mm"
                else:
                    technical_info['focal_length'] = f"{focal_length}mm"

            return technical_info if technical_info else None

        except Exception as e:
            logger.debug(f"Error extracting technical info: {e}")

        return None

def _convert_gps_coordinate(self, coord_tuple) -> float:
        """Convert GPS coordinate from tuple format to decimal degrees"""
        try:
            degrees = float(coord_tuple[0])
            minutes = float(coord_tuple[1])
            seconds = float(coord_tuple[2])
            return degrees + (minutes / 60.0) + (seconds / 3600.0)
        except:
            return 0.0

def format_metadata(self, metadata: Dict[str, Any]) -> str:
        """
        Format metadata for display in output file

        Args:
            metadata: Dictionary containing metadata

        Returns:
            Formatted metadata string
        """
        if not metadata:
            return ""

        lines = []

        # Format datetime
        if 'datetime' in metadata:
            lines.append(f"Photo Date: {metadata['datetime']}")

        # Format location
        if 'location' in metadata:
            location = metadata['location']
            location_parts = []

            if 'latitude' in location and 'longitude' in location:
                location_parts.append(f"GPS: {location['latitude']:.6f}, {location['longitude']:.6f}")

            if 'altitude' in location:
                location_parts.append(f"Altitude: {location['altitude']:.1f}m")

            if location_parts:
                lines.append("Location: " + ", ".join(location_parts))

        # Format camera info
        if 'camera' in metadata:
            camera = metadata['camera']
            camera_parts = []

            if 'make' in camera and 'model' in camera:
                camera_parts.append(f"{camera['make']} {camera['model']}")

            if 'lens' in camera:
                camera_parts.append(f"Lens: {camera['lens']}")

            if camera_parts:
                lines.append("Camera: " + ", ".join(camera_parts))

        # Format technical info
        if 'technical' in metadata:
            technical = metadata['technical']
            technical_parts = []

            for key, value in technical.items():
                technical_parts.append(f"{key.replace('_', ' ').title()}: {value}")

            if technical_parts:
                lines.append("Settings: " + ", ".join(technical_parts))

        return "\n".join(lines)

def load_config(self, config_file: str) -> dict:
        """Load configuration from JSON file"""
        try:
            config_path = Path(config_file)
            if not config_path.is_absolute():
                # Look for config file in script directory first
                script_dir = Path(__file__).parent
                config_path = script_dir / config_file

            if not config_path.exists():
                self.logger.warning(f"Config file not found: {config_path}")
                return self.get_default_config()

            with open(config_path, 'r') as f:
                content = f.read().strip()
                if not content:
                    self.logger.info(f"Config file {config_path} is empty. Using default config.")
                    return self.get_default_config()
                config = json.loads(content)
                self.logger.info(f"Configuration loaded from: {config_path}")
                return config
        except json.JSONDecodeError as e:
            self.logger.error(f"Error parsing config file {config_file}: {e}")
            self.logger.info("Using default config.")
            return self.get_default_config()
        except Exception as e:
            self.logger.error(f"Error loading config file {config_file}: {e}")
            self.logger.info("Using default config.")
            return self.get_default_config()

def resize_frame(self, frame: np.ndarray) -> np.ndarray:
        """Resize frame based on config settings"""
        height, width = frame.shape[:2]
        new_width = self.config["resize_width"]
        new_height = self.config["resize_height"]

        if new_width and new_height:
            return cv2.resize(frame, (new_width, new_height))
        elif new_width:
            ratio = new_width / width
            new_height = int(height * ratio)
            return cv2.resize(frame, (new_width, new_height))
        elif new_height:
            ratio = new_height / height
            new_width = int(width * ratio)
            return cv2.resize(frame, (new_width, new_height))

        return frame

def generate_html(self, input_dir: Path, output_dir: Path, description_file: Optional[Path] = None) -> Dict[str, Any]:
        """
        Generate HTML report from descriptions using descriptions_to_html.py

        Args:
            input_dir: Directory that was processed
            output_dir: Output directory for HTML report
            description_file: Specific description file to process

        Returns:
            Dictionary with step results
        """
        self.logger.info("Starting HTML generation...")

        # Find description file
        if description_file and description_file.exists():
            desc_file = description_file
        else:
            # Look for description files in input directory
            desc_files = self.discovery.find_files_by_type(input_dir, "descriptions")

            # Also check the standard descriptions output directory
            descriptions_dir = self.config.get_step_output_dir("image_description")
            if not desc_files and descriptions_dir.exists():
                desc_files = self.discovery.find_files_by_type(descriptions_dir, "descriptions")

            if not desc_files:
                # Check if descriptions were created in a previous step
                if "describe" in self.step_results and self.step_results["describe"].get("description_file"):
                    desc_file = self.step_results["describe"]["description_file"]
                else:
                    self.logger.warning("No description files found for HTML generation")
                    return {"success": True, "processed": 0, "output_dir": output_dir}
            else:
                desc_file = desc_files[0]  # Use first found file

        self.logger.info(f"Using description file: {desc_file}")

        try:
            # Get HTML generation settings
            step_config = self.config.get_step_config("html_generation")

            # Create output file path
            output_dir.mkdir(parents=True, exist_ok=True)
            html_file = output_dir / "image_descriptions.html"

            # Build command
            cmd = [
                sys.executable, "descriptions_to_html.py",
                str(desc_file),
                str(html_file),
                "--title", step_config.get("title", "Image Analysis Report"),
                "--log-dir", str(self.config.base_output_dir / "logs")
            ]

            if step_config.get("include_details", False):
                cmd.append("--full")

            self.logger.info(f"Running: {' '.join(cmd)}")
            result = subprocess.run(cmd, capture_output=True, text=True, encoding='utf-8', errors='replace')

            # Log the subprocess output for transparency
            if result.stdout.strip():
                self.logger.info(f"descriptions_to_html.py output:\n{result.stdout}")
            if result.stderr.strip():
                self.logger.warning(f"descriptions_to_html.py stderr:\n{result.stderr}")

            if result.returncode == 0:
                self.logger.info("HTML generation completed successfully")

                return {
                    "success": True,
                    "processed": 1,
                    "output_dir": output_dir,
                    "html_file": html_file
                }
            else:
                self.logger.error(f"HTML generation failed: {result.stderr}")
                return {"success": False, "error": result.stderr}

        except Exception as e:
            self.logger.error(f"Error during HTML generation: {e}")
            return {"success": False, "error": str(e)}

def _update_statistics(self, step: str, step_result: Dict[str, Any]) -> None:
        """Update workflow statistics based on step results"""
        if step_result.get("success"):
            processed = step_result.get("processed", 0)
            if step == "video":
                self.statistics['total_videos_processed'] += processed
            elif step == "convert":
                self.statistics['total_conversions'] += processed
                self.statistics['total_images_processed'] += processed
            elif step == "describe":
                self.statistics['total_descriptions'] += processed
                self.statistics['total_images_processed'] += processed

            self.statistics['total_files_processed'] += processed

def load_config(self) -> Dict[str, Any]:
        """Load workflow configuration from JSON file"""
        try:
            config_path = Path(self.config_file)
            if not config_path.is_absolute():
                script_dir = Path(__file__).parent
                config_path = script_dir / self.config_file

            if config_path.exists():
                with open(config_path, 'r', encoding='utf-8') as f:
                    return json.load(f)
            else:
                # Return default config if file doesn't exist
                return self.get_default_config()

        except Exception as e:
            # Use basic logging here since we don't have access to the WorkflowLogger yet
            import logging
            logging.warning(f"Could not load workflow config: {e}")
            return self.get_default_config()

def get_default_config(self) -> Dict[str, Any]:
        """Get default workflow configuration"""
        return {
            "workflow": {
                "base_output_dir": "workflow_output",
                "preserve_structure": True,
                "cleanup_intermediate": False,
                "steps": {
                    "video_extraction": {"enabled": True, "output_subdir": "extracted_frames"},
                    "image_conversion": {"enabled": True, "output_subdir": "converted_images"},
                    "image_description": {"enabled": True, "output_subdir": "descriptions"},
                    "html_generation": {"enabled": True, "output_subdir": "html_reports"}
                }
            },
            "file_patterns": {
                "videos": [".mp4", ".avi", ".mkv", ".mov", ".wmv", ".flv", ".webm", ".m4v"],
                "images": [".jpg", ".jpeg", ".png", ".bmp", ".tiff", ".webp"],
                "heic": [".heic", ".heif"],
                "descriptions": ["image_descriptions.txt"]
            }
        }

def base_output_dir(self) -> Path:
        """Get the base output directory path"""
        if self._base_output_dir is None:
            base_dir = self.config.get("workflow", {}).get("base_output_dir", "workflow_output")
            self._base_output_dir = Path(base_dir).resolve()
        return self._base_output_dir

def set_base_output_dir(self, path: Union[str, Path]) -> None:
        """Set a custom base output directory"""
        self._base_output_dir = Path(path).resolve()

def is_step_enabled(self, step_name: str) -> bool:
        """Check if a workflow step is enabled"""
        return self.config.get("workflow", {}).get("steps", {}).get(step_name, {}).get("enabled", True)

def get_step_config(self, step_name: str) -> Dict[str, Any]:
        """Get configuration for a specific step"""
        return self.config.get("workflow", {}).get("steps", {}).get(step_name, {})

def get_file_patterns(self, pattern_type: str) -> List[str]:
        """Get file patterns for a specific type"""
        return self.config.get("file_patterns", {}).get(pattern_type, [])

def info(self, message: str) -> None:
        """Log info message"""
        self.logger.info(message)

def warning(self, message: str) -> None:
        """Log warning message"""
        self.logger.warning(message)

def error(self, message: str) -> None:
        """Log error message"""
        self.logger.error(message)

def debug(self, message: str) -> None:
        """Log debug message"""
        self.logger.debug(message)

def get_relative_path_structure(self, file_path: Path, base_path: Path) -> Path:
        """
        Get relative path structure for preserving directory hierarchy

        Args:
            file_path: Full path to file
            base_path: Base directory path

        Returns:
            Relative path structure
        """
        try:
            return file_path.relative_to(base_path)
        except ValueError:
            # If file is not relative to base, just return filename
            return Path(file_path.name)

