        try:
            extractor = VideoFrameExtractor()
            print("✓ VideoFrameExtractor can be instantiated")
        except Exception as e:
            print(f"⚠ VideoFrameExtractor instantiation warning: {e}")

        return True

    except Exception as e:
        print(f"✗ Class instantiation error: {e}")
        return False

// EncodeOutputWithJQ encodes data with jq query filtering
func EncodeOutputWithJQ(ctx context.Context, w io.Writer, format OutputFormat, data interface{}, jqQuery string) error {
	// Create pipeline with jq query
	pipeline, err := jqyaml.New(jqyaml.WithQuery(jqQuery))
	if err != nil {
		return fmt.Errorf("failed to create jq pipeline: %w", err)
	}

	// Convert OutputFormat to yamlformat.Format
	var yf yamlformat.Format
	switch format {
	case FormatJSON:
		yf = yamlformat.FormatJSON
	default:
		yf = yamlformat.FormatYAML
	}

	// Create context with timeout
	ctx, cancel := context.WithTimeout(ctx, jqQueryTimeout)
	defer cancel()

	// Execute pipeline with writer option
	return pipeline.Execute(ctx, data, jqyaml.WithWriter(w, yf))
}

// Marshal marshals data for the JSON format (used in github.go)
func (f OutputFormat) Marshal(data interface{}) ([]byte, error) {
	if f == FormatJSON {
		return yamlformat.MarshalJSON(data)
	}
	return yamlformat.Marshal(data)
}

func TestEncodeOutputWithJQ(t *testing.T) {
	tests := []struct {
		name        string
		format      OutputFormat
		data        interface{}
		jqQuery     string
		wantContain string
		wantEmpty   bool
		wantErr     bool
	}{
		{
			name:   "extract single field",
			format: FormatYAML,
			data: map[string]interface{}{
				"name": "test",
				"value": 42,
			},
			jqQuery:     ".name",
			wantContain: "test",
		},
		{
			name:   "filter array",
			format: FormatJSON,
			data: map[string]interface{}{
				"items": []interface{}{
					map[string]interface{}{"id": 1, "active": true},
					map[string]interface{}{"id": 2, "active": false},
					map[string]interface{}{"id": 3, "active": true},
				},
			},
			jqQuery:     ".items[] | select(.active) | .id",
			wantContain: "1",
		},
		{
			name:   "construct object",
			format: FormatYAML,
			data: map[string]interface{}{
				"user": map[string]interface{}{
					"name": "Alice",
					"age":  30,
					"email": "alice@example.com",
				},
			},
			jqQuery:     ".user | {name, age}",
			wantContain: "name: Alice",
		},
		{
			name:   "invalid jq query",
			format: FormatYAML,
			data: map[string]interface{}{
				"test": "data",
			},
			jqQuery: ".invalid syntax[",
			wantErr: true,
		},
		{
			name:   "empty result",
			format: FormatJSON,
			data: map[string]interface{}{
				"items": []interface{}{},
			},
			jqQuery:   ".items[]",
			wantEmpty: true,
		},
		{
			name:   "multiple results as YAML",
			format: FormatYAML,
			data: map[string]interface{}{
				"numbers": []interface{}{1, 2, 3},
			},
			jqQuery:     ".numbers[]",
			wantContain: "1\n---\n2\n---\n3",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var buf bytes.Buffer
			err := EncodeOutputWithJQ(context.Background(), &buf, tt.format, tt.data, tt.jqQuery)

			if (err != nil) != tt.wantErr {
				t.Errorf("EncodeOutputWithJQ() error = %v, wantErr %v", err, tt.wantErr)
				return
			}

			if err != nil {
				return // Skip output check if error was expected
			}

			output := buf.String()

			// Check if we expect empty output
			if tt.wantEmpty {
				if output != "" {
					t.Errorf("EncodeOutputWithJQ() output = %v, want empty", output)
				}
				return
			}

			// Check for expected content
			if tt.wantContain != "" && !strings.Contains(output, tt.wantContain) {
				t.Errorf("EncodeOutputWithJQ() output = %v, want to contain %v", output, tt.wantContain)
			}
		})
	}
}

