func TestEncodeOutputWithJQTimeout(t *testing.T) {
	if testing.Short() {
		t.Skip("Skipping timeout test in short mode")
	}

	// This test verifies that long-running jq queries are terminated by the timeout
	// We create a large dataset and use a complex query that would take too long

	// Create a large dataset with nested structures
	largeData := make([]interface{}, 10000)
	for i := range largeData {
		largeData[i] = map[string]interface{}{
			"id": i,
			"nested": map[string]interface{}{
				"value": i * 2,
				"deep": map[string]interface{}{
					"data": i * 3,
				},
			},
		}
	}

	// Use a pathologically slow jq query - cartesian product that would take forever
	slowQuery := `. as $all | .[] | . as $item | $all[] | select(.id > $item.id) | {a: $item.id, b: .id}`

	var buf bytes.Buffer
	err := EncodeOutputWithJQ(context.Background(), &buf, FormatJSON, largeData, slowQuery)

	// We expect this to timeout (context deadline exceeded)
	if err == nil {
		t.Error("Expected timeout error, but got none")
	}

	// Check for context deadline exceeded error
	// Note: Ideally we would only check errors.Is(err, context.DeadlineExceeded),
	// but go-jq-yamlformat currently returns "execution timeout after Xs" without
	// properly wrapping the context.DeadlineExceeded error. This is a known issue
	// that should be fixed in the library.
	if !errors.Is(err, context.DeadlineExceeded) {
		// Fallback check for the specific error message from go-jq-yamlformat
		if !strings.Contains(err.Error(), "execution timeout after") {
			t.Errorf("Expected context.DeadlineExceeded or 'execution timeout after', got: %v", err)
		}
	}
}

def _cleanup_expired_sessions(self) -> None:
        """Remove expired sessions from active sessions."""
        current_time = datetime.utcnow()
        expired_sessions = []

        for session_id, session in self.active_sessions.items():
            if current_time > session["session_end"]:
                expired_sessions.append(session_id)

        for session_id in expired_sessions:
            del self.active_sessions[session_id]

        if expired_sessions:
            self.logger.debug(f"Cleaned up {len(expired_sessions)} expired sessions")

def _generate_page_info(
        self, event_type: str, session: Dict[str, Any]
    ) -> Dict[str, Any]:
        """Generate page information based on event type."""
        if event_type == "product_view":
            category = random.choice(self.product_categories)
            product_id = f"prod_{category}_{random.randint(1000, 9999)}"
            return {
                "page_url": f"/product/{product_id}",
                "page_title": f"{self.fake.catch_phrase()} - Product",
                "page_category": "product",
                "product_id": product_id,
                "product_category": category,
            }
        elif event_type == "search":
            search_term = random.choice(
                [
                    self.fake.word(),
                    f"{random.choice(self.product_categories)} {self.fake.word()}",
                    self.fake.catch_phrase(),
                ]
            )
            return {
                "page_url": f"/search?q={search_term.replace(' ', '+')}",
                "page_title": f"Search: {search_term}",
                "page_category": "search",
                "search_term": search_term,
                "search_results_count": random.randint(0, 1000),
            }
        elif event_type in ["add_to_cart", "remove_from_cart"]:
            category = random.choice(self.product_categories)
            product_id = f"prod_{category}_{random.randint(1000, 9999)}"
            return {
                "page_url": f"/product/{product_id}",
                "page_title": f"{self.fake.catch_phrase()} - Product",
                "page_category": "product",
                "product_id": product_id,
                "product_category": category,
                "quantity": random.randint(1, 5),
                "price": round(random.uniform(10, 500), 2),
            }
        elif event_type == "begin_checkout":
            return {
                "page_url": "/checkout",
                "page_title": "Checkout",
                "page_category": "checkout",
                "cart_value": round(random.uniform(50, 1000), 2),
                "cart_items_count": random.randint(1, 10),
            }
        elif event_type == "complete_checkout":
            return {
                "page_url": "/checkout/complete",
                "page_title": "Order Complete",
                "page_category": "checkout",
                "order_id": f"ord_{int(datetime.utcnow().timestamp())}_{random.randint(1000, 9999)}",
                "order_value": round(random.uniform(50, 1000), 2),
                "payment_method": random.choice(["credit_card", "paypal", "apple_pay"]),
            }
        else:
            # Generic page view
            page_cat = self._weighted_choice(self.page_categories)
            page_name = random.choice(page_cat["pages"])
            return {
                "page_url": f"/{page_name}",
                "page_title": f"{page_name.replace('_', ' ').title()}",
                "page_category": page_cat["category"],
            }

def get_message_key(self, message: Dict[str, Any]) -> Optional[str]:
        """Get message key for partitioning by session_id."""
        return message.get("session_id")

