def test_session_correlation(self, producer):
        """Test that events from the same session are correlated."""
        # Generate multiple messages and check session correlation
        messages = []
        for _ in range(5):
            message = producer.generate_message()
            messages.append(message)

        # Check that we have sessions
        session_ids = [msg["session_id"] for msg in messages]
        assert len(set(session_ids)) >= 1  # Should have at least one session

        # Check that messages from same session have same user_id
        sessions = {}
        for msg in messages:
            session_id = msg["session_id"]
            if session_id not in sessions:
                sessions[session_id] = {"user_id": msg["user_id"], "messages": []}
            sessions[session_id]["messages"].append(msg)

            # All messages from same session should have same user_id
            assert msg["user_id"] == sessions[session_id]["user_id"]

async def _get_image_metadata(
    image_path: str,
    blob_service: BlobStorageService
) -> Dict[str, Any]:
    try:
        logger.info(f"Fetching metadata for image: {image_path}")

        # Get blob properties
        blob_client = blob_service.get_blob_client("images", image_path)

        try:
            properties = blob_client.get_blob_properties()

            metadata = {
                "filename": image_path.split('/')[-1],
                "size": properties.size,
                "content_type": properties.content_settings.content_type,
                "last_modified": properties.last_modified.isoformat() if properties.last_modified else None,
                "etag": properties.etag,
                "blob_type": str(properties.blob_type),
                "creation_time": properties.creation_time.isoformat() if properties.creation_time else None,
                "custom_metadata": properties.metadata or {}
            }

            # Add image dimensions if available in metadata
            if properties.metadata and "width" in properties.metadata:
                metadata["dimensions"] = {
                    "width": int(properties.metadata.get("width", 0)),
                    "height": int(properties.metadata.get("height", 0))
                }

            logger.info(f"Successfully fetched metadata for {image_path}")
            return metadata

        except Exception as blob_error:
            logger.error(f"Error accessing blob {image_path}: {str(blob_error)}")
            # Return basic metadata if blob access fails
            return {
                "filename": image_path.split('/')[-1],
                "error": "Could not access blob properties"
            }

    except Exception as e:
        logger.error(f"Error fetching metadata for {image_path}: {str(e)}")
        raise HTTPException(
            status_code=500, 
            detail=f"Failed to fetch metadata: {str(e)}"
        )

async def get_images_statistics(
    batch_id: Optional[str] = None,
    stats_service: StatisticsService = Depends(get_statistics_service)
):
    """
    Get total images count across all batches or for a specific batch.
    Returns a simple count for dashboard display.
    """
    try:
        statistics = await stats_service.get_all_statistics(batch_id=batch_id)
        if statistics is None:
            raise HTTPException(status_code=500, detail="Error retrieving statistics.")

        # Calculate total images from images_per_batch
        total_images = sum(batch.count for batch in statistics.images_per_batch)

        return {"total_images": total_images}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Error in /statistics/images endpoint (batch_id: {batch_id}): {e}", exc_info=True)
        raise HTTPException(status_code=500, detail="Internal server error while retrieving image statistics.")

