/**
 * Fetch images for a specific batch
 */
async function fetchBatchImages(batchId) {
    try {
        console.log(`[DEBUG] Fetching images for batch: ${batchId}`);
        const response = await fetch(`/api/batch/${batchId}/images`);

        if (!response.ok) {
            throw new Error(`Failed to load batch images: ${response.status}`);
        }

        const data = await response.json();
        console.log(`[DEBUG] Batch images loaded successfully:`, data);

        // Return the images array from the response
        return data.images || [];

    } catch (error) {
        console.error(`[DEBUG] Error loading batch images for ${batchId}:`, error);
        showMessage(`Error loading batch images: ${error.message}`, "error");
        throw error;
    }
}

/**
 * Load available classes/categories
 */
async function loadClasses() {
    try {
        console.log("[DEBUG] Loading classes from server");
        const response = await fetch('/api/classes');

        if (!response.ok) {
            throw new Error(`Failed to load classes: ${response.status}`);
        }

        const data = await response.json();
        console.log("[DEBUG] Classes loaded successfully:", data);

        const AppState = getAppState();
        AppState.classes = data.classes;

        // Populate class selection buttons
        if (window.modules?.eventHandlers?.populateClassButtons) {
            window.modules.eventHandlers.populateClassButtons(data.classes);
        } else if (window.populateClassButtons) {
            window.populateClassButtons(data.classes);
        }

        addLogEntry(`Loaded ${data.classes.length} annotation classes`);
        return data.classes;

    } catch (error) {
        console.error("[DEBUG] Error loading classes:", error);
        showMessage("Error loading classes. See console for details.", "error");
        throw error;
    }
}

/**
 * Load specific image for annotation
 */
async function loadImage(imagePath, loadId = null) {
    const AppState = getAppState();

    // Check if this load is still expected (prevent race conditions)
    if (loadId && AppState.expectedLoadId !== loadId) {
        console.log(`[DEBUG] Cancelling load for ${imagePath} - newer request exists`);
        return;
    }

    try {
        console.log(`[DEBUG] Loading image: ${imagePath}`);
        AppState.loading = true;

        // Show loading indicator
        const canvas = AppState.fabricCanvas;
        if (canvas) {
            canvas.clear();
            // Add loading text to canvas
            const loadingText = new fabric.Text('Loading image...', {
                left: canvas.width / 2,
                top: canvas.height / 2,
                originX: 'center',
                originY: 'center',
                fontSize: 20,
                fill: '#666'
            });
            canvas.add(loadingText);
            canvas.renderAll();
        }

        // Create image element
        const img = new Image();
        img.crossOrigin = 'anonymous';

        return new Promise((resolve, reject) => {
            img.onload = async function() {
                try {
                    // Final race condition check
                    if (loadId && AppState.expectedLoadId !== loadId) {
                        console.log(`[DEBUG] Load cancelled during image load for ${imagePath}`);
                        resolve();
                        return;
                    }

                    console.log(`[DEBUG] Image loaded successfully: ${img.naturalWidth}x${img.naturalHeight}`);

                    if (canvas) {
                        // Clear canvas and annotations
                        canvas.clear();
                        AppState.annotations = []; // Clear annotations array

                        // Clear annotations from sidebar
                        if (window.rebuildAnnotationList) {
                            window.rebuildAnnotationList();
                        }

                        // Get container dimensions for responsive sizing
                        const canvasContainer = document.getElementById('canvas-container');

                        // Calculate available space accounting for sidebars
                        let availableWidth = window.innerWidth;
                        let availableHeight = window.innerHeight;

                        // Account for toolbar and other UI elements
                        availableHeight -= 140;

                        // Account for sidebars
                        const leftSidebar = document.getElementById('left-sidebar');
                        const rightSidebar = document.getElementById('right-sidebar');

                        if (leftSidebar && !leftSidebar.classList.contains('collapsed')) {
                            availableWidth -= leftSidebar.offsetWidth;
                        } else if (leftSidebar && leftSidebar.classList.contains('collapsed')) {
                            availableWidth -= 60;
                        }

                        if (rightSidebar && !rightSidebar.classList.contains('collapsed')) {
                            availableWidth -= rightSidebar.offsetWidth;
                        } else if (rightSidebar && rightSidebar.classList.contains('collapsed')) {
                            availableWidth -= 60;
                        }

                        // Use most of the available space
                        const maxWidth = Math.max(600, availableWidth - 40);
                        const maxHeight = Math.max(400, availableHeight - 40);

                        // Calculate scale to fit image in available space
                        const scale = Math.min(maxWidth / img.naturalWidth, maxHeight / img.naturalHeight, 1);

                        const canvasWidth = img.naturalWidth * scale;
                        const canvasHeight = img.naturalHeight * scale;

                        // Set canvas dimensions to be larger and more responsive
                        canvas.setDimensions({
                            width: canvasWidth,
                            height: canvasHeight
                        });

                        // Create fabric image
                        const fabricImg = new fabric.Image(img, {
                            selectable: false,
                            evented: false,
                            scaleX: scale,
                            scaleY: scale
                        });

                        // Add image to canvas
                        canvas.add(fabricImg);
                        canvas.sendToBack(fabricImg);

                        // Update state
                        AppState.currentImage = fabricImg;
                        AppState.currentImagePath = imagePath;
                        AppState.currentScale = scale; // Set currentScale for annotation coordinate conversion
                        AppState.originalImageWidth = img.naturalWidth;
                        AppState.originalImageHeight = img.naturalHeight;

                        // Center canvas in container
                        if (window.modules?.canvasManager?.centerCanvas) {
                            window.modules.canvasManager.centerCanvas();
                        }

                        // Load annotations for this image
                        await loadAnnotations(imagePath);

                        // Load metadata
                        await loadMetadata(imagePath);

                        // Load sensor data
                        const batchId = AppState.currentBatch;
                        const imageId = AppState.currentImageId;
                        if (batchId && imageId) {
                            await loadSensorData(batchId, imageId);
                        }

                        // Update status
                        const imageNameStatus = document.getElementById('image-name-status');
                        if (imageNameStatus) {
                            imageNameStatus.textContent = imagePath.split('/').pop();
                        }

                        canvas.renderAll();
                        addLogEntry(`Image loaded: ${imagePath.split('/').pop()}`);
                    }

                    AppState.loading = false;
                    resolve(img);

                } catch (error) {
                    console.error(`[DEBUG] Error processing loaded image:`, error);
                    AppState.loading = false;
                    reject(error);
                }
            };

            img.onerror = function() {
                console.error(`[DEBUG] Failed to load image: ${imagePath}`);
                AppState.loading = false;
                reject(new Error(`Failed to load image: ${imagePath}`));
            };

            // Start loading
            img.src = `/api/image/${imagePath}`;
        });

    } catch (error) {
        console.error(`[DEBUG] Error loading image ${imagePath}:`, error);
        AppState.loading = false;
        showMessage(`Error loading image: ${error.message}`, "error");
        throw error;
    }
}

