/**
 * Load existing annotations for current image
 */
async function loadAnnotations(imagePath) {
    const AppState = getAppState();

    try {
        console.log(`[DEBUG] Loading annotations for image: ${imagePath}`);

        const batchId = AppState.currentBatch;
        const imageId = AppState.currentImageId;

        if (!batchId || !imageId) {
            console.log("[DEBUG] No batch or image ID available for loading annotations");
            return [];
        }

        // Use the correct API URL format that matches the original main.js
        const apiUrl = `/api/annotations/${imagePath}?batch_id=${batchId}&image_id=${imageId}`;
        console.log(`[DEBUG] Loading annotations from: ${apiUrl}`);

        const response = await fetch(apiUrl);

        if (!response.ok) {
            if (response.status === 404) {
                console.log("[DEBUG] No annotations found for this image");
                return [];
            } else {
                console.warn(`[DEBUG] Failed to load annotations: ${response.status}`);
                return [];
            }
        }

        const data = await response.json();
        console.log('[DEBUG] Full annotation API response:', data);

        // The API returns AnnotationGetResponse with structure: {exists: bool, coco: CocoModel, ...}
        if (!data.exists || !data.coco) {
            console.log("[DEBUG] No COCO data found in response");
            return [];
        }

        const cocoData = data.coco;
        console.log(`[DEBUG] COCO data:`, cocoData);
        console.log(`[DEBUG] Found ${cocoData.annotations?.length || 0} annotations`);

        if (cocoData.annotations && cocoData.annotations.length > 0) {
            // Parse and display annotations using the full COCO structure
            if (window.parseCocoAnnotations) {
                window.parseCocoAnnotations(cocoData);
            }
            addLogEntry(`Loaded ${cocoData.annotations.length} annotations`);
            return cocoData.annotations;
        }

        return [];

    } catch (error) {
        console.error("[DEBUG] Error loading annotations:", error);
        return [];
    }
}

/**
 * Load image metadata information
 */
async function loadMetadata(imagePath) {
    try {
        console.log(`[DEBUG] Loading metadata for: ${imagePath}`);

        // Use the original path-based API that matches main.js
        const response = await fetch(`/api/metadata/${imagePath}`);

        if (response.ok) {
            const metadata = await response.json();
            console.log("[DEBUG] Metadata loaded:", metadata);

            // Display metadata
            displayMetadata(metadata);
            return metadata;
        } else {
            console.warn(`[DEBUG] Failed to load metadata: ${response.status}`);
        }

    } catch (error) {
        console.error("[DEBUG] Error loading metadata:", error);
    }

    return null;
}

/**
 * Display metadata in the metadata panel
 */
function displayMetadata(metadata) {
    const metadataBox = document.getElementById('metadata-box');
    if (!metadataBox) return;

    if (!metadata || Object.keys(metadata).length === 0) {
        metadataBox.innerHTML = '<p class="text-gray-500 dark:text-gray-400">No metadata available</p>';
        return;
    }

    let html = '<div class="space-y-2 text-sm">';

    // Format common metadata fields
    if (metadata.filename) {
        html += `<div><strong>Filename:</strong> ${metadata.filename}</div>`;
    }
    if (metadata.size) {
        html += `<div><strong>Size:</strong> ${formatFileSize(metadata.size)}</div>`;
    }
    if (metadata.dimensions) {
        html += `<div><strong>Dimensions:</strong> ${metadata.dimensions.width} × ${metadata.dimensions.height}</div>`;
    }
    if (metadata.format) {
        html += `<div><strong>Format:</strong> ${metadata.format}</div>`;
    }
    if (metadata.created_date) {
        html += `<div><strong>Created:</strong> ${formatDate(metadata.created_date)}</div>`;
    }
    if (metadata.modified_date) {
        html += `<div><strong>Modified:</strong> ${formatDate(metadata.modified_date)}</div>`;
    }

    // Add any additional metadata
    Object.keys(metadata).forEach(key => {
        if (!['filename', 'size', 'dimensions', 'format', 'created_date', 'modified_date'].includes(key)) {
            html += `<div><strong>${key}:</strong> ${JSON.stringify(metadata[key])}</div>`;
        }
    });

    html += '</div>';
    metadataBox.innerHTML = html;
}

    // Add any additional metadata
key => {
        if (!['filename', 'size', 'dimensions', 'format', 'created_date', 'modified_date'].includes(key)) {
            html += `<div><strong>${key}:</strong> ${JSON.stringify(metadata[key])}</div>`;
        }
    }

/**
 * Load sensor data associated with image
 */
async function loadSensorData(batchId, imageId) {
    try {
        console.log(`[DEBUG] Loading sensor data for batch: ${batchId}, image: ${imageId}`);

        // Use the correct API path that matches the original main.js
        const response = await fetch(`/api/sensor/${imageId}?batch_id=${batchId}&image_id=${imageId}`);

        if (response.ok) {
            const data = await response.json();
            console.log("[DEBUG] Sensor data response:", data);

            // Extract sensor data from response (matches original format)
            const sensorData = data.sensor || {};

            // Display sensor data
            displaySensorData(sensorData);
            return sensorData;
        } else if (response.status === 404) {
            console.log("[DEBUG] No sensor data found");
            displaySensorData(null);
        } else {
            console.warn(`[DEBUG] Failed to load sensor data: ${response.status}`);
        }

    } catch (error) {
        console.error("[DEBUG] Error loading sensor data:", error);
        displaySensorData(null);
    }

    return null;
}

/**
 * Display sensor data in the sensor panel
 */
function displaySensorData(sensorData) {
    const sensorTable = document.getElementById('sensor-data-table');
    if (!sensorTable) return;

    if (!sensorData || Object.keys(sensorData).length === 0) {
        sensorTable.innerHTML = '<tr><td colspan="2" class="p-3 text-center text-gray-500 dark:text-gray-400">No sensor data available</td></tr>';
        return;
    }

    let html = '';
    Object.keys(sensorData).forEach(key => {
        const value = sensorData[key];
        html += `
            <tr class="border-b border-gray-200 dark:border-gray-600">
                <td class="p-2 font-medium text-gray-700 dark:text-gray-300">${key}</td>
                <td class="p-2 text-gray-600 dark:text-gray-400">${formatSensorValue(value)}</td>
            </tr>
        `;
    });

    sensorTable.innerHTML = html;
}

key => {
        const value = sensorData[key];
        html += `
            <tr class="border-b border-gray-200 dark:border-gray-600">
                <td class="p-2 font-medium text-gray-700 dark:text-gray-300">${key}</td>
                <td class="p-2 text-gray-600 dark:text-gray-400">${formatSensorValue(value)}</td>
            </tr>
        `;
    }

/**
 * Format sensor value for display
 */
function formatSensorValue(value) {
    if (typeof value === 'number') {
        return value.toFixed(2);
    } else if (typeof value === 'object') {
        return JSON.stringify(value);
    }
    return String(value);
}

/**
 * Helper function to format file size
 */
function formatFileSize(bytes) {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
}

/**
 * Helper function to format date
 */
function formatDate(date) {
    if (!date) return 'Unknown';
    const d = new Date(date);
    if (isNaN(d.getTime())) return 'Invalid Date';
    return d.toLocaleDateString() + ' ' + d.toLocaleTimeString();
}

/**
 * Setup all event handlers for the application
 */
function setupEventHandlers() {
    console.log("[DEBUG] Setting up event handlers");

    // Submit button handler
    setupSubmitButtonHandler();

    // Skip button handler
    setupSkipButtonHandler();

    // Delete button handler
    setupDeleteButtonHandler();

    // Accept button handler (validation mode)
    setupAcceptButtonHandler();

    // Reject button handler (validation mode)
    setupRejectButtonHandler();

    // Batch selector handler
    setupBatchSelectorHandler();

    // Mode toggle handler
    setupModeToggleHandler();

    // Class selection handlers
    setupClassSelectionHandlers();

    // Keyboard shortcuts
    setupKeyboardShortcuts();

    // Canvas interaction handlers
    setupCanvasHandlers();

    console.log("[DEBUG] All event handlers setup complete");
}

/**
 * Setup submit button event handler
 */
function setupSubmitButtonHandler() {
    const submitBtn = document.getElementById('submit-btn');
    if (!submitBtn) return;

    submitBtn.addEventListener('click', async function() {
        await handleSubmitAnnotations();
    });
}

async function() {
        await handleSubmitAnnotations();
    }

/**
 * Handle annotation submission
 */
async function handleSubmitAnnotations() {
    const AppState = getAppState();

    try {
        console.group("[DEBUG] Annotation Submission Process");
        console.log("[DEBUG] Submit button clicked");
        console.log("[DEBUG] Current AppState:", {
            currentBatch: AppState.currentBatch,
            currentImageId: AppState.currentImageId,
            annotationsCount: AppState.annotations?.length || 0,
            currentImagePath: AppState.currentImagePath
        });

        if (!AppState.currentBatch || !AppState.currentImageId) {
            console.error("[DEBUG] Missing required identifiers");
            showMessage("No image loaded to submit annotations for", "warning");
            return;
        }

        // Disable submit button to prevent multiple clicks
        const submitBtn = document.getElementById('submit-btn');
        if (submitBtn) {
            submitBtn.disabled = true;
            submitBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> <span>Submitting...</span>';
        }

        // Always submit, even if no annotations
        let cocoPayload;
        if (!AppState.annotations || AppState.annotations.length === 0) {
            console.warn("[DEBUG] No annotations to submit, submitting blank [] to overwrite existing");

            // Build blank COCO payload with all required fields for proper CosmosDB update
            cocoPayload = {
                info: {
                    description: "Facade AI Studio Annotations",
                    date_created: new Date().toISOString()
                },
                images: [{
                    id: AppState.currentImageId,
                    file_name: `${AppState.currentBatch}/cam/${AppState.currentImageId}.jpg`,
                    width: AppState.originalImageWidth || 800,
                    height: AppState.originalImageHeight || 600
                }],
                annotations: [], // This should overwrite existing annotations
                categories: AppState.classes?.map((cls, idx) => ({
                    id: idx + 1,
                    name: cls.name || cls,
                    supercategory: "object"
                })) || [],
                // Add required CosmosDB fields
                BatchID: AppState.currentBatch,
                ImageID: AppState.currentImageId,
                id: AppState.currentImageId,
                Status: "Labelled" // Mark as labelled even with empty annotations
            };
        } else {
            // Log each annotation before conversion
            console.log("[DEBUG] Raw annotations before conversion:");
            AppState.annotations.forEach((annotation, index) => {
                console.log(`[DEBUG] Annotation ${index}:`, {
                    type: annotation.type,
                    points: annotation.points?.length || 0,
                    customData: annotation.customData,
                    stroke: annotation.stroke,
                    fill: annotation.fill
                });
            });

            // Convert annotations to COCO format
            console.log("[DEBUG] Converting to COCO format...");
            cocoPayload = convertFabricToCoco(AppState.annotations);
            console.log("[DEBUG] COCO conversion result:", cocoPayload);

            if (!cocoPayload) {
                throw new Error("Failed to convert annotations to COCO format");
            }

            // Ensure required CosmosDB fields are present
            cocoPayload.BatchID = AppState.currentBatch;
            cocoPayload.ImageID = AppState.currentImageId;
            cocoPayload.id = AppState.currentImageId;
            cocoPayload.Status = "Labelled";
        }

        // Validate COCO structure
        console.log("[DEBUG] COCO validation:", {
            hasAnnotations: Array.isArray(cocoPayload.annotations),
            annotationCount: cocoPayload.annotations?.length || 0,
            hasCategories: Array.isArray(cocoPayload.categories),
            categoryCount: cocoPayload.categories?.length || 0,
            hasImages: Array.isArray(cocoPayload.images),
            imageCount: cocoPayload.images?.length || 0,
            hasBatchID: !!cocoPayload.BatchID,
            hasImageID: !!cocoPayload.ImageID,
            hasStatus: !!cocoPayload.Status
        });

        // Prepare the payload for submission
        const payload = {
            coco: cocoPayload,
            log: [`Submitted ${AppState.annotations?.length || 0} annotations at ${new Date().toISOString()}`]
        };

        console.log("[DEBUG] Final payload structure:", {
            hasCoco: 'coco' in payload,
            hasLog: 'log' in payload,
            cocoType: typeof payload.coco,
            logType: typeof payload.log,
            payloadSize: JSON.stringify(payload).length,
            isEmptySubmission: (AppState.annotations?.length || 0) === 0
        });

        // Use the simpler API URL format that matches the backend routing
        const apiUrl = `/api/annotations/${AppState.currentBatch}/${AppState.currentImageId}?batch_id=${AppState.currentBatch}&image_id=${AppState.currentImageId}`;
        console.log("[DEBUG] Submitting to URL:", apiUrl);

        // Submit to server
        console.log("[DEBUG] Making POST request...");
        const response = await fetch(apiUrl, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify(payload)
        });

        console.log("[DEBUG] Response received:", {
            status: response.status,
            statusText: response.statusText,
            ok: response.ok,
            headers: Object.fromEntries(response.headers.entries())
        });

        if (!response.ok) {
            const errorText = await response.text();
            console.error("[DEBUG] Error response body:", errorText);

            try {
                const errorData = JSON.parse(errorText);
                console.error("[DEBUG] Parsed error data:", errorData);
                throw new Error(errorData.detail || `Server error: ${response.status}`);
            } catch (parseError) {
                console.error("[DEBUG] Could not parse error response as JSON");
                throw new Error(`Server error: ${response.status} - ${errorText}`);
            }
        }

        const result = await response.json();
        console.log("[DEBUG] Submission successful:", result);

        // Check if CosmosDB was updated successfully
        if (result.cosmosDBSaved === false && result.cosmosDBError) {
            console.warn("[DEBUG] CosmosDB save failed:", result.cosmosDBError);
            showMessage(`Warning: ${result.cosmosDBError}`, "warning");
        }

        const annotationCount = AppState.annotations?.length || 0;
        const message = annotationCount === 0 
            ? "Successfully submitted empty annotations (cleared existing)"
            : `Successfully submitted ${annotationCount} annotations`;

        addLogEntry(`Submitted ${annotationCount} annotations for ${AppState.currentImageId}`);
        showMessage(message, "success");

        // Auto-navigate to next image after successful submission
        setTimeout(() => {
            navigateToNextImage();
        }, 500);

    } catch (error) {
        console.error("[DEBUG] Error submitting annotations:", error);
        console.error("[DEBUG] Error stack:", error.stack);
        showMessage(`Error submitting annotations: ${error.message}`, "error");
    } finally {
        console.groupEnd();
        // Reset button state
        const submitBtn = document.getElementById('submit-btn');
        if (submitBtn) {
            submitBtn.disabled = false;
            submitBtn.innerHTML = '<i class="fas fa-check"></i> <span>Submit</span>';
        }
    }
}

