/**
 * Debounce utility for event processing
 */
function debounce(func, wait) {
    let timeout;
    return function executedFunction(...args) {
        const later = () => {
            clearTimeout(timeout);
            func.apply(this, args);
        };
        clearTimeout(timeout);
        timeout = setTimeout(later, wait);
    };
}

function executedFunction(...args) {
        const later = () => {
            clearTimeout(timeout);
            func.apply(this, args);
        };
        clearTimeout(timeout);
        timeout = setTimeout(later, wait);
    }

() => {
            clearTimeout(timeout);
            func.apply(this, args);
        }

/**
 * Throttle utility for event processing
 */
function throttle(func, limit) {
    let inThrottle;
    return function executedFunction(...args) {
        if (!inThrottle) {
            func.apply(this, args);
            inThrottle = true;
            setTimeout(() => inThrottle = false, limit);
        }
    };
}

function executedFunction(...args) {
        if (!inThrottle) {
            func.apply(this, args);
            inThrottle = true;
            setTimeout(() => inThrottle = false, limit);
        }
    }

/**
 * Create event processor for specific event types
 */
function createEventProcessor(eventType, handler) {
    return {
        type: eventType,
        handler: handler,
        process: function(event) {
            if (event.type === this.type) {
                this.handler(event);
                return true;
            }
            return false;
        }
    };
}

function(event) {
            if (event.type === this.type) {
                this.handler(event);
                return true;
            }
            return false;
        }

constructor() {
        this.queue = [];
        this.processing = false;
    }

add(event) {
        this.queue.push({
            ...event,
            timestamp: Date.now()
        });
    }

async process() {
        if (this.processing) return;

        this.processing = true;

        try {
            while (this.queue.length > 0) {
                const event = this.queue.shift();
                await this.processEvent(event);
            }
        } catch (error) {
            console.error("[DEBUG] Error processing event queue:", error);
        } finally {
            this.processing = false;
        }
    }

async processEvent(event) {
        console.log("[DEBUG] Processing queued event:", event.type);

        switch (event.type) {
            case 'batch_annotation':
            case 'annotation_created':
            case 'annotation_modified':
            case 'annotation_deleted':
                await processBatchEvents([event]);
                break;
            case 'validation':
                await processValidationEvents([event]);
                break;
            case 'save':
                await processSaveEvents([event]);
                break;
            case 'load':
                await processLoadEvents([event]);
                break;
        }
    }

clear() {
        this.queue = [];
    }

size() {
        return this.queue.length;
    }

/**
 * Initialize event processor
 */
function initializeEventProcessor() {
    console.log("[DEBUG] Event processor initialized");

    // Start processing queue periodically
    setInterval(() => {
        if (eventQueue.size() > 0) {
            eventQueue.process();
        }
    }, 1000);
}

    // Start processing queue periodically
() => {
        if (eventQueue.size() > 0) {
            eventQueue.process();
        }
    }

/**
 * Cleanup event processor
 */
function cleanupEventProcessor() {
    eventQueue.clear();
    console.log("[DEBUG] Event processor cleaned up");
}

