                ${entry.validator_notes ? `<div class="text-sm text-gray-600 dark:text-gray-400 mt-1">${entry.validator_notes}</div>` : ''}
            </div>
        `;
    });

    html += '</div>';
    historyContainer.innerHTML = html;
}

