/**
 * Initialize validation for user role
 */
function initValidationForRole() {
    const AppState = getAppState();

    if (AppState.user?.role === 'Reviewer') {
        // For reviewers, start in validation mode
        const modeToggle = document.getElementById('mode-toggle-switch');
        if (modeToggle) {
            modeToggle.checked = true;
            modeToggle.disabled = true; // Prevent changing mode
            toggleValidationMode(true);
        }

        console.log("[DEBUG] Initialized validation mode for Reviewer role");
    }

    // Setup validation keyboard shortcuts
    setupValidationKeyboardShortcuts();
}

def _report_progress(self):
        """Report progress either via callback or stdout."""
        if self.progress_callback:
            self.progress_callback(self._indexing_stats.copy())
        else:
            total = self._indexing_stats.get('total_files', 0)
            processed = self._indexing_stats.get('files_processed', 0)
            current = self._indexing_stats.get('current_dir', '')
            if total:
                percent = (processed / total) * 100
                print(f"Indexing {processed}/{total} files ({percent:.1f}%) - {current}", end='\r', flush=True)
            else:
                print(f"Indexing... ({current})", end='\r', flush=True)

  // MARK: - CellLayoutView

func paintCells(origin: (x: Int, y: Int), into buffer: inout CellBuffer) {
    // フレームサイズを計算
    let frameWidth = width.map { Int($0) } ?? 0
    let frameHeight = height.map { Int($0) } ?? 0

    // 子ビューをセルバッファに描画
    if let cellChild = child as? CellLayoutView {
      cellChild.paintCells(origin: origin, into: &buffer)
    } else {
      // CellLayoutViewを実装していない場合はアダプタを使用
      let adapter = CellLayoutAdapter(child)
      adapter.paintCells(origin: origin, into: &buffer)
    }

    // フレーム幅が指定されている場合、余剰部分をクリア
    if frameWidth > 0 {
      for row in 0..<(frameHeight > 0 ? frameHeight : 1) {
        for col in 0..<frameWidth {
          let r = origin.y + row
          let c = origin.x + col
          // 既存のコンテンツがない場合のみ空白を設定
          if buffer.getCell(row: r, col: c) == nil {
            buffer.setCell(row: r, col: c, cell: Cell(character: " "))
          }
        }
      }
    }
  }

