async function runAllTests() {
  console.log(`Found ${tests.length} test suites to run.\n`);

  for (const test of tests) {
    await runTest(test);
  }

  console.log('\n' + '='.repeat(60));
  console.log('📊 Test Summary');
  console.log('='.repeat(60));
  console.log(`✅ Passed: ${passed}`);
  console.log(`❌ Failed: ${failed}`);
  console.log(`📋 Total:  ${tests.length}`);
  console.log('='.repeat(60));

  if (failed > 0) {
    console.log('\n⚠️  Some tests failed. Please check the output above.');
    process.exit(1);
  } else {
    console.log('\n🎉 All tests passed!');
    process.exit(0);
  }
}

// Check for required environment variables
function checkEnvironment() {
  const required = ['NEO4J_URI', 'NEO4J_USERNAME', 'NEO4J_PASSWORD'];
  const missing = required.filter(key => !process.env[key]);

  if (missing.length > 0) {
    console.error('❌ Missing required environment variables:');
    missing.forEach(key => console.error(`   - ${key}`));
    console.error('\nPlease check your .env file or set these variables.');
    process.exit(1);
  }
}

def resolve_conflicts(sop: Dict) -> bool:
    """Return True if no conflicts found."""
    conflicts: List[str] = []
    if sop.get("logic_issues"):
        conflicts.extend(sop["logic_issues"])
    if not sop.get("safety"):
        conflicts.append("Missing safety procedures.")
    if conflicts:
        sop["conflict_fields"] = conflicts
        return False
    return True

def run_arbiter(data: Dict) -> Dict:
    sop = deepcopy(data)
    sop["arbiter_backup"] = deepcopy(sop)
    if resolve_conflicts(sop):
        sop["status"] = "arbiter_complete"
    else:
        sop["status"] = "arbiter_conflict"
    return sop

def validate_logic(sop: Dict) -> List[str]:
    """Return list of logic issues in the SOP."""
    issues = []
    if not sop.get("tools"):
        issues.append("Missing tool list.")
    proc = sop.get("procedure", [])
    if not isinstance(proc, list) or not proc:
        issues.append("Procedure steps are missing or invalid.")
    else:
        actions = ["install", "remove", "check", "clean", "torque", "grease"]
        for idx, step in enumerate(proc, 1):
            if not any(verb in step.lower() for verb in actions):
                issues.append(f"Step {idx} may lack a clear action: '{step}'")
    return issues

def load_rules() -> Dict:
    if RULES_FILE.is_file():
        try:
            return json.loads(RULES_FILE.read_text())
        except Exception:
            pass
    return DEFAULT_REG_RULES

def apply_safety(sop: Dict) -> List[str]:
    added = []
    sop.setdefault("safety", [])
    for rule in PPE_DEFAULTS:
        if rule not in sop["safety"]:
            sop["safety"].append(rule)
            added.append(rule)
    for step in sop.get("procedure", []):
        for keyword, warning in HAZARD_FLAGS:
            if keyword in step.lower() and warning not in sop["safety"]:
                sop["safety"].append(warning)
                added.append(warning)
    return added

def explain_sop(sop: Dict) -> Tuple[List[str], List[str]]:
    breakdown: List[str] = []
    tech_notes: List[str] = []

    breakdown.append(f"📌 Purpose: {sop.get('purpose', '').strip()}")
    breakdown.append(f"📍 Scope: {sop.get('scope', '').strip()}")

    breakdown.append("🧰 Tools needed:")
    for tool in sop.get('tools', []):
        breakdown.append(f"  - {tool}")
    breakdown.append("📦 Materials needed:")
    for mat in sop.get('materials', []):
        breakdown.append(f"  - {mat}")

    if sop.get('safety'):
        breakdown.append("🛡️ Safety Notes:")
        for note in sop['safety']:
            breakdown.append(f"  ⚠️ {note}")

    breakdown.append("🛠️ Procedure Steps:")
    for i, step in enumerate(sop.get('procedure', []), 1):
        breakdown.append(f"  Step {i}: {step}")
        text = step.lower()
        if any(k in text for k in ['remove', 'disassemble']):
            tech_notes.append(
                f"Step {i}: Disassembly step - ensure parts are organized and secure."
            )
        if any(k in text for k in ['torque', 'tighten']):
            tech_notes.append(
                f"Step {i}: Fastening step - use torque wrench to manufacturer spec."
            )
        if 'grease' in text:
            tech_notes.append(
                f"Step {i}: Lubrication - apply correct grease sparingly."
            )

    return breakdown, tech_notes

