def test_aiml_api_context_window_bounds(self):
        """Test that AI/ML API model context windows are within valid bounds."""
        from crewai.llm import LLM_CONTEXT_WINDOW_SIZES

        aiml_models = {k: v for k, v in LLM_CONTEXT_WINDOW_SIZES.items() 
                      if k.startswith("openai/")}

        MIN_CONTEXT = 1024
        MAX_CONTEXT = 2097152

        for model_name, context_size in aiml_models.items():
            assert MIN_CONTEXT <= context_size <= MAX_CONTEXT, (
                f"Model {model_name} context window {context_size} is outside "
                f"valid bounds [{MIN_CONTEXT}, {MAX_CONTEXT}]"
            )

def test_aiml_api_different_model_types(self):
        """Test different types of models available through AI/ML API."""
        model_types = {
            "llama": "openai/meta-llama/Meta-Llama-3.1-70B-Instruct-Turbo",
            "claude": "openai/anthropic/claude-3-5-sonnet-20241022",
            "mistral": "openai/mistralai/Mixtral-8x7B-Instruct-v0.1",
            "qwen": "openai/Qwen/Qwen2.5-72B-Instruct-Turbo",
            "deepseek": "openai/deepseek-ai/DeepSeek-V2.5",
        }

        for model_type, model_name in model_types.items():
            llm = LLM(model=model_name)
            assert llm.model == model_name
            assert llm._get_custom_llm_provider() == "openai"
            assert llm.get_context_window_size() > 0, (
                f"{model_type} model should have positive context window"
            )

// Initialize blockchain connection
function initializeBlockchain() {
    if (!PRIVATE_KEY || !CONTRACT_ADDRESS) {
        console.warn("⚠️  Blockchain configuration missing. Smart contract features disabled.");
        return;
    }

    try {
        provider = new ethers.JsonRpcProvider(POLYGON_RPC_URL);
        wallet = new ethers.Wallet(PRIVATE_KEY, provider);
        nftContract = new ethers.Contract(CONTRACT_ADDRESS, NFT_CONTRACT_ABI, wallet);
        polContract = new ethers.Contract(POL_TOKEN_ADDRESS, POL_TOKEN_ABI, provider);
        console.log("✅ Blockchain connection initialized");
    } catch (error) {
        console.error("❌ Failed to initialize blockchain connection:", error);
    }
}

// Check POL balance and allowance for a wallet
async (req, res) => {
    const { wallet, amount } = req.body;

    if (!wallet || !amount) {
        return res.status(400).json({ ok: false, message: 'ウォレットアドレスと金額が必要です' });
    }

    if (!polContract) {
        return res.status(503).json({ ok: false, message: 'ブロックチェーン接続が利用できません' });
    }

    try {
        const amountWei = ethers.parseUnits(amount.toString(), 18); // POL has 18 decimals
        const balance = await polContract.balanceOf(wallet);
        const allowance = await polContract.allowance(wallet, CONTRACT_ADDRESS);

        const canPay = balance >= amountWei && allowance >= amountWei;

        res.json({
            ok: true,
            canPay,
            balance: ethers.formatUnits(balance, 18),
            allowance: ethers.formatUnits(allowance, 18),
            required: amount
        });
    } catch (error) {
        console.error('支払い能力確認エラー:', error);
        res.status(500).json({ ok: false, message: '内部サーバーエラー' });
    }
}

// Enhanced bid endpoint with payment verification
async (req, res) => {
    const { wallet, price, signature, message } = req.body;

    if (!wallet || !price || !signature || !message) {
        return res.status(400).json({ ok: false, message: '必要な情報が不足しています' });
    }

    if (price <= 0) {
        return res.status(400).json({ ok: false, message: '価格は1以上である必要があります' });
    }

    try {
        // Verify signature first
        const signerAddress = verifyMessage(message, signature);
        if (signerAddress.toLowerCase() !== wallet.toLowerCase()) {
            return res.status(401).json({ ok: false, message: '署名が一致しません' });
        }

        // Check POL payment capability if blockchain is available
        if (polContract) {
            const amountWei = ethers.parseUnits(price.toString(), 18);
            const balance = await polContract.balanceOf(wallet);
            const allowance = await polContract.allowance(wallet, CONTRACT_ADDRESS);

            if (balance < amountWei) {
                return res.status(400).json({ ok: false, message: 'POL残高が不足しています' });
            }

            if (allowance < amountWei) {
                return res.status(400).json({ 
                    ok: false, 
                    message: 'POLの使用許可が不足しています。approveを実行してください',
                    needsApproval: true,
                    contractAddress: CONTRACT_ADDRESS
                });
            }
        }

        // Save bid to database
        const saved = await prisma.auctionBid.create({
            data: {
                wallet: wallet,
                price: parseInt(price)
            }
        });

        console.log("✅ 支払い確認済み入札保存完了", saved);

        // Broadcast to all clients
        io.emit('new-bid', saved);

        res.json({ ok: true, bid: saved });

    } catch (error) {
        console.error('入札エラー:', error);
        res.status(500).json({ ok: false, message: 'サーバーエラー: 入札できませんでした' });
    }
}

// Execute NFT mint for pending mints
async (req, res) => {
    const { date } = req.body;

    if (!date) {
        return res.status(400).json({ ok: false, message: '日付が必要です' });
    }

    if (!nftContract) {
        return res.status(503).json({ ok: false, message: 'スマートコントラクト接続が利用できません' });
    }

    try {
        // Check if there's a pending mint for this date
        const pendingMint = await prisma.PendingMint.findUnique({
            where: { date: date }
        });

        if (!pendingMint) {
            return res.status(404).json({ ok: false, message: '指定された日付のPendingMintが見つかりません' });
        }

        // Check if already minted on blockchain
        const exists = await nftContract.exists(date);
        if (exists) {
            return res.status(400).json({ ok: false, message: 'この日付のNFTは既にmint済みです' });
        }

        // Execute mint transaction
        console.log(`🔄 Minting NFT for ${date} to ${pendingMint.wallet}...`);

        const priceWei = ethers.parseUnits(pendingMint.price.toString(), 18);
        const tx = await nftContract.mintToWinner(
            date,
            pendingMint.wallet,
            priceWei,
            pendingMint.metadataUrl
        );

        console.log(`⏳ Transaction submitted: ${tx.hash}`);
        const receipt = await tx.wait();
        console.log(`✅ NFT minted successfully! Block: ${receipt.blockNumber}`);

        // Update database to mark as minted
        await prisma.PendingMint.update({
            where: { date: date },
            data: { 
                // You might want to add a 'minted' boolean field to the schema
                metadataUrl: `${pendingMint.metadataUrl} - MINTED:${tx.hash}`
            }
        });

        res.json({
            ok: true,
            message: 'NFTのmintが完了しました',
            txHash: tx.hash,
            blockNumber: receipt.blockNumber
        });

    } catch (error) {
        console.error('NFT mint エラー:', error);

        if (error.message.includes('Insufficient POL balance')) {
            res.status(400).json({ ok: false, message: '落札者のPOL残高が不足しています' });
        } else if (error.message.includes('POL transfer failed')) {
            res.status(400).json({ ok: false, message: 'POLの転送に失敗しました。allowanceを確認してください' });
        } else {
            res.status(500).json({ ok: false, message: 'NFTのmintに失敗しました', error: error.message });
        }
    }
}

// Get mint status for a date
async (req, res) => {
    const { date } = req.params;

    try {
        const pendingMint = await prisma.PendingMint.findUnique({
            where: { date: date }
        });

        let blockchainStatus = null;
        if (nftContract) {
            try {
                const exists = await nftContract.exists(date);
                if (exists) {
                    const auctionInfo = await nftContract.getAuctionInfo(date);
                    blockchainStatus = {
                        exists: true,
                        winner: auctionInfo.winner,
                        price: ethers.formatUnits(auctionInfo.price, 18),
                        minted: auctionInfo.minted,
                        metadataUri: auctionInfo.metadataUri
                    };
                }
            } catch (error) {
                console.warn('ブロックチェーン状態確認エラー:', error);
            }
        }

        res.json({
            pendingMint,
            blockchainStatus
        });

    } catch (error) {
        console.error('Mint状態確認エラー:', error);
        res.status(500).json({ ok: false, message: '内部サーバーエラー' });
    }
}

    /**
     * Private constructor to prevent instantiation of utility class.
     */
private ModernCollectionProcessor() {
        throw new UnsupportedOperationException("Utility class cannot be instantiated");
    }

    /**
     * Checks if a value exists in a collection using Stream API.
     * Replaces legacy: for (int i = 0; i < array.length; i++) { if (array[i].equals(value)) ... }
     */
public static <T> boolean contains(Collection<T> collection, T value) {
        if (collection == null || value == null) {
            return false;
        }

        return collection.stream()
                        .anyMatch(item -> Objects.equals(item, value));
    }

    /**
     * Finds the first matching element using Stream API with predicate.
     * Demonstrates functional programming approach to searching.
     */
public static <T> Optional<T> findFirst(Collection<T> collection, Predicate<T> predicate) {
        if (collection == null || predicate == null) {
            return Optional.empty();
        }

        return collection.stream()
                        .filter(predicate)
                        .findFirst();
    }

    /**
     * Filters collection elements using Stream API.
     * Replaces manual loop-based filtering with functional approach.
     */
public static <T> List<T> filter(Collection<T> collection, Predicate<T> predicate) {
        if (collection == null || predicate == null) {
            return new ArrayList<>();
        }

        return collection.stream()
                        .filter(predicate)
                        .collect(Collectors.toList());
    }

    /**
     * Transforms collection elements using Stream API map operation.
     * Demonstrates functional transformation instead of manual loops.
     */
public static <T, R> List<R> map(Collection<T> collection, Function<T, R> mapper) {
        if (collection == null || mapper == null) {
            return new ArrayList<>();
        }

        return collection.stream()
                        .map(mapper)
                        .collect(Collectors.toList());
    }

    /**
     * Counts elements matching a condition using Stream API.
     * Replaces manual counter loops with functional counting.
     */
public static <T> long count(Collection<T> collection, Predicate<T> predicate) {
        if (collection == null || predicate == null) {
            return 0;
        }

        return collection.stream()
                        .filter(predicate)
                        .count();
    }

    /**
     * Groups collection elements by a classifier function.
     * Demonstrates advanced Stream API operations for data organization.
     */
public static <T, K> Map<K, List<T>> groupBy(Collection<T> collection, Function<T, K> classifier) {
        if (collection == null || classifier == null) {
            return new HashMap<>();
        }

        return collection.stream()
                        .collect(Collectors.groupingBy(classifier));
    }

    /**
     * Processes collection elements in parallel for better performance.
     * Demonstrates modern parallel processing capabilities.
     */
public static <T, R> List<R> parallelMap(Collection<T> collection, Function<T, R> mapper) {
        if (collection == null || mapper == null) {
            return new ArrayList<>();
        }

        return collection.parallelStream()
                        .map(mapper)
                        .collect(Collectors.toList());
    }

    /**
     * Reduces collection to a single value using Stream API.
     * Replaces manual accumulation loops with functional reduction.
     */
public static <T> Optional<T> reduce(Collection<T> collection, java.util.function.BinaryOperator<T> accumulator) {
        if (collection == null || accumulator == null) {
            return Optional.empty();
        }

        return collection.stream()
                        .reduce(accumulator);
    }

    /**
     * Creates a Set from array for O(1) lookup performance.
     * Modernizes array-based contains operations.
     */
public static <T> Set<T> arrayToSet(T[] array) {
        if (array == null) {
            return new HashSet<>();
        }

        return Arrays.stream(array)
                    .collect(Collectors.toSet());
    }

    /**
     * Validates SSN against special cases using modern Set operations.
     * Replaces legacy for-loop array iteration with O(1) Set lookup.
     */
public static boolean isSpecialCaseSsn(String ssn, Set<String> specialCases) {
        if (ssn == null || specialCases == null) {
            return false;
        }

        return specialCases.contains(ssn);
    }

    /**
     * Processes lines from input using Stream API.
     * Replaces while-loop line reading with functional processing.
     */
public static List<String> processLines(Stream<String> lines, Predicate<String> filter) {
        if (lines == null || filter == null) {
            return new ArrayList<>();
        }

        return lines.filter(filter)
                   .map(String::trim)
                   .filter(line -> !line.isEmpty())
                   .collect(Collectors.toList());
    }

    /**
     * Creates a range of integers using IntStream.
     * Replaces manual for-loop index generation with functional approach.
     */
public static List<Integer> range(int start, int end) {
        return IntStream.range(start, end)
                       .boxed()
                       .collect(Collectors.toList());
    }

    /**
     * Partitions collection into two groups based on predicate.
     * Demonstrates advanced Stream API partitioning operations.
     */
public static <T> Map<Boolean, List<T>> partition(Collection<T> collection, Predicate<T> predicate) {
        if (collection == null || predicate == null) {
            Map<Boolean, List<T>> result = new HashMap<>();
            result.put(true, new ArrayList<>());
            result.put(false, new ArrayList<>());
            return result;
        }

        return collection.stream()
                        .collect(Collectors.partitioningBy(predicate));
    }

    /**
     * Finds distinct elements using Stream API.
     * Replaces manual duplicate checking with functional deduplication.
     */
public static <T> List<T> distinct(Collection<T> collection) {
        if (collection == null) {
            return new ArrayList<>();
        }

        return collection.stream()
                        .distinct()
                        .collect(Collectors.toList());
    }

    /**
     * Sorts collection using Stream API with custom comparator.
     * Demonstrates functional sorting instead of manual sorting loops.
     */
public static <T> List<T> sort(Collection<T> collection, Comparator<T> comparator) {
        if (collection == null) {
            return new ArrayList<>();
        }

        return collection.stream()
                        .sorted(comparator)
                        .collect(Collectors.toList());
    }

    /**
     * Private constructor for builder pattern.
     */
private ModernInputProcessor(Builder builder) {
        this.scanner = builder.scanner != null ? builder.scanner : new Scanner(System.in);
        this.validators = new HashMap<>(builder.validators);
        this.prompts = new HashMap<>(builder.prompts);
    }

    /**
     * Creates a new builder for constructing ModernInputProcessor.
     */
public static Builder builder() {
        return new Builder();
    }

    /**
     * Processes user input using functional validation.
     * Replaces legacy while-loop input processing with functional approach.
     */
public Optional<String> promptFor(String fieldName) {
        String prompt = prompts.getOrDefault(fieldName, fieldName + "?");
        InputValidator validator = validators.getOrDefault(fieldName, InputValidator.alwaysValid());

        System.out.println(prompt);
        String input = scanner.nextLine();

        if (input == null || input.trim().isEmpty()) {
            return Optional.empty();
        }

        return validator.validate(input.trim()) ? 
               Optional.of(input.trim()) : 
               Optional.empty();
    }

    /**
     * Processes multiple inputs using Stream API.
     * Demonstrates functional approach to collecting multiple inputs.
     */
public Map<String, String> promptForMultiple(List<String> fieldNames) {
        if (fieldNames == null || fieldNames.isEmpty()) {
            return new HashMap<>();
        }

        return fieldNames.stream()
                        .collect(HashMap::new,
                               (map, field) -> promptFor(field).ifPresent(value -> map.put(field, value)),
                               HashMap::putAll);
    }

    /**
     * Processes input with retry logic using functional programming.
     * Replaces manual retry loops with functional retry mechanism.
     */
public Optional<String> promptWithRetry(String fieldName, int maxAttempts) {
        for (int attempt = 1; attempt <= maxAttempts; attempt++) {
            if (attempt > 1) {
                System.out.println("Invalid input. Please try again.");
            }
            Optional<String> result = promptFor(fieldName);
            if (result.isPresent()) {
                return result;
            }
        }
        return Optional.empty();
    }

    /**
     * Processes input until a termination condition is met.
     * Modernizes legacy while(!done) patterns with functional streaming.
     */
public List<String> collectUntil(String fieldName, Predicate<String> terminationCondition) {
        List<String> results = new ArrayList<>();

        while (true) {
            Optional<String> input = promptFor(fieldName);
            if (input.isPresent()) {
                String value = input.get();
                if (terminationCondition.test(value)) {
                    break;
                }
                results.add(value);
            }
        }

        return results;
    }

    /**
     * Processes structured input using command pattern.
     * Demonstrates modern approach to handling different input types.
     */
public <T> Optional<T> processStructuredInput(String fieldName, Function<String, T> parser) {
        return promptFor(fieldName)
                .map(input -> {
                    try {
                        return parser.apply(input);
                    } catch (Exception e) {
                        System.out.println("Invalid format: " + e.getMessage());
                        return null;
                    }
                })
                .filter(Objects::nonNull);
    }

    /**
     * Closes the scanner resource safely.
     */
public void close() {
        if (scanner != null) {
            scanner.close();
        }
    }

public Builder withScanner(Scanner scanner) {
            this.scanner = scanner;
            return this;
        }

public Builder withValidator(String fieldName, InputValidator validator) {
            this.validators.put(fieldName, validator);
            return this;
        }

public Builder withPrompt(String fieldName, String prompt) {
            this.prompts.put(fieldName, prompt);
            return this;
        }

public Builder withField(String fieldName, String prompt, InputValidator validator) {
            this.prompts.put(fieldName, prompt);
            this.validators.put(fieldName, validator);
            return this;
        }

public ModernInputProcessor build() {
            return new ModernInputProcessor(this);
        }

static InputValidator alwaysValid() {
            return input -> true;
        }

static InputValidator notEmpty() {
            return input -> input != null && !input.trim().isEmpty();
        }

static InputValidator matches(String regex) {
            return input -> input != null && input.matches(regex);
        }

static InputValidator minLength(int minLength) {
            return input -> input != null && input.length() >= minLength;
        }

static InputValidator maxLength(int maxLength) {
            return input -> input != null && input.length() <= maxLength;
        }

static InputValidator and(InputValidator first, InputValidator second) {
            return input -> first.validate(input) && second.validate(input);
        }

static InputValidator or(InputValidator first, InputValidator second) {
            return input -> first.validate(input) || second.validate(input);
        }

