            # Apply circuit breaker
            @service_breaker
            def service_call():
                if should_fail:
                    raise Exception("Service failure")
                return {"status": "success", "user_id": user_id}

            return service_call()

def service_call():
                if should_fail:
                    raise Exception("Service failure")
                return {"status": "success", "user_id": user_id}

