def _load_config(self, config_file: str) -> Dict[str, Any]:
        """Load configuration from JSON file"""
        if not Path(config_file).exists():
            raise FileNotFoundError(f"Configuration file not found: {config_file}")

        try:
            with open(config_file, 'r', encoding='utf-8') as f:
                config = json.load(f)

            self.logger.debug(f"Loaded configuration from: {config_file}")
            return config

        except Exception as e:
            raise ValueError(f"Failed to load configuration from {config_file}: {e}")

def _apply_file_filters(self, model: ProjectModel, filters: Dict[str, Any]) -> ProjectModel:
        """Apply file-level filters"""
        include_patterns = self._compile_patterns(filters.get('include', []))
        exclude_patterns = self._compile_patterns(filters.get('exclude', []))

        if not include_patterns and not exclude_patterns:
            return model

        filtered_files = {}
        for file_path, file_model in model.files.items():
            if self._should_include_file(file_path, include_patterns, exclude_patterns):
                filtered_files[file_path] = file_model

        model.files = filtered_files
        self.logger.debug(f"File filtering: {len(model.files)} files after filtering")
        return model

def _apply_element_filters(self, model: ProjectModel, filters: Dict[str, Any]) -> ProjectModel:
        """Apply element-level filters"""
        for file_path, file_model in model.files.items():
            model.files[file_path] = self._filter_file_elements(file_model, filters)

        return model

def _filter_file_elements(self, file_model: FileModel, filters: Dict[str, Any]) -> FileModel:
        """Filter elements within a file"""
        # Filter structs
        if 'structs' in filters:
            file_model.structs = self._filter_dict(
                file_model.structs, 
                filters['structs']
            )

        # Filter enums
        if 'enums' in filters:
            file_model.enums = self._filter_dict(
                file_model.enums, 
                filters['enums']
            )

        # Filter unions
        if 'unions' in filters:
            file_model.unions = self._filter_dict(
                file_model.unions, 
                filters['unions']
            )

        # Filter functions
        if 'functions' in filters:
            file_model.functions = self._filter_list(
                file_model.functions, 
                filters['functions'],
                key=lambda f: f.name
            )

        # Filter globals
        if 'globals' in filters:
            file_model.globals = self._filter_list(
                file_model.globals, 
                filters['globals'],
                key=lambda g: g.name
            )

        # Filter macros
        if 'macros' in filters:
            file_model.macros = self._filter_list(
                file_model.macros, 
                filters['macros']
            )

        # Filter typedefs
        if 'typedefs' in filters:
            file_model.typedefs = self._filter_dict(
                file_model.typedefs, 
                filters['typedefs']
            )

        return file_model

def _apply_model_transformations(self, model: ProjectModel, transformations: Dict[str, Any]) -> ProjectModel:
        """Apply model-level transformations"""
        # Rename elements
        if 'rename' in transformations:
            model = self._apply_renaming(model, transformations['rename'])

        # Add elements
        if 'add' in transformations:
            model = self._apply_additions(model, transformations['add'])

        # Remove elements
        if 'remove' in transformations:
            model = self._apply_removals(model, transformations['remove'])

        return model

def _process_include_relations(self, model: ProjectModel, max_depth: int) -> ProjectModel:
        """Process include relationships up to specified depth"""
        self.logger.info(f"Processing include relations with max depth: {max_depth}")

        # Create a mapping of file paths to their models for quick lookup
        file_map = {file_model.file_path: file_model for file_model in model.files.values()}

        # Process each file's includes
        for file_path, file_model in model.files.items():
            self._process_file_includes(file_model, file_map, max_depth, 1, set())

        return model

def _find_included_file(self, include_name: str, project_root: str) -> Optional[str]:
        """Find the actual file path for an include"""
        # Common include paths to search
        search_paths = [
            Path(project_root),
            Path(project_root) / "include",
            Path(project_root) / "src",
            Path(project_root) / "lib",
            Path(project_root) / "headers"
        ]

        # Try different extensions
        extensions = ['.h', '.hpp', '.hxx', '']

        for search_path in search_paths:
            if not search_path.exists():
                continue

            for ext in extensions:
                file_path = search_path / f"{include_name}{ext}"
                if file_path.exists():
                    return str(file_path.resolve())

        return None

def _compile_patterns(self, patterns: List[str]) -> List[re.Pattern]:
        """Compile regex patterns with error handling"""
        compiled_patterns = []

        for pattern in patterns:
            try:
                compiled_patterns.append(re.compile(pattern))
            except re.error as e:
                self.logger.warning(f"Invalid regex pattern '{pattern}': {e}")

        return compiled_patterns

def _should_include_file(self, file_path: str, include_patterns: List[re.Pattern], 
                           exclude_patterns: List[re.Pattern]) -> bool:
        """Check if a file should be included based on filters"""
        # Check include patterns
        if include_patterns:
            if not any(pattern.search(file_path) for pattern in include_patterns):
                return False

        # Check exclude patterns
        if exclude_patterns:
            if any(pattern.search(file_path) for pattern in exclude_patterns):
                return False

        return True

def _filter_dict(self, items: Dict, filters: Dict) -> Dict:
        """Filter a dictionary based on include/exclude patterns"""
        include_patterns = self._compile_patterns(filters.get('include', []))
        exclude_patterns = self._compile_patterns(filters.get('exclude', []))

        filtered = {}
        for name, item in items.items():
            # Check include patterns
            if include_patterns:
                if not any(pattern.search(name) for pattern in include_patterns):
                    continue

            # Check exclude patterns
            if exclude_patterns:
                if any(pattern.search(name) for pattern in exclude_patterns):
                    continue

            filtered[name] = item

        return filtered

def _filter_list(self, items: List, filters: Dict, key=None) -> List:
        """Filter a list based on include/exclude patterns"""
        include_patterns = self._compile_patterns(filters.get('include', []))
        exclude_patterns = self._compile_patterns(filters.get('exclude', []))

        filtered = []
        for item in items:
            item_name = key(item) if key else str(item)

            # Check include patterns
            if include_patterns:
                if not any(pattern.search(item_name) for pattern in include_patterns):
                    continue

            # Check exclude patterns
            if exclude_patterns:
                if any(pattern.search(item_name) for pattern in exclude_patterns):
                    continue

            filtered.append(item)

        return filtered

def _save_model(self, model: ProjectModel, output_file: str) -> None:
        """Save model to JSON file"""
        try:
            model.save(output_file)
            self.logger.debug(f"Model saved to: {output_file}")
        except Exception as e:
            raise ValueError(f"Failed to save model to {output_file}: {e}")

[Fact]
    public void AnalyzeInterface_DetectsServiceInterface()
    {
        // Arrange
        var detector = new ServicePatternDetector();
        var sourceCode = @"
            namespace Rac.Audio;
            public interface IAudioService
            {
                void PlaySound(string path);
                void SetVolume(float volume);
            }";

        var syntaxTree = CSharpSyntaxTree.ParseText(sourceCode);
        var compilation = CSharpCompilation.Create("Test").AddSyntaxTrees(syntaxTree);
        var semanticModel = compilation.GetSemanticModel(syntaxTree);
        var context = new AnalysisContextWrapper(semanticModel);

        var interfaceDecl = syntaxTree.GetRoot()
            .DescendantNodes()
            .OfType<InterfaceDeclarationSyntax>()
            .First();

        // Act
        detector.AnalyzeInterface(context, interfaceDecl);
        var patterns = detector.GetDetectedPatterns();

        // Assert
        Assert.Single(patterns);
        var pattern = patterns.First();
        Assert.Equal("Audio", pattern.ModuleName);
        Assert.Equal("IAudioService", pattern.ServiceInterface);
        Assert.Contains("PlaySound", pattern.ServiceMethods);
        Assert.Contains("SetVolume", pattern.ServiceMethods);
        Assert.Contains("PlaySound", pattern.BasicServiceMethods);
        Assert.Contains("SetVolume", pattern.BasicServiceMethods);
    }

[Fact]
    public void AnalyzeClass_DetectsServiceImplementation()
    {
        // Arrange
        var detector = new ServicePatternDetector();
        var sourceCode = @"
            namespace Rac.Audio;

            public interface IAudioService
            {
                void PlaySound(string path);
            }

            public class OpenALAudioService : IAudioService
            {
                public void PlaySound(string path) { }
                public void PlaySound3D(string path, float x, float y, float z) { }
            }";

        var syntaxTree = CSharpSyntaxTree.ParseText(sourceCode);
        var compilation = CSharpCompilation.Create("Test").AddSyntaxTrees(syntaxTree);
        var semanticModel = compilation.GetSemanticModel(syntaxTree);
        var context = new AnalysisContextWrapper(semanticModel);

        var classDecl = syntaxTree.GetRoot()
            .DescendantNodes()
            .OfType<ClassDeclarationSyntax>()
            .First();

        // Act
        detector.AnalyzeClass(context, classDecl);
        var patterns = detector.GetDetectedPatterns();

        // Assert
        Assert.Single(patterns);
        var pattern = patterns.First();
        Assert.Equal("Audio", pattern.ModuleName);
        Assert.Equal("OpenALAudioService", pattern.Implementation);
        Assert.Contains("PlaySound", pattern.ImplementationMethods);
        Assert.Contains("PlaySound3D", pattern.ImplementationMethods);
    }

[Fact]
    public void AnalyzeClass_DetectsNullService()
    {
        // Arrange
        var detector = new ServicePatternDetector();
        var sourceCode = @"
            namespace Rac.Audio;

            public interface IAudioService
            {
                void PlaySound(string path);
            }

            public class NullAudioService : IAudioService
            {
                public void PlaySound(string path) { }
            }";

        var syntaxTree = CSharpSyntaxTree.ParseText(sourceCode);
        var compilation = CSharpCompilation.Create("Test").AddSyntaxTrees(syntaxTree);
        var semanticModel = compilation.GetSemanticModel(syntaxTree);
        var context = new AnalysisContextWrapper(semanticModel);

        var classDecl = syntaxTree.GetRoot()
            .DescendantNodes()
            .OfType<ClassDeclarationSyntax>()
            .First();

        // Act
        detector.AnalyzeClass(context, classDecl);
        var patterns = detector.GetDetectedPatterns();

        // Assert
        Assert.Single(patterns);
        var pattern = patterns.First();
        Assert.Equal("Audio", pattern.ModuleName);
        Assert.Equal("NullAudioService", pattern.NullImplementation);
        Assert.Empty(pattern.ImplementationMethods); // Null services don't contribute implementation methods
    }

[Fact]
    public void MetricsCalculator_CalculatesCorrectCoverage()
    {
        // Arrange
        var calculator = new MetricsCalculator();
        var pattern = new ServicePattern
        {
            ModuleName = "Audio",
            ServiceInterface = "IAudioService",
            Implementation = "OpenALAudioService",
            ServiceMethods = { "PlaySound", "SetVolume" },
            BasicServiceMethods = { "PlaySound", "SetVolume" },
            ImplementationMethods = { "PlaySound", "SetVolume", "PlaySound3D" },
            FacadeMethods = { "PlaySound" }
        };

        // Act
        var metrics = calculator.CalculateMetrics(new[] { pattern });

        // Assert
        var module = metrics.Modules.First();
        Assert.Equal("Audio", module.Name);

        // Service coverage: 2 out of 3 implementation methods exposed = 67%
        Assert.Equal(67, Math.Round(module.ServiceCoverage));

        // Facade coverage: 1 out of 2 basic service methods exposed = 50%
        Assert.Equal(50, Math.Round(module.FacadeCoverage));
    }

