func NewMockJSONStorage() *MockJSONStorage {
	return &MockJSONStorage{
		ShouldFail: false,
		ResponseData: map[string]string{
			"profile_id":  "mock-profile-id",
			"profile_url": "https://mock.pprofio.com/profiles/mock-profile-id.pprof",
			"type":        "cpu",
		},
	}
}

func (m *MockJSONStorage) Upload(ctx context.Context, filePath string) (string, error) {
	if m.ShouldFail {
		return "", fmt.Errorf("mock upload failed")
	}

	// Determine profile type from filename
	profileType := "unknown"
	if contains(filePath, "cpu") {
		profileType = "cpu"
	} else if contains(filePath, "memory") || contains(filePath, "heap") {
		profileType = "memory"
	} else if contains(filePath, "goroutine") {
		profileType = "goroutine"
	} else if contains(filePath, "mutex") {
		profileType = "mutex"
	} else if contains(filePath, "block") {
		profileType = "block"
	}

	// Create response with correct profile type
	response := map[string]string{
		"profile_id":  "mock-profile-id",
		"profile_url": "https://mock.pprofio.com/profiles/mock-profile-id.pprof",
		"type":        profileType,
	}

	// Override with custom data if provided
	for k, v := range m.ResponseData {
		response[k] = v
	}
	response["type"] = profileType // Always use detected type

	jsonData, err := json.Marshal(response)
	if err != nil {
		return "", fmt.Errorf("failed to marshal mock response: %w", err)
	}

	return string(jsonData), nil
}

// Helper function since strings.Contains isn't available in all contexts
func contains(s, substr string) bool {
	return len(s) >= len(substr) && s[len(s)-len(substr):] == substr || 
		   (len(s) > len(substr) && findSubstring(s, substr))
}

func findSubstring(s, substr string) bool {
	for i := 0; i <= len(s)-len(substr); i++ {
		if s[i:i+len(substr)] == substr {
			return true
		}
	}
	return false
}

func NewMockFailingJSONStorage(errorMsg string) *MockFailingJSONStorage {
	return &MockFailingJSONStorage{
		ErrorMessage: errorMsg,
	}
}

func (m *MockFailingJSONStorage) Upload(ctx context.Context, filePath string) (string, error) {
	return "", fmt.Errorf(m.ErrorMessage)
}

func NewMockInvalidJSONStorage() *MockInvalidJSONStorage {
	return &MockInvalidJSONStorage{}
}

func (m *MockInvalidJSONStorage) Upload(ctx context.Context, filePath string) (string, error) {
	return "invalid json response", nil
}

func TestNew(t *testing.T) {
	t.Parallel()

	t.Run("ValidConfig", func(t *testing.T) {
		tempDir, err := os.MkdirTemp("", "pprofio-test")
		if err != nil {
			t.Fatalf("Failed to create temp directory: %v", err)
		}
		defer os.RemoveAll(tempDir)

		storage, err := NewFileStorage(tempDir)
		if err != nil {
			t.Fatalf("Failed to create storage: %v", err)
		}

		config := Config{
			APIKey:          "test-key",
			IngestURL:       "https://api.pprofio.com",
			SampleRate:      5 * time.Second,
			ProfileDuration: 1 * time.Second,
			Storage:         storage,
			ServiceName:     "test-service",
			Tags:            map[string]string{"env": "test"},
			EnableCPU:       true,
			EnableMemory:    true,
		}

		profiler, err := New(config)
		if err != nil {
			t.Fatalf("New() error = %v", err)
		}

		if profiler == nil {
			t.Fatal("New() returned nil profiler")
		}

		if profiler.config.ServiceName != config.ServiceName {
			t.Errorf("Expected service name %v, got %v", config.ServiceName, profiler.config.ServiceName)
		}
	})

	t.Run("InvalidConfig", func(t *testing.T) {
		config := Config{
			// Missing required fields
		}

		profiler, err := New(config)
		if err == nil {
			t.Error("New() with invalid config should return error")
		}

		if profiler != nil {
			t.Error("New() with invalid config should return nil profiler")
		}
	})

	t.Run("ConfigWithMissingStorageAndCredentials", func(t *testing.T) {
		config := Config{
			SampleRate:      5 * time.Second,
			ProfileDuration: 1 * time.Second,
			ServiceName:     "test-service",
			OutputToStdout:  false, // Explicitly set to false so Storage is required
			// Missing Storage, APIKey, and IngestURL
		}

		profiler, err := New(config)
		if err == nil {
			t.Error("New() with missing storage and credentials should return error")
		}

		if profiler != nil {
			t.Error("New() with missing storage and credentials should return nil profiler")
		}
	})
}

