		EnableMemory:    true,
	}

	profiler, err := New(config)
	if err != nil {
		t.Fatalf("New() error = %v", err)
	}

	t.Run("StopAfterStart", func(t *testing.T) {
		ctx := context.Background()

		// Start the profiler
		err := profiler.Start(ctx)
		if err != nil {
			t.Fatalf("Start() error = %v", err)
