def test_network_connectivity_e2e(self):
        """Test network connectivity to the UAT API."""
        config = Config.uat()
        try:
            response = requests.get(config.base_url, timeout=10)
            # We don't care about the response content, just that we can reach the server
            assert True  # If we get here, connectivity is working
        except requests.exceptions.ConnectionError:
            pytest.skip("Network connectivity issue - cannot reach UAT API")
        except requests.exceptions.Timeout:
            pytest.skip("Network timeout - UAT API is not responding")

def test_authentication_error_handling_e2e(self):
        """Test authentication error handling with invalid credentials."""
        # Create auth client with invalid credentials
        config = Config.uat()
        invalid_auth = AuthClient("invalid_user", "invalid_pass", config)

        # Attempt authentication and expect it to fail
        try:
            with pytest.raises(PermissionError, match="Unauthorized: Invalid credentials"):
                invalid_auth.authenticate()
        except requests.exceptions.ConnectionError:
            pytest.skip("Network connectivity issue - cannot reach UAT API")
        except Exception as e:
            # If we get any other exception, re-raise it as it might be what we're testing for
            if "Unauthorized" in str(e) or "401" in str(e):
                # This is expected - authentication failed as intended
                pass
            else:
                raise

def calculate_obv(self, data: pd.DataFrame) -> pd.DataFrame:
        """Calculate On-Balance Volume (OBV)."""
        data = data.copy()
        obv = []
        prev_obv = 0

        for i in range(len(data)):
            if i == 0:
                obv.append(data['volume'].iloc[i])
            else:
                if data['close'].iloc[i] > data['close'].iloc[i-1]:
                    obv.append(prev_obv + data['volume'].iloc[i])
                elif data['close'].iloc[i] < data['close'].iloc[i-1]:
                    obv.append(prev_obv - data['volume'].iloc[i])
                else:
                    obv.append(prev_obv)
            prev_obv = obv[-1]

        data['obv'] = obv
        return data

def calculate_stop_levels(self, data: pd.DataFrame, entry_price: float, entry_date: pd.Timestamp) -> Dict:
        """Calculate various stop loss levels."""
        current_data = data[data.index >= entry_date].copy()

        if len(current_data) == 0:
            return {}

        latest_data = current_data.iloc[-1]
        days_held = len(current_data) - 1

        # Fixed stop loss
        fixed_stop = entry_price * (1 - self.stop_loss_pct)

        # ATR trailing stop
        if 'atr' in latest_data and not pd.isna(latest_data['atr']):
            atr_stop = latest_data['close'] - (latest_data['atr'] * self.atr_multiplier)
        else:
            atr_stop = fixed_stop

        # Time stop
        time_stop_triggered = days_held >= self.time_stop_days

        return {
            'fixed_stop': fixed_stop,
            'atr_stop': atr_stop,
            'time_stop_triggered': time_stop_triggered,
            'days_held': days_held,
            'current_price': latest_data['close']
        }

def should_exit_position(self, data: pd.DataFrame, entry_price: float, entry_date: pd.Timestamp) -> Tuple[bool, str]:
        """Determine if position should be exited based on stop conditions."""
        stop_levels = self.calculate_stop_levels(data, entry_price, entry_date)

        if not stop_levels:
            return False, "No data available"

        current_price = stop_levels['current_price']

        # Check fixed stop loss
        if current_price <= stop_levels['fixed_stop']:
            return True, "Fixed stop loss triggered"

        # Check ATR trailing stop
        if current_price <= stop_levels['atr_stop']:
            return True, "ATR trailing stop triggered"

        # Check time stop
        if stop_levels['time_stop_triggered']:
            return True, "Time stop triggered"

        # Check technical sell signals
        latest_signals = self.generate_signals(data.tail(1))
        if not latest_signals.empty and latest_signals['sell_signal'].iloc[-1]:
            return True, "Technical sell signal"

        return False, "Hold position"

def example_color_detection():
    """Example of color-based object detection."""
    print("=== Color-based Detection Example ===")

    # Create test image if it doesn't exist
    if not os.path.exists("test_image.jpg"):
        os.system("python3 create_test_image.py")

    # Initialize detector
