def run_command(command, description):
    """Run a command and display its description."""
    print(f"\n{'='*60}")
    print(f"EXAMPLE: {description}")
    print(f"Command: {command}")
    print(f"{'='*60}")

    result = subprocess.run(command, shell=True, capture_output=True, text=True)

    if result.returncode == 0:
        print("SUCCESS")
        if result.stdout:
            # Show first few lines of output
            lines = result.stdout.split('\n')
            for line in lines[:10]:
                if line.strip():
                    print(f"  {line}")
            if len(lines) > 10:
                print(f"  ... ({len(lines) - 10} more lines)")
    else:
        print("ERROR:")
        print(result.stderr)

def filter_problems(
    dataset: dict[str, Any],
    problems: str | list[str] | None = None,
    custom_splits: dict[str, Any] | None = None,
    excluded_ids: list[str] | None = None,
) -> dict[str, Any]:
    excluded_ids = excluded_ids or []
    custom_splits = custom_splits or {}
    problems = "all" if problems is None else problems

    if not isinstance(problems, str):
        # Check that all problems are valid task names.
        for problem in problems:
            if problem not in dataset:
                raise ValueError(
                    f"Invalid problem id: '{problem}'.\nChoose from: {sorted(dataset)}"
                )

        # Make sure all problems are unique.
        if len(problems) != len(set(problems)):
            raise ValueError("Duplicate problem IDs found in the list.")

        return problems  # Assuming a list of problem IDs.

    if problems == "all":
        return [k for k in dataset if k not in excluded_ids]
    elif problems in dataset:
        return [problems]  # Single task
    elif problems in custom_splits:
        return custom_splits[problems]
    else:
        raise ValueError(
            f"Invalid split or problem id: '{problems}'.\nChoose from: {sorted(dataset) + ['all'] + sorted(custom_splits)}"
        )

// Groups sets a GROUPS frame for the window
func (w *WindowSpec) Groups(frame *WindowFrame) *WindowSpec {
	frame.frameType = FrameTypeGroups
	w.frame = frame
	return w
}

// PercentRank creates a PERCENT_RANK() window function
func PercentRank() *WindowFunctionExpr {
	return &WindowFunctionExpr{
		funcName: "PERCENT_RANK",
		args:     nil,
	}
}

// CumeDist creates a CUME_DIST() window function
func CumeDist() *WindowFunctionExpr {
	return &WindowFunctionExpr{
		funcName: "CUME_DIST",
		args:     nil,
	}
}

// NthValue creates a NTH_VALUE() window function
func NthValue(expr Expr, n int) *WindowFunctionExpr {
	return &WindowFunctionExpr{
		funcName: "NTH_VALUE",
		args:     []Expr{expr, &LiteralExpr{value: n}},
	}
}

// Ntile creates a NTILE() window function
func Ntile(buckets int) *WindowFunctionExpr {
	return &WindowFunctionExpr{
		funcName: "NTILE",
		args:     []Expr{&LiteralExpr{value: buckets}},
	}
}

// evaluatePercentRank implements PERCENT_RANK() window function
func (e *Evaluator) evaluatePercentRank(
	_ *WindowFunctionExpr,
	window *WindowSpec,
	columns map[string]arrow.Array,
	dataLength int,
) (arrow.Array, error) {
	mem := e.mem

	// Create result builder
	builder := array.NewFloat64Builder(mem)
	defer builder.Release()

	// Handle partitioning
	if len(window.partitionBy) > 0 {
		// Process each partition separately
		partitions := e.buildPartitions(window.partitionBy, columns, dataLength)

		for _, partition := range partitions {
			ranks := e.calculateRanksForPartition(partition, window, columns)

			// Convert ranks to percent ranks
			partitionSize := len(partition)
			for _, rank := range ranks {
				var percentRank float64
				if partitionSize <= 1 {
					percentRank = 0.0
				} else {
					percentRank = float64(rank-1) / float64(partitionSize-1)
				}
				builder.Append(percentRank)
			}
		}
	} else {
		// No partitioning - calculate for entire dataset
		ranks := e.calculateRanks(window, columns, dataLength)

		for _, rank := range ranks {
			var percentRank float64
			if dataLength <= 1 {
				percentRank = 0.0
			} else {
				percentRank = float64(rank-1) / float64(dataLength-1)
			}
			builder.Append(percentRank)
		}
	}

	return builder.NewArray(), nil
}

// evaluateCumeDist implements CUME_DIST() window function
func (e *Evaluator) evaluateCumeDist(
	_ *WindowFunctionExpr,
	window *WindowSpec,
	columns map[string]arrow.Array,
	dataLength int,
) (arrow.Array, error) {
	mem := e.mem

	// Create result builder
	builder := array.NewFloat64Builder(mem)
	defer builder.Release()

	// Handle partitioning
	if len(window.partitionBy) > 0 {
		// Process each partition separately
		partitions := e.buildPartitions(window.partitionBy, columns, dataLength)

		for _, partition := range partitions {
			cumeDist := e.calculateCumulativeDistribution(partition, window, columns)

			for _, dist := range cumeDist {
				builder.Append(dist)
			}
		}
	} else {
		// No partitioning - calculate for entire dataset
		fullDataset := make([]int, dataLength)
		for i := 0; i < dataLength; i++ {
			fullDataset[i] = i
		}
		cumeDist := e.calculateCumulativeDistribution(fullDataset, window, columns)

		for _, dist := range cumeDist {
			builder.Append(dist)
		}
	}

	return builder.NewArray(), nil
}

// evaluateNthValue implements NTH_VALUE() window function
func (e *Evaluator) evaluateNthValue(
	expr *WindowFunctionExpr,
	_ *WindowSpec,
	columns map[string]arrow.Array,
	dataLength int,
) (arrow.Array, error) {
	if len(expr.args) < nthValueMinArgs {
		return nil, fmt.Errorf("NTH_VALUE requires two arguments")
	}

	// Get the N value (which position to get)
	nLit, ok := expr.args[1].(*LiteralExpr)
	if !ok {
		return nil, fmt.Errorf("NTH_VALUE second argument must be a literal")
	}
	n, ok := nLit.value.(int)
	if !ok || n <= 0 {
		return nil, fmt.Errorf("NTH_VALUE second argument must be a positive integer")
	}

	// Get the column to evaluate
	colExpr, ok := expr.args[0].(*ColumnExpr)
	if !ok {
		return nil, fmt.Errorf("NTH_VALUE first argument must be a column")
	}

	column, exists := columns[colExpr.name]
	if !exists {
		return nil, fmt.Errorf("column %s not found", colExpr.name)
	}

	// Create result array based on column type
	switch arr := column.(type) {
	case *array.Int64:
		builder := array.NewInt64Builder(e.mem)
		defer builder.Release()

		// Simplified logic: Get the nth value for each frame
		for i := 0; i < dataLength; i++ {
			if n <= arr.Len() && !arr.IsNull(n-1) {
				builder.Append(arr.Value(n - 1))
			} else {
				builder.AppendNull()
			}
		}
		return builder.NewArray(), nil

	case *array.String:
		builder := array.NewStringBuilder(e.mem)
		defer builder.Release()

		for i := 0; i < dataLength; i++ {
			if n <= arr.Len() && !arr.IsNull(n-1) {
				builder.Append(arr.Value(n - 1))
			} else {
				builder.AppendNull()
			}
		}
		return builder.NewArray(), nil

	default:
		return nil, fmt.Errorf("unsupported column type for NTH_VALUE: %T", column)
	}
}

// evaluateNtile implements NTILE() window function
func (e *Evaluator) evaluateNtile(
	expr *WindowFunctionExpr,
	window *WindowSpec,
	columns map[string]arrow.Array,
	dataLength int,
) (arrow.Array, error) {
	if len(expr.args) == 0 {
		return nil, fmt.Errorf("NTILE requires one argument")
	}

	// Get the number of buckets
	bucketsLit, ok := expr.args[0].(*LiteralExpr)
	if !ok {
		return nil, fmt.Errorf("NTILE argument must be a literal")
	}
	buckets, ok := bucketsLit.value.(int)
	if !ok {
		return nil, fmt.Errorf("NTILE argument must be an integer")
	}

	if buckets <= 0 {
		return nil, fmt.Errorf("NTILE buckets must be positive")
	}

	mem := e.mem
	builder := array.NewInt64Builder(mem)
	defer builder.Release()

	// Handle partitioning
	if len(window.partitionBy) > 0 {
		// Process each partition separately
		partitions := e.buildPartitions(window.partitionBy, columns, dataLength)

		for _, partition := range partitions {
			ntiles := e.calculateNtiles(len(partition), buckets)
			for _, ntile := range ntiles {
				builder.Append(int64(ntile))
			}
		}
	} else {
		// No partitioning - calculate for entire dataset
		ntiles := e.calculateNtiles(dataLength, buckets)
		for _, ntile := range ntiles {
			builder.Append(int64(ntile))
		}
	}

	return builder.NewArray(), nil
}

// Helper methods for window function calculations

// calculateRanks calculates ranks for ordering
func (e *Evaluator) calculateRanks(_ *WindowSpec, _ map[string]arrow.Array, dataLength int) []int {
	// Simplified rank calculation - in reality this would need proper ordering
	ranks := make([]int, dataLength)
	for i := 0; i < dataLength; i++ {
		ranks[i] = i + 1
	}
	return ranks
}

// calculateRanksForPartition calculates ranks within a partition
func (e *Evaluator) calculateRanksForPartition(
	partition []int,
	_ *WindowSpec,
	_ map[string]arrow.Array,
) []int {
	ranks := make([]int, len(partition))
	for i := 0; i < len(partition); i++ {
		ranks[i] = i + 1
	}
	return ranks
}

// calculateCumulativeDistribution calculates cumulative distribution
func (e *Evaluator) calculateCumulativeDistribution(
	partition []int,
	_ *WindowSpec,
	_ map[string]arrow.Array,
) []float64 {
	size := len(partition)
	cumeDist := make([]float64, size)
	for i := 0; i < size; i++ {
		cumeDist[i] = float64(i+1) / float64(size)
	}
	return cumeDist
}

// calculateNtiles distributes rows into buckets
func (e *Evaluator) calculateNtiles(rowCount, buckets int) []int {
	ntiles := make([]int, rowCount)

	// Calculate base bucket size and remainder
	baseSize := rowCount / buckets
	remainder := rowCount % buckets

	// Distribute rows into buckets
	currentRow := 0
	for bucket := 1; bucket <= buckets; bucket++ {
		bucketSize := baseSize
		if remainder > 0 {
			bucketSize++
			remainder--
		}

		for i := 0; i < bucketSize && currentRow < rowCount; i++ {
			ntiles[currentRow] = bucket
			currentRow++
		}
	}

	return ntiles
}

// buildPartitions creates partitions based on partition columns
func (e *Evaluator) buildPartitions(
	_ []string,
	_ map[string]arrow.Array,
	dataLength int,
) [][]int {
	// Simplified partitioning - in reality this would need proper grouping logic
	// For now, return a single partition with all rows
	partition := make([]int, dataLength)
	for i := 0; i < dataLength; i++ {
		partition[i] = i
	}
	return [][]int{partition}
}

// TestPhase4WindowFunctionCreation tests that the new window functions can be created
func TestPhase4WindowFunctionCreation(t *testing.T) {
	// Test PERCENT_RANK function creation
	percentRank := PercentRank()
	assert.Equal(t, "PERCENT_RANK", percentRank.funcName)
	assert.Empty(t, percentRank.args)

	// Test CUME_DIST function creation
	cumeDist := CumeDist()
	assert.Equal(t, "CUME_DIST", cumeDist.funcName)
	assert.Empty(t, cumeDist.args)

	// Test NTH_VALUE function creation
	nthValue := NthValue(Col("test"), 2)
	assert.Equal(t, "NTH_VALUE", nthValue.funcName)
	assert.Len(t, nthValue.args, 2)

	// Test NTILE function creation
	ntile := Ntile(4)
	assert.Equal(t, "NTILE", ntile.funcName)
	assert.Len(t, ntile.args, 1)
}

// TestGroupsFrameType tests GROUPS frame type
func TestGroupsFrameType(t *testing.T) {
	// Create window with GROUPS frame
	window := NewWindow().
		OrderBy("value", true).
		Groups(Between(Preceding(1), CurrentRow()))

	// Test frame type is set correctly
	assert.Equal(t, FrameTypeGroups, window.frame.frameType)
	assert.Equal(t, BoundaryPreceding, window.frame.start.boundaryType)
	assert.Equal(t, 1, window.frame.start.offset)
	assert.Equal(t, BoundaryCurrentRow, window.frame.end.boundaryType)
}

// TestWindowExpressionCreation tests window expression creation with new functions
func TestWindowExpressionCreation(t *testing.T) {
	// Test PERCENT_RANK with window
	percentRankExpr := PercentRank().Over(
		NewWindow().
			PartitionBy("department").
			OrderBy("salary", true),
	)

	assert.NotNil(t, percentRankExpr)
	assert.Equal(t, "PERCENT_RANK", percentRankExpr.function.(*WindowFunctionExpr).funcName)
	assert.Len(t, percentRankExpr.window.partitionBy, 1)
	assert.Equal(t, "department", percentRankExpr.window.partitionBy[0])

	// Test NTILE with window
	ntileExpr := Ntile(4).Over(
		NewWindow().OrderBy("value", true),
	)

	assert.NotNil(t, ntileExpr)
	assert.Equal(t, "NTILE", ntileExpr.function.(*WindowFunctionExpr).funcName)
	assert.Len(t, ntileExpr.window.orderBy, 1)
	assert.Equal(t, "value", ntileExpr.window.orderBy[0].column)
	assert.True(t, ntileExpr.window.orderBy[0].ascending)
}

def __init__(self):
        self.error_count = 0
        self.max_retries = 3
        self.retry_delay = 1.0
        self.error_callbacks: Dict[str, Callable] = {}

def retry_on_failure(self, max_retries: Optional[int] = None, delay: Optional[float] = None):
        """
        装饰器：在失败时重试

        Args:
            max_retries: 最大重试次数
            delay: 重试间隔（秒）
        """
        max_retries = max_retries if max_retries is not None else self.max_retries
        delay = delay if delay is not None else self.retry_delay

        def decorator(func: Callable) -> Callable:
            @wraps(func)
            def wrapper(*args, **kwargs):
                last_exception = None

                for attempt in range(max_retries + 1):
                    try:
                        return func(*args, **kwargs)
                    except Exception as e:
                        last_exception = e
                        if attempt < max_retries:
                            logger.warning(f"函数 {func.__name__} 第 {attempt + 1} 次尝试失败: {e}")
                            logger.info(f"等待 {delay} 秒后重试...")
                            time.sleep(delay)
                        else:
                            logger.error(f"函数 {func.__name__} 在 {max_retries + 1} 次尝试后仍然失败")

                # 所有重试都失败了
                if last_exception is not None:
                    raise last_exception
                else:
                    raise RuntimeError("未知错误")

            return wrapper
        return decorator

def __init__(self):
        self.resources = []
        self.cleanup_callbacks = []

def __init__(self, initial_value: int = 0):
        self._value = initial_value
        self._lock = threading.Lock()

def safe_thread(func: Callable) -> Callable:
    """
    装饰器：确保线程安全执行

    Args:
        func: 要执行的函数
    """
    @wraps(func)
    def wrapper(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except Exception as e:
            error_handler.handle_exception(e, f"线程执行 {func.__name__}")
            return None
    return wrapper

def wrapper(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except Exception as e:
            error_handler.handle_exception(e, f"线程执行 {func.__name__}")
            return None

def test_function(should_fail: bool = False):
        if should_fail:
            raise ValueError("测试错误")
        return "成功"

def __init__(self, config_file: str = "config.json"):
        self.config_file = config_file
        self.default_config = {
            "model_path": "yolo/yoloaimonnx/onnxmd/10w320v5.onnx",
            "conf_threshold": 0.4,
            "nms_threshold": 0.4,
            "input_size": [640, 640],
            "screen_crop_size": [1920, 1080],
            "providers": ["ROCMExecutionProvider"],
            "names": {0: 't_body', 1: 't_head', 2: 'ct_body', 3: 'ct_head'}
        }
        self.config = self.load_config()

def initialize_model(self) -> None:
        """初始化ONNX模型"""
        try:
            model_path = self.config.config["model_path"]
            if not os.path.exists(model_path):
                raise FileNotFoundError(f"模型文件不存在: {model_path}")

            providers = self.config.config["providers"]
            self.ort_session = ort.InferenceSession(model_path, providers=providers)
            logger.info(f"模型加载成功: {model_path}")
        except Exception as e:
            logger.error(f"模型初始化失败: {e}")
            raise

def on_press(self, key) -> None:
        """键盘按键处理"""
        try:
            if hasattr(key, 'char'):
                if key.char == 'e':
                    # 移动鼠标到最近的头部目标
                    if hasattr(self, 'last_boxes'):
                        self.aim_controller.aim_head(self.last_boxes, self.last_scores, self.last_class_ids, self.t_or_ct)
                elif key.char == 'q':
                    # 退出程序
                    self.running = False
                    logger.info('程序退出')
                elif key.char == 'o':
                    # 切换 t 和 ct 的状态
                    self.t_or_ct = not self.t_or_ct
                    logger.info(f'当前标签为: {"t" if self.t_or_ct else "ct"}')
                elif key.char == 'i':
                    # 切换显示图像状态
                    self.show_image = not self.show_image
                    logger.info(f'显示图像: {self.show_image}')
        except Exception as e:
            logger.error(f"键盘事件处理失败: {e}")

