generateSessionId(sessionName) {
    const date = new Date().toISOString().split('T')[0];
    const slug = sessionName.toLowerCase().replace(/[^a-z0-9]/g, '-').replace(/-+/g, '-');
    return `${date}-${slug}`;
  }

generateId() {
    return createHash('md5').update(Date.now().toString() + Math.random().toString()).digest('hex').substring(0, 8);
  }

function formatOutput(data, format = 'text') {
  switch (format) {
    case 'json':
      return JSON.stringify(data, null, 2);
    case 'yaml':
      return yaml.dump(data);
    case 'text':
    default:
      return data;
  }
}

function formatTimestamp(date) {
  if (!date) return 'Never';
  const d = new Date(date);
  return d.toLocaleDateString() + ' ' + d.toLocaleTimeString();
}

function formatDuration(startTime, endTime) {
  if (!startTime) return 'Unknown duration';
  const start = new Date(startTime);
  const end = endTime ? new Date(endTime) : new Date();
  const duration = end - start;
  const hours = Math.floor(duration / 3600000);
  const minutes = Math.floor((duration % 3600000) / 60000);

  if (hours > 0) {
    return `${hours}h ${minutes}m`;
  }
  return `${minutes}m`;
}

function formatMemorySize(bytes) {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

function formatList(items, emptyMessage = 'No items found') {
  if (!items || items.length === 0) {
    return emptyMessage;
  }
  return items;
}

function truncateText(text, maxLength = 80) {
  if (!text || text.length <= maxLength) return text;
  return text.substring(0, maxLength - 3) + '...';
}

/**
 * Input sanitization utilities for Claude Memory
 */

function sanitizeInput(input, maxLength = 1000) {
  if (typeof input !== 'string') return '';
  return input
    .replace(/[<>]/g, '') // Remove potential HTML/script tags
    .replace(/\.\./g, '') // Remove path traversal attempts
    .slice(0, maxLength)
    .trim();
}

function sanitizeDescription(description, maxLength = 500) {
  if (!description || typeof description !== 'string') {
    throw new Error('Description is required and must be a string');
  }

  const sanitized = sanitizeInput(description, maxLength);
  if (sanitized.length === 0) {
    throw new Error('Description cannot be empty after sanitization');
  }

  return sanitized;
}

function sanitizeMultiline(text, maxLength = 5000) {
  if (!text || typeof text !== 'string') return '';
  return text
    .replace(/[<>]/g, '') // Remove potential HTML/script tags
    .slice(0, maxLength)
    .trim();
}

function validatePath(inputPath) {
  if (!inputPath) return process.cwd();

  // Resolve and normalize the path
  const resolvedPath = path.resolve(inputPath);

  // Ensure it doesn't contain path traversal
  if (resolvedPath.includes('..')) {
    throw new Error('Invalid path: path traversal not allowed');
  }

  return resolvedPath;
}

function validatePriority(priority) {
  const validPriorities = ['critical', 'high', 'medium', 'low'];
  if (!validPriorities.includes(priority)) {
    throw new Error(`Invalid priority. Must be one of: ${validPriorities.join(', ')}`);
  }
  return priority;
}

function validateStatus(status) {
  const validStatuses = ['open', 'in_progress', 'completed'];
  if (!validStatuses.includes(status)) {
    throw new Error(`Invalid status. Must be one of: ${validStatuses.join(', ')}`);
  }
  return status;
}

function validateOutputFormat(format) {
  const validFormats = ['text', 'json', 'yaml'];
  if (!validFormats.includes(format)) {
    throw new Error(`Invalid output format. Must be one of: ${validFormats.join(', ')}`);
  }
  return format;
}

# Windows path handling
def get_windows_path(path):
    """Convert path to Windows-compatible format"""
    if platform.system().lower() == 'windows':
        return path.replace('/', '\\')
    return path

