def check_dependencies():
    """Check if required packages are installed"""
    required_packages = ['flask', 'pandas', 'requests', 'flask_cors']
    missing_packages = []

    for package in required_packages:
        try:
            __import__(package)
        except ImportError:
            missing_packages.append(package)

    if missing_packages:
        print(f"❌ Missing required packages: {', '.join(missing_packages)}")
        print("💡 Please run setup_windows.bat to install dependencies.")
        return False

    return True

/**
 * Basic swarm implementation for fallback when advanced features are not available
 */
async function basicSwarmNew(args, flags) {
  try {
    // Input validation using helper
    const validationErrors = validateSwarmInput(args, flags);
    if (validationErrors.length > 0) {
      console.error('❌ Validation errors:', validationErrors.join(', '));
      return { 
        success: false, 
        error: 'Validation failed', 
        message: validationErrors.join(', '),
        validationErrors 
      };
    }

    // Ensure flags object exists
    if (!flags || typeof flags !== 'object') {
      console.warn('⚠️  No flags provided, using defaults');
      flags = {};
    }

    // Get the objective from args
    const objective = (args || []).join(' ').trim();

    if (!objective) {
      console.error("❌ Usage: swarm <objective>");
      showSwarmHelp();
      return;
    }

    console.log('🚀 Starting basic swarm execution...');
    console.log(`📋 Objective: ${objective}`);

    // Try to use the swarm executor
    try {
      const { executeSwarm } = await import('./swarm-executor.js');
      if (typeof executeSwarm !== 'function') {
        throw new Error('executeSwarm is not a function');
      }
      const result = await executeSwarm(objective, flags);
      console.log('✅ Swarm execution completed successfully');
      return result;
    } catch (executorError) {
      console.log('⚠️  Swarm executor not available, using basic implementation');
      console.log(`Debug: ${executorError.message}`);

      // Fallback to basic console output
      console.log('\n🐝 Basic Swarm Mode Active');
      console.log('================================================');
      console.log(`Objective: ${objective}`);
      console.log(`Strategy: ${flags.strategy || 'auto'}`);
      console.log(`Max Agents: ${flags.maxAgents || 3}`);
      console.log(`Mode: ${flags.mode || 'centralized'}`);

      if (flags.executor) {
        console.log('\n📝 Task Breakdown:');
        console.log('1. Analyze objective and requirements');
        console.log('2. Create execution plan');
        console.log('3. Execute tasks step by step');
        console.log('4. Validate results');

        console.log('\n💡 Recommendations:');
        console.log('- Install full Claude Flow package for advanced features');
        console.log('- Use Claude Code integration for better coordination');
        console.log('- Consider upgrading to TypeScript version');

        return {
          success: true,
          objective,
          mode: 'basic',
          message: 'Basic swarm mode completed. Upgrade for advanced features.'
        };
      }
    }
  } catch (error) {
    console.error('❌ Error in basic swarm execution:', error.message);
    console.error('Stack trace:', error.stack);

    // Return structured error response
    return {
      success: false,
      error: error.message,
      objective: (args || []).join(' '),
      timestamp: new Date().toISOString(),
      stack: error.stack
    };
  }
}

// Input validation helper
function validateSwarmInput(args, flags) {
  const errors = [];

  if (!args || !Array.isArray(args)) {
    errors.push('Arguments must be an array');
  }

  if (args && args.length === 0) {
    errors.push('Objective cannot be empty');
  }

  if (flags && typeof flags !== 'object') {
    errors.push('Flags must be an object');
  }

  if (flags && flags.maxAgents) {
    const maxAgents = parseInt(flags.maxAgents);
    if (isNaN(maxAgents) || maxAgents < SWARM_CONSTANTS.MIN_AGENTS || maxAgents > SWARM_CONSTANTS.MAX_AGENTS) {
      errors.push(`Max agents must be between ${SWARM_CONSTANTS.MIN_AGENTS} and ${SWARM_CONSTANTS.MAX_AGENTS}`);
    }
  }

  return errors;
}

def parse_product_features(features_str: str) -> Dict[str, str]:
    """
    Parse product features string into a dictionary.

    Args:
        features_str: String containing product features

    Returns:
        Dictionary of feature name to feature value
    """
    if not isinstance(features_str, str) or not features_str:
        return {}

    features = {}
    for feature in features_str.split('|'):
        feature = feature.strip()
        if not feature or ':' not in feature:
            continue

        parts = feature.split(':', 1)

        raw_key = parts[0].strip().lower().replace(' ', '_')
        key = segment_key(raw_key)

        value = parts[1].strip() if len(parts) > 1 else ""

        if value.lower() in JUNK_VALUES:
            continue

        if is_numeric_value(value):
            value = NUMERIC_PLACEHOLDER

        features[key] = value

    return features

def standardize_features(features: Dict[str, str], key_clusters: Dict[str, List[str]]) -> Dict[str, str]:
    """
    Standardize features using clustered keys.

    Args:
        features: Dictionary of feature name to feature value
        key_clusters: Dictionary mapping representative keys to lists of similar keys

    Returns:
        Dictionary of standardized features
    """
    standardized = {}

    superkeys = create_superkeys(features)
    if superkeys:
        for superkey, value in superkeys.items():
            standardized[superkey] = value

    for rep_key, similar_keys in key_clusters.items():
        for key in similar_keys:
            if key in features:
                if rep_key not in standardized:
                    standardized[rep_key] = features[key]
                    break

    return standardized

def create_superkeys(features: Dict[str, str]) -> Dict[str, str]:
    """
    Create standardized superkeys from product features.

    Args:
        features: Dictionary of product features

    Returns:
        Dictionary of superkeys
    """
    superkeys = {}

    for superkey, feature_keys in SUPERKEY_CONFIG.items():
        values = []
        for key in feature_keys:
            if key in features and features[key] and features[key].lower() not in JUNK_VALUES:
                values.append(features[key])

        if values:
            superkeys[superkey] = values[0]  # Take the first non-empty value

    return superkeys

def extract_attributes(df: pd.DataFrame) -> Dict[str, List[str]]:
    """
    Extract unique attributes from product dataset.

    Args:
        df: Product DataFrame

    Returns:
        Dictionary of attribute categories to attribute values
    """
    attributes = {
        "color": set(),
        "material": set(),
        "style": set(),
        "category": set(),
        "shape": set(),
        "pattern": set(),
        "finish": set()
    }

    for _, row in df.iterrows():
        features = row['standardized_features_map']
        if not isinstance(features, dict):
            try:
                if isinstance(features, str):
                    features = json.loads(features.replace("'", "\""))
                else:
                    continue
            except:
                continue

        if 'Color' in features:
            attributes['color'].add(features['Color'].lower())
        if 'Material' in features:
            attributes['material'].add(features['Material'].lower())
        if 'Style' in features:
            attributes['style'].add(features['Style'].lower())
        if 'Shape' in features:
            attributes['shape'].add(features['Shape'].lower())
        if 'Pattern' in features:
            attributes['pattern'].add(features['Pattern'].lower())
        if 'Finish' in features:
            attributes['finish'].add(features['Finish'].lower())

        if pd.notna(row['product_class']):
            attributes['category'].add(row['product_class'].lower())

    return {k: list(v) for k, v in attributes.items()}

def save_embeddings(self, file_path: str):
        """
        Save document embeddings to file.

        Args:
            file_path: Path to save embeddings
        """
        data = {
            "doc_ids": self.doc_ids,
            "embeddings": {doc_id: embedding.tolist() for doc_id, embedding in self.doc_embeddings.items()}
        }

        with open(file_path, "w") as f:
            json.dump(data, f)

        logger.info(f"Saved embeddings to {file_path}")

def calculate_mrr(
    ranking: List[str],
    relevance: Dict[str, float]
) -> float:
    """
    Calculate Mean Reciprocal Rank.

    Args:
        ranking: List of item IDs
        relevance: Dictionary of item ID to relevance score

    Returns:
        MRR score
    """
    for i, item_id in enumerate(ranking):
        if relevance.get(item_id, 0) > 0:
            return 1 / (i + 1)

    return 0

def evaluate_queries(
    queries: List[Dict[str, Any]],
    k_values: List[int] = [3, 5, 10]
) -> Dict[str, Any]:
    """
    Evaluate queries using various metrics.

    Args:
        queries: List of query dictionaries
        k_values: List of k values for metrics

    Returns:
        Dictionary of evaluation results
    """
    results = {
        "overall": {
            f"ndcg@{k}": 0 for k in k_values
        },
        "by_query_type": {},
        "by_space_type": {},
        "confidence": {
            "avg": 0,
            "by_query_type": {}
        }
    }

    results["overall"]["mrr"] = 0
    for k in k_values:
        results["overall"][f"precision@{k}"] = 0
        results["overall"][f"recall@{k}"] = 0

    valid_queries = 0
    total_confidence = 0

    query_types = set()
    query_type_counts = {}
    query_type_confidence = {}

    for query in queries:
        if not query.get("gold_standard_ranking"):
            continue

        query_type = query.get("query_type", "unknown")
        query_types.add(query_type)

        query_type_counts[query_type] = query_type_counts.get(query_type, 0) + 1

        confidence = query.get("relevance_confidence_avg", 0)
        total_confidence += confidence

        if query_type not in query_type_confidence:
            query_type_confidence[query_type] = []
        query_type_confidence[query_type].append(confidence)

        relevance = {
            c["product_id"]: c["similarity_score"]
            for c in query.get("stage1_candidates", [])
        }

        ranking = query["gold_standard_ranking"]

        for k in k_values:
            ndcg = calculate_ndcg(ranking, relevance, k)
            results["overall"][f"ndcg@{k}"] += ndcg

        mrr = calculate_mrr(ranking, relevance)
        results["overall"]["mrr"] += mrr

        for k in k_values:
            precision, recall = calculate_precision_recall(ranking, relevance, k)
            results["overall"][f"precision@{k}"] += precision
            results["overall"][f"recall@{k}"] += recall

        valid_queries += 1

    if valid_queries > 0:
        for metric in results["overall"]:
            results["overall"][metric] /= valid_queries

        results["confidence"]["avg"] = total_confidence / valid_queries

    for query_type in query_types:
        results["by_query_type"][query_type] = {
            f"ndcg@{k}": 0 for k in k_values
        }
        results["by_query_type"][query_type]["mrr"] = 0
        results["by_query_type"][query_type]["count"] = query_type_counts[query_type]

        for k in k_values:
            results["by_query_type"][query_type][f"precision@{k}"] = 0
            results["by_query_type"][query_type][f"recall@{k}"] = 0

    for query_type, confidences in query_type_confidence.items():
        results["confidence"]["by_query_type"][query_type] = sum(confidences) / len(confidences)

    return results

def test_word_segmentation():
    """Test word segmentation."""
    test_keys = [
        "producttype", "capacityquarts", "primarycolor", "mainmaterial"
    ]
    expected = [
        "product_type", "capacity_quarts", "primary_color", "main_material"
    ]

    for key, expected_result in zip(test_keys, expected):
        result = segment_key(key)
        logger.info(f"Segmenting '{key}' -> '{result}' (Expected: '{expected_result}')")
        assert result == expected_result

def test_numeric_value_detection():
    """Test numeric value detection."""
    test_values = [
        "5", "10.5", "3.7 lbs", "5 feet", "5feet", "not a number", "red"
    ]
    expected = [
        True, True, True, True, True, False, False
    ]

    for value, expected_result in zip(test_values, expected):
        result = is_numeric_value(value)
        logger.info(f"Is '{value}' numeric? {result} (Expected: {expected_result})")
        assert result == expected_result

public PomodoroService(PomodoroSessionRepository sessionRepository,
                          PomodoroTaskRepository taskRepository,
                          PomodoroConfigRepository configRepository,
                          TodoRepository todoRepository,
                          UserContextService userContextService) {
        this.sessionRepository = sessionRepository;
        this.taskRepository = taskRepository;
        this.configRepository = configRepository;
        this.todoRepository = todoRepository;
        this.userContextService = userContextService;
    }

    /**
     * Creates a new Pomodoro session for the current user.
     */
public PomodoroSessionResponse createSession(CreatePomodoroSessionRequest request) {
        UUID userId = userContextService.getCurrentUserId();

        // Check if user already has an active session
        sessionRepository.findActiveSessionByUserId(userId).ifPresent(session -> {
            throw new IllegalStateException("User already has an active Pomodoro session");
        });

        // Create new session
        PomodoroSession session = new PomodoroSession(userId, request.getWorkDuration(), request.getBreakDuration());
        session.setStartTime(LocalDateTime.now());
        session = sessionRepository.save(session);

        // Add tasks if provided
        if (request.getTasks() != null && !request.getTasks().isEmpty()) {
            List<PomodoroTask> tasks = new ArrayList<>();
            for (int i = 0; i < request.getTasks().size(); i++) {
                CreatePomodoroTaskRequest taskRequest = request.getTasks().get(i);
                PomodoroTask task = new PomodoroTask(session.getId(), taskRequest.getDescription(), i);
                task.setTodoId(taskRequest.getTodoId());
                tasks.add(taskRepository.save(task));
            }
            session.setTasks(tasks);
        }

        return toSessionResponse(session);
    }

    /**
     * Updates an existing Pomodoro session.
     */
public PomodoroSessionResponse updateSession(UUID sessionId, UpdatePomodoroSessionRequest request) {
        UUID userId = userContextService.getCurrentUserId();

        PomodoroSession session = sessionRepository.findById(sessionId)
                .orElseThrow(() -> new IllegalArgumentException("Session not found"));

        if (!session.getUserId().equals(userId)) {
            throw new IllegalArgumentException("Session does not belong to current user");
        }

        switch (request.getAction()) {
            case START:
                if (session.getStatus() != PomodoroSession.SessionStatus.ACTIVE) {
                    throw new IllegalStateException("Session is not active");
                }
                session.setStartTime(LocalDateTime.now());
                break;

            case PAUSE:
                if (session.getStatus() != PomodoroSession.SessionStatus.ACTIVE) {
                    throw new IllegalStateException("Session is not active");
                }
                session.setStatus(PomodoroSession.SessionStatus.PAUSED);
                break;

            case RESUME:
                if (session.getStatus() != PomodoroSession.SessionStatus.PAUSED) {
                    throw new IllegalStateException("Session is not paused");
                }
                session.setStatus(PomodoroSession.SessionStatus.ACTIVE);
                break;

            case COMPLETE:
                session.setStatus(PomodoroSession.SessionStatus.COMPLETED);
                session.setEndTime(LocalDateTime.now());
                if (session.getSessionType() == SessionType.WORK) {
                    session.setCompletedCycles(session.getCompletedCycles() + 1);
                }
                break;

            case CANCEL:
                session.setStatus(PomodoroSession.SessionStatus.CANCELLED);
                session.setEndTime(LocalDateTime.now());
                break;

            case SWITCH_TYPE:
                if (request.getSessionType() != null) {
                    session.setSessionType(request.getSessionType());
                }
                break;
        }

        session = sessionRepository.save(session);
        return toSessionResponse(session);
    }

    /**
     * Gets the current active session for the user.
     */
public PomodoroSessionResponse getActiveSession() {
        UUID userId = userContextService.getCurrentUserId();

        return sessionRepository.findActiveSessionByUserId(userId)
                .map(this::toSessionResponse)
                .orElseThrow(() -> new ActiveSessionNotFoundException());
    }

    /**
     * Gets session history for the current user.
     */
@Transactional(readOnly = true)
    public Page<PomodoroSessionResponse> getSessionHistory(Pageable pageable) {
        UUID userId = userContextService.getCurrentUserId();

        return sessionRepository.findByUserId(userId, pageable)
                .map(this::toSessionResponseWithoutTasks);
    }

    /**
     * Updates a task within a session.
     */
public PomodoroTaskResponse updateTask(UUID taskId, UpdatePomodoroTaskRequest request) {
        UUID userId = userContextService.getCurrentUserId();

        PomodoroTask task = taskRepository.findById(taskId)
                .orElseThrow(() -> new IllegalArgumentException("Task not found"));

        // Verify task belongs to user's session
        PomodoroSession session = sessionRepository.findById(task.getSessionId())
                .orElseThrow(() -> new IllegalArgumentException("Session not found"));

        if (!session.getUserId().equals(userId)) {
            throw new IllegalArgumentException("Task does not belong to current user");
        }

        task.setCompleted(request.getCompleted());

        // If task is linked to a Todo and is being marked as completed, update the Todo
        if (request.getCompleted() && task.getTodoId() != null) {
            // Note: Todo IDs are Long, not UUID - would need to convert or update Todo to use UUID
            // For now, we'll skip auto-updating the Todo status
        }

        task = taskRepository.save(task);
        return toTaskResponse(task);
    }

    /**
     * Gets all tasks for a session.
     */
public List<PomodoroTaskResponse> getSessionTasks(UUID sessionId) {
        UUID userId = userContextService.getCurrentUserId();

        PomodoroSession session = sessionRepository.findById(sessionId)
                .orElseThrow(() -> new IllegalArgumentException("Session not found"));

        if (!session.getUserId().equals(userId)) {
            throw new IllegalArgumentException("Session does not belong to current user");
        }

        List<PomodoroTask> tasks = taskRepository.findBySessionId(sessionId);
        return tasks.stream()
                .map(this::toTaskResponse)
                .collect(Collectors.toList());
    }

    /**
     * Adds a task to an existing session.
     */
public PomodoroTaskResponse addTaskToSession(UUID sessionId, CreatePomodoroTaskRequest request) {
        UUID userId = userContextService.getCurrentUserId();

        PomodoroSession session = sessionRepository.findById(sessionId)
                .orElseThrow(() -> new IllegalArgumentException("Session not found"));

        if (!session.getUserId().equals(userId)) {
            throw new IllegalArgumentException("Session does not belong to current user");
        }

        // Get current max order index
        List<PomodoroTask> existingTasks = taskRepository.findBySessionId(sessionId);
        int maxOrderIndex = existingTasks.stream()
                .mapToInt(PomodoroTask::getOrderIndex)
                .max()
                .orElse(-1);

        PomodoroTask task = new PomodoroTask(sessionId, request.getDescription(), maxOrderIndex + 1);
        task.setTodoId(request.getTodoId());
        task = taskRepository.save(task);

        return toTaskResponse(task);
    }

    /**
     * Removes a task from a session.
     */
public void removeTaskFromSession(UUID taskId) {
        UUID userId = userContextService.getCurrentUserId();

        PomodoroTask task = taskRepository.findById(taskId)
                .orElseThrow(() -> new IllegalArgumentException("Task not found"));

        // Verify task belongs to user's session
        PomodoroSession session = sessionRepository.findById(task.getSessionId())
                .orElseThrow(() -> new IllegalArgumentException("Session not found"));

        if (!session.getUserId().equals(userId)) {
            throw new IllegalArgumentException("Task does not belong to current user");
        }

        taskRepository.deleteById(taskId);
    }

    /**
     * Gets or creates user's Pomodoro configuration.
     */
public PomodoroConfigResponse getConfig() {
        UUID userId = userContextService.getCurrentUserId();

        PomodoroConfig config = configRepository.findByUserId(userId)
                .orElseGet(() -> {
                    PomodoroConfig newConfig = new PomodoroConfig(userId);
                    return configRepository.save(newConfig);
                });

        return toConfigResponse(config);
    }

    /**
     * Updates user's Pomodoro configuration.
     */
public PomodoroConfigResponse updateConfig(UpdatePomodoroConfigRequest request) {
        UUID userId = userContextService.getCurrentUserId();

        PomodoroConfig config = configRepository.findByUserId(userId)
                .orElseGet(() -> new PomodoroConfig(userId));

        if (request.getWorkDuration() != null) {
            config.setWorkDuration(request.getWorkDuration());
        }
        if (request.getShortBreakDuration() != null) {
            config.setShortBreakDuration(request.getShortBreakDuration());
        }
        if (request.getLongBreakDuration() != null) {
            config.setLongBreakDuration(request.getLongBreakDuration());
        }
        if (request.getCyclesBeforeLongBreak() != null) {
            config.setCyclesBeforeLongBreak(request.getCyclesBeforeLongBreak());
        }
        if (request.getAlarmSound() != null) {
            config.setAlarmSound(AlarmSound.fromValue(request.getAlarmSound()));
        }
        if (request.getAlarmVolume() != null) {
            config.setAlarmVolume(request.getAlarmVolume());
        }
        if (request.getAutoStartBreaks() != null) {
            config.setAutoStartBreaks(request.getAutoStartBreaks());
        }
        if (request.getAutoStartWork() != null) {
            config.setAutoStartWork(request.getAutoStartWork());
        }

        config = configRepository.save(config);
        return toConfigResponse(config);
    }

    // Conversion methods
private PomodoroSessionResponse toSessionResponse(PomodoroSession session) {
        PomodoroSessionResponse response = new PomodoroSessionResponse();
        response.setId(session.getId());
        response.setUserId(session.getUserId());
        response.setStartTime(session.getStartTime());
        response.setEndTime(session.getEndTime());
        response.setWorkDuration(session.getWorkDuration());
        response.setBreakDuration(session.getBreakDuration());
        response.setCompletedCycles(session.getCompletedCycles());
        response.setStatus(session.getStatus().name());
        response.setSessionType(session.getSessionType().name());
        response.setCreatedAt(session.getCreatedAt());
        response.setUpdatedAt(session.getUpdatedAt());

        if (session.getTasks() != null) {
            List<PomodoroTaskResponse> taskResponses = session.getTasks().stream()
                    .map(this::toTaskResponse)
                    .collect(Collectors.toList());
            response.setTasks(taskResponses);
        }

        return response;
    }

private PomodoroSessionResponse toSessionResponseWithoutTasks(PomodoroSession session) {
        PomodoroSessionResponse response = new PomodoroSessionResponse();
        response.setId(session.getId());
        response.setUserId(session.getUserId());
        response.setStartTime(session.getStartTime());
        response.setEndTime(session.getEndTime());
        response.setWorkDuration(session.getWorkDuration());
        response.setBreakDuration(session.getBreakDuration());
        response.setCompletedCycles(session.getCompletedCycles());
        response.setStatus(session.getStatus().name());
        response.setSessionType(session.getSessionType().name());
        response.setCreatedAt(session.getCreatedAt());
        response.setUpdatedAt(session.getUpdatedAt());
        // Don't include tasks to avoid lazy loading issues
        return response;
    }

private PomodoroTaskResponse toTaskResponse(PomodoroTask task) {
        PomodoroTaskResponse response = new PomodoroTaskResponse();
        response.setId(task.getId());
        response.setSessionId(task.getSessionId());
        response.setTodoId(task.getTodoId());
        response.setDescription(task.getDescription());
        response.setCompleted(task.getCompleted());
        response.setOrderIndex(task.getOrderIndex());
        response.setCreatedAt(task.getCreatedAt());
        response.setUpdatedAt(task.getUpdatedAt());

        // Optionally load linked Todo
        // Note: Todo IDs are Long, not UUID - would need to convert or update Todo to use UUID
        // For now, we'll skip loading the linked Todo

        return response;
    }

private PomodoroConfigResponse toConfigResponse(PomodoroConfig config) {
        PomodoroConfigResponse response = new PomodoroConfigResponse();
        response.setId(config.getId());
        response.setUserId(config.getUserId());
        response.setWorkDuration(config.getWorkDuration());
        response.setShortBreakDuration(config.getShortBreakDuration());
        response.setLongBreakDuration(config.getLongBreakDuration());
        response.setCyclesBeforeLongBreak(config.getCyclesBeforeLongBreak());
        response.setAlarmSound(config.getAlarmSound().getValue());
        response.setAlarmVolume(config.getAlarmVolume());
        response.setAutoStartBreaks(config.getAutoStartBreaks());
        response.setAutoStartWork(config.getAutoStartWork());
        response.setCreatedAt(config.getCreatedAt());
        response.setUpdatedAt(config.getUpdatedAt());
        return response;
    }

