// Load reads the config file from the current directory.
// If the config file doesn't exist, it attempts to migrate from .env
func Load() (*Config, error) {
	v := viper.New()
	v.SetConfigName("liquidai")
	v.SetConfigType("yaml")
	v.AddConfigPath(".")

	cfg := &Config{}

	// Try to read config
	if err := v.ReadInConfig(); err != nil {
		if _, ok := err.(viper.ConfigFileNotFoundError); ok {
			// Config doesn't exist, try to migrate from .env
			if err := migrateFromEnv(cfg); err != nil {
				return nil, fmt.Errorf("failed to migrate from .env: %w", err)
			}
			return cfg, nil
		}
		return nil, fmt.Errorf("failed to read config: %w", err)
	}

	if err := v.Unmarshal(cfg); err != nil {
		return nil, fmt.Errorf("failed to parse config: %w", err)
	}

	return cfg, nil
}

// Save writes the config to the liquidai.yaml file
func (c *Config) Save() error {
	v := viper.New()
	v.SetConfigFile(configFile)

	if err := v.MergeConfigMap(map[string]interface{}{
		"version":  1,
		"security": c.Security,
		"stack":    c.Stack,
		"database": c.Database,
	}); err != nil {
		return fmt.Errorf("failed to merge config: %w", err)
	}

	return v.WriteConfig()
}

// ExportEnv exports all config values as environment variables
// This is needed for docker-compose compatibility
func (c *Config) ExportEnv() error {
	vars := map[string]string{
		"JWT_SECRET":      c.Security.JWTSecret,
		"API_SECRET":      c.Security.APISecret,
		"AUTH_SECRET":     c.Security.AuthSecret,
		"STACK_VERSION":   c.Stack.Version,
		"MODEL_IMAGE":     c.Stack.Model.Image,
		"MODEL_NAME":      c.Stack.Model.Name,
		"POSTGRES_DB":     c.Database.Name,
		"POSTGRES_USER":   c.Database.User,
		"POSTGRES_PORT":   fmt.Sprintf("%d", c.Database.Port),
		"POSTGRES_SCHEMA": c.Database.Schema,
		"POSTGRES_PASSWORD": c.Database.Password,
		"DATABASE_URL":    c.Database.URL,
	}

	for k, v := range vars {
		if err := os.Setenv(k, v); err != nil {
			return fmt.Errorf("failed to set environment variable %s: %w", k, err)
		}
	}

	return nil
}

func generateRandomString(length int) string {
	const charset = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
	b := make([]byte, length)
	for i := range b {
		randomBytes := make([]byte, 1)
		if _, err := rand.Read(randomBytes); err != nil {
			panic(err) // This should never happen
		}
		b[i] = charset[randomBytes[0]%byte(len(charset))]
	}
	return string(b)
}

func migrateFromEnv(cfg *Config) error {
	if _, err := os.Stat(".env"); os.IsNotExist(err) {
		return initDefaultConfig(cfg)
	}

	file, err := os.Open(".env")
	if err != nil {
		return fmt.Errorf("failed to open .env: %w", err)
	}
	defer file.Close()

	envVars := make(map[string]string)
	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		line := scanner.Text()
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}

		parts := strings.SplitN(line, "=", 2)
		if len(parts) != 2 {
			continue
		}
		envVars[parts[0]] = parts[1]
	}

	cfg.Version = 1
	cfg.Security.JWTSecret = envVars["JWT_SECRET"]
	cfg.Security.APISecret = envVars["API_SECRET"]
	cfg.Security.AuthSecret = envVars["AUTH_SECRET"]
	cfg.Stack.Version = envVars["STACK_VERSION"]
	cfg.Stack.Model.Image = envVars["MODEL_IMAGE"]
	cfg.Stack.Model.Name = envVars["MODEL_NAME"]
	cfg.Database.Name = envVars["POSTGRES_DB"]
	cfg.Database.User = envVars["POSTGRES_USER"]
	cfg.Database.Password = envVars["POSTGRES_PASSWORD"]
	cfg.Database.Port = 5432
	cfg.Database.Schema = envVars["POSTGRES_SCHEMA"]
	cfg.Database.URL = envVars["DATABASE_URL"]

	if err := cfg.Save(); err != nil {
		return fmt.Errorf("failed to save migrated config: %w", err)
	}

	// Backup and remove .env
	if err := os.Rename(".env", ".env.bak"); err != nil {
		return fmt.Errorf("failed to backup .env: %w", err)
	}

	return nil
}

// CheckDockerRunning verifies if Docker daemon is running
func CheckDockerRunning() error {
	cmd := exec.Command("docker", "info")
	if err := cmd.Run(); err != nil {
		return fmt.Errorf("docker daemon is not running: %w", err)
	}
	return nil
}

// ComposeUp starts the Docker Compose stack with the specified env file
func ComposeUp(envFile string) error {
	cmd := exec.Command("docker", "compose", "--env-file", envFile, "up", "-d", "--wait")
	output, err := cmd.CombinedOutput()
	if err != nil {
		return fmt.Errorf("failed to start docker compose stack: %w\nOutput: %s", err, string(output))
	}
	return nil
}

// ComposeDown stops the Docker Compose stack
func ComposeDown(envFile string) error {
	cmd := exec.Command("docker", "compose", "--env-file", envFile, "down")
	output, err := cmd.CombinedOutput()
	if err != nil {
		return fmt.Errorf("failed to stop docker compose stack: %w\nOutput: %s", err, string(output))
	}
	return nil
}

// CreateVolume creates a Docker volume if it doesn't exist
func CreateVolume(name string) error {
	// Check if volume exists
	cmd := exec.Command("docker", "volume", "inspect", name)
	if err := cmd.Run(); err == nil {
		return nil // Volume already exists
	}

	// Create volume
	cmd = exec.Command("docker", "volume", "create", name)
	if err := cmd.Run(); err != nil {
		return fmt.Errorf("failed to create volume %s: %w", name, err)
	}
	return nil
}

// RemoveContainer removes a Docker container by name if it exists
func RemoveContainer(name string) error {
	// Check if container exists
	cmd := exec.Command("docker", "ps", "-a", "--format", "{{.Names}}")
	output, err := cmd.Output()
	if err != nil {
		return fmt.Errorf("failed to list containers: %w", err)
	}

	containers := strings.Split(string(output), "\n")
	exists := false
	for _, container := range containers {
		if container == name {
			exists = true
			break
		}
	}

	if !exists {
		return nil
	}

	// Remove container
	cmd = exec.Command("docker", "rm", "-f", name)
	if err := cmd.Run(); err != nil {
		return fmt.Errorf("failed to remove container %s: %w", name, err)
	}
	return nil
}

// LoadConfig loads the configuration and exports environment variables
func LoadConfig() (*config.Config, error) {
	cfg, err := config.Load()
	if err != nil {
		return nil, fmt.Errorf("failed to load config: %w", err)
	}

	if err := cfg.ExportEnv(); err != nil {
		return nil, fmt.Errorf("failed to export environment variables: %w", err)
	}

	return cfg, nil
}

// SetEnvVar updates a configuration value and exports it as an environment variable
func SetEnvVar(name, value string, override bool) error {
	cfg, err := config.Load()
	if err != nil {
		return fmt.Errorf("failed to load config: %w", err)
	}

	// Update config based on variable name
	switch name {
	case "JWT_SECRET":
		if override || cfg.Security.JWTSecret == "" {
			cfg.Security.JWTSecret = value
		}
	case "API_SECRET":
		if override || cfg.Security.APISecret == "" {
			cfg.Security.APISecret = value
		}
	case "AUTH_SECRET":
		if override || cfg.Security.AuthSecret == "" {
			cfg.Security.AuthSecret = value
		}
	case "STACK_VERSION":
		if override || cfg.Stack.Version == "" {
			cfg.Stack.Version = value
		}
	case "MODEL_IMAGE":
		if override || cfg.Stack.Model.Image == "" {
			cfg.Stack.Model.Image = value
		}
	case "MODEL_NAME":
		if override || cfg.Stack.Model.Name == "" {
			cfg.Stack.Model.Name = value
		}
	case "POSTGRES_DB":
		if override || cfg.Database.Name == "" {
			cfg.Database.Name = value
		}
	case "POSTGRES_USER":
		if override || cfg.Database.User == "" {
			cfg.Database.User = value
		}
	case "POSTGRES_PASSWORD":
		if override || cfg.Database.Password == "" {
			cfg.Database.Password = value
		}
	case "POSTGRES_PORT":
		if override || cfg.Database.Port == 0 {
			cfg.Database.Port = 5432 // Always use default port
		}
	case "POSTGRES_SCHEMA":
		if override || cfg.Database.Schema == "" {
			cfg.Database.Schema = value
		}
	case "DATABASE_URL":
		if override || cfg.Database.URL == "" {
			cfg.Database.URL = value
		}
	default:
		return fmt.Errorf("unknown environment variable: %s", name)
	}

	// Save config and export environment variables
	if err := cfg.Save(); err != nil {
		return fmt.Errorf("failed to save config: %w", err)
	}

	if err := cfg.ExportEnv(); err != nil {
		return fmt.Errorf("failed to export environment variables: %w", err)
	}

	if override {
		fmt.Printf("%s in config is overridden with new value and exported\n", name)
	} else {
		fmt.Printf("%s already exists in config, the existing value is exported\n", name)
	}

	return nil
}

def get_request_id(request: Request) -> str:
    """Get request ID from state or generate a new one if not present"""
    try:
