override suspend fun sendPasswordResetEmail(to: String, resetLink: String) {
        withContext(Dispatchers.IO) {
            try {
                val message = mailSender.createMimeMessage()
                val helper = MimeMessageHelper(message, true, "UTF-8")

                helper.setTo(to)
                helper.setSubject("Password Reset Request")

                val context = Context()
                context.setVariable("resetLink", resetLink)

                val htmlContent = templateEngine.process("email/password-reset-email", context)
                helper.setText(htmlContent, true)

                mailSender.send(message)
                logger.info("Password reset email sent to: $to")
            } catch (e: Exception) {
                logger.error("Failed to send password reset email to: $to", e)
                throw e
            }
        }
    }

    /**
     * Convert SearchRequestDto to SearchCriteria domain model
     */
fun toDomain(dto: SearchRequestDto): SearchCriteria {
        return SearchCriteria(
            query = dto.query,
            category = dto.category,
            minPrice = dto.minPrice,
            maxPrice = dto.maxPrice,
            location = dto.location,
            sortBy = parseSortOption(dto.sortBy),
            limit = dto.limit,
            offset = dto.offset
        )
    }

    /**
     * Convert SearchResult domain model to SearchResponseDto
     */
fun toDto(result: SearchResult, limit: Int, offset: Int): SearchResponseDto {
        val page = if (limit > 0) offset / limit + 1 else 1
        val totalPages = if (limit > 0) (result.totalCount + limit - 1) / limit else 1

        return SearchResponseDto(
            ads = result.ads.map { toDto(it) },
            totalCount = result.totalCount,
            sources = result.sources,
            page = page,
            totalPages = totalPages,
            pageSize = limit
        )
    }

    /**
     * Parse sort option from string
     */
private fun parseSortOption(sortBy: String?): SortOption {
        return when (sortBy?.uppercase()) {
            "PRICE_ASC" -> SortOption.PRICE_ASC
            "PRICE_DESC" -> SortOption.PRICE_DESC
            "DATE_DESC" -> SortOption.DATE_DESC
            "DATE_ASC" -> SortOption.DATE_ASC
            else -> SortOption.RELEVANCE
        }
    }

constructor() {
        this.viewports = [];
        this.models = [null, null, null];
        this.wireframeMode = false;
        this.isSync = false;
        this.loadingStates = [false, false, false];

        this.init();
    }

initViewport(index) {
        const viewportElement = document.getElementById(`viewport${index + 1}`);
        const loadingElement = document.getElementById(`loading${index + 1}`);

        // 创建场景
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0xf0f0f0);

        // 创建相机
        const camera = new THREE.PerspectiveCamera(
            75,
            viewportElement.clientWidth / (viewportElement.clientHeight - 60),
            0.1,
            1000
        );
        camera.position.set(0, 0, 5);

        // 创建渲染器
        const renderer = new THREE.WebGLRenderer({ 
            antialias: true,
            alpha: true
        });
        renderer.setSize(
            viewportElement.clientWidth,
            viewportElement.clientHeight - 60
        );
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;

        // 添加到DOM
        viewportElement.appendChild(renderer.domElement);

        // 创建控制器
        const controls = new THREE.OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.dampingFactor = 0.05;
        controls.enableZoom = true;
        controls.enablePan = true;
        controls.enableRotate = true;

        // 添加灯光
        this.addLights(scene);

        // 绑定同步事件
        this.bindSyncEvents(controls, index);

        // 存储视窗信息
        this.viewports[index] = {
            scene,
            camera,
            renderer,
            controls,
            element: viewportElement,
            loadingElement
        };

        // 隐藏加载指示器
        loadingElement.style.display = 'none';

        // 处理窗口大小变化
        window.addEventListener('resize', () => this.handleResize(index));
    }

