async loadModel(file, viewportIndex) {
        const viewport = this.viewports[viewportIndex];
        if (!viewport) return;

        // 显示加载状态
        this.showLoading(viewportIndex);

        try {
            const extension = file.name.split('.').pop().toLowerCase();
            let loader;

            // 根据文件类型选择加载器
            switch (extension) {
                case 'stl':
                    loader = new THREE.STLLoader();
                    break;
                case 'ply':
                    loader = new THREE.PLYLoader();
                    break;
                case 'obj':
                    loader = new THREE.OBJLoader();
                    break;
                default:
                    throw new Error('不支持的文件格式');
            }

            // 读取文件
            const fileData = await this.readFile(file);

            // 加载模型
            const geometry = await this.loadGeometry(loader, fileData, extension);

            // 创建材质
            const material = new THREE.MeshPhongMaterial({
                color: this.getModelColor(viewportIndex),
                shininess: 100,
                side: THREE.DoubleSide
            });

            // 创建网格
            let mesh;
            if (extension === 'obj') {
                // OBJ文件返回的是Group对象
                mesh = geometry;
                mesh.traverse((child) => {
                    if (child.isMesh) {
                        child.material = material;
                        child.castShadow = true;
                        child.receiveShadow = true;
                    }
                });
            } else {
                mesh = new THREE.Mesh(geometry, material);
                mesh.castShadow = true;
                mesh.receiveShadow = true;
            }

            // 清除之前的模型
            this.clearModel(viewportIndex);

            // 添加新模型到场景
            viewport.scene.add(mesh);
            this.models[viewportIndex] = mesh;

            // 调整模型大小和位置
            this.fitModelToView(mesh, viewport);

            // 更新模型信息
            this.updateModelInfo(viewportIndex, file.name, geometry);

            // 启用同步
            this.isSync = true;

        } catch (error) {
            console.error('加载模型失败:', error);
            alert(`加载模型失败: ${error.message}`);
        } finally {
            this.hideLoading(viewportIndex);
        }
    }

