            reader.onload = (event) => resolve(event.target.result);
            reader.onerror = () => reject(new Error('文件读取失败'));
            reader.readAsArrayBuffer(file);
        }

loadGeometry(loader, fileData, extension) {
        return new Promise((resolve, reject) => {
            try {
                if (extension === 'obj') {
                    // OBJ文件需要字符串数据
                    const textData = new TextDecoder().decode(fileData);
                    const result = loader.parse(textData);
                    resolve(result);
                } else {
                    // STL和PLY文件使用ArrayBuffer
                    const result = loader.parse(fileData);
                    resolve(result);
                }
            } catch (error) {
                reject(error);
            }
        });
    }

