getModelColor(index) {
        const colors = [0x667eea, 0xe74c3c, 0x2ecc71];
        return colors[index % colors.length];
    }

updateModelInfo(viewportIndex, fileName, geometry) {
        const viewport = this.viewports[viewportIndex];

        // 计算顶点数
        let vertexCount = 0;
        if (geometry.isBufferGeometry) {
            vertexCount = geometry.attributes.position ? geometry.attributes.position.count : 0;
        } else if (geometry.isGroup) {
            // 对于OBJ文件的Group对象
            geometry.traverse((child) => {
                if (child.isMesh && child.geometry.attributes.position) {
                    vertexCount += child.geometry.attributes.position.count;
                }
            });
        }

        // 创建信息显示
        const infoDiv = document.createElement('div');
        infoDiv.className = 'model-info';
        infoDiv.innerHTML = `
            <div><strong>${fileName}</strong></div>
            <div>顶点数: ${vertexCount.toLocaleString()}</div>
        `;

        viewport.element.appendChild(infoDiv);
    }

