handleResize(index) {
        const viewport = this.viewports[index];
        if (!viewport) return;

        const width = viewport.element.clientWidth;
        const height = viewport.element.clientHeight - 60;

        viewport.camera.aspect = width / height;
        viewport.camera.updateProjectionMatrix();
        viewport.renderer.setSize(width, height);
    }

(viewport) => {
            if (viewport) {
                viewport.camera.position.set(5, 5, 5);
                viewport.camera.lookAt(0, 0, 0);
                viewport.controls.target.set(0, 0, 0);
                viewport.controls.update();
            }
        }

toggleWireframe() {
        this.wireframeMode = !this.wireframeMode;

        this.models.forEach((model) => {
            if (model) {
                if (model.isMesh) {
                    model.material.wireframe = this.wireframeMode;
                } else if (model.isGroup) {
                    model.traverse((child) => {
                        if (child.isMesh) {
                            child.material.wireframe = this.wireframeMode;
                        }
                    });
                }
            }
        });
    }

