def _discover_study_dirs(self) -> Dict[str, Path]:
        """Discover available study directories."""
        study_dirs = {}
        for item in self.repo_path.iterdir():
            if item.is_dir() and not item.name.startswith('.'):
                # Skip git and other hidden directories
                if item.name not in ['.git', '__pycache__']:
                    study_dirs[item.name] = item
        return study_dirs

def search_content(self, query: str, topic: str = None) -> None:
        """Search for content across study materials."""
        print(f"🔍 Searching for: '{query}'")
        if topic:
            print(f"📁 In topic: {topic}")
        print("=" * 50)

        results = []
        search_paths = []

        if topic and topic in self.study_dirs:
            search_paths = [self.study_dirs[topic]]
        else:
            search_paths = list(self.study_dirs.values())

        for dir_path in search_paths:
            md_files = list(dir_path.glob("**/*.md"))
            for md_file in md_files:
                matches = self._search_in_file(md_file, query)
                if matches:
                    results.extend(matches)

        if not results:
            print("❌ No matches found.")
            return

        # Display results
        for result in results[:20]:  # Limit to top 20 results
            file_path, line_num, line_content = result
            relative_path = file_path.relative_to(self.repo_path)
            print(f"\n📄 {relative_path}:{line_num}")
            print(f"   {line_content.strip()}")

        if len(results) > 20:
            print(f"\n... and {len(results) - 20} more matches")

        print(f"\nTotal matches: {len(results)}")

def _search_in_file(self, file_path: Path, query: str) -> List[Tuple[Path, int, str]]:
        """Search for query in a specific file."""
        matches = []
        try:
            with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                for line_num, line in enumerate(f, 1):
                    if re.search(query, line, re.IGNORECASE):
                        matches.append((file_path, line_num, line))
        except (IOError, UnicodeDecodeError):
            pass  # Skip files that can't be read
        return matches

function App() {
  const [tasks, setTasks] = useState([]);
  const [inputValue, setInputValue] = useState('');

  const addTask = () => {
    if (inputValue.trim() !== '') {
      setTasks([...tasks, { id: Date.now(), text: inputValue, completed: false }]);
      setInputValue('');
    }
  };

  const toggleTask = (id) => {
    setTasks(tasks.map(task =>
      task.id === id ? { ...task, completed: !task.completed } : task
    ));
  };

  const deleteTask = (id) => {
    setTasks(tasks.filter(task => task.id !== id));
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter') {
      addTask();
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 py-8 px-4">
      <div className="max-w-md mx-auto bg-white rounded-xl shadow-lg p-6">
        {/* Header with animation */}
        <h1 className="text-3xl font-bold text-center text-gray-800 mb-8 animate-pulse">
          My To-Do List
        </h1>

        {/* Input section */}
        <div className="mb-6">
          <div className="flex gap-2">
            <input
              type="text"
              value={inputValue}
              onChange={(e) => setInputValue(e.target.value)}
              onKeyPress={handleKeyPress}
              placeholder="Add a new task..."
              className="flex-1 px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all"
            />
            <button
              onClick={addTask}
              className="px-6 py-3 bg-blue-500 text-white rounded-lg hover:bg-blue-600 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 transition-all transform hover:scale-105 active:scale-95"
            >
              Add
            </button>
          </div>
        </div>

        {/* Task list */}
        <div className="space-y-2">
          {tasks.length === 0 ? (
            <p className="text-center text-gray-500 py-8">
              No tasks yet. Add one above!
            </p>
          ) : (
            tasks.map((task) => (
              <div
                key={task.id}
                className={`flex items-center gap-3 p-3 rounded-lg border transition-all hover:shadow-md ${
                  task.completed
                    ? 'bg-green-50 border-green-200'
                    : 'bg-gray-50 border-gray-200'
                }`}
              >
                <button
                  onClick={() => toggleTask(task.id)}
                  className={`w-5 h-5 rounded-full border-2 flex items-center justify-center transition-all ${
                    task.completed
                      ? 'bg-green-500 border-green-500 text-white'
                      : 'border-gray-300 hover:border-green-400'
                  }`}
                >
                  {task.completed && (
                    <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20">
                      <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                    </svg>
                  )}
                </button>

                <span
                  className={`flex-1 transition-all ${
                    task.completed
                      ? 'text-green-700 line-through'
                      : 'text-gray-800'
                  }`}
                >
                  {task.text}
                </span>

                <button
                  onClick={() => deleteTask(task.id)}
                  className="p-1 text-red-500 hover:text-red-700 hover:bg-red-50 rounded transition-all"
                >
                  <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20">
                    <path fillRule="evenodd" d="M4.293 4.293a1 1 0 011.414 0L10 8.586l4.293-4.293a1 1 0 111.414 1.414L11.414 10l4.293 4.293a1 1 0 01-1.414 1.414L10 11.414l-4.293 4.293a1 1 0 01-1.414-1.414L8.586 10 4.293 5.707a1 1 0 010-1.414z" clipRule="evenodd" />
                  </svg>
                </button>
              </div>
            ))
          )}
        </div>

        {/* Task counter */}
        {tasks.length > 0 && (
          <div className="mt-6 pt-4 border-t border-gray-200">
            <p className="text-center text-sm text-gray-600">
              {tasks.filter(task => !task.completed).length} of {tasks.length} tasks remaining
            </p>
          </div>
        )}
      </div>
    </div>
  );
}

