function deleteTileAt(r, c) {
    if (gameState.voidCrystals <= 0) return false;
    if (r < 0 || r >= settings.boardSize || c < 0 || c >= settings.boardSize) return false;
    const tileValue = gameState.board[r][c].value;
    if (tileValue === 0) return false;
    gameState.board[r][c] = createTile();
    gameState.voidCrystals -= 1;
    if (tileValue === gameState.highestTile) {
        gameState.highestTile = getMaxTile(gameState.board);
    }
    updateDisplay();
    renderBoard();
    return true;
}

function enterDeleteMode() {
    if (gameState.voidCrystals === 0) return;
    gameState.deleteMode = true;
    const board = document.getElementById('gameBoard');
    board.classList.add('delete-mode');
}

function handleBoardClick(e) {
    if (!gameState.deleteMode) return;
    const tileElement = e.target.closest('.tile');
    if (!tileElement) return;
    const board = document.getElementById('gameBoard');
    const tiles = Array.from(board.children);
    const index = tiles.indexOf(tileElement);
    if (index === -1) return;
    const r = Math.floor(index / settings.boardSize);
    const c = index % settings.boardSize;
    const success = deleteTileAt(r, c);
    if (success) {
        gameState.deleteMode = false;
        board.classList.remove('delete-mode');
    }
}

() => {
  beforeEach(() => {
    setupDom();
    gameState.board = Array.from({ length: settings.boardSize }, () => (
      Array.from({ length: settings.boardSize }, () => ({ id: null, value: 0 }))
    ));
    gameState.voidCrystals = 0;
    gameState.highestTile = 2;
    gameState.gameActive = true;
    jest.useFakeTimers();
  });

  afterEach(() => {
    jest.useRealTimers();
    if (Math.random.mockRestore) {
      Math.random.mockRestore();
    }
  });

  test('gaining new max tile grants a void crystal', () => {
    gameState.board[0][0] = { id: 1, value: 2 };
    gameState.board[0][1] = { id: 2, value: 2 };
    jest.spyOn(Math, 'random').mockReturnValue(0);
    move('left');
    jest.runAllTimers();
    expect(gameState.voidCrystals).toBe(1);
  });

  test('deleteTileAt consumes a crystal and clears tile', () => {
    gameState.board[0][0] = { id: 1, value: 4 };
    gameState.voidCrystals = 1;
    const result = deleteTileAt(0, 0);
    expect(result).toBe(true);
    expect(gameState.board[0][0].value).toBe(0);
    expect(gameState.voidCrystals).toBe(0);
  });

  test('deleting highest tile updates gameState.highestTile', () => {
    gameState.board[0][0] = { id: 1, value: 16 };
    gameState.board[0][1] = { id: 2, value: 8 };
    gameState.highestTile = 16;
    gameState.voidCrystals = 1;

    deleteTileAt(0, 0);

    expect(gameState.highestTile).toBe(8);
  });
}

