// Utility functions
int is_text_file(const char* filename) {
    if (!filename) return 0;
    const char* ext = strrchr(filename, '.');
    if (!ext) return 1; // Assume text if no extension
    ext++; // Skip the dot
    return (strcmp(ext, "txt") == 0 || strcmp(ext, "md") == 0 || 
            strcmp(ext, "py") == 0 || strcmp(ext, "c") == 0 || 
            strcmp(ext, "cpp") == 0 || strcmp(ext, "h") == 0 ||
            strcmp(ext, "js") == 0 || strcmp(ext, "html") == 0 ||
            strcmp(ext, "css") == 0 || strcmp(ext, "json") == 0);
}

int is_json_file(const char* filename) {
    if (!filename) return 0;
    const char* ext = strrchr(filename, '.');
    return ext && strcmp(ext, ".json") == 0;
}

char* read_file_content(const char* file_path) {
    FILE* file = fopen(file_path, "rb");
    if (!file) return NULL;

    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    char* content = malloc(file_size + 1);
    if (!content) {
        fclose(file);
        return NULL;
    }

    size_t bytes_read = fread(content, 1, file_size, file);
    content[bytes_read] = '\0';
    fclose(file);
    return content;
}

int count_lines_in_file(const char* file_path) {
    FILE* file = fopen(file_path, "r");
    if (!file) return 0;

    int count = 0;
    char ch;
    while ((ch = fgetc(file)) != EOF) {
        if (ch == '\n') count++;
    }
    fclose(file);
    return count;
}

int count_files_in_directory(const char* dir_path, const char* extension) {
    DIR* dir = opendir(dir_path);
    if (!dir) return 0;

    int count = 0;
    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG) { // Regular file
            if (!extension || strstr(entry->d_name, extension)) {
                count++;
            }
        }
    }
    closedir(dir);
    return count;
}

// Text dataset functions
TextDataset* create_text_dataset(int initial_capacity) {
    TextDataset* ds = malloc(sizeof(TextDataset));
    if (!ds) return NULL;

    ds->capacity = initial_capacity > 0 ? initial_capacity : 1000;
    ds->lines = malloc(ds->capacity * sizeof(char*));
    ds->num_lines = 0;
    ds->source_file = NULL;

    if (!ds->lines) {
        free(ds);
        return NULL;
    }

    return ds;
}

void free_text_dataset(TextDataset* ds) {
    if (!ds) return;

    for (int i = 0; i < ds->num_lines; i++) {
        if (ds->lines[i]) free(ds->lines[i]);
    }
    if (ds->lines) free(ds->lines);
    if (ds->source_file) free(ds->source_file);
    free(ds);
}

int add_line_to_text_dataset(TextDataset* ds, const char* line) {
    if (!ds || !line) return 0;

    if (ds->num_lines >= ds->capacity) {
        int new_capacity = ds->capacity * 2;
        char** new_lines = realloc(ds->lines, new_capacity * sizeof(char*));
        if (!new_lines) return 0;
        ds->lines = new_lines;
        ds->capacity = new_capacity;
    }

    ds->lines[ds->num_lines] = strdup(line);
    if (!ds->lines[ds->num_lines]) return 0;

    ds->num_lines++;
    return 1;
}

TextDataset* load_text_dataset_from_file(const char* file_path) {
    FILE* file = fopen(file_path, "r");
    if (!file) return NULL;

    TextDataset* ds = create_text_dataset(1000);
    if (!ds) {
        fclose(file);
        return NULL;
    }

    ds->source_file = strdup(file_path);
    char line[MAX_LINE_LEN];

    while (fgets(line, sizeof(line), file) && ds->num_lines < MAX_DATASET_SIZE) {
        size_t len = strlen(line);
        if (len > 0 && line[len-1] == '\n') line[len-1] = '\0';
        if (len > 1) { // Skip empty lines
            if (!add_line_to_text_dataset(ds, line)) {
                free_text_dataset(ds);
                fclose(file);
                return NULL;
            }
        }
    }

    fclose(file);
    return ds;
}

// JSON dataset functions
JsonDataset* create_json_dataset(int initial_capacity) {
    JsonDataset* ds = malloc(sizeof(JsonDataset));
    if (!ds) return NULL;

    ds->capacity = initial_capacity > 0 ? initial_capacity : 1000;
    ds->inputs = malloc(ds->capacity * sizeof(char*));
    ds->outputs = malloc(ds->capacity * sizeof(char*));
    ds->num_samples = 0;
    ds->source_file = NULL;

    if (!ds->inputs || !ds->outputs) {
        if (ds->inputs) free(ds->inputs);
        if (ds->outputs) free(ds->outputs);
        free(ds);
        return NULL;
    }

    return ds;
}

void free_json_dataset(JsonDataset* ds) {
    if (!ds) return;

    for (int i = 0; i < ds->num_samples; i++) {
        if (ds->inputs[i]) free(ds->inputs[i]);
        if (ds->outputs[i]) free(ds->outputs[i]);
    }
    if (ds->inputs) free(ds->inputs);
    if (ds->outputs) free(ds->outputs);
    if (ds->source_file) free(ds->source_file);
    free(ds);
}

int add_sample_to_json_dataset(JsonDataset* ds, const char* input, const char* output) {
    if (!ds || !input || !output) return 0;

    if (ds->num_samples >= ds->capacity) {
        int new_capacity = ds->capacity * 2;
        char** new_inputs = realloc(ds->inputs, new_capacity * sizeof(char*));
        char** new_outputs = realloc(ds->outputs, new_capacity * sizeof(char*));
        if (!new_inputs || !new_outputs) {
            if (new_inputs) free(new_inputs);
            if (new_outputs) free(new_outputs);
            return 0;
        }
        ds->inputs = new_inputs;
        ds->outputs = new_outputs;
        ds->capacity = new_capacity;
    }

    ds->inputs[ds->num_samples] = strdup(input);
    ds->outputs[ds->num_samples] = strdup(output);

    if (!ds->inputs[ds->num_samples] || !ds->outputs[ds->num_samples]) {
        if (ds->inputs[ds->num_samples]) free(ds->inputs[ds->num_samples]);
        if (ds->outputs[ds->num_samples]) free(ds->outputs[ds->num_samples]);
        return 0;
    }

    ds->num_samples++;
    return 1;
}

JsonDataset* parse_json_dataset(const char* json_content, const char* source_file) {
    if (!json_content) return NULL;

    JsonDataset* ds = create_json_dataset(1000);
    if (!ds) return NULL;

    ds->source_file = source_file ? strdup(source_file) : NULL;

    // Simple JSON parsing for {"input": "...", "output": "..."} format
    char* content_copy = strdup(json_content);
    if (!content_copy) {
        free_json_dataset(ds);
        return NULL;
    }

    char* line = strtok(content_copy, "\n");
    while (line && ds->num_samples < MAX_DATASET_SIZE) {
        // Skip empty lines and comments
        while (*line && isspace(*line)) line++;
        if (*line == '\0' || *line == '#') {
            line = strtok(NULL, "\n");
            continue;
        }

        // Look for input and output fields
        char* input_start = strstr(line, "\"input\"");
        char* output_start = strstr(line, "\"output\"");

        if (input_start && output_start) {
            // Extract input
            char* input_quote = strchr(input_start + 7, '"');
            char* input_end = strchr(input_quote + 1, '"');
            if (input_quote && input_end) {
                *input_end = '\0';
                char* input = input_quote + 1;

                // Extract output
                char* output_quote = strchr(output_start + 8, '"');
                char* output_end = strchr(output_quote + 1, '"');
                if (output_quote && output_end) {
                    *output_end = '\0';
                    char* output = output_quote + 1;

                    if (!add_sample_to_json_dataset(ds, input, output)) {
                        free(content_copy);
                        free_json_dataset(ds);
                        return NULL;
                    }
                }
            }
        }

        line = strtok(NULL, "\n");
    }

    free(content_copy);
    return ds;
}

int validate_json_format(const char* json_content) {
    if (!json_content) return 0;

    // Simple validation - check for basic JSON structure
    int brace_count = 0;
    int quote_count = 0;
    int has_input = 0;
    int has_output = 0;

    for (int i = 0; json_content[i]; i++) {
        char c = json_content[i];
        if (c == '{') brace_count++;
        else if (c == '}') brace_count--;
        else if (c == '"') quote_count++;

        // Check for input/output fields
        if (strncmp(&json_content[i], "\"input\"", 7) == 0) has_input = 1;
        if (strncmp(&json_content[i], "\"output\"", 8) == 0) has_output = 1;
    }

    return brace_count == 0 && quote_count % 2 == 0 && has_input && has_output;
}

// Combined dataset functions
Dataset* create_dataset(DatasetType type) {
    Dataset* ds = malloc(sizeof(Dataset));
    if (!ds) return NULL;

    ds->type = type;
    ds->text_data = NULL;
    ds->json_data = NULL;
    ds->total_samples = 0;
    ds->file_paths = NULL;
    ds->num_files = 0;

    if (type == DATASET_TYPE_TEXT || type == DATASET_TYPE_MIXED) {
        ds->text_data = create_text_dataset(1000);
        if (!ds->text_data) {
            free(ds);
            return NULL;
        }
    }

    if (type == DATASET_TYPE_JSON || type == DATASET_TYPE_MIXED) {
        ds->json_data = create_json_dataset(1000);
        if (!ds->json_data) {
            if (ds->text_data) free_text_dataset(ds->text_data);
            free(ds);
            return NULL;
        }
    }

    return ds;
}

void free_dataset(Dataset* dataset) {
    if (!dataset) return;

    if (dataset->text_data) free_text_dataset(dataset->text_data);
    if (dataset->json_data) free_json_dataset(dataset->json_data);

    for (int i = 0; i < dataset->num_files; i++) {
        if (dataset->file_paths[i]) free(dataset->file_paths[i]);
    }
    if (dataset->file_paths) free(dataset->file_paths);

    free(dataset);
}

Dataset* load_dataset_from_file(const char* file_path) {
    if (!file_path) return NULL;

    if (is_json_file(file_path)) {
        Dataset* ds = create_dataset(DATASET_TYPE_JSON);
        if (!ds) return NULL;

        char* content = read_file_content(file_path);
        if (!content) {
            free_dataset(ds);
            return NULL;
        }

        ds->json_data = parse_json_dataset(content, file_path);
        free(content);

        if (!ds->json_data) {
            free_dataset(ds);
            return NULL;
        }

        ds->total_samples = ds->json_data->num_samples;
        return ds;
    } else {
        Dataset* ds = create_dataset(DATASET_TYPE_TEXT);
        if (!ds) return NULL;

        ds->text_data = load_text_dataset_from_file(file_path);
        if (!ds->text_data) {
            free_dataset(ds);
            return NULL;
        }

        ds->total_samples = ds->text_data->num_lines;
        return ds;
    }
}

Dataset* load_dataset_from_directory(const char* dir_path, DatasetType type) {
    DIR* dir = opendir(dir_path);
    if (!dir) return NULL;

    Dataset* dataset = create_dataset(type);
    if (!dataset) {
        closedir(dir);
        return NULL;
    }

    // Count files first
    int file_count = 0;
    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG) {
            if ((type == DATASET_TYPE_TEXT && is_text_file(entry->d_name)) ||
                (type == DATASET_TYPE_JSON && is_json_file(entry->d_name)) ||
                type == DATASET_TYPE_MIXED) {
                file_count++;
            }
        }
    }

    if (file_count == 0) {
        free_dataset(dataset);
        closedir(dir);
        return NULL;
    }

    // Allocate file paths array
    dataset->file_paths = malloc(file_count * sizeof(char*));
    dataset->num_files = file_count;

    // Reset directory
    rewinddir(dir);

    int file_idx = 0;
    while ((entry = readdir(dir)) != NULL && file_idx < file_count) {
        if (entry->d_type == DT_REG) {
            if ((type == DATASET_TYPE_TEXT && is_text_file(entry->d_name)) ||
                (type == DATASET_TYPE_JSON && is_json_file(entry->d_name)) ||
                type == DATASET_TYPE_MIXED) {

                // Create full path
                char full_path[MAX_FILENAME_LEN];
                snprintf(full_path, sizeof(full_path), "%s/%s", dir_path, entry->d_name);
                dataset->file_paths[file_idx] = strdup(full_path);

                // Load file content
                if (is_json_file(entry->d_name)) {
                    char* content = read_file_content(full_path);
                    if (content) {
                        JsonDataset* json_data = parse_json_dataset(content, full_path);
                        if (json_data) {
                            // Merge with existing JSON data
                            for (int i = 0; i < json_data->num_samples; i++) {
                                add_sample_to_json_dataset(dataset->json_data, 
                                                         json_data->inputs[i], 
                                                         json_data->outputs[i]);
                            }
                            free_json_dataset(json_data);
                        }
                        free(content);
                    }
                } else {
                    TextDataset* text_data = load_text_dataset_from_file(full_path);
                    if (text_data) {
                        // Merge with existing text data
                        for (int i = 0; i < text_data->num_lines; i++) {
                            add_line_to_text_dataset(dataset->text_data, text_data->lines[i]);
                        }
                        free_text_dataset(text_data);
                    }
                }

                file_idx++;
            }
        }
    }

    closedir(dir);

    // Calculate total samples
    dataset->total_samples = 0;
    if (dataset->text_data) dataset->total_samples += dataset->text_data->num_lines;
    if (dataset->json_data) dataset->total_samples += dataset->json_data->num_samples;

    return dataset;
}

Dataset* load_finetune_dataset(const char* dir_path) {
    return load_dataset_from_directory(dir_path, DATASET_TYPE_JSON);
}

void shuffle_dataset(Dataset* dataset) {
    if (!dataset) return;

    srand(time(NULL));

    if (dataset->text_data && dataset->text_data->num_lines > 0) {
        for (int i = dataset->text_data->num_lines - 1; i > 0; i--) {
            int j = rand() % (i + 1);
            char* tmp = dataset->text_data->lines[i];
            dataset->text_data->lines[i] = dataset->text_data->lines[j];
            dataset->text_data->lines[j] = tmp;
        }
    }

    if (dataset->json_data && dataset->json_data->num_samples > 0) {
        for (int i = dataset->json_data->num_samples - 1; i > 0; i--) {
            int j = rand() % (i + 1);
            char* tmp_input = dataset->json_data->inputs[i];
            char* tmp_output = dataset->json_data->outputs[i];
            dataset->json_data->inputs[i] = dataset->json_data->inputs[j];
            dataset->json_data->outputs[i] = dataset->json_data->outputs[j];
            dataset->json_data->inputs[j] = tmp_input;
            dataset->json_data->outputs[j] = tmp_output;
        }
    }
}

int get_dataset_size(Dataset* dataset) {
    return dataset ? dataset->total_samples : 0;
}

// Batch creation
Batch* create_batch(Dataset* dataset, int start_idx, int batch_size, int seq_len, int vocab_size) {
    if (!dataset || batch_size <= 0 || seq_len <= 0) return NULL;

    Batch* batch = malloc(sizeof(Batch));
    if (!batch) return NULL;

    batch->batch_size = batch_size;
    batch->seq_len = seq_len;
    batch->actual_batch_size = 0;

    int total_size = batch_size * seq_len;
    batch->input_ids = malloc(total_size * sizeof(int));
    batch->target_ids = malloc(total_size * sizeof(int));

    if (!batch->input_ids || !batch->target_ids) {
        if (batch->input_ids) free(batch->input_ids);
        if (batch->target_ids) free(batch->target_ids);
        free(batch);
        return NULL;
    }

    // Initialize with padding
    for (int i = 0; i < total_size; i++) {
        batch->input_ids[i] = 0;  // PAD token
        batch->target_ids[i] = 0; // PAD token
    }

    // Fill batch with data
    int batch_idx = 0;
    int dataset_idx = start_idx;

    while (batch_idx < batch_size && dataset_idx < dataset->total_samples) {
        char* text = NULL;

        // Get text from appropriate dataset
        if (dataset->text_data && dataset_idx < dataset->text_data->num_lines) {
            text = dataset->text_data->lines[dataset_idx];
        } else if (dataset->json_data) {
            int json_idx = dataset_idx - (dataset->text_data ? dataset->text_data->num_lines : 0);
            if (json_idx >= 0 && json_idx < dataset->json_data->num_samples) {
                // For JSON, concatenate input and output
                int total_len = strlen(dataset->json_data->inputs[json_idx]) + 
                               strlen(dataset->json_data->outputs[json_idx]) + 2;
                text = malloc(total_len);
                if (text) {
                    snprintf(text, total_len, "%s %s", 
                            dataset->json_data->inputs[json_idx],
                            dataset->json_data->outputs[json_idx]);
                }
            }
        }

        if (text) {
            // Simple tokenization (character-level)
            int seq_pos = 0;
            for (int i = 0; text[i] && seq_pos < seq_len; i++) {
                int token_id = (int)text[i] % vocab_size;
                batch->input_ids[batch_idx * seq_len + seq_pos] = token_id;
                if (seq_pos < seq_len - 1) {
                    batch->target_ids[batch_idx * seq_len + seq_pos] = token_id;
                }
                seq_pos++;
            }

            // Free temporary text if it was allocated
            if (text != dataset->text_data->lines[dataset_idx]) {
                free(text);
            }

            batch->actual_batch_size++;
        }

        batch_idx++;
        dataset_idx++;
    }

    return batch;
}

void free_batch(Batch* batch) {
    if (!batch) return;
    if (batch->input_ids) free(batch->input_ids);
    if (batch->target_ids) free(batch->target_ids);
    free(batch);
}

// Default generation configuration
void set_default_generation_config(GenerationConfig* config) {
    if (!config) return;

    config->temperature = 1.0f;
    config->top_k = 40;
    config->top_p = 0.9f;
    config->max_length = 100;
    config->min_length = 1;
    config->repetition_penalty = 1.0f;
    config->do_sample = 1;
    config->num_beams = 1;
    config->pad_token_id = 0;
    config->eos_token_id = 3;
    config->bos_token_id = 2;
}

void print_generation_config(const GenerationConfig* config) {
    if (!config) return;

    printf("Generation Config:\n");
    printf("  Temperature: %.2f\n", config->temperature);
    printf("  Top-k: %d\n", config->top_k);
    printf("  Top-p: %.2f\n", config->top_p);
    printf("  Max length: %d\n", config->max_length);
    printf("  Min length: %d\n", config->min_length);
    printf("  Repetition penalty: %.2f\n", config->repetition_penalty);
    printf("  Do sample: %s\n", config->do_sample ? "yes" : "no");
    printf("  Num beams: %d\n", config->num_beams);
    printf("  Special tokens: PAD=%d, BOS=%d, EOS=%d\n", 
           config->pad_token_id, config->bos_token_id, config->eos_token_id);
}

Arena* create_inference_arena(size_t size_mb) {
    size_t size_bytes = size_mb * 1024 * 1024;
    return create_arena(size_bytes);
}

InferenceContext* create_inference_context(Transformer* model, Tokenizer* tokenizer) {
    if (!model || !tokenizer) return NULL;

    InferenceContext* ctx = malloc(sizeof(InferenceContext));
    if (!ctx) return NULL;

    ctx->model = model;
    ctx->tokenizer = tokenizer;
    set_default_generation_config(&ctx->config);

    // Create inference arena (default 1GB)
    ctx->inference_arena = create_inference_arena(1024);
    if (!ctx->inference_arena) {
        free(ctx);
        return NULL;
    }

    // Allocate token buffer
    ctx->max_generated = ctx->config.max_length;
    ctx->generated_tokens = malloc(ctx->max_generated * sizeof(int));
    ctx->num_generated = 0;

    if (!ctx->generated_tokens) {
        destroy_arena(ctx->inference_arena);
        free(ctx);
        return NULL;
    }

    return ctx;
}

void free_inference_context(InferenceContext* ctx) {
    if (!ctx) return;

    if (ctx->inference_arena) {
        destroy_arena(ctx->inference_arena);
    }
    if (ctx->generated_tokens) {
        free(ctx->generated_tokens);
    }
    free(ctx);
}

void reset_inference_arena(InferenceContext* ctx) {
    if (ctx && ctx->inference_arena) {
        arena_reset(ctx->inference_arena);
    }
}

Transformer* load_model_for_inference(const char* model_path) {
    if (!model_path) return NULL;

    // Create a minimal transformer for loading
    Transformer* model = create_transformer(2, 10000, 512, 512, 8, 2048);
    if (!model) return NULL;

    // Load the model weights
    if (!load_transformer(model, model_path)) {
        free_transformer(model);
        return NULL;
    }

    return model;
}

int validate_model_for_inference(Transformer* model) {
    if (!model) return 0;

    // Check basic model parameters
    if (model->n_layers <= 0 || model->embed_dim <= 0 || 
        model->n_heads <= 0 || model->ff_hidden_dim <= 0 ||
        model->vocab_size <= 0 || model->max_seq_len <= 0) {
        return 0;
    }

    // Check that embed_dim is divisible by n_heads
    if (model->embed_dim % model->n_heads != 0) {
        return 0;
    }

    return 1;
}

int check_model_compatibility(Transformer* model, Tokenizer* tokenizer) {
    if (!model || !tokenizer) return 0;

    // Check vocabulary size compatibility
    if (tokenizer->vocab_size > model->vocab_size) {
        return 0;
    }

    return 1;
}

float* compute_attention_mask(int seq_len, int max_seq_len) {
    float* mask = malloc(max_seq_len * max_seq_len * sizeof(float));
    if (!mask) return NULL;

    // Create causal mask (lower triangular)
    for (int i = 0; i < max_seq_len; i++) {
        for (int j = 0; j < max_seq_len; j++) {
            if (i < seq_len && j < seq_len && j <= i) {
                mask[i * max_seq_len + j] = 0.0f;  // Allow attention
            } else {
                mask[i * max_seq_len + j] = -1e9f; // Mask attention
            }
        }
    }

    return mask;
}

int* create_position_ids(int seq_len) {
    int* position_ids = malloc(seq_len * sizeof(int));
    if (!position_ids) return NULL;

    for (int i = 0; i < seq_len; i++) {
        position_ids[i] = i;
    }

    return position_ids;
}

int greedy_next_token(float* logits, int vocab_size) {
    if (!logits || vocab_size <= 0) return 0;

    int best_token = 0;
    float best_score = logits[0];

    for (int i = 1; i < vocab_size; i++) {
        if (logits[i] > best_score) {
            best_score = logits[i];
            best_token = i;
        }
    }

    return best_token;
}

int top_k_sampling(float* logits, int vocab_size, int top_k, float temperature) {
    if (!logits || vocab_size <= 0 || top_k <= 0) return 0;

    // Create a copy of logits for sorting
    float* logits_copy = malloc(vocab_size * sizeof(float));
    if (!logits_copy) return 0;

    memcpy(logits_copy, logits, vocab_size * sizeof(float));

    // Apply temperature
    for (int i = 0; i < vocab_size; i++) {
        logits_copy[i] /= temperature;
    }

    // Find top-k indices
    int* indices = malloc(vocab_size * sizeof(int));
    if (!indices) {
        free(logits_copy);
        return 0;
    }

    for (int i = 0; i < vocab_size; i++) {
        indices[i] = i;
    }

    // Sort by logits (descending)
    for (int i = 0; i < vocab_size - 1; i++) {
        for (int j = i + 1; j < vocab_size; j++) {
            if (logits_copy[indices[i]] < logits_copy[indices[j]]) {
                int temp = indices[i];
                indices[i] = indices[j];
                indices[j] = temp;
            }
        }
    }

    // Sample from top-k
    int selected_idx = rand() % top_k;
    int selected_token = indices[selected_idx];

    free(logits_copy);
    free(indices);

    return selected_token;
}

int top_p_sampling(float* logits, int vocab_size, float top_p, float temperature) {
    if (!logits || vocab_size <= 0 || top_p <= 0.0f || top_p > 1.0f) return 0;

    // Apply temperature and softmax
    float* probs = malloc(vocab_size * sizeof(float));
    if (!probs) return 0;

    float max_logit = logits[0];
    for (int i = 1; i < vocab_size; i++) {
        if (logits[i] > max_logit) max_logit = logits[i];
    }

    float sum_exp = 0.0f;
    for (int i = 0; i < vocab_size; i++) {
        probs[i] = expf((logits[i] - max_logit) / temperature);
        sum_exp += probs[i];
    }

    for (int i = 0; i < vocab_size; i++) {
        probs[i] /= sum_exp;
    }

    // Sort by probability (descending)
    int* indices = malloc(vocab_size * sizeof(int));
    if (!indices) {
        free(probs);
        return 0;
    }

    for (int i = 0; i < vocab_size; i++) {
        indices[i] = i;
    }

    for (int i = 0; i < vocab_size - 1; i++) {
        for (int j = i + 1; j < vocab_size; j++) {
            if (probs[indices[i]] < probs[indices[j]]) {
                int temp = indices[i];
                indices[i] = indices[j];
                indices[j] = temp;
            }
        }
    }

    // Find cumulative probability threshold
    float cumulative_prob = 0.0f;
    int cutoff_idx = vocab_size - 1;

    for (int i = 0; i < vocab_size; i++) {
        cumulative_prob += probs[indices[i]];
        if (cumulative_prob >= top_p) {
            cutoff_idx = i;
            break;
        }
    }

    // Sample from top-p tokens
    int selected_idx = rand() % (cutoff_idx + 1);
    int selected_token = indices[selected_idx];

    free(probs);
    free(indices);

    return selected_token;
}

int sample_next_token(InferenceContext* ctx, float* logits, int vocab_size) {
    if (!ctx || !logits || vocab_size <= 0) return 0;

    if (!ctx->config.do_sample) {
        return greedy_next_token(logits, vocab_size);
    }

    // Apply repetition penalty if needed
    if (ctx->config.repetition_penalty != 1.0f && ctx->num_generated > 0) {
        for (int i = 0; i < ctx->num_generated; i++) {
            int token_id = ctx->generated_tokens[i];
            if (token_id >= 0 && token_id < vocab_size) {
                logits[token_id] /= ctx->config.repetition_penalty;
            }
        }
    }

    // Choose sampling method
    if (ctx->config.top_p > 0.0f && ctx->config.top_p < 1.0f) {
        return top_p_sampling(logits, vocab_size, ctx->config.top_p, ctx->config.temperature);
    } else if (ctx->config.top_k > 0 && ctx->config.top_k < vocab_size) {
        return top_k_sampling(logits, vocab_size, ctx->config.top_k, ctx->config.temperature);
    } else {
        return greedy_next_token(logits, vocab_size);
    }
}

int generate_tokens(InferenceContext* ctx, const char* prompt, int* output_tokens, int max_output_tokens) {
    if (!ctx || !output_tokens || max_output_tokens <= 0) return 0;

    reset_inference_arena(ctx);

    // Encode prompt
    int prompt_tokens[ctx->model->max_seq_len];
    int prompt_length = encode_text_with_special_tokens(ctx->tokenizer, prompt, prompt_tokens, ctx->model->max_seq_len);

    if (prompt_length <= 0) return 0;

    // Initialize generation
    ctx->num_generated = 0;
    int total_length = prompt_length;

    // Copy prompt tokens to output
    for (int i = 0; i < prompt_length && i < max_output_tokens; i++) {
        output_tokens[i] = prompt_tokens[i];
    }

    // Generate tokens
    while (total_length < ctx->config.max_length && ctx->num_generated < max_output_tokens) {
        // Create input tensor
        Tensor* input = create_tensor(2, (int[]){1, total_length}, TENSOR_TYPE_INT);
        if (!input) break;

        // Copy current sequence
        memcpy(input->data, output_tokens, total_length * sizeof(int));

        // Forward pass
        Value* logits_value = transformer_forward_ad(ctx->inference_arena, input, NULL, ctx->model, 0);
        if (!logits_value) {
            free_tensor(input);
            break;
        }

        // Get logits for the last position
        float* logits = (float*)logits_value->data->data;
        int vocab_size = ctx->model->vocab_size;
        float* last_logits = logits + (total_length - 1) * vocab_size;

        // Sample next token
        int next_token = sample_next_token(ctx, last_logits, vocab_size);

        // Add to output
        if (total_length < max_output_tokens) {
            output_tokens[total_length] = next_token;
            ctx->generated_tokens[ctx->num_generated++] = next_token;
            total_length++;
        }

        // Check for EOS
        if (next_token == ctx->config.eos_token_id) {
            break;
        }

        // Clean up
        free_tensor(input);
        free_graph(logits_value);
    }

    return total_length;
}

char* generate_text(InferenceContext* ctx, const char* prompt) {
    if (!ctx || !prompt) return NULL;

    int max_tokens = ctx->config.max_length;
    int* tokens = malloc(max_tokens * sizeof(int));
    if (!tokens) return NULL;

    int num_tokens = generate_tokens(ctx, prompt, tokens, max_tokens);
    if (num_tokens <= 0) {
        free(tokens);
        return NULL;
    }

    // Decode tokens to text
    char* result = decode_tokens(ctx->tokenizer, tokens, num_tokens);
    free(tokens);

    return result;
}

char* generate_text_interactive(InferenceContext* ctx, const char* prompt) {
    if (!ctx || !prompt) return NULL;

    printf("Generating text for prompt: '%s'\n", prompt);
    printf("Press Enter to continue generation, 'q' to quit\n");

    int max_tokens = ctx->config.max_length;
    int* tokens = malloc(max_tokens * sizeof(int));
    if (!tokens) return NULL;

    // Encode prompt
    int prompt_tokens[ctx->model->max_seq_len];
    int prompt_length = encode_text_with_special_tokens(ctx->tokenizer, prompt, prompt_tokens, ctx->model->max_seq_len);

    if (prompt_length <= 0) {
        free(tokens);
        return NULL;
    }

    // Copy prompt tokens
    int total_length = prompt_length;
    for (int i = 0; i < prompt_length; i++) {
        tokens[i] = prompt_tokens[i];
    }

    // Print initial prompt
    char* current_text = decode_tokens(ctx->tokenizer, tokens, total_length);
    printf("%s", current_text);
    fflush(stdout);
    free(current_text);

    // Interactive generation
    while (total_length < max_tokens) {
        // Generate next token
        reset_inference_arena(ctx);

        Tensor* input = create_tensor(2, (int[]){1, total_length}, TENSOR_TYPE_INT);
        if (!input) break;

        memcpy(input->data, tokens, total_length * sizeof(int));

        Value* logits_value = transformer_forward_ad(ctx->inference_arena, input, NULL, ctx->model, 0);
        if (!logits_value) {
            free_tensor(input);
            break;
        }

        float* logits = (float*)logits_value->data->data;
        int vocab_size = ctx->model->vocab_size;
        float* last_logits = logits + (total_length - 1) * vocab_size;

        int next_token = sample_next_token(ctx, last_logits, vocab_size);

        // Add token
        tokens[total_length++] = next_token;

        // Decode and print new token
        char* new_text = decode_tokens(ctx->tokenizer, tokens + total_length - 1, 1);
        printf("%s", new_text);
        fflush(stdout);
        free(new_text);

        // Check for EOS
        if (next_token == ctx->config.eos_token_id) {
            break;
        }

        // Check for user input
        if (total_length % 10 == 0) {  // Check every 10 tokens
            struct timeval tv;
            gettimeofday(&tv, NULL);

            fd_set fds;
            FD_ZERO(&fds);
            FD_SET(0, &fds);

            tv.tv_sec = 0;
            tv.tv_usec = 0;

            if (select(1, &fds, NULL, NULL, &tv) > 0) {
                char input_char;
                if (read(0, &input_char, 1) > 0) {
                    if (input_char == 'q' || input_char == 'Q') {
                        break;
                    }
                }
            }
        }

        free_tensor(input);
        free_graph(logits_value);
    }

    printf("\n");

    // Return full generated text
    char* result = decode_tokens(ctx->tokenizer, tokens, total_length);
    free(tokens);

    return result;
}

void log_inference_stats(const InferenceContext* ctx, const char* prompt, const char* generated) {
    if (!ctx) return;

    printf("=== Inference Stats ===\n");
    printf("Prompt length: %zu characters\n", strlen(prompt));
    printf("Generated length: %zu characters\n", strlen(generated));
    printf("Tokens generated: %d\n", ctx->num_generated);
    printf("Model: %d layers, %d dim, %d heads\n", 
           ctx->model->n_layers, ctx->model->embed_dim, ctx->model->n_heads);
    printf("Vocabulary size: %d\n", ctx->model->vocab_size);
    printf("=====================\n");
}

void print_token_distribution(float* logits, int vocab_size, int top_k) {
    if (!logits || vocab_size <= 0) return;

    printf("Top-%d token probabilities:\n", top_k);

    // Create index array
    int* indices = malloc(vocab_size * sizeof(int));
    if (!indices) return;

    for (int i = 0; i < vocab_size; i++) {
        indices[i] = i;
    }

    // Sort by logits (descending)
    for (int i = 0; i < vocab_size - 1; i++) {
        for (int j = i + 1; j < vocab_size; j++) {
            if (logits[indices[i]] < logits[indices[j]]) {
                int temp = indices[i];
                indices[i] = indices[j];
                indices[j] = temp;
            }
        }
    }

    // Print top-k
    for (int i = 0; i < top_k && i < vocab_size; i++) {
        printf("  [%d] %.4f\n", indices[i], logits[indices[i]]);
    }

    free(indices);
}

// Hash function for token lookup
static unsigned int hash_token(const char* token) {
    unsigned int hash = 5381;
    int c;
    while ((c = *token++)) {
        hash = ((hash << 5) + hash) + c;
    }
    return hash;
}

Tokenizer* create_tokenizer(int max_vocab_size) {
    Tokenizer* tokenizer = malloc(sizeof(Tokenizer));
    if (!tokenizer) return NULL;

    tokenizer->max_vocab_size = max_vocab_size > 0 ? max_vocab_size : MAX_VOCAB_SIZE;
    tokenizer->vocab_size = 0;
    tokenizer->max_token_id = 0;

    // Allocate vocabulary array
    tokenizer->vocab = malloc(tokenizer->max_vocab_size * sizeof(VocabEntry));
    if (!tokenizer->vocab) {
        free(tokenizer);
        return NULL;
    }

    // Initialize mapping arrays
    tokenizer->id_to_token = malloc(tokenizer->max_vocab_size * sizeof(char*));
    tokenizer->token_to_id = malloc(tokenizer->max_vocab_size * sizeof(int));

    if (!tokenizer->id_to_token || !tokenizer->token_to_id) {
        if (tokenizer->id_to_token) free(tokenizer->id_to_token);
        if (tokenizer->token_to_id) free(tokenizer->token_to_id);
        free(tokenizer->vocab);
        free(tokenizer);
        return NULL;
    }

    // Initialize all entries
    for (int i = 0; i < tokenizer->max_vocab_size; i++) {
        tokenizer->vocab[i].token = NULL;
        tokenizer->vocab[i].frequency = 0;
        tokenizer->vocab[i].id = -1;
        tokenizer->id_to_token[i] = NULL;
        tokenizer->token_to_id[i] = -1;
    }

    // Add special tokens
    add_token_to_vocab(tokenizer, "<PAD>");
    add_token_to_vocab(tokenizer, "<UNK>");
    add_token_to_vocab(tokenizer, "<BOS>");
    add_token_to_vocab(tokenizer, "<EOS>");

    return tokenizer;
}

void free_tokenizer(Tokenizer* tokenizer) {
    if (!tokenizer) return;

    // Free vocabulary entries
    for (int i = 0; i < tokenizer->vocab_size; i++) {
        if (tokenizer->vocab[i].token) {
            free(tokenizer->vocab[i].token);
        }
    }

    // Free mapping arrays
    for (int i = 0; i < tokenizer->max_vocab_size; i++) {
        if (tokenizer->id_to_token[i]) {
            free(tokenizer->id_to_token[i]);
        }
    }

    if (tokenizer->vocab) free(tokenizer->vocab);
    if (tokenizer->id_to_token) free(tokenizer->id_to_token);
    if (tokenizer->token_to_id) free(tokenizer->token_to_id);

    free(tokenizer);
}

int add_token_to_vocab(Tokenizer* tokenizer, const char* token) {
    if (!tokenizer || !token) return -1;

    // Check if token already exists
    for (int i = 0; i < tokenizer->vocab_size; i++) {
        if (tokenizer->vocab[i].token && strcmp(tokenizer->vocab[i].token, token) == 0) {
            tokenizer->vocab[i].frequency++;
            return tokenizer->vocab[i].id;
        }
    }

    // Add new token if there's space
    if (tokenizer->vocab_size >= tokenizer->max_vocab_size) {
        return -1;
    }

    int id = tokenizer->vocab_size;
    tokenizer->vocab[id].token = strdup(token);
    tokenizer->vocab[id].frequency = 1;
    tokenizer->vocab[id].id = id;

    if (!tokenizer->vocab[id].token) {
        return -1;
    }

    tokenizer->vocab_size++;
    if (id > tokenizer->max_token_id) {
        tokenizer->max_token_id = id;
    }

    return id;
}

int get_token_id(Tokenizer* tokenizer, const char* token) {
    if (!tokenizer || !token) return UNK_TOKEN_ID;

    for (int i = 0; i < tokenizer->vocab_size; i++) {
        if (tokenizer->vocab[i].token && strcmp(tokenizer->vocab[i].token, token) == 0) {
            return tokenizer->vocab[i].id;
        }
    }

    return UNK_TOKEN_ID;
}

const char* get_token_by_id(Tokenizer* tokenizer, int id) {
    if (!tokenizer || id < 0 || id >= tokenizer->vocab_size) {
        return "<UNK>";
    }

    return tokenizer->vocab[id].token;
}

void normalize_text(char* text) {
    if (!text) return;

    // Convert to lowercase and normalize whitespace
    int j = 0;
    int prev_space = 1;

    for (int i = 0; text[i]; i++) {
        char c = text[i];

        if (isspace(c)) {
            if (!prev_space) {
                text[j++] = ' ';
                prev_space = 1;
            }
        } else {
            text[j++] = tolower(c);
            prev_space = 0;
        }
    }

    // Remove trailing space
    if (j > 0 && text[j-1] == ' ') {
        j--;
    }

    text[j] = '\0';
}

int is_special_token(const char* token) {
    if (!token) return 0;
    return (strcmp(token, "<PAD>") == 0 || strcmp(token, "<UNK>") == 0 ||
            strcmp(token, "<BOS>") == 0 || strcmp(token, "<EOS>") == 0);
}

int count_words(const char* text) {
    if (!text) return 0;

    int count = 0;
    int in_word = 0;

    for (int i = 0; text[i]; i++) {
        if (isspace(text[i])) {
            in_word = 0;
        } else if (!in_word) {
            count++;
            in_word = 1;
        }
    }

    return count;
}

int build_vocab_from_text(Tokenizer* tokenizer, const char* text) {
    if (!tokenizer || !text) return 0;

    char* text_copy = strdup(text);
    if (!text_copy) return 0;

    normalize_text(text_copy);

    // Simple word-based tokenization
    char* word = strtok(text_copy, " \t\n\r.,!?;:()[]{}\"'");
    while (word && tokenizer->vocab_size < tokenizer->max_vocab_size) {
        if (strlen(word) > 0 && !is_special_token(word)) {
            add_token_to_vocab(tokenizer, word);
        }
        word = strtok(NULL, " \t\n\r.,!?;:()[]{}\"'");
    }

    free(text_copy);
    return 1;
}

int build_vocab_from_file(Tokenizer* tokenizer, const char* file_path) {
    FILE* file = fopen(file_path, "r");
    if (!file) return 0;

    char line[4096];
    int success = 1;

    while (fgets(line, sizeof(line), file) && success) {
        size_t len = strlen(line);
        if (len > 0 && line[len-1] == '\n') line[len-1] = '\0';

        if (len > 1) {
            success = build_vocab_from_text(tokenizer, line);
        }
    }

    fclose(file);
    return success;
}

int build_vocab_from_directory(Tokenizer* tokenizer, const char* dir_path) {
    DIR* dir = opendir(dir_path);
    if (!dir) return 0;

    struct dirent* entry;
    int success = 1;

    while ((entry = readdir(dir)) != NULL && success) {
        if (entry->d_type == DT_REG) {
            char full_path[1024];
            snprintf(full_path, sizeof(full_path), "%s/%s", dir_path, entry->d_name);

            // Only process text files
            if (strstr(entry->d_name, ".txt") || strstr(entry->d_name, ".md") ||
                strstr(entry->d_name, ".py") || strstr(entry->d_name, ".c") ||
                strstr(entry->d_name, ".cpp") || strstr(entry->d_name, ".h")) {
                success = build_vocab_from_file(tokenizer, full_path);
            }
        }
    }

    closedir(dir);
    return success;
}

void finalize_vocab(Tokenizer* tokenizer) {
    if (!tokenizer) return;

    // Sort vocabulary by frequency
    qsort(tokenizer->vocab, tokenizer->vocab_size, sizeof(VocabEntry), compare_vocab_entries);

    // Rebuild ID mappings
    for (int i = 0; i < tokenizer->vocab_size; i++) {
        tokenizer->vocab[i].id = i;
        tokenizer->id_to_token[i] = strdup(tokenizer->vocab[i].token);
        tokenizer->token_to_id[i] = i;
    }

    tokenizer->max_token_id = tokenizer->vocab_size - 1;
}

int encode_text(Tokenizer* tokenizer, const char* text, int* tokens, int max_tokens) {
    if (!tokenizer || !text || !tokens || max_tokens <= 0) return 0;

    char* text_copy = strdup(text);
    if (!text_copy) return 0;

    normalize_text(text_copy);

    int token_count = 0;
    char* word = strtok(text_copy, " \t\n\r.,!?;:()[]{}\"'");

    while (word && token_count < max_tokens) {
        int token_id = get_token_id(tokenizer, word);
        tokens[token_count++] = token_id;
        word = strtok(NULL, " \t\n\r.,!?;:()[]{}\"'");
    }

    free(text_copy);
    return token_count;
}

int encode_text_with_special_tokens(Tokenizer* tokenizer, const char* text, int* tokens, int max_tokens) {
    if (!tokenizer || !text || !tokens || max_tokens <= 2) return 0;

    // Add BOS token
    tokens[0] = BOS_TOKEN_ID;

    // Encode the text
    int text_tokens = encode_text(tokenizer, text, tokens + 1, max_tokens - 2);

    // Add EOS token
    tokens[text_tokens + 1] = EOS_TOKEN_ID;

    return text_tokens + 2;
}

char* decode_tokens(Tokenizer* tokenizer, const int* tokens, int num_tokens) {
    if (!tokenizer || !tokens || num_tokens <= 0) return NULL;

    // Calculate total length needed
    int total_length = 0;
    for (int i = 0; i < num_tokens; i++) {
        const char* token = get_token_by_id(tokenizer, tokens[i]);
        if (token) {
            total_length += strlen(token) + 1; // +1 for space
        }
    }

    char* result = malloc(total_length + 1);
    if (!result) return NULL;

    result[0] = '\0';
    int pos = 0;

    for (int i = 0; i < num_tokens; i++) {
        const char* token = get_token_by_id(tokenizer, tokens[i]);
        if (token && !is_special_token(token)) {
            int len = strlen(token);
            strcpy(result + pos, token);
            pos += len;
            result[pos++] = ' ';
        }
    }

    // Remove trailing space
    if (pos > 0 && result[pos-1] == ' ') {
        pos--;
    }
    result[pos] = '\0';

    return result;
}

// Character-level tokenization (fallback)
int encode_char_level(const char* text, int* tokens, int max_tokens, int vocab_size) {
    if (!text || !tokens || max_tokens <= 0) return 0;

    int count = 0;
    for (int i = 0; text[i] && count < max_tokens; i++) {
        tokens[count++] = (int)text[i] % vocab_size;
    }

    return count;
}

int save_vocab(Tokenizer* tokenizer, const char* file_path) {
    if (!tokenizer || !file_path) return 0;

    FILE* file = fopen(file_path, "w");
    if (!file) return 0;

    // Write vocabulary size
    fprintf(file, "%d\n", tokenizer->vocab_size);

    // Write each token and its frequency
    for (int i = 0; i < tokenizer->vocab_size; i++) {
        fprintf(file, "%s\t%d\n", tokenizer->vocab[i].token, tokenizer->vocab[i].frequency);
    }

    fclose(file);
    return 1;
}

int load_vocab(Tokenizer* tokenizer, const char* file_path) {
    if (!tokenizer || !file_path) return 0;

    FILE* file = fopen(file_path, "r");
    if (!file) return 0;

    // Read vocabulary size
    int vocab_size;
    if (fscanf(file, "%d\n", &vocab_size) != 1) {
        fclose(file);
        return 0;
    }

    // Clear existing vocabulary
    for (int i = 0; i < tokenizer->vocab_size; i++) {
        if (tokenizer->vocab[i].token) {
            free(tokenizer->vocab[i].token);
        }
    }
    tokenizer->vocab_size = 0;

    // Read vocabulary entries
    char token[256];
    int frequency;

    for (int i = 0; i < vocab_size && i < tokenizer->max_vocab_size; i++) {
        if (fscanf(file, "%255s\t%d\n", token, &frequency) == 2) {
            tokenizer->vocab[i].token = strdup(token);
            tokenizer->vocab[i].frequency = frequency;
            tokenizer->vocab[i].id = i;
            tokenizer->vocab_size++;
        }
    }

    fclose(file);

    // Rebuild mappings
    finalize_vocab(tokenizer);

    return 1;
}

// Legacy function for backward compatibility
int encode(const char* text, int* tokens, int max_tokens) {
    // Create a simple character-level tokenizer
    return encode_char_level(text, tokens, max_tokens, 10000);
}

bool Effect::standardInit(WS2812FX* strip) {
    // Validate strip pointer
    if (strip == nullptr) {
        return false;
    }

    if (_isInitialized) {
        return true; // Already initialized
    }

    // Get runtime data and mark as initialized
    auto runtime = strip->getSegmentRuntime();
    if (runtime) {
        runtime->modeinit = false;
    }

    _isInitialized = true;
    return true;
}

