    /**
     * 指定年の資産データから目標達成率を計算する
     *
     * @param yearlyAssets 年別資産データ
     * @param goalAmount   目標金額
     * @return 目標達成率（パーセント）
     */
public BigDecimal calculateAchievementRate(YearlyAssets yearlyAssets, BigDecimal goalAmount) {
        if (yearlyAssets == null || goalAmount == null || goalAmount.compareTo(BigDecimal.ZERO) == 0) {
            return BigDecimal.ZERO;
        }

        BigDecimal totalAssets = calculateTotalAssets(yearlyAssets);

        // 達成率を計算（パーセント）
        return totalAssets.divide(goalAmount, DIVISION_SCALE, RoundingMode.HALF_UP)
                .multiply(BigDecimal.valueOf(100))
                .setScale(2, RoundingMode.HALF_UP);
    }

    /**
     * 年別資産データから総資産額を計算する
     *
     * @param yearlyAssets 年別資産データ
     * @return 総資産額
     */
public BigDecimal calculateTotalAssets(YearlyAssets yearlyAssets) {
        if (yearlyAssets == null) {
            return BigDecimal.ZERO;
        }
        return yearlyAssets.getCash()
                .add(yearlyAssets.getSecurities())
                .add(yearlyAssets.getCrypto());
    }

def channel_summaries(channel_name):
    """Display AI summaries for videos from a specific channel"""
    try:
        # Get all videos from this channel that have summaries
        videos_with_summaries = database_storage.get_videos_with_summaries_by_channel(channel_name)

        if not videos_with_summaries:
            return render_template('error.html', 
                                 error_message=f"No AI summaries found for channel: {channel_name}"), 404

        return render_template('channel_summaries.html',
                             channel_name=channel_name,
                             videos_with_summaries=videos_with_summaries,
                             total_videos=len(videos_with_summaries))

    except Exception as e:
        return render_template('error.html', 
                             error_message=f"Error loading summaries for channel {channel_name}: {str(e)}"), 500

