def test_validate_search_options_accepts_url_filters(self):
        """Test that validate_search_options accepts URL filter parameters."""
        # Valid options should not raise
        options = {
            "query": "test",
            "include_urls": ["*/about/*", "*.edu/*"],
            "exclude_urls": ["*/blog/*", "*/news/*"]
        }
        validate_search_options(options, SEARCH_OPTIONS_TYPES)

def test_validate_search_options_rejects_invalid_url_filter_types(self):
        """Test that validate_search_options rejects invalid types for URL filters."""
        # String instead of list should raise
        options = {
            "query": "test",
            "include_urls": "*/about/*"  # Should be a list
        }
        with pytest.raises(ValueError, match="Invalid value for option 'include_urls'"):
            validate_search_options(options, SEARCH_OPTIONS_TYPES)

        # Dict instead of list should raise
        options = {
            "query": "test",
            "exclude_urls": {"pattern": "*/blog/*"}  # Should be a list
        }
        with pytest.raises(ValueError, match="Invalid value for option 'exclude_urls'"):
            validate_search_options(options, SEARCH_OPTIONS_TYPES)

def test_validate_search_options_accepts_empty_lists(self):
        """Test that empty lists are valid for URL filters."""
        options = {
            "query": "test",
            "include_urls": [],
            "exclude_urls": []
        }
        validate_search_options(options, SEARCH_OPTIONS_TYPES)

def test_validate_search_options_accepts_none_values(self):
        """Test that None values are valid for optional URL filters."""
        options = {
            "query": "test",
            "include_urls": None,
            "exclude_urls": None
        }
        validate_search_options(options, SEARCH_OPTIONS_TYPES)

TORCH_LIBRARY_IMPL(feature_transformer, CUDA, m) {
    m.impl("add_gpu", &add_gpu);
    m.impl("transform_gpu", &transform_gpu);
}

// Helper function to check tensor requirements
void check_tensor_requirements(const torch::Tensor& tensor, torch::ScalarType dtype, const char* tensor_name) {
    TORCH_CHECK(tensor.device().is_cpu(), tensor_name, " must be on CPU");
    TORCH_CHECK(tensor.dtype() == dtype, tensor_name, " must be ", dtype);
    TORCH_CHECK(tensor.dim() == 1, tensor_name, " must be 1-dimensional");
    TORCH_CHECK(tensor.is_contiguous(), tensor_name, " must be contiguous");
}

explicit PyFeatureTransformer(int64_t num_partition) 
        : impl_(num_partition)
        , max_partition_size_(1024)  // Configurable parameter for GPU hash table size
    {
        if (torch::cuda::is_available()) {
            // Initialize GPU storage
            auto options = torch::TensorOptions()
                .dtype(torch::kInt64)
                .device(torch::kCUDA);
            partition_keys_ = torch::full({static_cast<int64_t>(num_partition) * static_cast<int64_t>(max_partition_size_)}, -1, options);

            auto int32_options = torch::TensorOptions()
                .dtype(torch::kInt32)
                .device(torch::kCUDA);
            partition_values_ = torch::empty({static_cast<int64_t>(num_partition) * static_cast<int64_t>(max_partition_size_)}, int32_options);
            partition_sizes_ = torch::zeros({num_partition}, int32_options);
        }
    }

torch::Tensor add(const torch::Tensor& feature) {
        TORCH_CHECK(!finalized_, "FeatureGroup already finalized");
        TORCH_CHECK(feature.dtype() == torch::kInt64, "Feature tensor must be int64");
        TORCH_CHECK(feature.dim() == 1, "Feature tensor must be 1-dimensional");

        if (feature.device().is_cuda() && torch::cuda::is_available()) {
            auto output = torch::empty_like(feature, torch::TensorOptions().dtype(torch::kInt32));
            cuda::add_gpu(
                feature,
                output,
                impl_.num_partition(),
                partition_keys_,
                partition_values_,
                partition_sizes_,
                max_partition_size_
            );
            return output;
        } else {
            check_tensor_requirements(feature, torch::kInt64, "Feature tensor");
            return impl_.add(feature);
        }
    }

torch::Tensor transform(const torch::Tensor& feature) {
        TORCH_CHECK(finalized_, "FeatureGroup not finalized");
        TORCH_CHECK(feature.dtype() == torch::kInt32, "Feature tensor must be int32");
        TORCH_CHECK(feature.dim() == 1, "Feature tensor must be 1-dimensional");

        if (feature.device().is_cuda() && torch::cuda::is_available()) {
            auto output = torch::empty_like(feature, torch::TensorOptions().dtype(torch::kInt32));
            auto partition_offset = partition_splits().to(torch::kCUDA);
            cuda::transform_gpu(feature, output, partition_offset);
            return output;
        } else {
            check_tensor_requirements(feature, torch::kInt32, "Feature tensor");
            return impl_.transform(feature);
        }
    }

torch::Tensor unique_fids() {
        TORCH_CHECK(finalized_, "FeatureGroup not finalized");
        return impl_.unique_fids();
    }

torch::Tensor partition_splits() {
        TORCH_CHECK(finalized_, "FeatureGroup not finalized");
        return impl_.partition_splits();
    }

void clear() {
        impl_.clear();
        finalized_ = false;
        if (torch::cuda::is_available()) {
            // Reset all GPU tensors to initial state
            partition_keys_.fill_(-1);
            partition_values_.zero_();
            partition_sizes_.zero_();
        }
    }

void finalize() {
        impl_.finalize();
        finalized_ = true;
    }

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    py::class_<PyFeatureTransformer>(m, "FeatureTransformer")
        .def(py::init<int64_t>(), py::arg("num_partition"))
        .def("add", &PyFeatureTransformer::add, "Add features to the transformer")
        .def("transform", &PyFeatureTransformer::transform, "Transform feature indices to global indices")
        .def("unique_fids", &PyFeatureTransformer::unique_fids, "Get unique feature IDs")
        .def("partition_splits", &PyFeatureTransformer::partition_splits, "Get partition split points")
        .def("clear", &PyFeatureTransformer::clear, "Clear the transformer state")
        .def("finalize", &PyFeatureTransformer::finalize, "Finalize the transformer");
}

FeatureTransformer::FeatureTransformer(int64_t num_partition)
    : finalized_(false)
    , num_partition_(static_cast<int32_t>(num_partition))
    , partitions_(static_cast<int32_t>(num_partition))
{
    // Reserve space in each partition map to reduce rehashing
    const size_t estimated_partition_size = 1024;  // Adjustable based on expected usage
    for (auto& partition : partitions_) {
        partition.reserve(estimated_partition_size);
    }
}

void FeatureTransformer::clear() {
    // Completely recreate the partitions to ensure clean state
    partitions_.clear();
    partitions_.resize(num_partition_);

    // Reserve space in each partition map to reduce rehashing
    const size_t estimated_partition_size = 1024;  // Same as constructor
    for (auto& partition : partitions_) {
        partition.reserve(estimated_partition_size);
    }
    finalized_ = false;
}

void FeatureTransformer::finalize() {
    finalized_ = true;
}

int32_t FeatureTransformer::get_mixed_index(int32_t partition_id, int32_t local_index) const {
    return (partition_id << 20) | (local_index & LOCAL_INDEX_MASK);
}

std::pair<int32_t, int32_t> FeatureTransformer::split_mixed_index(int32_t mixed_index) const {
    int32_t partition_id = (mixed_index & PARTITION_INDEX_MASK) >> 20;
    int32_t local_index = mixed_index & LOCAL_INDEX_MASK;
    return {partition_id, local_index};
}

torch::Tensor FeatureTransformer::add(const torch::Tensor& feature) {
    TORCH_CHECK(!finalized_, "FeatureGroup already finalized");
    TORCH_CHECK(feature.dtype() == torch::kInt64, "Feature must be int64");
    TORCH_CHECK(feature.dim() == 1, "Feature must be 1D tensor");

    auto output = torch::empty_like(feature, torch::dtype(torch::kInt32));
    auto feature_accessor = feature.accessor<int64_t, 1>();
    auto output_accessor = output.accessor<int32_t, 1>();

    for (int64_t i = 0; i < feature.size(0); ++i) {
        const int64_t fid = feature_accessor[i];
        const int32_t partition_id = static_cast<int32_t>(std::abs(fid % static_cast<int64_t>(num_partition_)));
        auto& partition_dict = partitions_[partition_id];

        auto it = partition_dict.find(fid);
        if (it != partition_dict.end()) {
            output_accessor[i] = get_mixed_index(partition_id, it->second);
        } else {
            int32_t new_index = static_cast<int32_t>(partition_dict.size());
            partition_dict[fid] = new_index;
            output_accessor[i] = get_mixed_index(partition_id, new_index);
        }
    }
    return output;
}

torch::Tensor FeatureTransformer::transform(const torch::Tensor& feature) {
    TORCH_CHECK(finalized_, "FeatureGroup not finalized");
    TORCH_CHECK(feature.dtype() == torch::kInt32, "Feature must be int32");
    TORCH_CHECK(feature.dim() == 1, "Feature must be 1D tensor");

    auto partition_offset_tensor = partition_splits();
    auto partition_offset_accessor = partition_offset_tensor.accessor<int32_t, 1>();

    auto output = torch::empty_like(feature, torch::dtype(torch::kInt32));
    auto feature_accessor = feature.accessor<int32_t, 1>();
    auto output_accessor = output.accessor<int32_t, 1>();

    for (int64_t i = 0; i < feature.size(0); ++i) {
        const int32_t mix_index = feature_accessor[i];
        auto [partition_id, local_index] = split_mixed_index(mix_index);
        output_accessor[i] = partition_offset_accessor[partition_id] + local_index;
    }
    return output;
}

torch::Tensor FeatureTransformer::unique_fids() {
    TORCH_CHECK(finalized_, "FeatureGroup not finalized");
    auto partition_offset_tensor = partition_splits();
    auto partition_offset_accessor = partition_offset_tensor.accessor<int32_t, 1>();

    auto output = torch::full({partition_offset_accessor[num_partition_]}, -1, torch::dtype(torch::kInt64));
    auto output_accessor = output.accessor<int64_t, 1>();

    for (int32_t i = 0; i < num_partition_; ++i) {
        const int32_t offset = partition_offset_accessor[i];
        for (const auto& [fid, local_index] : partitions_[i]) {
            const int32_t global_index = offset + local_index;
            output_accessor[global_index] = fid;
        }
    }
    return output;
}

torch::Tensor FeatureTransformer::partition_splits() {
    TORCH_CHECK(finalized_, "FeatureGroup not finalized");
    auto output = torch::empty({num_partition_ + 1}, torch::dtype(torch::kInt32));
    auto output_accessor = output.accessor<int32_t, 1>();

    output_accessor[0] = 0;
    for (int32_t i = 0; i < num_partition_; ++i) {
        // Don't add placeholder features for empty partitions
        output_accessor[i + 1] = output_accessor[i] + static_cast<int32_t>(partitions_[i].size());
    }
    return output;
}

void SetUp() override {
        transformer_ = std::make_unique<FeatureTransformer>(num_partition_);
    }

TEST_F(FeatureTransformerTest, TestAdd) {
    std::vector<int> feature = {1, 5, 9, 1, 5};  // Test duplicates
    auto result = transformer_->add(feature);
    ASSERT_EQ(result.size(), feature.size());

    // First occurrence of each feature should get sequential indices
    auto first_result = result[0];  // for feature 1
    auto second_result = result[1]; // for feature 5
    auto third_result = result[2];  // for feature 9

    // Duplicate features should map to same indices
    EXPECT_EQ(result[3], first_result);  // duplicate 1
    EXPECT_EQ(result[4], second_result); // duplicate 5
}

TEST_F(FeatureTransformerTest, TestTransform) {
    std::vector<int> feature = {1, 5, 9};
    auto mixed_indices = transformer_->add(feature);
    transformer_->finalize();

    auto result = transformer_->transform(mixed_indices);
    ASSERT_EQ(result.size(), feature.size());

    // Transformed indices should be sequential and unique
    for (size_t i = 1; i < result.size(); ++i) {
        EXPECT_LT(result[i-1], result[i]);
    }
}

TEST_F(FeatureTransformerTest, TestUniqueFids) {
    std::vector<int> feature = {1, 5, 9, 1, 5};
    transformer_->add(feature);
    transformer_->finalize();

    auto unique_fids = transformer_->unique_fids();
    std::vector<bool> found(3, false);  // Should have 3 unique features

    for (int fid : unique_fids) {
        if (fid == 1 || fid == 5 || fid == 9) {
            found[fid == 1 ? 0 : (fid == 5 ? 1 : 2)] = true;
        }
    }

    // All unique features should be present
    for (bool f : found) {
        EXPECT_TRUE(f);
    }
}

TEST_F(FeatureTransformerTest, TestPartitionSplits) {
    std::vector<int> feature = {1, 5, 9};
    transformer_->add(feature);
    transformer_->finalize();

    auto splits = transformer_->partition_splits();
    ASSERT_EQ(splits.size(), num_partition_ + 1);
    EXPECT_EQ(splits[0], 0);  // First split should be 0

    // Splits should be monotonically increasing
    for (size_t i = 1; i < splits.size(); ++i) {
        EXPECT_LE(splits[i-1], splits[i]);
    }

    // Empty partitions should have size 1 (containing partition index)
    for (size_t i = 1; i < splits.size(); ++i) {
        EXPECT_GE(splits[i] - splits[i-1], 1);
    }
}

TEST_F(FeatureTransformerTest, TestClear) {
    std::vector<int> feature = {1, 5, 9};
    transformer_->add(feature);
    transformer_->finalize();

    transformer_->clear();
    EXPECT_DEATH(transformer_->transform(feature), ".*");  // Should assert since not finalized

    // After clear, should be able to add features again
    auto result = transformer_->add(feature);
    ASSERT_EQ(result.size(), feature.size());
}

TEST_F(FeatureTransformerTest, TestFinalization) {
    std::vector<int> feature = {1, 5, 9};
    transformer_->add(feature);

    // Before finalization
    EXPECT_DEATH(transformer_->transform(feature), ".*");
    EXPECT_DEATH(transformer_->unique_fids(), ".*");
    EXPECT_DEATH(transformer_->partition_splits(), ".*");

    transformer_->finalize();

    // After finalization
    EXPECT_DEATH(transformer_->add(feature), ".*");
}

int main(int argc, char **argv) {
    testing::InitGoogleTest(&argc, argv);
    return RUN_ALL_TESTS();
}

