				service.fgaService.client.(*MockFgaClient).On("Write", mock.Anything, mock.MatchedBy(func(req ClientWriteRequest) bool {
					return len(req.Writes) == 0 && len(req.Deletes) == 1
				})).Return(&ClientWriteResponse{}, nil).Once()

