            _timer.CaptureCompareUnits[0].CaptureCompareValue = 10;

            // Count up to 10
            for (int i = 0; i <= 10; i++)
            {
                Assert.Equal((ushort)i, _timer.TimerValue);
                _timer.Tick();
            }

            // Count down to 0
            for (int i = 9; i >= 0; i--)
            {
                Assert.Equal((ushort)i, _timer.TimerValue);
                _timer.Tick();
            }

            Assert.Equal(1, _timer.TimerValue); // Should start counting up again
        }

