constructor(context) {
        super(context);
        this.initializeImageAssets("capacitor");
    }

    /**
     * Render a capacitor element
     * @param {Object} element - The capacitor element to render
     * @param {Object} state - Current element state (hover, selected, etc.)
     */
render(element, state = {}) {
        if (!this.isImageLoaded()) {
            return; // Wait for images to load
        }

        const image = this.getCurrentImage(state);
        if (!image) {
            return;
        }

        const ctx = this.context;
        const x = element.position.x;
        const y = element.position.y;

        // Draw the capacitor image
        ctx.drawImage(image, x, y);

        // Draw the capacitor label if present
        if (element.id) {
            ctx.fillStyle = 'black';
            ctx.font = '12px Arial';
            ctx.fillText(element.id, x, y - 5);
        }
    }

constructor(context) {
        if (new.target === ElementRenderer) {
            throw new Error("Cannot instantiate abstract class ElementRenderer directly.");
        }
        this.context = context;
        this.images = {};
        this.imageLoaded = false;
        this.loadingPromise = null;
    }

    /**
     * Initialize all image assets for a component type
     * @param {string} type - The component type (e.g., 'resistor', 'capacitor')
     * @returns {Promise} Promise that resolves when all images are loaded
     */
initializeImageAssets(type) {
        if (this.loadingPromise) {
            return this.loadingPromise;
        }

        const variants = ["default", "hover", "selected", "hover_selected"];

        // Check if we're in a browser environment
        if (typeof window !== 'undefined' && window.Image) {
            const loadPromises = [];

            variants.forEach(variant => {
                const imagePath = getImagePath(type, variant);
                const img = new Image();

                const loadPromise = new Promise((resolve, reject) => {
                    img.onload = () => {
                        this.images[variant] = img;
                        if (variant === "default") {
                            this.imageLoaded = true;
                        }
                        resolve(img);
                    };

                    img.onerror = () => {
                        reject(new Error(`Failed to load image: ${imagePath}`));
                    };
                });

                img.src = imagePath;
                loadPromises.push(loadPromise);
            });

            this.loadingPromise = Promise.all(loadPromises);
        } else {
            // Node.js environment - create mock images for testing
            variants.forEach(variant => {
                const imagePath = getImagePath(type, variant);
                this.images[variant] = {
                    src: imagePath,
                    width: 50,
                    height: 50,
                    complete: true
                };
            });
            this.imageLoaded = true;
            this.loadingPromise = Promise.resolve(this.images);
        }

        return this.loadingPromise;
    }

