    /**
     * Render a junction element
     * @param {Object} element - The junction element to render
     * @param {Object} state - Current element state (hover, selected, etc.)
     */
render(element, state = {}) {
        if (!this.isImageLoaded()) {
            return; // Wait for images to load
        }

        const image = this.getCurrentImage(state);
        if (!image) {
            return;
        }

        const ctx = this.context;
        const x = element.position.x;
        const y = element.position.y;

        // Draw the junction image
        ctx.drawImage(image, x, y);

        // Draw the junction label if present
        if (element.id) {
            ctx.fillStyle = 'black';
            ctx.font = '12px Arial';
            ctx.fillText(element.id, x, y - 5);
        }
    }

constructor(context) {
        super(context);
        this.initializeImageAssets("resistor");
    }

    /**
     * Render a resistor element
     * @param {Object} element - The resistor element to render
     * @param {Object} state - Current element state (hover, selected, etc.)
     */
render(element, state = {}) {
        if (!this.isImageLoaded()) {
            return; // Wait for images to load
        }

        const image = this.getCurrentImage(state);
        if (!image) {
            return;
        }

        const ctx = this.context;
        const x = element.position.x;
        const y = element.position.y;

        // Draw the resistor image
        ctx.drawImage(image, x, y);

        // Draw the resistor label if present
        if (element.id) {
            ctx.fillStyle = 'black';
            ctx.font = '12px Arial';
            ctx.fillText(element.id, x, y - 5);
        }
    }

/**
 * Gets the base image name from a component type
 * @param {string} type - The component type (e.g., 'resistor', 'capacitor')
 * @returns {string} The base image name (e.g., 'R', 'C')
 */
function getBaseImageNameFromType(type) {
    if (!type || typeof type !== 'string') {
        throw new Error('Invalid or unknown type');
    }

    const normalizedType = type.toLowerCase();
    const baseName = TYPE_TO_IMAGE_MAP[normalizedType];

    if (!baseName) {
        throw new Error(`Invalid or unknown type: ${type}`);
    }

    return baseName;
}

/**
 * Generates an image path for a given component type and variant
 * @param {string} type - The component type (e.g., 'resistor', 'capacitor')
 * @param {string} variant - The image variant ('default', 'hover', 'selected', 'hover_selected')
 * @returns {string} The complete image path
 */
function getImagePath(type, variant = 'default') {
    if (!type || typeof type !== 'string') {
        throw new Error('Invalid or unknown type');
    }

    const base = getBaseImageNameFromType(type);
    const suffix = variant === 'default' ? '' : `_${variant}`;

    // Using a relative path that works in both browser and Node.js environments
    const imagePath = `../assets/${base}${suffix}.png`;

    return imagePath;
}

/**
 * Gets all available image variants for a component type
 * @param {string} type - The component type
 * @returns {Object} Object containing all variant paths
 */
function getAllImageVariants(type) {
    const variants = ['default', 'hover', 'selected', 'hover_selected'];
    const images = {};

    variants.forEach(variant => {
        images[variant] = getImagePath(type, variant);
    });

    return images;
}

variant => {
        images[variant] = getImagePath(type, variant);
    }

constructor() {
        this.calls = [];
    }

drawImage(...args) {
        this.calls.push({ method: 'drawImage', args });
    }

fillText(...args) {
        this.calls.push({ method: 'fillText', args });
    }

set fillStyle(value) {
        this.calls.push({ method: 'set fillStyle', value });
    }

set font(value) {
        this.calls.push({ method: 'set font', value });
    }

getCalls() {
        return this.calls;
    }

clearCalls() {
        this.calls = [];
    }

