def _extract_safety_plan_data(self, sheet) -> Dict[str, List[str]]:
        """Extract data from the safety plan sheet"""
        result = {}

        for column, ranges in self.safety_plan_ranges.items():
            column_data = []

            for start_row, end_row in ranges:
                for row in range(start_row, end_row + 1):
                    cell_value = sheet[f"{column}{row}"].value
                    if cell_value is not None:
                        column_data.append(str(cell_value))

            result[column] = column_data

        return result

def _extract_risk_assessment_data(self, sheet) -> Dict[str, List[str]]:
        """Extract data from the risk assessment sheet"""
        result = {}

        for column in self.risk_assessment_columns:
            column_data = []

            for row in self.risk_assessment_rows:
                cell_value = sheet[f"{column}{row}"].value
                if cell_value is not None:
                    column_data.append(str(cell_value))

            result[column] = column_data

        return result

def _extract_form_data(self, workbook) -> Dict[str, Any]:
        """Extract the form data (confirmed information) from the Excel file"""
        form_data: Dict[str, Any] = {}

        for sheet_name in workbook.sheetnames:
            sheet = workbook[sheet_name]

            project_name = sheet["I9"].value
            location = sheet["I11"].value
            period = sheet["I13"].value
            workers = sheet["Q15"].value

            if any([project_name, location, period, workers]):
                if project_name is not None:
                    form_data["project_name"] = str(project_name)
                if location is not None:
                    form_data["location"] = str(location)
                if period is not None:
                    form_data["period"] = str(period)
                if workers is not None and str(workers).isdigit():
                    form_data["workers"] = int(workers)
                break

        return form_data

def _generate_safety_plan_vba(self, safety_plan_data: Dict[str, List[str]]) -> str:
        """Generate VBA code for safety plan sheet"""
        vba_code = "    ' 安全施工計画書シートのデータ入力\n"

        for column, values in safety_plan_data.items():
            if not values:
                continue

            vba_code += f"    ' {column}列のデータ入力\n"

            row_ranges = self.safety_plan_ranges[column]
            current_row_idx = 0

            for start_row, end_row in row_ranges:
                range_values = []
                for row in range(start_row, end_row + 1):
                    if current_row_idx < len(values):
                        range_values.append(values[current_row_idx])
                        current_row_idx += 1
                    else:
                        break

                if range_values:
                    vba_code += f"    ' 行{start_row}-{end_row}のデータ\n"
                    for i, value in enumerate(range_values):
                        row = start_row + i
                        vba_code += f'    Worksheets("安全施工計画書").Range("{column}{row}").Value = "{value}"\n'

        return vba_code

def _generate_risk_assessment_vba(self, risk_assessment_data: Dict[str, List[str]]) -> str:
        """Generate VBA code for risk assessment sheet"""
        vba_code = "    ' リスクアセスメントシートのデータ入力\n"

        for column, values in risk_assessment_data.items():
            if not values:
                continue

            vba_code += f"    ' {column}列のデータ入力\n"

            for i, value in enumerate(values):
                if i < len(self.risk_assessment_rows):
                    row = self.risk_assessment_rows[i]
                    vba_code += f'    Worksheets("リスクアセスメント").Range("{column}{row}").Value = "{value}"\n'

        return vba_code

async def acu_stats():
    """Get ACU consumption statistics"""
    global llm_service
    if not llm_service:
        llm_service = LLMIntegration()
    return llm_service.get_acu_stats()

async def chat(request: ChatRequest):
    """
    Process chat messages and generate responses using multiple LLMs

    インタラクティブ質問プロセス（3回以上）:
    - 初回：工事名、施工場所、工期、作業員数など確定情報を聞く
    - 2回目以降：LLMが不足と判断した情報を追加で質問（Claude 3が担当）
    - 最終確認：入力項目を整理してユーザーに最終確認をする
    - VBAコード生成：確認後にコードを生成

    ワークフロー：チャット→追加質問→チャット→追加質問→チャット→情報生成→VBAコード生成
    """
    session_id = "default"  # Use a single session for simplicity

    if session_id not in conversation_store:
        conversation_store[session_id] = []
        question_round_store[session_id] = 0

    conversation_store[session_id].append(request.messages[-1])

    question_round_store[session_id] += 1
    current_round = question_round_store[session_id]

    if request.form_data:
        form_data_store[session_id] = request.form_data

    if request.file_data:
        excel_data_store[session_id] = request.file_data

    try:
        llm_responses = await llm_service.process_with_all_llms(
            conversation_store[session_id],
            excel_data_store.get(session_id),
            form_data_store.get(session_id)
        )

        if current_round == 1:
            system_message = Message(
                role=MessageRole.SYSTEM,
                content="あなたは工事現場の安全計画に関する情報を収集するアシスタントです。最初の質問として、工事名、施工場所、工期、作業員数などの基本情報を尋ねてください。"
            )

            temp_messages = [system_message] + conversation_store[session_id]

            claude_responses = await llm_service.process_with_all_llms(temp_messages)
            response_content = claude_responses[2]  # Claude's response (index 2)

            if not response_content or len(response_content.strip()) == 0:
                response_content = "工事名、施工場所、工期、作業員数などの確定情報を教えてください。"

        elif current_round < 4:
            response_content = llm_responses[2]  # Claude's response (index 2)

        elif current_round == 4:
            form_info = ""
            if session_id in form_data_store:
                form_data = form_data_store[session_id]
                form_info = f"""
                【確定情報】
                工事名: {form_data.get('project_name', '未入力')}
                施工場所: {form_data.get('location', '未入力')}
                工期: {form_data.get('period', '未入力')}
                作業者数: {form_data.get('workers', '未入力')}
                """

            conversation_summary = llm_responses[0]

            response_content = f"""
            これまでの情報を整理しました。以下の内容で最終確認をお願いします。

            {form_info}

            【会話から抽出した情報】
            {conversation_summary}

            この情報でVBAコードを生成してよろしいですか？
            不足している情報があれば教えてください。
            """

        else:
            if session_id in excel_data_store and session_id in form_data_store:
                last_user_message = request.messages[-1].content.lower()
                if "はい" in last_user_message or "ok" in last_user_message or "よろしい" in last_user_message:
                    vba_code = await llm_service.generate_vba_code(
                        conversation_store[session_id],
                        excel_data_store[session_id],
                        form_data_store[session_id]
                    )
                    response_content = f"VBAコードを生成しました。以下のコードをExcelマクロとして使用できます：\n\n```vba\n{vba_code}\n```"
                else:
                    response_content = llm_responses[2]
            else:
                response_content = "Excelファイルと必要な情報をすべて提供してください。VBAコードを生成するには、Excelファイルのアップロードと工事名、施工場所、工期、作業員数の情報が必要です。"

        assistant_message = Message(role=MessageRole.ASSISTANT, content=response_content)
        conversation_store[session_id].append(assistant_message)

        return {
            "message": assistant_message,
            "conversation": conversation_store[session_id],
            "round": current_round
        }

    except Exception as e:
        raise HTTPException(status_code=500, detail=f"LLM処理エラー: {str(e)}")

async def submit_form(form_data: FormData):
    """
    Submit form data with project details
    """
    try:
        session_id = "default"
        form_data_store[session_id] = form_data.dict()

        return {
            "message": "フォームデータが正常に保存されました。",
            "data": form_data.dict()
        }

    except Exception as e:
        raise HTTPException(status_code=500, detail=f"フォームデータ処理エラー: {str(e)}")

async def get_conversation():
    """
    Get current conversation history
    """
    session_id = "default"

    if session_id not in conversation_store:
        return {"conversation": []}

    return {"conversation": conversation_store[session_id]}

async def reset_conversation():
    """
    Reset the conversation and stored data
    """
    session_id = "default"

    if session_id in conversation_store:
        del conversation_store[session_id]

    if session_id in excel_data_store:
        del excel_data_store[session_id]

    if session_id in form_data_store:
        del form_data_store[session_id]

    if session_id in question_round_store:
        del question_round_store[session_id]

    return {"message": "会話とデータがリセットされました。"}

func displayTemplateContents(pipeline *parser.Pipeline, level int) {
	if pipeline == nil {
		return
	}

	for _, include := range pipeline.Includes {
		fmt.Printf("Template: %s (%s)\n", include.Path, include.Type)
		fmt.Println(strings.Repeat("-", len("Template: "+include.Path+" ("+include.Type+")")))
		fmt.Println(include.Content)
		fmt.Println()

		if include.Pipeline != nil {
			displayTemplateContents(include.Pipeline, level+1)
		}
	}
}

func buildTemplateInfoTree(pipeline *parser.Pipeline) []TemplateInfo {
	if pipeline == nil || len(pipeline.Includes) == 0 {
		return nil
	}

	result := []TemplateInfo{}

	for _, include := range pipeline.Includes {
		info := TemplateInfo{
			Path:    include.Path,
			Type:    include.Type,
			Content: include.Content,
		}

		if include.Pipeline != nil {
			info.Includes = buildTemplateInfoTree(include.Pipeline)
		}

		result = append(result, info)
	}

	return result
}

func displayTemplateJSON(pipeline *parser.Pipeline) {
	rootInfo := TemplateInfo{
		Path:     pipeline.FilePath,
		Type:     "root",
		Content:  "",
		Includes: buildTemplateInfoTree(pipeline),
	}

	jsonData, err := json.MarshalIndent(rootInfo, "", "  ")
	if err != nil {
		fmt.Printf("Error generating JSON: %v\n", err)
		return
	}

	fmt.Println(string(jsonData))
}

func displayTemplateYAML(pipeline *parser.Pipeline) {
	rootInfo := TemplateInfo{
		Path:     pipeline.FilePath,
		Type:     "root",
		Content:  "",
		Includes: buildTemplateInfoTree(pipeline),
	}

	yamlData, err := yaml.Marshal(rootInfo)
	if err != nil {
		fmt.Printf("Error generating YAML: %v\n", err)
		return
	}

	fmt.Println(string(yamlData))
}

func displayTemplateTable(pipeline *parser.Pipeline) {
	fmt.Println("| Template Path | Type | Included From |")
	fmt.Println("|--------------|------|---------------|")

	displayTemplateTableRows(pipeline, "")
}

func displayTemplateTableRows(pipeline *parser.Pipeline, parent string) {
	if pipeline == nil {
		return
	}

	for _, include := range pipeline.Includes {
		fmt.Printf("| %s | %s | %s |\n", include.Path, include.Type, parent)

		if include.Pipeline != nil {
			displayTemplateTableRows(include.Pipeline, include.Path)
		}
	}
}

func processIncludeMap(includeMap map[string]interface{}, parentFilePath string) *Include {
	include := &Include{}

	if localPath, ok := includeMap["local"]; ok {
		if localPathStr, ok := localPath.(string); ok {
			include.Type = "local"
			include.Path = localPathStr
		}
	}

	if filePath, ok := includeMap["file"]; ok {
		if filePathStr, ok := filePath.(string); ok {
			include.Type = "file"
			include.Path = filePathStr
			include.File = filePathStr
		}
	}

	if remotePath, ok := includeMap["remote"]; ok {
		if remotePathStr, ok := remotePath.(string); ok {
			include.Type = "remote"
			include.Path = remotePathStr
		}
	}

	if templatePath, ok := includeMap["template"]; ok {
		if templatePathStr, ok := templatePath.(string); ok {
			include.Type = "template"
			include.Path = templatePathStr
		}
	}

	if projectPath, ok := includeMap["project"]; ok {
		if projectPathStr, ok := projectPath.(string); ok {
			include.Type = "project"
			include.Project = projectPathStr

			if ref, ok := includeMap["ref"]; ok {
				if refStr, ok := ref.(string); ok {
					include.Ref = refStr
				}
			}

			if file, ok := includeMap["file"]; ok {
				if fileStr, ok := file.(string); ok {
					include.File = fileStr
					include.Path = fileStr
				}
			}
		}
	}

	return include
}

func isAbsolutePath(path string) bool {
	return filepath.IsAbs(path)
}

func getDirectoryPath(filePath string) string {
	return filepath.Dir(filePath)
}

func getFileContent(filePath string) string {
	content, err := ioutil.ReadFile(filePath)
	if err != nil {
		return fmt.Sprintf("Error reading file: %v", err)
	}
	return string(content)
}

func LoadIncludedTemplates(pipeline *Pipeline) error {
	for _, include := range pipeline.Includes {
		if include.Type == "local" {
			includePath := include.Path
			if !isAbsolutePath(includePath) {
				dir := getDirectoryPath(pipeline.FilePath)
				includePath = filepath.Join(dir, includePath)
			}

			if _, err := os.Stat(includePath); os.IsNotExist(err) {
				include.Content = fmt.Sprintf("Error: File '%s' does not exist", includePath)
				continue
			}

			includedPipeline, err := ParseFileWithIncludes(includePath, true)
			if err != nil {
				include.Content = fmt.Sprintf("Error parsing file: %v", err)
				continue
			}

			include.Content = getFileContent(includePath)
			include.Pipeline = includedPipeline
		} else if include.Type == "file" {
			includePath := include.Path
			if !isAbsolutePath(includePath) {
				dir := getDirectoryPath(pipeline.FilePath)
				includePath = filepath.Join(dir, includePath)
			}

			if _, err := os.Stat(includePath); os.IsNotExist(err) {
				include.Content = fmt.Sprintf("Error: File '%s' does not exist", includePath)
				continue
			}

			include.Content = getFileContent(includePath)
			includedPipeline, _ := ParseFileWithIncludes(includePath, true)
			include.Pipeline = includedPipeline
		} else if include.Type == "remote" || include.Type == "template" || include.Type == "project" {
			include.Content = fmt.Sprintf("Include type '%s' requires GitLab API access.\n", include.Type)
			if include.Type == "project" {
				include.Content += fmt.Sprintf("Project: %s\n", include.Project)
				if include.Ref != "" {
					include.Content += fmt.Sprintf("Ref: %s\n", include.Ref)
				}
				if include.File != "" {
					include.Content += fmt.Sprintf("File: %s\n", include.File)
				}
			} else {
				include.Content += fmt.Sprintf("Path: %s\n", include.Path)
			}
		}
	}

	return nil
}

func DisplayTemplateHierarchy(pipeline *Pipeline, indent string, visited map[string]bool) string {
	if pipeline == nil {
		return ""
	}

	if visited == nil {
		visited = make(map[string]bool)
	}

	if visited[pipeline.FilePath] {
		return indent + "└── " + filepath.Base(pipeline.FilePath) + " (circular reference)\n"
	}

	visited[pipeline.FilePath] = true

	result := indent + "└── " + filepath.Base(pipeline.FilePath) + "\n"

	if len(pipeline.Includes) > 0 {
		newIndent := indent + "    "
		for _, include := range pipeline.Includes {
			includeType := include.Type
			includePath := include.Path

			if include.Pipeline != nil {
				result += DisplayTemplateHierarchy(include.Pipeline, newIndent, visited)
			} else {
				result += newIndent + "└── " + includeType + ": " + includePath
				if include.Type == "project" {
					result += " (project: " + include.Project
					if include.Ref != "" {
						result += ", ref: " + include.Ref
					}
					if include.File != "" {
						result += ", file: " + include.File
					}
					result += ")"
				}
				result += "\n"
			}
		}
	}

	return result
}

def database_url_async(self) -> str:
        """Get async database URL with asyncpg driver."""
        if self.database_url.startswith("postgresql://"):
            return self.database_url.replace("postgresql://", "postgresql+asyncpg://")
        return self.database_url

constructor() {
    this.testResults = [];
    this.currentTestName = "";
  }

assertTrue(condition, message) {
    if (!condition) {
      throw new Error(`アサーション失敗: ${message}. 条件がfalseです`);
    }
  }

assertNotNull(value, message) {
    if (value === null || value === undefined) {
      throw new Error(
        `アサーション失敗: ${message}. 値がnullまたはundefinedです`,
      );
    }
  }

assertHasProperty(obj, property, message) {
    if (!obj || !obj.hasOwnProperty(property)) {
      throw new Error(
        `アサーション失敗: ${message}. プロパティ '${property}' が存在しません`,
      );
    }
  }

assertIsArray(value, message) {
    if (!Array.isArray(value)) {
      throw new Error(`アサーション失敗: ${message}. 値が配列ではありません`);
    }
  }

assertIsObject(value, message) {
    if (typeof value !== "object" || value === null || Array.isArray(value)) {
      throw new Error(
        `アサーション失敗: ${message}. 値がオブジェクトではありません`,
      );
    }
  }

assertIsString(value, message) {
    if (typeof value !== "string") {
      throw new Error(`アサーション失敗: ${message}. 値が文字列ではありません`);
    }
  }

  /**
   * 単一テストの実行
   */
runTest(testName, testFunction) {
    this.currentTestName = testName;
    const startTime = new Date();

    try {
      Logger.log(`[実際APIテスト開始] ${testName}`);
      const result = testFunction();

      // Promiseの場合は待機
      if (result && typeof result.then === "function") {
        result
          .then(() => {
            this.recordSuccess(testName, startTime);
          })
          .catch((error) => {
            this.recordFailure(testName, error, startTime);
          });
      } else {
        this.recordSuccess(testName, startTime);
      }
    } catch (error) {
      this.recordFailure(testName, error, startTime);
    }
  }

() => {
            this.recordSuccess(testName, startTime);
          }

(error) => {
            this.recordFailure(testName, error, startTime);
          }

recordSuccess(testName, startTime) {
    const duration = new Date() - startTime;
    this.testResults.push({
      name: testName,
      status: "PASS",
      duration: duration,
      message: "成功",
    });
    Logger.log(`[テスト成功] ${testName} (${duration}ms)`);
  }

recordFailure(testName, error, startTime) {
    const duration = new Date() - startTime;
    this.testResults.push({
      name: testName,
      status: "FAIL",
      duration: duration,
      message: error.message,
      error: error,
    });
    Logger.log(`[テスト失敗] ${testName}: ${error.message} (${duration}ms)`);
  }

(failure) => {
        Logger.log(`❌ ${failure.name}: ${failure.message}`);
      }

(success) => {
        Logger.log(`✅ ${success.name} (${success.duration}ms)`);
      }

