({ excuse, onSave, onDelete, isSaved = false, showDelete = false }) => {
  const [copied, setCopied] = useState(false);
  const [saved, setSaved] = useState(false);

  const colorClass = getToneColor(excuse.tone);
  const emoji = getToneEmoji(excuse.tone);

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(excuse.text);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (err) {
      console.error('Failed to copy:', err);
    }
  };

  const handleSave = () => {
    const success = saveExcuse(excuse);
    if (success) {
      setSaved(true);
      if (onSave) onSave(excuse);
      setTimeout(() => setSaved(false), 2000);
    }
  };

  const handleDelete = () => {
    if (window.confirm('Are you sure you want to delete this excuse?')) {
      const success = deleteSavedExcuse(excuse.id);
      if (success && onDelete) {
        onDelete(excuse.id);
      }
    }
  };

  const handleEmail = () => {
    const subject = `Sorry Not Sorry - ${excuse.tone} excuse`;
    const body = `Here's my excuse:\n\n"${excuse.text}"\n\nGenerated with Sorry Not Sorry - the excuse generator with attitude!`;
    const mailto = `mailto:?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
    window.open(mailto);
  };

  return (
    <div className={`card-glow p-6 hover:border-${colorClass} transition-all duration-300`}>
      {/* Header */}
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center space-x-2">
          <span className="text-xl">{emoji}</span>
          <span className={`font-bold uppercase tracking-wider text-${colorClass}`}>
            {excuse.tone}
          </span>
        </div>
        {isSaved && (
          <span className="text-xs text-gray-500">
            Saved {new Date(excuse.savedAt).toLocaleDateString()}
          </span>
        )}
      </div>

      {/* Excuse Text */}
      <div className="mb-6">
        <p className="text-lg leading-relaxed text-gray-100">
          "{excuse.text}"
        </p>
      </div>

      {/* Action Buttons */}
      <div className="flex flex-wrap gap-3">
        <button
          onClick={handleCopy}
          className={`neon-button text-${colorClass} text-sm flex items-center space-x-2 ${
            copied ? 'opacity-50' : ''
          }`}
          disabled={copied}
        >
          {copied ? <Check size={16} /> : <Copy size={16} />}
          <span>{copied ? 'Copied!' : 'Copy'}</span>
        </button>

        {!isSaved && (
          <button
            onClick={handleSave}
            className={`neon-button text-neon-green text-sm flex items-center space-x-2 ${
              saved ? 'opacity-50' : ''
            }`}
            disabled={saved}
          >
            {saved ? <Check size={16} /> : <Save size={16} />}
            <span>{saved ? 'Saved!' : 'Save'}</span>
          </button>
        )}

        <button
          onClick={handleEmail}
          className="neon-button text-neon-blue text-sm flex items-center space-x-2"
        >
          <Mail size={16} />
          <span>Email</span>
        </button>

        {showDelete && (
          <button
            onClick={handleDelete}
            className="neon-button text-neon-yellow text-sm flex items-center space-x-2 hover:text-red-400"
          >
            <Trash2 size={16} />
            <span>Delete</span>
          </button>
        )}
      </div>

      {/* Metadata */}
      <div className="mt-4 pt-4 border-t border-gray-700">
        <p className="text-xs text-gray-500">
          Generated {new Date(excuse.createdAt).toLocaleString()}
        </p>
      </div>
    </div>
  );
}

