                  key={item.name}
                  href={item.path}
                  className={`px-3 py-2 text-sm font-medium transition-all duration-300 ${
                    item.current
                      ? 'neon-text-pink border-b-2 border-neon-pink'
                      : 'text-gray-300 hover:neon-text-blue hover:scale-105'
                  }`}
                >
                  {item.name}
                </Link>
              ))}

              {/* User Info */}
              {userSession?.isLoggedIn ? (
                <div className="flex items-center space-x-4">
                  <div className="flex items-center space-x-2 text-neon-green">
                    <User size={16} />
                    <span className="text-sm">{userSession.email}</span>
                  </div>
                  <button
                    onClick={handleLogout}
                    className="flex items-center space-x-1 text-gray-400 hover:text-neon-yellow transition-colors"
                  >
                    <LogOut size={16} />
                    <span>Logout</span>
                  </button>
                </div>
              ) : (
                <Link
                  href="/account"
                  className="neon-button text-neon-pink hover:text-neon-blue text-sm"
                >
                  Login
                </Link>
              )}
            </div>

            {/* Mobile menu button */}
            <div className="md:hidden">
              <button
                onClick={() => setIsMenuOpen(!isMenuOpen)}
                className="text-neon-pink hover:text-neon-blue transition-colors"
              >
                {isMenuOpen ? <X size={24} /> : <Menu size={24} />}
              </button>
            </div>
          </div>
        </div>

        {/* Mobile Navigation */}
        {isMenuOpen && (
          <div className="md:hidden">
            <div className="px-2 pt-2 pb-3 space-y-1 bg-black border-t border-neon-pink/30">
              {navItems.map((item) => (
                <Link
                  key={item.name}
                  href={item.path}
                  className={`block px-3 py-2 text-base font-medium transition-all duration-300 ${
                    item.current
                      ? 'neon-text-pink border-l-4 border-neon-pink bg-gray-900'
                      : 'text-gray-300 hover:neon-text-blue hover:bg-gray-900'
                  }`}
                  onClick={() => setIsMenuOpen(false)}
                >
                  {item.name}
                </Link>
              ))}

              {/* Mobile User Info */}
              <div className="border-t border-gray-700 pt-4 mt-4">
                {userSession?.isLoggedIn ? (
                  <div className="space-y-2">
                    <div className="flex items-center space-x-2 px-3 py-2 text-neon-green">
                      <User size={16} />
                      <span className="text-sm">{userSession.email}</span>
                    </div>
                    <button
                      onClick={() => {
                        handleLogout();
                        setIsMenuOpen(false);
                      }}
                      className="flex items-center space-x-2 px-3 py-2 text-gray-400 hover:text-neon-yellow transition-colors w-full"
                    >
                      <LogOut size={16} />
                      <span>Logout</span>
                    </button>
                  </div>
                ) : (
                  <Link
                    href="/account"
                    className="block px-3 py-2 text-neon-pink hover:text-neon-blue transition-colors"
                    onClick={() => setIsMenuOpen(false)}
                  >
                    Login
                  </Link>
                )}
              </div>
            </div>
          </div>
        )}
      </nav>
    </header>
  );
}

