({ selectedTone, onToneChange, className = '' }) => {
  const toneDescriptions = {
    sassy: 'For when you\'re fabulous',
    witty: 'Clever comebacks',
    empathetic: 'Actually sorry',
    savage: 'No mercy',
  };

  return (
    <div className={`space-y-4 ${className}`}>
      <h3 className="text-lg font-semibold neon-text-yellow">Choose Your Tone</h3>
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        {availableTones.map((tone) => {
          const isSelected = selectedTone === tone;
          const colorClass = getToneColor(tone);
          const emoji = getToneEmoji(tone);

          return (
            <button
              key={tone}
              onClick={() => onToneChange(tone)}
              className={`p-4 rounded-lg border-2 transition-all duration-300 transform hover:scale-105 ${
                isSelected
                  ? `border-${colorClass} bg-${colorClass} bg-opacity-20 shadow-neon`
                  : 'border-gray-600 hover:border-gray-400'
              }`}
            >
              <div className="text-center">
                <div className="text-2xl mb-2">{emoji}</div>
                <div
                  className={`font-bold uppercase tracking-wider mb-1 ${
                    isSelected ? `text-${colorClass}` : 'text-white'
                  }`}
                >
                  {tone}
                </div>
                <div className="text-xs text-gray-400">
                  {toneDescriptions[tone]}
                </div>
              </div>
            </button>
          );
        })}
      </div>
    </div>
  );
}

