() => {
  const router = useRouter();
  const [userSession, setUserSessionState] = useState(null);
  const [subscriptionStatus, setSubscriptionStatus] = useState(null);
  const [remainingUsage, setRemainingUsage] = useState(null);
  const [isLoggingIn, setIsLoggingIn] = useState(false);
  const [email, setEmail] = useState('');
  const [isCheckingSubscription, setIsCheckingSubscription] = useState(false);
  const [isCreatingCheckout, setIsCreatingCheckout] = useState(false);
  const [checkoutError, setCheckoutError] = useState(null);

  useEffect(() => {
    loadUserData();
    checkUrlParams();
  }, []);

  const checkUrlParams = () => {
    const urlParams = new URLSearchParams(window.location.search);
    if (urlParams.get('success')) {
      // Payment successful
      setTimeout(() => {
        alert('🎉 Payment successful! Your subscription is now active.');
        loadUserData(); // Refresh subscription status
        router.replace('/account'); // Remove URL params
      }, 500);
    } else if (urlParams.get('canceled')) {
      // Payment canceled
      setTimeout(() => {
        alert('Payment was canceled. You can try again anytime!');
        router.replace('/account'); // Remove URL params
      }, 500);
    }
  };

  const loadUserData = async () => {
    setIsCheckingSubscription(true);

    try {
      const session = await getUserSessionWithStripe();
      const status = await getSubscriptionStatus(session?.email);
      const usage = await getRemainingUsage(session?.email);

      setUserSessionState(session);
      setSubscriptionStatus(status);
      setRemainingUsage(usage);
    } catch (error) {
      console.error('Error loading user data:', error);
    } finally {
      setIsCheckingSubscription(false);
    }
  };

  const handleLogin = async (e) => {
    e.preventDefault();
    if (!email.trim()) {
      alert('Please enter your email address');
      return;
    }

    setIsLoggingIn(true);

    // Simulate login delay
    setTimeout(async () => {
      setUserSession({
        isLoggedIn: true,
        email: email.trim(),
      });
      await loadUserData();
      setIsLoggingIn(false);
    }, 1000);
  };

  const handleLogout = () => {
    clearUserSession();
    setEmail('');
    setUserSessionState(null);
    setSubscriptionStatus(null);
    setRemainingUsage(null);
    router.push('/');
  };

  const handleUpgrade = async (plan) => {
    if (!userSession?.isLoggedIn) {
      alert('Please log in first to upgrade your plan');
      return;
    }

    if (subscriptionStatus?.plan === plan) {
      alert('You already have this plan!');
      return;
    }

    setIsCreatingCheckout(true);
    setCheckoutError(null);

    try {
      const checkoutUrl = await createStripeCheckout(plan, userSession.email);

      // Redirect to Stripe Checkout
      window.location.href = checkoutUrl;
    } catch (error) {
      console.error('Error creating checkout session:', error);
      setCheckoutError(error.message);
    } finally {
      setIsCreatingCheckout(false);
    }
  };

  const plans = [
    {
      name: 'Free',
      price: '$0',
      period: 'forever',
      features: [
        '10 excuses per session',
        'All 4 tones available',
        'Save & copy excuses',
        'Email sharing',
      ],
      limitations: [
        'Limited daily usage',
        'No priority support',
      ],
      current: subscriptionStatus?.plan === 'free',
      buttonText: 'Current Plan',
      disabled: true,
    },
    {
      name: 'Pro',
      price: '$4.99',
      period: 'per month',
      features: [
        'Unlimited excuse generation',
        'All tones & future updates',
        'Advanced customization',
        'Priority support',
        'Export to multiple formats',
        'Custom tone training',
      ],
      limitations: [],
      current: subscriptionStatus?.plan === 'pro',
      buttonText: subscriptionStatus?.plan === 'pro' ? 'Current Plan' : 'Upgrade to Pro',
      disabled: subscriptionStatus?.plan === 'pro' || subscriptionStatus?.plan === 'lifetime',
      onUpgrade: () => handleUpgrade('pro'),
      popular: true,
    },
    {
      name: 'Lifetime',
      price: '$19.99',
      period: 'one-time',
      features: [
        'Everything in Pro',
        'Lifetime access',
        'Future feature access',
        'Premium support',
        'Early access to new tools',
        'Commercial usage rights',
      ],
      limitations: [],
      current: subscriptionStatus?.plan === 'lifetime',
      buttonText: subscriptionStatus?.plan === 'lifetime' ? 'Current Plan' : 'Get Lifetime',
      disabled: subscriptionStatus?.plan === 'lifetime',
      onUpgrade: () => handleUpgrade('lifetime'),
      bestValue: true,
    },
  ];

  return (
    <div className="flex-1 py-12 px-4 sm:px-6 lg:px-8">
      <div className="max-w-4xl mx-auto">
        {/* Header */}
        <div className="text-center mb-12">
          <h1 className="text-4xl md:text-5xl font-bold mb-6">
            <span className="neon-text-pink">Account</span>
            <br />
            <span className="neon-text-blue glitch-text" data-text="MANAGEMENT">
              MANAGEMENT
            </span>
          </h1>
          <p className="text-xl text-gray-300 max-w-2xl mx-auto">
            Manage your account, subscription, and excuse preferences.
          </p>
        </div>

        {!userSession?.isLoggedIn ? (
          // Login Form
          <div className="max-w-md mx-auto">
            <div className="card-glow p-8">
              <h2 className="text-2xl font-bold neon-text-green mb-6 text-center">
                Sign In to Your Account
              </h2>
              <form onSubmit={handleLogin} className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-gray-300 mb-2">
                    Email Address
                  </label>
                  <input
                    type="email"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    placeholder="your@email.com"
                    className="w-full px-4 py-3 bg-gray-900 border border-gray-700 rounded-lg text-white placeholder-gray-500 focus:border-neon-pink focus:outline-none"
                    required
                  />
                </div>
                <button
                  type="submit"
                  disabled={isLoggingIn}
                  className={`w-full neon-button text-neon-pink flex items-center justify-center space-x-2 ${
                    isLoggingIn ? 'opacity-50 cursor-not-allowed' : ''
                  }`}
                >
                  <LogIn size={20} />
                  <span>{isLoggingIn ? 'Signing In...' : 'Sign In'}</span>
                </button>
              </form>
              <p className="text-center text-sm text-gray-400 mt-4">
                Enter any email to access your account and subscription features.
              </p>
            </div>
          </div>
        ) : (
          // Account Dashboard
          <div className="space-y-8">
            {/* User Info */}
            <div className="card-glow p-6">
              <div className="flex items-center justify-between">
                <div className="flex items-center space-x-4">
                  <div className="w-12 h-12 bg-neon-pink bg-opacity-20 rounded-full flex items-center justify-center">
                    <User className="text-neon-pink" size={24} />
                  </div>
                  <div>
                    <h3 className="text-xl font-bold text-white">{userSession.email}</h3>
                    <p className="text-gray-400">
                      Member since {new Date(userSession.loginDate).toLocaleDateString()}
                    </p>
                  </div>
                </div>
                <button
                  onClick={handleLogout}
                  className="neon-button text-neon-yellow flex items-center space-x-2"
                >
                  <LogOut size={16} />
                  <span>Sign Out</span>
                </button>
              </div>
            </div>

            {/* Subscription Status */}
            <div className="card-glow p-6">
              <div className="flex items-center justify-between mb-4">
                <div className="flex items-center space-x-3">
                  <Crown className="text-neon-yellow" size={24} />
                  <h3 className="text-xl font-bold">Subscription Status</h3>
                  {isCheckingSubscription && (
                    <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-neon-pink"></div>
                  )}
                </div>
                <span className={`px-3 py-1 rounded-full text-xs font-bold uppercase ${
                  subscriptionStatus?.plan === 'free' 
                    ? 'bg-gray-700 text-gray-300'
                    : subscriptionStatus?.plan === 'pro'
                    ? 'bg-neon-blue bg-opacity-20 text-neon-blue'
                    : 'bg-neon-yellow bg-opacity-20 text-neon-yellow'
                }`}>
                  {subscriptionStatus?.plan || 'free'}
                  {subscriptionStatus?.isStripeCustomer && (
                    <span className="ml-1">🎯</span>
                  )}
                </span>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <p className="text-sm text-gray-400 mb-1">Usage This Session</p>
                  <p className="neon-text-green text-lg">
                    {remainingUsage === 'unlimited' 
                      ? '∞ Unlimited' 
                      : `${subscriptionStatus?.usageCount || 0}/${subscriptionStatus?.maxUsage || 10} used`
                    }
                  </p>
                </div>
                {subscriptionStatus?.currentPeriodEnd && (
                  <div>
                    <p className="text-sm text-gray-400 mb-1">
                      {subscriptionStatus.plan === 'lifetime' ? 'Access' : 'Next Billing'}
                    </p>
                    <p className="text-white">
                      {subscriptionStatus.plan === 'lifetime' 
                        ? 'Lifetime Access' 
                        : new Date(subscriptionStatus.currentPeriodEnd).toLocaleDateString()
                      }
                    </p>
                  </div>
                )}
              </div>

              {subscriptionStatus?.plan === 'free' && !subscriptionStatus?.isStripeCustomer && (
                <div className="mt-4 p-4 bg-neon-pink bg-opacity-10 border border-neon-pink rounded-lg">
                  <p className="text-neon-pink text-sm">
                    💎 Upgrade to Pro for unlimited excuse generation and premium features!
                  </p>
                </div>
              )}

              {subscriptionStatus?.isStripeCustomer && (
                <div className="mt-4 p-4 bg-neon-green bg-opacity-10 border border-neon-green rounded-lg">
                  <div className="flex items-center space-x-2">
                    <CreditCard className="text-neon-green" size={16} />
                    <p className="text-neon-green text-sm">
                      Stripe Customer ID: {subscriptionStatus.customerId}
                    </p>
                  </div>
                </div>
              )}
            </div>

            {/* Error Display */}
            {checkoutError && (
              <div className="card-glow p-6 border-red-500">
                <div className="flex items-center space-x-3 mb-3">
                  <AlertCircle className="text-red-400" size={24} />
                  <h3 className="text-lg font-bold text-red-400">Payment Error</h3>
                </div>
                <p className="text-gray-300 mb-4">{checkoutError}</p>
                <button
                  onClick={() => setCheckoutError(null)}
                  className="neon-button text-neon-blue text-sm"
                >
                  Try Again
                </button>
              </div>
            )}

            {/* Pricing Plans */}
            <div className="space-y-6">
              <div className="text-center">
                <h2 className="text-3xl font-bold mb-4">
                  <span className="neon-text-yellow">Choose Your</span> Plan
                </h2>
                <p className="text-gray-400">
                  Upgrade for unlimited excuses and premium features
                </p>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                {plans.map((plan) => (
                  <div
                    key={plan.name}
                    className={`card-glow p-6 relative ${
                      plan.popular ? 'border-neon-blue' : plan.bestValue ? 'border-neon-yellow' : ''
                    }`}
                  >
                    {plan.popular && (
                      <div className="absolute -top-3 left-1/2 transform -translate-x-1/2">
                        <span className="bg-neon-blue px-3 py-1 rounded-full text-xs font-bold text-black">
                          MOST POPULAR
                        </span>
                      </div>
                    )}
                    {plan.bestValue && (
                      <div className="absolute -top-3 left-1/2 transform -translate-x-1/2">
                        <span className="bg-neon-yellow px-3 py-1 rounded-full text-xs font-bold text-black">
                          BEST VALUE
                        </span>
                      </div>
                    )}

                    <div className="text-center mb-6">
                      <h3 className="text-2xl font-bold mb-2">{plan.name}</h3>
                      <div className="text-3xl font-bold neon-text-pink mb-1">
                        {plan.price}
                      </div>
                      <div className="text-sm text-gray-400">{plan.period}</div>
                    </div>

                    <ul className="space-y-3 mb-6">
                      {plan.features.map((feature, index) => (
                        <li key={index} className="flex items-center space-x-2">
                          <Check className="text-neon-green" size={16} />
                          <span className="text-sm">{feature}</span>
                        </li>
                      ))}
                      {plan.limitations.map((limitation, index) => (
                        <li key={index} className="flex items-center space-x-2">
                          <X className="text-red-400" size={16} />
                          <span className="text-sm text-gray-500">{limitation}</span>
                        </li>
                      ))}
                    </ul>

                    <button
                      onClick={plan.onUpgrade}
                      disabled={plan.disabled || isCreatingCheckout}
                      className={`w-full neon-button ${
                        plan.current 
                          ? 'text-neon-green' 
                          : plan.popular 
                          ? 'text-neon-blue' 
                          : plan.bestValue 
                          ? 'text-neon-yellow' 
                          : 'text-neon-pink'
                      } ${(plan.disabled || isCreatingCheckout) ? 'opacity-50 cursor-not-allowed' : ''}`}
                    >
                      {isCreatingCheckout ? 'Creating Checkout...' : plan.buttonText}
                    </button>
                  </div>
                ))}
              </div>
            </div>

            {/* Stripe Integration Notice */}
            <div className="card-glow p-6 border-neon-blue">
              <div className="flex items-center space-x-3 mb-3">
                <CreditCard className="text-neon-blue" size={24} />
                <h3 className="text-lg font-bold neon-text-blue">Secure Payments by Stripe</h3>
              </div>
              <p className="text-gray-300">
                All payments are processed securely through Stripe. Your payment information is never stored on our servers. 
                Upgrade to unlock unlimited excuse generation and premium features.
              </p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

