() => {
  const router = useRouter();
  const [userInput, setUserInput] = useState('');
  const [selectedTone, setSelectedTone] = useState('sassy');
  const [isGenerating, setIsGenerating] = useState(false);
  const [canGenerate, setCanGenerate] = useState(true);
  const [subscriptionStatus, setSubscriptionStatus] = useState(null);
  const [remainingUsage, setRemainingUsage] = useState(null);
  const [isLoadingStatus, setIsLoadingStatus] = useState(true);

  useEffect(() => {
    loadSubscriptionStatus();
  }, []);

  const loadSubscriptionStatus = async () => {
    setIsLoadingStatus(true);

    try {
      const session = getUserSession();
      const userEmail = session?.email;

      const status = await getSubscriptionStatus(userEmail);
      const usage = await getRemainingUsage(userEmail);
      const canGen = await canGenerateExcuse(userEmail);

      setSubscriptionStatus(status);
      setRemainingUsage(usage);
      setCanGenerate(canGen);
    } catch (error) {
      console.error('Error loading subscription status:', error);
    } finally {
      setIsLoadingStatus(false);
    }
  };

  const handleGenerate = async () => {
    const session = getUserSession();
    const userEmail = session?.email;

    // Check if user can generate
    const canGen = await canGenerateExcuse(userEmail);
    if (!canGen) {
      return;
    }

    if (userInput.trim().length < 3) {
      alert('Please tell us what you need an excuse for!');
      return;
    }

    setIsGenerating(true);

    // Simulate API delay for better UX
    setTimeout(async () => {
      try {
        const excuses = generateExcuses(userInput, selectedTone, 3);

        // Increment usage count for free users
        await incrementUsageCount(userEmail);

        // Navigate to results page with generated excuses
        router.push({
          pathname: '/results',
          query: {
            excuses: JSON.stringify(excuses),
            userInput: userInput,
            tone: selectedTone,
          },
        });
      } catch (error) {
        console.error('Error generating excuses:', error);
        alert('Oops! Something went wrong. Please try again.');
      } finally {
        setIsGenerating(false);
      }
    }, 1500);
  };

  const placeholderTexts = [
    "being late to your best friend's wedding",
    "eating the last slice of pizza",
    "forgetting your anniversary",
    "not responding to texts for 3 days",
    "bailing on plans at the last minute",
    "accidentally liking your ex's photo from 2019",
    "showing up to a zoom call in pajamas",
    "being brutally honest about their cooking",
  ];

  const [placeholder, setPlaceholder] = useState(placeholderTexts[0]);

  useEffect(() => {
    const interval = setInterval(() => {
      setPlaceholder(placeholderTexts[Math.floor(Math.random() * placeholderTexts.length)]);
    }, 3000);
    return () => clearInterval(interval);
  }, []);

  return (
