        <div className="text-center mb-12">
          <h1 className="text-4xl md:text-5xl font-bold mb-6">
            <span className="neon-text-pink">Generate Your</span>
            <br />
            <span className="neon-text-blue glitch-text" data-text="EXCUSE">
              EXCUSE
            </span>
          </h1>
          <p className="text-xl text-gray-300 max-w-2xl mx-auto">
            Tell us what you need an excuse for, choose your tone, and we'll craft the perfect response.
          </p>
        </div>

        {/* Usage Status */}
        {!isLoadingStatus && subscriptionStatus && (
          <div className="mb-8 p-4 card-glow max-w-2xl mx-auto">
            <div className="flex items-center justify-between">
              <div className="flex items-center space-x-3">
                {subscriptionStatus.plan !== 'free' && <Crown className="text-neon-yellow" size={20} />}
                {subscriptionStatus.isStripeCustomer && (
                  <div className="w-2 h-2 bg-neon-green rounded-full animate-pulse" title="Stripe Customer"></div>
                )}
                <div>
                  <p className="text-sm text-gray-400">
                    {subscriptionStatus.plan === 'free' ? 'Free Plan' : `${subscriptionStatus.plan.toUpperCase()} Plan`}
                    {subscriptionStatus.isStripeCustomer && (
                      <span className="ml-2 text-xs text-neon-green">🎯 Stripe</span>
                    )}
                  </p>
                  <p className="neon-text-yellow">
                    {remainingUsage === 'unlimited' 
                      ? '∞ Unlimited Excuses' 
                      : `${remainingUsage} Excuses Remaining`
                    }
                  </p>
                </div>
              </div>
              {subscriptionStatus.plan === 'free' && remainingUsage <= 3 && (
                <button
                  onClick={() => router.push('/account')}
                  className="neon-button text-neon-pink text-sm"
                >
