            <div className="flex items-center space-x-3 mb-4">
              <AlertCircle className="text-neon-yellow" size={24} />
              <h3 className="text-lg font-bold neon-text-yellow">Oops! You've Hit Your Limit</h3>
            </div>
            <p className="text-gray-300 mb-4">
