                onClick={() => router.push('/account')}
                className="neon-button text-neon-yellow"
              >
                Get Lifetime Access
              </button>
            </div>
          </div>
        )}

        <div className="space-y-8">
          {/* Input Section */}
          <div className="card-glow p-8">
            <h2 className="text-2xl font-bold neon-text-green mb-6">
