            <span className="neon-text-pink">Saved</span>
            <br />
            <span className="neon-text-blue glitch-text" data-text="EXCUSES">
              EXCUSES
            </span>
          </h1>
          <p className="text-xl text-gray-300 max-w-2xl mx-auto">
            Your collection of perfectly crafted excuses, ready for any situation.
          </p>
        </div>

        {/* Stats */}
        <div className="grid grid-cols-2 md:grid-cols-5 gap-4 mb-8">
          <div className="card-glow p-4 text-center">
            <div className="text-2xl font-bold neon-text-pink">{totalCount}</div>
            <div className="text-sm text-gray-400">Total Saved</div>
          </div>
          {availableTones.map((tone) => (
            <div key={tone} className="card-glow p-4 text-center">
              <div className={`text-2xl font-bold text-${getToneColor(tone)}`}>
                {toneStats[tone] || 0}
              </div>
              <div className="text-sm text-gray-400 capitalize">{tone}</div>
            </div>
          ))}
        </div>

        {totalCount === 0 ? (
          // Empty State
          <div className="text-center py-20">
            <div className="text-6xl mb-6">📝</div>
            <h2 className="text-2xl font-bold neon-text-yellow mb-4">
              No Saved Excuses Yet
            </h2>
            <p className="text-gray-400 mb-8 max-w-md mx-auto">
              Start generating excuses and save your favorites for future use. 
              You'll never be caught without the perfect response!
            </p>
            <Link
              href="/generate"
              className="neon-button text-neon-pink inline-flex items-center space-x-2"
            >
              <Plus size={20} />
              <span>Generate Your First Excuse</span>
