// Helper function to create checkout session
async (priceId, customerId = null) => {
  const sessionConfig = {
    payment_method_types: ['card'],
    line_items: [
      {
        price: priceId,
        quantity: 1,
      },
    ],
    mode: priceId === STRIPE_CONFIG.products.lifetime.priceId ? 'payment' : 'subscription',
    success_url: STRIPE_CONFIG.successUrl,
    cancel_url: STRIPE_CONFIG.cancelUrl,
    metadata: {
      productType: priceId === STRIPE_CONFIG.products.lifetime.priceId ? 'lifetime' : 'pro',
    },
  };

  if (customerId) {
    sessionConfig.customer = customerId;
  } else {
    sessionConfig.customer_creation = 'always';
  }

  return await stripe.checkout.sessions.create(sessionConfig);
}

// Helper function to get customer by email
async (email) => {
  const customers = await stripe.customers.list({
    email: email,
    limit: 1,
  });
  return customers.data[0] || null;
}

// Helper function to get subscription status
async (customerId) => {
  try {
    const subscriptions = await stripe.subscriptions.list({
      customer: customerId,
      status: 'active',
      limit: 1,
    });

    if (subscriptions.data.length > 0) {
      const subscription = subscriptions.data[0];
      return {
        status: 'active',
        plan: 'pro',
        currentPeriodEnd: new Date(subscription.current_period_end * 1000),
        cancelAtPeriodEnd: subscription.cancel_at_period_end,
      };
    }

    // Check for lifetime purchases (one-time payments)
    const payments = await stripe.paymentIntents.list({
      customer: customerId,
      limit: 10,
    });

    const lifetimePayment = payments.data.find(
      payment => payment.status === 'succeeded' && 
      payment.metadata?.productType === 'lifetime'
    );

    if (lifetimePayment) {
      return {
        status: 'active',
        plan: 'lifetime',
        currentPeriodEnd: null, // Lifetime doesn't expire
        cancelAtPeriodEnd: false,
      };
    }

    return {
      status: 'inactive',
      plan: 'free',
      currentPeriodEnd: null,
      cancelAtPeriodEnd: false,
    };
  } catch (error) {
    console.error('Error getting subscription status:', error);
    return {
      status: 'inactive',
      plan: 'free',
      currentPeriodEnd: null,
      cancelAtPeriodEnd: false,
    };
  }
}

// Check subscription status via API
async (email) => {
  if (!email) return null;

  try {
    const response = await fetch('/api/subscription-status', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ email }),
    });

    if (!response.ok) {
      throw new Error('Failed to check subscription status');
    }

    const subscriptionData = await response.json();
    return subscriptionData;
  } catch (error) {
    console.error('Error checking Stripe subscription:', error);
    return null;
  }
}

