// Enhanced subscription status with Stripe integration
async (email = null) => {
  const session = getLocalUserSession();
  const userEmail = email || session?.email;

  if (!userEmail) {
    // Return default free plan for non-authenticated users
    return {
      plan: 'free',
      status: 'inactive',
      usageCount: 0,
      maxUsage: 10,
      isStripeCustomer: false,
    };
  }

  // Check Stripe subscription
  const stripeData = await checkStripeSubscriptionStatus(userEmail);

  if (stripeData && stripeData.plan !== 'free') {
    return {
      plan: stripeData.plan,
      status: stripeData.status,
      currentPeriodEnd: stripeData.currentPeriodEnd,
      cancelAtPeriodEnd: stripeData.cancelAtPeriodEnd,
      usageCount: 0, // Pro/Lifetime users have unlimited usage
      maxUsage: Infinity,
      isStripeCustomer: true,
      customerId: stripeData.customerId,
    };
  }

  // Fall back to local storage for free users
  const localStorageKey = 'sorry_not_sorry_subscription';
  const localData = localStorage.getItem(localStorageKey);

  if (localData) {
    try {
      const parsed = JSON.parse(localData);
      return {
        ...parsed,
        isStripeCustomer: false,
      };
    } catch {
      // Handle corrupted data
    }
  }

  // Default free plan
  const defaultSubscription = {
    plan: 'free',
    status: 'inactive',
    usageCount: 0,
    maxUsage: 10,
    isStripeCustomer: false,
  };

  localStorage.setItem(localStorageKey, JSON.stringify(defaultSubscription));
  return defaultSubscription;
}

// Check if user can generate excuse (with Stripe integration)
async (email = null) => {
  const status = await getSubscriptionStatus(email);

  if (status.plan === 'pro' || status.plan === 'lifetime') {
    return true;
  }

  return status.usageCount < status.maxUsage;
}

// Increment usage count (only for free users)
async (email = null) => {
  const status = await getSubscriptionStatus(email);

  // Don't increment for paid users
  if (status.isStripeCustomer && status.plan !== 'free') {
    return status;
  }

  // Increment local storage counter for free users
  const updatedStatus = {
    ...status,
    usageCount: status.usageCount + 1,
  };

  const localStorageKey = 'sorry_not_sorry_subscription';
  localStorage.setItem(localStorageKey, JSON.stringify(updatedStatus));

  return updatedStatus;
}

// Get remaining usage count
async (email = null) => {
  const status = await getSubscriptionStatus(email);

  if (status.plan === 'pro' || status.plan === 'lifetime') {
    return 'unlimited';
  }

  return Math.max(0, status.maxUsage - status.usageCount);
}

// Create Stripe checkout session
async (plan, email) => {
  if (!plan || !email) {
    throw new Error('Plan and email are required');
  }

  const priceIds = {
    pro: process.env.NEXT_PUBLIC_STRIPE_PRO_PRICE_ID,
    lifetime: process.env.NEXT_PUBLIC_STRIPE_LIFETIME_PRICE_ID,
  };

  const priceId = priceIds[plan];
  if (!priceId) {
    throw new Error('Invalid plan selected');
  }

  try {
    const response = await fetch('/api/create-checkout-session', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        priceId,
        email,
        plan,
      }),
    });

    if (!response.ok) {
      const errorData = await response.json();
      throw new Error(errorData.error || 'Failed to create checkout session');
    }

    const { url } = await response.json();
    return url;
  } catch (error) {
    console.error('Error creating checkout session:', error);
    throw error;
  }
}

