def _get_common_columns(self) -> list:
        """Get common columns between df1 and df2.

        Returns:
            List of column names present in both dataframes.

        """
        return list(set(self.df1.columns) & set(self.df2.columns))

def _infer_type_from_data(self, col: str) -> str:
        """Infer feature type from data characteristics.

        Args:
            col: Column name to infer type for.

        Returns:
            str: "categorical" or "continuous"

        """
        if pd.api.types.is_numeric_dtype(self.df1[col]) and pd.api.types.is_numeric_dtype(self.df2[col]):
            nunique = min(self.df1[col].nunique(), self.df2[col].nunique())
            if nunique <= 20:
                return "categorical"
            else:
                return "continuous"
        else:
            return "categorical"

def _get_feature_type(self, col: str) -> str:
        """Get feature type for a single column.

        Args:
            col: Column name to get type for.

        Returns:
            str: "categorical" or "continuous"

        """
        if isinstance(self.kind, dict):
            t = self.kind.get(col, None)
            if t is not None:
                return t

        return self._infer_type_from_data(col)

def simulate_moe_activations(strategy: SparsityAwarePartitioningStrategy, num_layers: int = 32, num_experts: int = 64, num_iterations: int = 50):
  """
    Simulate MoE model activations with realistic sparsity patterns.

    This demonstrates how expert activation patterns vary across layers
    and how the sparsity-aware strategy adapts to these patterns.
    """
  print("🧠 Simulating MoE activation patterns...")

  for iteration in range(num_iterations):
    for layer_id in range(num_layers):
      # Simulate realistic sparsity patterns
      if layer_id < 8:  # Early layers: more uniform expert usage
        num_active_experts = min(8, num_experts)
        expert_indices = list(range(num_active_experts))
      elif layer_id < 24:  # Middle layers: typical top-k routing
        num_active_experts = 2  # Top-2 routing
        # Some experts are more popular than others
        if iteration % 3 == 0:
          expert_indices = [0, 1]  # Popular experts
        elif iteration % 3 == 1:
          expert_indices = [2, 3]  # Less popular
        else:
          expert_indices = [1, 4]  # Mixed
      else:  # Later layers: more sparse, specialized experts
        num_active_experts = 1
        expert_indices = [iteration % 8]  # Rotating through first 8 experts

      # Create realistic token distribution
      tokens_per_expert = {}
      total_tokens = 8 + (iteration%4)  # Varying batch sizes

      for i, expert_id in enumerate(expert_indices):
        # Uneven token distribution (realistic for MoE routing)
        if i == 0:
          tokens_per_expert[expert_id] = int(total_tokens*0.7)
        else:
          tokens_per_expert[expert_id] = int(total_tokens*0.3/(len(expert_indices) - 1))

      layer_outputs = {
        'layer_id': layer_id, 'expert_indices': expert_indices, 'tokens_per_expert': tokens_per_expert, 'total_tokens': total_tokens, 'num_experts': num_experts,
        'timestamp': time.time() + iteration*0.1
      }

      strategy.collect_activations(layer_outputs)

    # Check for rebalancing trigger
    if strategy.should_rebalance():
      print(f"⚖️  Rebalancing triggered at iteration {iteration}")

    # Print progress
    if (iteration+1) % 10 == 0:
      print(f"   Processed {iteration + 1}/{num_iterations} iterations")

async def _collect_sparsity_activations(self, shard: Shard, result: any, inference_state: Optional[dict]):
    """
    Collect activation statistics for sparsity-aware load balancing.

    This method extracts expert activation information from inference results
    and forwards it to the sparsity-aware partitioning strategy if enabled.
    """
    if not isinstance(self.partitioning_strategy, SparsityAwarePartitioningStrategy):
      return

    try:
      # Extract MoE-specific information from inference results
      # The exact format depends on the inference engine implementation
      layer_outputs = {}

      # For MoE models, check if the inference state contains expert routing info
      if inference_state and 'expert_routing' in inference_state:
        routing_info = inference_state['expert_routing']
        layer_outputs = {
          'layer_id': shard.start_layer if hasattr(shard, 'start_layer') else 0, 'expert_indices': routing_info.get('selected_experts', []), 'expert_weights': routing_info.get('expert_weights', []),
          'tokens_per_expert': routing_info.get('tokens_per_expert', {}), 'total_tokens': routing_info.get('total_tokens', 1), 'num_experts': routing_info.get('num_experts',
                                                                                                                                                               8), 'timestamp': time.time()
        }
      else:
        # Fallback: try to infer from result structure
        # This is a simplified heuristic - in practice, you'd need to examine
        # the actual inference engine outputs for MoE models
        if hasattr(result, 'shape') and len(result.shape) > 1:
          # Simple heuristic: assume some level of sparsity for MoE models
          layer_outputs = {
            'layer_id': shard.start_layer if hasattr(shard, 'start_layer') else 0,
            'expert_indices': list(range(2)),  # Assume top-2 routing
            'expert_weights': [0.6, 0.4],  # Dummy weights
            'tokens_per_expert': {0: 1, 1: 1},
            'total_tokens': result.shape[0] if hasattr(result, 'shape') else 1,
            'num_experts': 8,  # Common MoE configuration
            'timestamp': time.time()
          }

      if layer_outputs:
        self.partitioning_strategy.collect_activations(layer_outputs)

        # Trigger rebalancing check if needed
        if self.partitioning_strategy.should_rebalance():
          if DEBUG >= 1:
            print(f"Sparsity-aware rebalancing triggered for layer {layer_outputs.get('layer_id')}")
          # Note: Actual rebalancing would require coordination across nodes
          # For MVP, we just log the event

    except Exception as e:
      if DEBUG >= 2:
        print(f"Error collecting sparsity activations: {e}")
        # Don't let sparsity collection errors break inference

def get_expert_affinity_groups(self) -> Dict[str, List[int]]:
    """
    Identify groups of experts that are frequently co-activated.

    Returns:
        Dictionary mapping group_id to list of expert_ids that should be 
        placed on the same device to minimize communication
    """
    if not self.enabled:
      return {}

    affinity_groups = {}

    # For each layer, find co-activation patterns
    for layer_id in self.activation_history:
      layer_experts = list(self.activation_history[layer_id].keys())

      if len(layer_experts) < 2:
        continue

      # Simple co-activation heuristic: experts active in similar time windows
      co_activation_matrix = {}

      for expert1 in layer_experts:
        for expert2 in layer_experts:
          # Skip duplicate pairs (ensure consistent ordering regardless of type)
          try:
            if expert1 >= expert2:
              continue
          except TypeError:
            # Handle mixed types by converting to string for comparison
            if str(expert1) >= str(expert2):
              continue

          # Count overlapping activation windows
          hist1 = set(self.activation_history[layer_id][expert1])
          hist2 = set(self.activation_history[layer_id][expert2])

          if hist1 and hist2:
            overlap = len(hist1.intersection(hist2))
            total = len(hist1.union(hist2))
            co_activation_ratio = overlap/total if total > 0 else 0.0

            if co_activation_ratio > 0.3:  # Threshold for co-activation
              # Create group key handling mixed types
              try:
                min_expert, max_expert = min(expert1, expert2), max(expert1, expert2)
              except TypeError:
                # Handle mixed types by sorting as strings
                sorted_experts = sorted([expert1, expert2], key=str)
                min_expert, max_expert = sorted_experts[0], sorted_experts[1]

              group_key = f"layer_{layer_id}_group_{min_expert}_{max_expert}"
              affinity_groups[group_key] = [expert1, expert2]

    return affinity_groups

def tearDown(self):
    """Clean up test environment."""
    if 'EXO_SPARSITY_AWARE' in os.environ:
      del os.environ['EXO_SPARSITY_AWARE']

def test_should_rebalance_cooldown(self):
    """Test that rebalancing respects cooldown period."""
    # Add some activation data to trigger potential rebalancing
    for i in range(5):
      activation = {'layer_id': i, 'expert_indices': [0, 1] if i % 2 == 0 else [2, 3, 4, 5], 'total_tokens': 8, 'timestamp': time.time()}
      self.strategy.collect_activations(activation)

    # First call might trigger rebalance
    first_rebalance = self.strategy.should_rebalance()

    # Immediate second call should be blocked by cooldown
    second_rebalance = self.strategy.should_rebalance()

    if first_rebalance:
      self.assertFalse(second_rebalance)

