// Helper functions for formatting responses
func formatProjectsV2Response(projects []struct {
	ID     githubv4.ID
	Title  githubv4.String
	Number githubv4.Int
	URL    githubv4.String
	State  githubv4.String
}) string {
	if len(projects) == 0 {
		return "No Projects v2 found."
	}

	result := fmt.Sprintf("Found %d Projects v2:\n\n", len(projects))
	for _, project := range projects {
		result += fmt.Sprintf("- **%s** (#%d)\n", project.Title, project.Number)
		result += fmt.Sprintf("  - ID: %s\n", project.ID)
		result += fmt.Sprintf("  - State: %s\n", project.State)
		result += fmt.Sprintf("  - URL: %s\n\n", project.URL)
	}
	return result
}

func formatSingleProjectV2Response(project struct {
	ID     githubv4.ID
	Title  githubv4.String
	Number githubv4.Int
	URL    githubv4.String
	State  githubv4.String
	Public githubv4.Boolean
	Fields struct {
		Nodes []struct {
			ID   githubv4.ID
			Name githubv4.String
		}
	} `graphql:"fields(first: 20)"`
}) string {
	result := fmt.Sprintf("**%s** (#%d)\n", project.Title, project.Number)
	result += fmt.Sprintf("- ID: %s\n", project.ID)
	result += fmt.Sprintf("- State: %s\n", project.State)
	result += fmt.Sprintf("- Public: %t\n", project.Public)
	result += fmt.Sprintf("- URL: %s\n", project.URL)

	if len(project.Fields.Nodes) > 0 {
		result += "\n**Custom Fields:**\n"
		for _, field := range project.Fields.Nodes {
			result += fmt.Sprintf("- %s (ID: %s)\n", field.Name, field.ID)
		}
	}

	return result
}

func Test_GetProjectV2(t *testing.T) {
	// Verify tool definition once
	mockClient := githubv4.NewClient(nil)
	tool, _ := GetProjectV2(stubGetGQLClientFn(mockClient), translations.NullTranslationHelper)
	require.NoError(t, toolsnaps.Test(tool.Name, tool))

	assert.Equal(t, "get_project_v2", tool.Name)
	assert.NotEmpty(t, tool.Description)
	assert.Contains(t, tool.InputSchema.Properties, "project_id")
	assert.ElementsMatch(t, tool.InputSchema.Required, []string{"project_id"})
}

// RequiredInt64 is a helper function that can be used to fetch a requested parameter from the request.
// It does the following checks:
// 1. Checks if the parameter is present in the request.
// 2. Checks if the parameter is of the expected type.
// 3. Checks if the parameter is not empty, i.e: non-zero value
func RequiredInt64(r mcp.CallToolRequest, p string) (int64, error) {
	v, err := RequiredParam[float64](r, p)
	if err != nil {
		return 0, err
	}
	return int64(v), nil
}

private async Task InitializeStorageDirectories()
        {
            try
            {
                string filesDir = OmniPaths.GetPath(OmniPaths.GlobalPaths.KliveCloudFilesDirectory);
                string metadataDir = OmniPaths.GetPath(OmniPaths.GlobalPaths.KliveCloudMetadataDirectory);
                string folderPermissionsDir = OmniPaths.GetPath(OmniPaths.GlobalPaths.KliveCloudFolderPermissionsDirectory);

                await dataHandler.CreateDirectory(filesDir);
                await dataHandler.CreateDirectory(metadataDir);
                await dataHandler.CreateDirectory(folderPermissionsDir);

                ServiceLog("Storage directories initialized");
            }
            catch (Exception ex)
            {
                ServiceLogError(ex, "Failed to initialize storage directories");
                throw;
            }
        }

private async Task SetupFileTransferRoutes()
        {
            try
            {
                // Route to list all files
                await kliveAPI.CreateRoute("klivecloud/allfiles", async (req) =>
                {
                    await HandleGetAllFiles(req);
                }, HttpMethod.Get, KMProfileManager.KMPermissions.Guest);

                // Route to create folder
                await kliveAPI.CreateRoute("klivecloud/makefolder", async (req) =>
                {
                    await HandleMakeFolder(req);
                }, HttpMethod.Post, KMProfileManager.KMPermissions.Guest);

                // Route to upload files
                await kliveAPI.CreateRoute("klivecloud/uploadfiles", async (req) =>
                {
                    await HandleUploadFiles(req);
                }, HttpMethod.Post, KMProfileManager.KMPermissions.Guest);

                // Route to download file
                await kliveAPI.CreateRoute("klivecloud/downloadfile", async (req) =>
                {
                    await HandleDownloadFile(req);
                }, HttpMethod.Get, KMProfileManager.KMPermissions.Guest);

                // Route to set folder permissions
                await kliveAPI.CreateRoute("klivecloud/setfolderpermissions", async (req) =>
                {
                    await HandleSetFolderPermissions(req);
                }, HttpMethod.Post, KMProfileManager.KMPermissions.Guest);

                ServiceLog("File transfer routes created successfully");
            }
            catch (Exception ex)
            {
                ServiceLogError(ex, "Failed to setup file transfer routes");
                throw;
            }
        }

private async Task HandleGetAllFiles(KliveAPI.KliveAPI.UserRequest req)
        {
            try
            {
                string metadataDir = OmniPaths.GetPath(OmniPaths.GlobalPaths.KliveCloudMetadataDirectory);
                var allFiles = new List<FileMetadata>();

                if (Directory.Exists(metadataDir))
                {
                    string[] metadataFiles = Directory.GetFiles(metadataDir, "*.json");

                    foreach (string metadataFile in metadataFiles)
                    {
                        try
                        {
                            var metadata = await dataHandler.ReadAndDeserialiseDataFromFile<FileMetadata>(metadataFile);

                            // Check if user has access to this file's folder
                            if (await CheckFolderAccess(metadata.RelativePath, req.user))
                            {
                                allFiles.Add(metadata);
                            }
                        }
                        catch (Exception ex)
                        {
                            ServiceLog($"Failed to read metadata file {metadataFile}: {ex.Message}");
                        }
                    }
                }

                await req.ReturnResponse(JsonConvert.SerializeObject(allFiles), "application/json");
                ServiceLog($"Listed {allFiles.Count} accessible files for user {req.user?.Name ?? "unknown"}");
            }
            catch (Exception ex)
            {
                ServiceLogError(ex, "Error handling get all files request");
                await req.ReturnResponse("Error retrieving files", "text/plain", null, HttpStatusCode.InternalServerError);
            }
        }

private async Task HandleMakeFolder(KliveAPI.KliveAPI.UserRequest req)
        {
            try
            {
                string folderPath = req.userParameters.Get("path") ?? "";

                if (string.IsNullOrEmpty(folderPath))
                {
                    await req.ReturnResponse("Path parameter is required", "text/plain", null, HttpStatusCode.BadRequest);
                    return;
                }

                // Sanitize path to prevent directory traversal
                folderPath = SanitizePath(folderPath);

                // Check parent folder access
                string parentPath = Path.GetDirectoryName(folderPath) ?? "";
                if (!await CheckFolderAccess(parentPath, req.user))
                {
                    await req.ReturnResponse("Access denied to parent folder", "text/plain", null, HttpStatusCode.Forbidden);
                    return;
                }

                string fullPath = Path.Combine(OmniPaths.GetPath(OmniPaths.GlobalPaths.KliveCloudFilesDirectory), folderPath);

                await dataHandler.CreateDirectory(fullPath);

                await req.ReturnResponse($"Folder created: {folderPath}", "text/plain");
                ServiceLog($"Folder created: {folderPath} by user {req.user?.Name ?? "unknown"}");
            }
            catch (Exception ex)
            {
                ServiceLogError(ex, "Error handling make folder request");
                await req.ReturnResponse("Error creating folder", "text/plain", null, HttpStatusCode.InternalServerError);
            }
        }

private async Task HandleUploadFiles(KliveAPI.KliveAPI.UserRequest req)
        {
            try
            {
                // Handle base64 encoded file content in the request body
                // This supports all file types (.zip, .png, etc.) through Base64 encoding

                if (string.IsNullOrEmpty(req.userMessageContent))
                {
                    await req.ReturnResponse("No file data provided", "text/plain", null, HttpStatusCode.BadRequest);
                    return;
                }

                dynamic uploadData = JsonConvert.DeserializeObject(req.userMessageContent);
                string fileName = uploadData.fileName?.ToString() ?? "";
                string fileContent = uploadData.fileContent?.ToString() ?? "";
                string relativePath = uploadData.path?.ToString() ?? "";

                if (string.IsNullOrEmpty(fileName) || string.IsNullOrEmpty(fileContent))
                {
                    await req.ReturnResponse("fileName and fileContent are required", "text/plain", null, HttpStatusCode.BadRequest);
                    return;
                }

                // Sanitize paths
                fileName = SanitizeFileName(fileName);
                relativePath = SanitizePath(relativePath);

                // Check folder access permission
                if (!await CheckFolderAccess(relativePath, req.user))
                {
                    await req.ReturnResponse("Access denied to target folder", "text/plain", null, HttpStatusCode.Forbidden);
                    return;
                }

                // Create file metadata
                string fileId = RandomGeneration.GenerateRandomLengthOfNumbers(20);
                byte[] fileBytes = Convert.FromBase64String(fileContent);
                string fileHash = CalculateFileHash(fileBytes);

                var metadata = new FileMetadata
                {
                    FileId = fileId,
                    FileName = fileName,
                    RelativePath = relativePath,
                    FileSize = fileBytes.Length,
                    ContentType = GetContentType(fileName),
                    UploadedBy = req.user?.Name ?? "unknown",
                    UploaderUserId = req.user?.UserID ?? "unknown",
                    UploadTime = DateTime.Now,
                    FileHash = fileHash
                };

                // Save file
                string fullFilePath = Path.Combine(OmniPaths.GetPath(OmniPaths.GlobalPaths.KliveCloudFilesDirectory), relativePath, fileName);
                metadata.FilePath = fullFilePath;

                // Ensure directory exists
                string directory = Path.GetDirectoryName(fullFilePath);
                if (!string.IsNullOrEmpty(directory))
                {
                    await dataHandler.CreateDirectory(directory);
                }

                await dataHandler.WriteBytesToFile(fullFilePath, fileBytes);

                // Save metadata
                string metadataPath = Path.Combine(OmniPaths.GetPath(OmniPaths.GlobalPaths.KliveCloudMetadataDirectory), $"{fileId}.json");
                await dataHandler.SerialiseObjectToFile(metadataPath, metadata);

                await req.ReturnResponse(JsonConvert.SerializeObject(new { fileId = fileId, message = "File uploaded successfully" }), "application/json");
                ServiceLog($"File uploaded: {fileName} by user {req.user?.Name ?? "unknown"}");
            }
            catch (Exception ex)
            {
                ServiceLogError(ex, "Error handling upload files request");
                await req.ReturnResponse("Error uploading file", "text/plain", null, HttpStatusCode.InternalServerError);
            }
        }

private async Task HandleDownloadFile(KliveAPI.KliveAPI.UserRequest req)
        {
            try
            {
                string fileId = req.userParameters.Get("fileId") ?? "";

                if (string.IsNullOrEmpty(fileId))
                {
                    await req.ReturnResponse("fileId parameter is required", "text/plain", null, HttpStatusCode.BadRequest);
                    return;
                }

                // Get metadata
                string metadataPath = Path.Combine(OmniPaths.GetPath(OmniPaths.GlobalPaths.KliveCloudMetadataDirectory), $"{fileId}.json");

                if (!File.Exists(metadataPath))
                {
                    await req.ReturnResponse("File not found", "text/plain", null, HttpStatusCode.NotFound);
                    return;
                }

                var metadata = await dataHandler.ReadAndDeserialiseDataFromFile<FileMetadata>(metadataPath);

                // Check folder access permission
                if (!await CheckFolderAccess(metadata.RelativePath, req.user))
                {
                    await req.ReturnResponse("Access denied to file's folder", "text/plain", null, HttpStatusCode.Forbidden);
                    return;
                }

                if (!File.Exists(metadata.FilePath))
                {
                    await req.ReturnResponse("File data not found", "text/plain", null, HttpStatusCode.NotFound);
                    return;
                }

                // Read and return file
                byte[] fileBytes = await dataHandler.ReadBytesFromFile(metadata.FilePath);
                string base64Content = Convert.ToBase64String(fileBytes);

                var downloadResponse = new
                {
                    fileName = metadata.FileName,
                    contentType = metadata.ContentType,
                    fileSize = metadata.FileSize,
                    fileContent = base64Content
                };

                await req.ReturnResponse(JsonConvert.SerializeObject(downloadResponse), "application/json");
                ServiceLog($"File downloaded: {metadata.FileName} by user {req.user?.Name ?? "unknown"}");
            }
            catch (Exception ex)
            {
                ServiceLogError(ex, "Error handling download file request");
                await req.ReturnResponse("Error downloading file", "text/plain", null, HttpStatusCode.InternalServerError);
            }
        }

private string SanitizeFileName(string fileName)
        {
            if (string.IsNullOrEmpty(fileName)) return "";

            // Remove invalid filename characters
            foreach (char c in Path.GetInvalidFileNameChars())
            {
                fileName = fileName.Replace(c, '_');
            }

            return fileName;
        }

private string CalculateFileHash(byte[] fileBytes)
        {
            using (var sha256 = SHA256.Create())
            {
                byte[] hashBytes = sha256.ComputeHash(fileBytes);
                return Convert.ToBase64String(hashBytes);
            }
        }

private async Task HandleSetFolderPermissions(KliveAPI.KliveAPI.UserRequest req)
        {
            try
            {
                string folderPath = req.userParameters.Get("path") ?? "";
                string permissionLevel = req.userParameters.Get("permission") ?? "";

                if (string.IsNullOrEmpty(folderPath))
                {
                    await req.ReturnResponse("Path parameter is required", "text/plain", null, HttpStatusCode.BadRequest);
                    return;
                }

                if (string.IsNullOrEmpty(permissionLevel) || !int.TryParse(permissionLevel, out int permLevel))
                {
                    await req.ReturnResponse("Valid permission level (0-5) is required", "text/plain", null, HttpStatusCode.BadRequest);
                    return;
                }

                var requestedPermission = (KMProfileManager.KMPermissions)permLevel;

                // Users can only set permissions to their level or below
                if (req.user?.KlivesManagementRank < requestedPermission)
                {
                    await req.ReturnResponse("Cannot set permission level higher than your own", "text/plain", null, HttpStatusCode.Forbidden);
                    return;
                }

                // Sanitize path
                folderPath = SanitizePath(folderPath);

                var folderPermissions = new FolderPermissions
                {
                    FolderPath = folderPath,
                    RequiredPermission = requestedPermission,
                    SetBy = req.user?.Name ?? "unknown",
                    SetByUserId = req.user?.UserID ?? "unknown",
                    SetTime = DateTime.Now
                };

                // Save folder permissions
                string permissionsPath = Path.Combine(OmniPaths.GetPath(OmniPaths.GlobalPaths.KliveCloudFolderPermissionsDirectory), 
                    $"{folderPath.Replace("/", "_").Replace("\\", "_")}.json");

                await dataHandler.SerialiseObjectToFile(permissionsPath, folderPermissions);

                await req.ReturnResponse($"Folder permissions set: {folderPath} requires {requestedPermission} level", "text/plain");
                ServiceLog($"Folder permissions set for {folderPath} to {requestedPermission} by user {req.user?.Name ?? "unknown"}");
            }
            catch (Exception ex)
            {
                ServiceLogError(ex, "Error handling set folder permissions request");
                await req.ReturnResponse("Error setting folder permissions", "text/plain", null, HttpStatusCode.InternalServerError);
            }
        }

constructor() {
    this.sessionData = this.initializeSession();
    this.playerMetrics = this.loadPlayerMetrics();
    this.retentionData = this.loadRetentionData();
    this.performanceData = this.loadPerformanceData();

    this.initializeEventListeners();
    this.startSessionTracking();
  }

  /**
   * Load or initialize player metrics
   */
loadPlayerMetrics() {
    const stored = localStorage.getItem('sp_sim_player_metrics');
    if (stored) {
      return JSON.parse(stored);
    }

    return {
      totalSessions: 0,
      totalPlaytime: 0, // minutes
      averageSessionLength: 0,
      gamesCompleted: 0,
      gamesAbandoned: 0,
      retentionRate: 0,

      // Decision making patterns
      decisionSpeed: [], // time taken per decision
      decisionTypes: {}, // count of each decision type
      policyPreferences: {}, // preferred policy types

      // Performance metrics
      averageApproval: [],
      economicPerformance: [],
      crisisManagementScore: 0,
      learningProgression: 0,

      // Behavioral patterns
      sessionTimes: [], // when player typically plays
      preferredDifficulty: 'normal',
      featureUsage: {}, // which features are used most

      lastUpdated: Date.now(),
    };
  }

  /**
   * Load retention data
   */
loadRetentionData() {
    const stored = localStorage.getItem('sp_sim_retention_data');
    if (stored) {
      return JSON.parse(stored);
    }

    return {
      firstSession: Date.now(),
      lastSession: Date.now(),
      sessionsPerDay: [],
      weeklyRetention: [],
      monthlyRetention: [],
      returningPlayer: false,
      churnRisk: 'low', // low, medium, high
      engagementScore: 0,
    };
  }

  /**
   * Load performance benchmarking data
   */
loadPerformanceData() {
    const stored = localStorage.getItem('sp_sim_performance_data');
    if (stored) {
      return JSON.parse(stored);
    }

    return {
      loadTimes: [],
      memoryUsage: [],
      fps: [],
      turnProcessingTime: [],
      uiResponseTime: [],
      errorRate: 0,
      performanceScore: 100,
    };
  }

  /**
   * Start session tracking
   */
startSessionTracking() {
    this.updateRetentionMetrics();
    this.trackSessionStart();

    // Track activity every 30 seconds
    this.activityInterval = setInterval(() => {
      this.trackActivity();
    }, 30000);

    // Auto-save analytics every 2 minutes
    this.saveInterval = setInterval(() => {
      this.saveAnalytics();
    }, 120000);
  }

    // Track activity every 30 seconds
() => {
      this.trackActivity();
    }

    // Auto-save analytics every 2 minutes
() => {
      this.saveAnalytics();
    }

  /**
   * End current session
   */
endSession() {
    this.sessionData.endTime = Date.now();
    this.sessionData.duration = this.sessionData.endTime - this.sessionData.startTime;

    this.updatePlayerMetrics();
    this.saveAnalytics();

    if (this.activityInterval) {
      clearInterval(this.activityInterval);
    }
    if (this.saveInterval) {
      clearInterval(this.saveInterval);
    }
  }

  /**
   * Track a player decision
   */
trackDecision(decision) {
    const decisionData = {
      timestamp: Date.now(),
      type: decision.type || 'general',
      description: decision.description || decision.message,
      timeTaken: decision.timeTaken || 0, // milliseconds
      context: {
        turn: decision.turn,
        approval: decision.approval,
        economicState: decision.economicState,
      },
    };

    this.sessionData.decisions.push(decisionData);

    // Update decision metrics
    if (!this.playerMetrics.decisionTypes[decisionData.type]) {
      this.playerMetrics.decisionTypes[decisionData.type] = 0;
    }
    this.playerMetrics.decisionTypes[decisionData.type]++;

    if (decisionData.timeTaken > 0) {
      this.playerMetrics.decisionSpeed.push(decisionData.timeTaken);
    }

    eventSystem.emit('analytics:decision_tracked', { decision: decisionData });
  }

  /**
   * Track policy implementation
   */
trackPolicy(policy) {
    const policyData = {
      timestamp: Date.now(),
      type: policy.type,
      name: policy.name,
      effectiveness: policy.effectiveness || 0,
      cost: policy.cost || 0,
      duration: policy.duration || 0,
      approvalImpact: policy.approvalImpact || 0,
    };

    this.sessionData.policies.push(policyData);

    // Update policy preferences
    if (!this.playerMetrics.policyPreferences[policyData.type]) {
      this.playerMetrics.policyPreferences[policyData.type] = 0;
    }
    this.playerMetrics.policyPreferences[policyData.type]++;

    eventSystem.emit('analytics:policy_tracked', { policy: policyData });
  }

  /**
   * Track approval rating changes
   */
trackApprovalChange(oldApproval, newApproval, reason) {
    const change = {
      timestamp: Date.now(),
      from: oldApproval,
      to: newApproval,
      delta: newApproval - oldApproval,
      reason: reason || 'unknown',
    };

    this.sessionData.approvalChanges.push(change);
    this.playerMetrics.averageApproval.push(newApproval);

    eventSystem.emit('analytics:approval_tracked', { change });
  }

  /**
   * Track crisis management
   */
trackCrisisHandled(crisis, outcome) {
    const crisisData = {
      timestamp: Date.now(),
      type: crisis.type,
      severity: crisis.severity,
      outcome: outcome.success ? 'success' : 'failure',
      score: outcome.score || 0,
      responseTime: outcome.responseTime || 0,
    };

    this.sessionData.crisisesHandled.push(crisisData);

    // Update crisis management score
    const recentCrises = this.sessionData.crisisesHandled.slice(-10);
    const successRate = recentCrises.filter(c => c.outcome === 'success').length / recentCrises.length;
    this.playerMetrics.crisisManagementScore = Math.round(successRate * 100);

    eventSystem.emit('analytics:crisis_tracked', { crisis: crisisData });
  }

  /**
   * Track feature usage
   */
trackFeatureUsage(feature) {
    if (!this.playerMetrics.featureUsage[feature]) {
      this.playerMetrics.featureUsage[feature] = 0;
    }
    this.playerMetrics.featureUsage[feature]++;

    eventSystem.emit('analytics:feature_tracked', { feature });
  }

  /**
   * Track performance metrics
   */
trackPerformance(metrics) {
    if (metrics.loadTime) {
      this.performanceData.loadTimes.push({
        timestamp: Date.now(),
        value: metrics.loadTime,
      });
    }

    if (metrics.memoryUsage) {
      this.performanceData.memoryUsage.push({
        timestamp: Date.now(),
        value: metrics.memoryUsage,
      });
    }

    if (metrics.fps) {
      this.performanceData.fps.push({
        timestamp: Date.now(),
        value: metrics.fps,
      });
    }

    // Calculate performance score (100 = perfect, 0 = terrible)
    this.updatePerformanceScore();
  }

  /**
   * Get comprehensive analytics data
   */
getAnalytics() {
    return {
      session: this.sessionData,
      player: this.playerMetrics,
      retention: this.retentionData,
      performance: this.performanceData,
      insights: this.generateInsights(),
    };
  }

  /**
   * Get player performance summary
   */
getPlayerPerformance() {
    const avgApproval = this.playerMetrics.averageApproval.length > 0
      ? this.playerMetrics.averageApproval.reduce((a, b) => a + b, 0) / this.playerMetrics.averageApproval.length
      : 0;

    const avgSessionLength = this.playerMetrics.totalPlaytime / Math.max(1, this.playerMetrics.totalSessions);

    const completionRate = this.playerMetrics.gamesCompleted / 
      Math.max(1, this.playerMetrics.gamesCompleted + this.playerMetrics.gamesAbandoned);

    // Calculate overall score directly here to avoid circular dependency
    const overallScore = Math.round((
      avgApproval * 0.3 +
      this.playerMetrics.crisisManagementScore * 0.2 +
      this.playerMetrics.learningProgression * 0.2 +
      (completionRate * 100) * 0.3
    ));

    return {
      overallScore,
      averageApproval: Math.round(avgApproval),
      sessionLength: Math.round(avgSessionLength),
      completionRate: Math.round(completionRate * 100),
      crisisManagement: this.playerMetrics.crisisManagementScore,
      learningProgression: this.playerMetrics.learningProgression,
      performanceGrade: this.getPerformanceGradeFromScore(overallScore),
    };
  }

  /**
   * Get retention metrics
   */
getRetentionMetrics() {
    const daysSinceFirst = (Date.now() - this.retentionData.firstSession) / (1000 * 60 * 60 * 24);
    const daysSinceLast = (Date.now() - this.retentionData.lastSession) / (1000 * 60 * 60 * 24);

    return {
      daysSinceFirstPlay: Math.floor(daysSinceFirst),
      daysSinceLastPlay: Math.floor(daysSinceLast),
      totalSessions: this.playerMetrics.totalSessions,
      engagementScore: this.retentionData.engagementScore,
      churnRisk: this.retentionData.churnRisk,
      returningPlayer: this.retentionData.returningPlayer,
      weeklyRetention: this.calculateWeeklyRetention(),
    };
  }

  /**
   * Generate actionable insights
   */
generateInsights() {
    const insights = [];
    const performance = this.getPlayerPerformance();
    const retention = this.getRetentionMetrics();

    // Performance insights
    if (performance.averageApproval < 40) {
      insights.push({
        type: 'improvement',
        title: 'Approval Rating Challenge',
        message: 'Consider focusing on popular policies and crisis management to improve public approval.',
        priority: 'high',
      });
    }

    if (performance.sessionLength < 15) {
      insights.push({
        type: 'engagement',
        title: 'Short Sessions Detected',
        message: 'Try exploring different game features to increase engagement.',
        priority: 'medium',
      });
    }

    // Retention insights
    if (retention.churnRisk === 'high') {
      insights.push({
        type: 'retention',
        title: 'Churn Risk Alert',
        message: 'Consider trying tutorial mode or easier difficulty to improve experience.',
        priority: 'high',
      });
    }

    // Feature usage insights
    const mostUsedFeature = Object.keys(this.playerMetrics.featureUsage)
      .reduce((a, b) => this.playerMetrics.featureUsage[a] > this.playerMetrics.featureUsage[b] ? a : b, 'dashboard');

    if (mostUsedFeature) {
      insights.push({
        type: 'strength',
        title: 'Feature Mastery',
        message: `You're excelling at using the ${mostUsedFeature} feature!`,
        priority: 'low',
      });
    }

    return insights;
  }

  /**
   * Initialize event listeners
   */
initializeEventListeners() {
    // Track game events
    eventSystem.on(EVENTS.TURN_END, (event) => {
      this.sessionData.turnsPlayed++;
    });

    eventSystem.on(EVENTS.APPROVAL_CHANGE, (event) => {
      this.trackApprovalChange(
        event.data.oldApproval,
        event.data.newApproval,
