        const alt = $(elem).attr('alt') || '';
        if (src) {
          images.push({ src, alt });
        }
      }

  // Trích xuất tất cả links
extractLinks($, selector) {
    try {
      const links = [];
      $(selector).each((i, elem) => {
        const href = $(elem).attr('href');
        const text = $(elem).text().trim();
        if (href) {
          links.push({ href, text });
        }
      });
      return links;
    } catch (error) {
      return [];
    }
  }

