// Execute adds all child commands to the root command and sets flags appropriately.
// This is called by main.main(). It only needs to happen once to the rootCmd.
func Execute() {
	if err := rootCmd.Execute(); err != nil {
		log.Fatal().Err(err).Msgf("Error Executing crda command. Please raise at https://github.com/fabric8-analytics/cli-tools/issues, if issue persists.")
	}
}

// initConfig reads in config file and ENV variables if set.
func initConfig() {
	// Log Level Settings
	logLevel := zerolog.InfoLevel
	if debug {
		logLevel = zerolog.DebugLevel
	}
	zerolog.SetGlobalLevel(logLevel)
	log.Logger = log.Output(zerolog.ConsoleWriter{Out: os.Stderr})

	// config.yaml Settings
	log.Debug().Msgf("Setting Configuration files")
	configName := "config"
	configHome, err := homedir.Dir()
	crdaFolder := ".crda"
	if err != nil {
		log.Fatal().Err(err).Msgf(err.Error())
	}
	configPath := filepath.Join(configHome, crdaFolder)
	configFilePath := filepath.Join(configPath, configName)
	if cfgFile != "" {
		// Use config file from the flag.
		viper.SetConfigFile(cfgFile)
	} else {
		// Search config file in home path.
		viper.SetConfigName(configName) // name of config file (without extension)
		viper.SetConfigType("yaml")
		viper.AddConfigPath(configPath)
	}
	viper.AutomaticEnv() // read in environment variables that match

	//Handle Reading Config Files Error
	if err := viper.ReadInConfig(); err != nil {
		log.Debug().Msgf("Error reading config file.")
		if _, ok := err.(viper.ConfigFileNotFoundError); ok {
			// Config file not found, Creating one
			if _, err := os.Stat(configFilePath); os.IsNotExist(err) {
				log.Debug().Msgf("Creating config file.")
				os.MkdirAll(configPath, os.ModePerm)
				_, err := os.Create(configFilePath + ".yaml")
				if err != nil {
					log.Fatal().Err(err).Msgf(err.Error())
				}
			}
			viper.SetConfigFile(configFilePath + ".yaml")
		} else {
			// Config file was found but another error was produced
			log.Fatal().Err(err).Msgf(err.Error())
		}
	}
	viper.WriteConfig()
	log.Info().Msgf("Using config file %s.\n", viper.ConfigFileUsed())
	log.Debug().Msgf("Successfully configured config files %s.", viper.ConfigFileUsed())
}

func main() {
	cmd.Execute()
}

// buildAPIURL builds API Endpoint URL
func buildAPIURL(host string, endpoint string, threeScale string) url.URL {
	log.Debug().Msgf("Building API Url.")
	APIHost, err := url.Parse(host)
	if err != nil {
		log.Fatal().Err(err).Msgf("Unable to Parse Host URL")
	}
	url := url.URL{Host: APIHost.Hostname(), Path: endpoint}
	url.Scheme = "https"
	q := url.Query()
	q.Set("user_key", threeScale)
	url.RawQuery = q.Encode()
	log.Debug().Msgf("Success: Building API Url.")
	return url
}

// HTTPRequest is generic method for HTTP Requests to server
func HTTPRequest(data HTTPRequestType) *http.Response {
	log.Debug().Msgf("Executing HTTPRequest.")
	client := &http.Client{}
	url := buildAPIURL(data.Host, data.Endpoint, data.ThreeScaleToken)
	payload, _ := json.Marshal(&data.Payload)
	req, err := http.NewRequest(data.Method, url.String(), bytes.NewBuffer(payload))
	req.Header.Add("Content-Type", "application/json")

	if err != nil {
		log.Fatal().Err(err).Msgf("Unable to build request")
	}
	res, err := client.Do(req)
	if err != nil {
		log.Fatal().Err(err).Msgf("Unable to reach the server. hint: Check your Internet connection.")
	}
	log.Debug().Msgf("Success HTTPRequest.")
	return res
}

// MinimumArgs validates for Minimum arg in cmd
func MinimumArgs(n int, msg string) cobra.PositionalArgs {
	if msg == "" {
		return cobra.MinimumNArgs(1)
	}

	return func(cmd *cobra.Command, args []string) error {
		if len(args) < n {
			return &FlagError{Err: errors.New(msg)}
		}
		return nil
	}
}

func(cmd *cobra.Command, args []string) error {
		if len(args) < n {
			return &FlagError{Err: errors.New(msg)}
		}
		return nil
	}

func TestMinimumArgs(t *testing.T) {
	tests := []struct {
		N    int
		Args []string
	}{
		{
			N:    1,
			Args: []string{"v1.2.3"},
		},
		{
			N:    2,
			Args: []string{"v1.2.3", "cli/cli"},
		},
	}

	for _, test := range tests {
		if got := MinimumArgs(test.N, "")(nil, test.Args); got != nil {
			t.Errorf("Got: %v, Want: (nil)", got)
		}
	}
}

func TestMinimumNs_with_error(t *testing.T) {
	tests := []struct {
		N             int
		CustomMessage string
		WantMessage   string
	}{
		{
			N:             1,
			CustomMessage: "A custom msg",
			WantMessage:   "A custom msg",
		},
		{
			N:             1,
			CustomMessage: "",
			WantMessage:   "requires at least 1 arg(s), only received 0",
		},
	}

	for _, test := range tests {
		if got := MinimumArgs(test.N, test.CustomMessage)(nil, nil); got.Error() != test.WantMessage {
			t.Errorf("Got: %v, Want: %v", got, test.WantMessage)
		}
	}
}

