    ) -> QuerySet[Course]:
        qs = Course.objects.filter(stars__user__pk=info.context.user.pk)
        return get_paginator(qs, page_size, page, PaginatedCourseObjectType)

def resolve_resources(
        root: None,
        info: ResolveInfo,
        user: ID = None,
        course: ID = None,
        page: int = 1,
        page_size: int = settings.DEFAULT_PAGE_SIZE,
    ) -> graphene.ObjectType:
        qs: QuerySet[Resource] = Resource.objects.all()

        if user is not None:
            qs = qs.filter(user__pk=user)
        if course is not None:
            qs = qs.filter(course__pk=course)

        qs = order_resources_with_secret_algorithm(qs)
        return get_paginator(qs, page_size, page, PaginatedResourceObjectType)

def resolve_starred_resources(
        root: None,
        info: ResolveInfo,
        page: int = 1,
        page_size: int = settings.DEFAULT_PAGE_SIZE,
    ) -> QuerySet[Resource]:
        qs = Resource.objects.filter(stars__user__pk=info.context.user.pk)
        return get_paginator(qs, page_size, page, PaginatedResourceObjectType)

def order_subjects_by_num_courses(qs: QuerySet[Subject]) -> QuerySet[Subject]:
    """Sort the queryset so that the subjects with the most courses come first."""

    return qs.annotate(num_courses=Count("courses")).order_by(
        "-num_courses", "translations__name"
    )

def resolve_subjects(
        root: None,
        info: ResolveInfo,
        school: ID = None,
        page: int = 1,
        page_size: int = settings.DEFAULT_PAGE_SIZE,
    ) -> graphene.ObjectType:
        qs: QuerySet[Subject] = Subject.objects.all()

        if school is not None:
            qs = qs.filter(courses__school__pk=school)

        qs = order_subjects_by_num_courses(qs)
        return get_paginator(qs, page_size, page, PaginatedSubjectObjectType)

def perform_mutate(
        cls, form: DeleteUserForm, info: ResolveInfo
    ) -> DeleteUserMutation:
        user = cast(User, info.context.user)
        user.soft_delete()
        return cls(message=Messages.USER_DELETED)

def query_activities(
        self,
        page: Optional[int] = None,
        page_size: Optional[int] = None,
        assert_error: bool = False,
    ) -> JsonDict:
        variables = {
            "page": page,
            "pageSize": page_size,
        }

        # language=GraphQL
        graphql = (
            self.activity_fields
            + """
            query Activities($page: Int, $pageSize: Int) {
                activities(page: $page, pageSize: $pageSize) {
                    page
                    pages
                    hasNext
                    hasPrev
                    count
                    objects {
                        ...activityFields
                    }
                }
            }
            """
        )

        return self.execute(graphql, variables=variables, assert_error=assert_error)

