// SafeSQLString constructs a safe string to feed to SQLite3 CLI
// Queries made in Go should use prepared statements/parameters
// instead. This is also not safe for LIKE queries
func SafeSQLString(s *string) string {
	if s != nil {
		return fmt.Sprintf("'%s'", strings.ReplaceAll(*s, "'", "''"))
	}
	return "NULL"
}

def printStar(board, N):
  for b in board:
    print(''.join(b))

def white(board, y, x):
  for i in range(y, y+3):
    for j in range(x, x+3):
      board[i][j] = ' '

def star(board, y, x):
  for i in range(y, y+3):
    for j in range(x, x+3):
      if i == y+1 and j == x+1:
        board[i][j] = ' '
        continue
      board[i][j] = '*'

def dfs(board, n, y, x):
  nN = n//3
  if n == 3:
    star(board, y, x)
    return
  for i in range(y, y+n, nN):
    for j in range(x, x+n, nN):
      if i == y+nN and j == x+nN:
        continue

      dfs(board, nN, i, j)
  return

def _decodeSIP(order, params, min=2):
        if order == 1:
            return None
        k = 0
        a = []
        b = []
        for i in range(order+1):
            for j in range(order+1):
                if (i+j < min) or (i+j > order):
                    a.append(0.0)
                    b.append(0.0)
                else:
                    a.append(params[k])
                    b.append(params[k+1])
                    k += 2
        a = np.array(a).reshape((order+1, order+1))
        b = np.array(b).reshape((order+1, order+1))
        ab = np.array([a, b])
        return ab

