({ text }) => {
  const [animating, setAnimating] = useState(false);
  const [copied, setCopied] = useState(false);
  const animatingTimeout = useRef(null);
  const copiedTimeout = useRef(null);

  const handleCopy = e => {
    e.preventDefault();
    setAnimating(true);
    setCopied(true);
    clearTimeout(animatingTimeout.current);
    clearTimeout(copiedTimeout.current);
    animatingTimeout.current = setTimeout(() => {
      setAnimating(false);
    }, "100");
    copiedTimeout.current = setTimeout(() => {
      setCopied(false);
    }, "3000");
  };

  return (
    <CopyToClipboard text={text}>
      <HeroNPMWrapper>
        <HeroNPMCopy>{text}</HeroNPMCopy>
        <HeroNPMButton onClick={handleCopy}>
          <BounceAnimation bouncing={animating}>
            {copied ? "Copied" : "Copy"}
          </BounceAnimation>
        </HeroNPMButton>
      </HeroNPMWrapper>
    </CopyToClipboard>
  );
}

