    animatingTimeout.current = setTimeout(() => {
      setAnimating(false);
    }, "100");
    copiedTimeout.current = setTimeout(() => {
      setCopied(false);
    }, "3000");
  }

() => {
      setAnimating(false);
    }

() => {
      setCopied(false);
