// * Use isExternal prop to create an anchor link with the same styling
({ isExternal, ...props }) =>
  isExternal ? <a {...props} href={props.to} /> : <Link {...props} />

(err, server) => {
  if (err) {
    throw err
  }
  console.log('Connection established')

  server.whoami((err, keys) => {
    if (err) console.log('could not get keys, got err', err)
    else console.log('whoami details:', keys)

    console.log('disconnecting from server')
    server.close()
  })
}

(err, keys) => {
    if (err) console.log('could not get keys, got err', err)
    else console.log('whoami details:', keys)

    console.log('disconnecting from server')
    server.close()
  }

private def isStub(sym: Symbol): Boolean = sym match {
    case _: StubSymbol => true
    case _             => false
  }

public mutating func clearMusicianCreditsList() {
        self.frames[.musicianCreditsList] = nil
    }

public mutating func clearMusicianCreditsForRole(role: MusicianAndPerformerCredits) {
        self.musicianCreditsList?[role] = nil
    }

public mutating func clearInvolvedPeopleList() {
        self.frames[.involvedPeopleList] = nil
    }

public mutating func clearInvolvedPeopleForRole(role: InvolvedPersonCredits) {
        self.involvedPeopleList?[role] = nil
    }

init(identifier: String, key: UUID, contents: Data){
        self.flags = UnknownFrame.defaultFlags
        self.layout = .unknown(identifier)
//        print(self.layout)
        self.contents = contents
        self.frameKey = .unknown(uuid: uuid)
    }

func encodeContents(version: Version) throws -> Data {
        return self.contents
    }

