async create() {
    console.log('updating?', this.updating);
    if (this.updating) return;
    const { review } = this.state;
    if (!review.summary) {
      return NotificationManager.error(
        i18n.t('label.summary_missing'),
        i18n.t('label.error'),
        5000
      );
    }
    if (
      !Object.keys(review.reviewIndexScores).filter(index =>
        Number(review.reviewIndexScores[index].score)
      ).length
    ) {
      return NotificationManager.error(
        i18n.t('label.at_least_one_index'),
        i18n.t('label.error'),
        5000
      );
    }
    console.log('review before submitting', review);
    try {
      if (this.state.review.id) {
        let {
          id,
          reviewIndexScores,
          summary,
          pdfFile,
          reviewImages
        } = this.state.review;
        const plantProject = this.props.selectedPlantProject.id;
        await this.props.updateReview(
          {
            id,
            plantProject,
            summary,
            reviewIndexScores,
            pdfFile,
            reviewImages
          },
          this.props.selectedPlantProject
        );
      } else {
        await this.props.addReview(
          this.state.review,
          this.props.selectedPlantProject
        );
      }
      this.props.navigation.navigate('app_reviews');
    } catch (err) {
      console.error(err);
    }
  }

render() {
    console.log('state', this.state);
    return (
      <ScrollView
        contentContainerStyle={{
          paddingBottom: 80,
          backgroundColor: '#fff',
          flexGrow: 1
        }}
      >
        {/*Header*/}
        <View
          style={{
