static func json(fromXcresultFile file: String) throws -> Data {
        return try json(fromXcresultFile: file, shellOutExecutor: ShellOutExecutor())
    }

static func json(fromXcresultFile file: String, shellOutExecutor: ShellOutExecuting) throws -> Data {
        return try jsonData(fromCommand: "xcrun xccov view --report --json \(file)", shellOutExecutor: shellOutExecutor)
    }

func testWhenJSONIsFromXcresultItExectuesTheCorrectCommand() {
        let executor = SpyShellOutExecutor()
        let testPath = "test/test.xcodecov"
        let data = try! XcCovJSONParser.json(fromXcresultFile: testPath, shellOutExecutor: executor)

        XCTAssertEqual(executor.receivedCommand, "xcrun xccov view --report --json \(testPath)")
        XCTAssertEqual(data, executor.testResult.data(using: .utf8))
    }

func testWhenXcoverageFileIsInvalidThrowsAnError() throws {
        MockedXcCovJSONParser.xcoverageResult = nil

        XCTAssertThrowsError(try XcodeBuildCoverageParser.coverage(xcresultBundlePath: "derived", files: [], excludedTargets: [], coverageFileFinder: FakeXcodeCoverageFileFinder.self, xcCovParser: MockedXcCovJSONParser.self)) { error in
            XCTAssertEqual(error.localizedDescription, "Invalid coverage report")
        }
    }

func testWhenXcresultFileIsInvalidThrowsAnError() throws {
        FakeXcodeCoverageFileFinder.result = nil
        MockedXcCovJSONParser.xcresultResult = nil

        XCTAssertThrowsError(try XcodeBuildCoverageParser.coverage(xcresultBundlePath: "derived", files: [], excludedTargets: [], coverageFileFinder: FakeXcodeCoverageFileFinder.self, xcCovParser: MockedXcCovJSONParser.self)) { error in
            XCTAssertEqual(error.localizedDescription, "Invalid coverage report")
        }
    }

    /**
     * Generate a `WaypointModel` for the specified data
     *
     * @for LegModel
     * @method _generateWaypoint
     * @param data {string|array<string>}
     * @returns {WaypointModel}
     * @private
     */
_generateWaypoint(data) {
        const waypoint = new WaypointModel(data);
        const holdParameters = NavigationLibrary.findHoldParametersByFix(waypoint.name);

        if (holdParameters != null) {
            waypoint.setDefaultHoldParameters(holdParameters);
        }

        return waypoint;
    }

        // This calculates the inbound heading to the fix from the preceding waypoint,
        // and uses that as the fallbackInboundHeading.
        // If no preceding waypoing exists, then the original fallbackInboundHeading passed is used
(last, wpt) => {
            let [heading] = last;
            const [, lastWpt] = last;

            if (lastWpt !== null && wpt.name === waypointName.toUpperCase()) {
                heading = wpt.positionModel.bearingFromPosition(lastWpt.positionModel);
            }

            return [heading, wpt];
        }

    /**
     * The maxmimum speed allowed for the Waypoint, or hold if `#isHoldwaypoint`
     *
     * @returns {number}
     */
get speedMaximum() {
        if (this.isHoldWaypoint && this._holdParameters.speedMaximum !== undefined) {
            return this._holdParameters.speedMaximum;
        }

        return this._speedMaximum;
    }

    /**
     * The minimum speed allowed for the Waypoint
     *
     * @returns {number}
     */
get speedMinimum() {
        return this._speedMinimum;
    }

    /**
     * Set default parameters for the planned holding pattern at this waypoint, and will
     * set both `#_defaultHoldParameters` and `#_holdParameters` properties
     *
     * This should only be called immedately after creating a new `WaypointModel`
     *
     * @for WaypointModel
     * @method setDefaultHoldParameters
     * @param holdParameters {object}
     */
setDefaultHoldParameters(holdParameters) {
        // The rationale behind having both _defaultHoldParameters and _holdParameters is:
        // * Without this, once a hold command is executed with specific options (eg. HOLD BPK left 225),
        //   it could overwrite the parameters for a procedural hold
        // * This would mean that if the hold was cancelled and re-requested without any specific options (eg. HOLD BPK)
        //   it would still use "left 225", and not the expected defaults from the pocedure

        // These can't be the same reference, as we don't want any changes to made _holdParameters
        // (eg. timer) to be passed onto _defaultHoldParameters
        this._defaultHoldParameters = Object.assign({}, DEFAULT_HOLD_PARAMETERS, holdParameters);
        this._holdParameters = Object.assign({}, DEFAULT_HOLD_PARAMETERS, holdParameters);
    }

    /**
     * @constructor
     * @param holdJson {object}
     */
constructor(holdJson) {
        super();

        // holdsJson is permitted to be null/undefined/empty, but if valid must be an object
        if (holdJson != null && !_isObject(holdJson)) {
            throw new TypeError(
                `Invalid holdJson parameter passed to HoldCollection. Expected an object but found ${typeof holdJson}`
            );
        }

        /**
         * @inherited
         * @memberof BaseCollection
         * @property _items
         * @type {array<HoldModel>}
         * @default []
         */

        /**
         * @inherited
         * @memberof BaseCollection
         * @property length
         * @type {number}
         * @default #_items.length
         */

        this._init(holdJson);
    }

    /**
     * Public fascade for `#_items`
     *
     * @for HoldCollection
     * @property holds
     * @return {array<HoldModel>}
     */
get holds() {
        return this._items;
    }

    // ------------------------------ LIFECYCLE ------------------------------

    /**
     * Initialize the instance
     *
     * @for HoldCollection
     * @method _init
     * @param holdJson {object}
     */
_init(holdJson) {
        this.populateHolds(holdJson);
    }

    /**
     * @for HoldCollection
     * @method reset
     */
reset() {
        this.holds.forEach((item) => item.reset());

        this._items = [];
    }

    // ------------------------------ PUBLIC ------------------------------

    /**
     * Returns a flag indicating whether the `fixName` exists within the collection
     *
     * @for HoldCollection
     * @method containsHoldForFix
     * @param fixName {string}
     * @return {boolean}
     */
containsHoldForFix(fixName) {
        if (!fixName) {
            return false;
        }

        fixName = fixName.toUpperCase();

        return this._items.some((hold) => hold.fixName === fixName);
    }

    /**
     * Find holdParameters by `fixName` if it exists within the collection
     *
     * @for HoldCollection
     * @method findHoldParametersByFix
     * @param fixName {string}
     * @return {object|null}
     */
findHoldParametersByFix(fixName) {
        if (!fixName) {
            return null;
        }

        fixName = fixName.toUpperCase();

        const model = this._items.find((hold) => hold.fixName === fixName);

        return model ? model.holdParameters : null;
    }

    /**
     * Populates the hold collection with the specified holds object
     *
     * @for HoldCollection
     * @method populateHolds
     * @param holdJson {object}
     */
populateHolds(holdJson) {
        if (!holdJson) {
            return;
        }

        // Check for duplicate fixName as multiple collections may have to be combined
        // by the `NavigationLibrary` in the future
        Object.keys(holdJson).forEach((fixName) => {
            if (this.containsHoldForFix(fixName)) {
                return;
            }

            this._items.push(new HoldModel(fixName, holdJson[fixName]));
        });
    }

        // Check for duplicate fixName as multiple collections may have to be combined
        // by the `NavigationLibrary` in the future
(fixName) => {
            if (this.containsHoldForFix(fixName)) {
                return;
            }

            this._items.push(new HoldModel(fixName, holdJson[fixName]));
        }

    /**
     * @for HoldModel
     * @constructor
     * @param fixName {string}
     * @param holdString {string}
     */
constructor(fixName, holdString) {
        super();

        if (!_isString(fixName)) {
            throw new TypeError(
                `Invalid parameter, fixName must be a string, but found ${typeof fixName}`
            );
        } else if (!_isString(holdString)) {
            throw new TypeError(
                `Invalid parameter, holdString must be a string, but found ${typeof holdString}`
            );
        }

        /**
         * Name of the Fix
         *
         * @property fixName
         * @type {string}
         * @default ''
         */
        this.fixName = '';

        /**
         * The parameters of the hold
         *
         * @property holdParameters
         * @type {object}
         * @default null
         */
        this.holdParameters = null;

        this._init(fixName, holdString);
    }

    // ------------------------------ LIFECYCLE ------------------------------

    /**
     * Initialize the model
     *
     * @for HoldModel
     * @method _init
     * @param fixName {string}
     * @param holdString {string}
     * @private
     */
_init(fixName, holdString) {
        this.fixName = fixName;
        this.holdParameters = this._buildHoldParameters(holdString);

        return this;
    }

    /**
     * @for MapModel
     * @method reset
     */
reset() {
        this.fixName = '';
        this.holdParameters = null;
    }

    // ------------------------------ LIFECYCLE ------------------------------

    /**
     * Builds the HoldParameters from the specified string
     *
     * @for HoldModel
     * @method _buildHoldParameters
     * @param holdString {string}
     * @returns {object}
     * @private
     */
_buildHoldParameters(holdString) {
        const holdParameters = {};

        holdString.split('|').forEach((item) => {
            if (holdParameters.inboundHeading == null && isValidCourseString(item)) {
                holdParameters.inboundHeading = radians_normalize(degreesToRadians(180 + parseInt(item, 10)));

                return;
            }

            if (holdParameters.turnDirection == null && isValidDirectionString(item)) {
                holdParameters.turnDirection = directionNormalizer(item);

                return;
            }

            if (holdParameters.legLength == null && isLegLengthArg(item)) {
                holdParameters.legLength = item;

                return;
            }

            // The speed limit can be optional, but it tends to imply ICAO speed restrictions
            const [value, limit] = parseSpeedRestriction(item);
            if (value != null) {
                if (limit !== '-') {
                    throw new Error(`Invalid speedMaximum parameter for Fix '${this.fixName}': ${item} is not valid`);
                }

                holdParameters.speedMaximum = value;

                return;
            }

            throw new Error(`Unexpected parameter for Fix '${this.fixName}': ${item}`);
        });

        if (holdParameters.inboundHeading == null) {
            throw new Error(`Missing radial parameter for Fix '${this.fixName}': ${holdString}`);
        }

        if (holdParameters.turnDirection == null) {
            throw new Error(`Missing turnDirection parameter for Fix '${this.fixName}': ${holdString}`);
        }

        if (holdParameters.legLength == null) {
            throw new Error(`Missing legLength parameter for Fix '${this.fixName}': ${holdString}`);
        }

        return holdParameters;
    }

