def convert_input(self, value):
        '''make sure input is 1 or 2'''
        if value in (1, 2):
            return value, False

        raise ValueError('Only 1 or 2 mirrors supported')

def camera_to_engineering(from_coord, to_frame):
    if to_frame.n_mirrors == 1:
        return CAMERA_TO_ENGINEERING_1M_MATRIX, ZERO_OFFSET

    return CAMERA_TO_ENGINEERING_2M_MATRIX, ZERO_OFFSET

def engineering_to_camera(from_coord, to_frame):
    if from_coord.n_mirrors == 1:
        return ENGINEERING_1M_TO_CAMERA_MATRIX, ZERO_OFFSET
    return ENGINEERING_2M_TO_CAMERA_MATRIX, ZERO_OFFSET

def _lxc_exec(context: Context, cmd: List[str], *args, **kwargs):
    return subprocess.run(
        ["lxc", "exec", context.container_name, "--"] + cmd, *args, **kwargs
    )

def _wait_for_boot(context: Context) -> None:
    retries = [2] * 5
    for sleep_time in retries:
        process = _lxc_exec(
            context, ["runlevel"], capture_output=True, text=True
        )
        try:
            _, runlevel = process.stdout.strip().split(" ", 2)
        except ValueError:
            print("Unexpected runlevel output: ", process.stdout.strip())
            runlevel = None
        if runlevel == "2":
            break
        time.sleep(sleep_time)
    else:
        raise Exception("System did not boot in {}s".format(sum(retries)))

def cleanup_container():
        subprocess.run(["lxc", "stop", context.container_name])
        subprocess.run(["lxc", "delete", context.container_name])

def given_uat_is_installed(context):
    _lxc_exec(
        context,
        [
            "add-apt-repository",
            "--yes",
            "ppa:canonical-server/ua-client-daily",
        ],
    )
    _lxc_exec(context, ["apt-get", "update", "-qq"])
    _lxc_exec(
        context, ["apt-get", "install", "-qq", "-y", "ubuntu-advantage-tools"]
    )

def when_i_run_command(context, command):
    process = _lxc_exec(
        context, shlex.split(command), capture_output=True, text=True
    )
    context.process = process

def indices(t):
    import itertools
    for k in itertools.product(*[range(i) for i in t]):
        yield k

def normalize_angles(x, xmin, xmax):
    while np.any(x >= xmax):
        x -= np.where(x > xmax, 360, 0)
    while np.any(x < xmin):
        x += np.where(x < xmin, 360, 0)

