func sivaSize(init string) (int64, error) {
	info, err := ioutil.ReadDir("/tmp/sourced")
	if err != nil {
		return -1, err
	}

	if len(info) != 1 || !info[0].IsDir() {
		return -1, fmt.Errorf("/tmp/sourced directory wasn't in a clean status")
	}

	tmp := filepath.Join("/tmp/sourced", info[0].Name(), "transactioner")
	info, err = ioutil.ReadDir(tmp)
	if err != nil {
		return -1, err
	}

	var paths []string
	for _, fi := range info {
		if !fi.IsDir() {
			continue
		}

		matches := regSivaDir.FindStringSubmatch(fi.Name())
		if len(matches) != 2 {
			continue
		}

		if init == matches[1] {
			path := filepath.Join(tmp, fi.Name(), "siva")
			// the same siva file could be duplicated under
			// different directories if there are several
			// repositories being analyzed concurrently
			paths = append(paths, path)
		}
	}

	if len(paths) == 0 {
		return -1, fmt.Errorf(
			"couldn't find siva file for SHA1 %s in %s",
			init, tmp)

	}

	var size int64 = -1
	for _, path := range paths {
		fi, err := os.Stat(path)
		if err != nil {
			if os.IsNotExist(err) {
				// a previous found siva file generated from
				// another repository analysis could have been
				// already removed
				continue
			}

			return -1, err
		}

		if size < fi.Size() {
			size = fi.Size()
		}
	}

	if size < 0 {
		return -1, fmt.Errorf(
			"couldn't find siva file for SHA1 %s in %s",
			init, tmp)
	}

	return size, nil
}

def mocked_requests_get(*args, **kwargs) -> "MockResponse":  # noqa
    """A mock version of requests.get, so we don't need to call the API every time we run a test"""
    class MockResponse:
        def __init__(self, json_data, status_code):
            self.json_data = json_data
            self.status_code = status_code

        def json(self):
            return self.json_data

    if args[0] == HomeView.github_api:
        json_path = Path(__file__).resolve().parent / "mock_github_api_response.json"
        with open(json_path, 'r') as json_file:
            mock_data = json.load(json_file)

        return MockResponse(mock_data, 200)

    return MockResponse(None, 404)

def __init__(self, json_data, status_code):
            self.json_data = json_data
            self.status_code = status_code

def setUp(self):
        """Executed before each test method."""

        self.home_view = HomeView()

def _get_api_data(self) -> Dict[str, Dict[str, str]]:
        """Call the GitHub API and get information about our repos."""

        repo_dict = {repo_name: {} for repo_name in self.repos}

        # Fetch the data from the GitHub API
        api_data = requests.get(self.github_api)
        api_data = api_data.json()

        # Process the API data into our dict
        for repo in api_data:
            full_name = repo["full_name"]

            if full_name in self.repos:
                repo_dict[full_name] = {
                    "full_name": repo["full_name"],
                    "description": repo["description"],
                    "language": repo["language"],
                    "forks_count": repo["forks_count"],
                    "stargazers_count": repo["stargazers_count"],
                }
        return repo_dict

def get(self, request: WSGIRequest) -> HttpResponse:
        """Collect repo data and render the homepage view"""

        repo_data = self._get_repo_data()
        return render(request, "home/index.html", {"repo_data": repo_data})

// Add links to artifacts we've stuffed into the ENV.ARTIFACTS variable
async function linkToArtifacts() {
	if (ENV.BUILD_STATUS === 'SUCCESS' || ENV.BUILD_STATUS === 'UNSTABLE') {
		const artifacts = ENV.ARTIFACTS.split(';');
		if (artifacts.length !== 0) {
			const artifactsListing = '- ' + artifacts.map(a => danger.utils.href(`${ENV.BUILD_URL}artifact/${a}`, a)).join('\n- ');
			message(`:floppy_disk: Here are the artifacts produced:\n${artifactsListing}`);
		}
	}
}

