void polygon_offset(float factor, float units)
		{
			u32 _units = (u32&)units;
			u32 _factor = (u32&)factor;

			if (!test_property(GL_POLYGON_OFFSET_UNITS, _units) || !test_property(GL_POLYGON_OFFSET_FACTOR, _factor))
			{
