      /**
       * Given a CSS url() declaration 'url("http://foo")', return 'http://foo'.
       */
function urlFromCssDeclaration(declaration) {
        return declaration.slice(5, -2);
      }

  /** Return whether the computed font size of an element is big. */
fontIsBig(fnode) {
    const size = parseInt(getComputedStyle(fnode.element).fontSize, 10);
    return linearScale(size, 14, 50) ** this.bigFontCoeff;
  }

hasPriceInParentID(fnode) {
    return this.weightedIncludes(fnode.element.parentElement.id, 'price', this.hasPriceInParentIDCoeff);
  }

  /** Scores fnode with 'price' in its parent's class name */
hasPriceInParentClassName(fnode) {
    return this.weightedIncludes(fnode.element.parentElement.className, 'price', this.hasPriceInParentClassNameCoeff);
  }

hasBackgroundImage(fnode) {
    const bgImage = getComputedStyle(fnode.element)['background-image'];
    return bgImage && bgImage.startsWith('url("') && bgImage.endsWith('")');
    // The app doesn't yet know how to deal with non-url() types of background
    // images.
  }

  /**
   * Return the aspect ratio of a fnode's client rect, with horizontal and
   * vertical rearranged so it's always >=1.
   */
aspectRatio(element) {
    const rect = element.getBoundingClientRect();
    return (rect.width > rect.height) ? (rect.width / rect.height) : (rect.height / rect.width);
  }

  /** Give a bonus for elements that have a non-extreme aspect ratio. */
hasSquareAspectRatio(fnode) {
    return linearScale(this.aspectRatio(fnode.element), 10, 5) ** this.extremeAspectCoeff;
  }

[Test]
        public void MemoizeReturningExpectedElementsWhenUsedAtInnerForEach()
        {
            var array = Enumerable.Range(1, 10).ToArray();
            var buffer = Enumerable.Range(1, 10).Memoize();

            var flowArray = InnerForEach(array);
            var flowBuffer = InnerForEach(buffer);

            flowArray.AssertSequenceEqual(flowBuffer);

            IEnumerable<object> InnerForEach(IEnumerable<int> source)
            {
                var firstVisitAtInnerLoopDone = false;

                //add 1-3 to cache (so enter inner loop)
                //consume 4-5 already cached
                //add 6-7 to cache (so enter inner loop)
                //consume 8-10 already cached

                yield return "enter outer loop";
                foreach (var i in source)
                {
                    yield return i;

                    if (i == 3 || i == 7)
                    {
                        //consume 1-3 already cached
                        //add 4-5 to cache (so go to outer loop)
                        //consume 1-7 already cached
                        //add 8-10 to cache (so go to outer loop)

                        yield return "enter inner loop";
                        foreach (var j in source)
                        {
                            yield return j;

                            if (!firstVisitAtInnerLoopDone && j == 5)
                            {
                                firstVisitAtInnerLoopDone = true;
                                break;
                            }
                        }
                        yield return "exit inner loop";
                    }
                }
                yield return "exit outer loop";

                yield return "enter last loop";
                //consume 1-10 (all item were already cached)
                foreach (var k in source)
                {
                    yield return k;
                }
                yield return "exit last loop";
            }
        }

