def get_github_url(self, obj):
        if obj.github_url:
            list_url = obj.github_url.split('/')
            return list_url[0] + '//github.com/' + list_url[4] + '/' + list_url[5].split('?')[0] #  remove get request params(client_id and secret)
        else:
            return ''

