//' Compute information of stars
//' @param star  star name
//' @param tjd_et  Julian day, Ephemeris time
//' @param iflag  a 32 bit integer containing bit flags that indicate what
//'               kind of computation is wanted
//' @return \code{swe_fixstar} returns a list with named entries \code{return},
//'         \code{star}, \code{xx}, and \code{serr} for return code, updated star name, 
//'         calculated values and error message.
//' @rdname expert-interface
//' @export
// [[Rcpp::export(swe_fixstar)]]
Rcpp::List fixstar(std::string star, double tjd_et, int iflag) {
  std::array<double, 6> xx;
  std::array<char, 256> serr;
  star.resize(41);
  int rtn = swe_fixstar(&star[0], tjd_et, iflag, &xx[0], &serr[0]);
  return Rcpp::List::create(Rcpp::Named("return") = rtn,
                            Rcpp::Named("star") = std::string(&star[0]),
                            Rcpp::Named("xx") = xx,
                            Rcpp::Named("serr") = std::string(&serr[0]));
}

//' Compute horizon information: azimuth, altiiude
//' @param tjd_ut  Julian day, UT time
//' @param calc_flag Type of reference system
//' @param geopoas The position vector (longitude, latitude, height)
//' @param atpress atmospheric pressure in mbar (hPa)
//' @param attemp atmospheric temperature in degrees Celsius
//' @return \code{swe_azalt} returns a list with named entries: 
//'      \code{xaz} for azi/alt info.
//' @rdname expert-interface
//' @export
// [[Rcpp::export(swe_azalt)]]
Rcpp::List azalt(double tjd_ut, int calc_flag, Rcpp::NumericVector geopos, double atpress, double attemp, Rcpp::NumericVector xin) {
  std::array<double, 3> xaz;
  swe_azalt(tjd_ut, calc_flag, &geopos[0], atpress, attemp, &xin[0], &xaz[0]);
  return Rcpp::List::create(Rcpp::Named("xaz") = xaz);
}

//' Compute the rise and set location of the object
//' @param tjd_ut  Julian day, UT time
//' @param ipl Plant number (otherwise -1)
//' @param starname The name of the star (otherwise "")
//' @param epheflag Type of ephemeris (4=Moshier, 1=JPL, 2=SE)
//' @param geopoas The position vector (longitude, latitude, height)
//' @param atpress atmospheric pressure in mbar (hPa)
//' @param attemp atmospheric temperature in degrees Celsius
//' @param horhgt The apparent horizon at rise/set in degrees
//' @return \code{swe_rise_trans_true_hor} returns a list with named entries: \code{i} success of function
//'      \code{tret} for azi/alt info and \code{serr} for possible error code
//' @rdname expert-interface
//' @export
// [[Rcpp::export(swe_rise_trans_true_hor)]]
Rcpp::List rise_trans_true_hor(double tjd_ut, int ipl, std::string starname, int epheflag, int rsmi,Rcpp::NumericVector geopos, double atpress, double attemp, double horhgt) {
  std::array<char, 256> serr;
  double tret;
  int i = swe_rise_trans_true_hor(tjd_ut, ipl, &starname[0], epheflag, rsmi, &geopos[0], atpress, attemp, horhgt, &tret, &serr[0]);
  return Rcpp::List::create(Rcpp::Named("return") = i,
                            Rcpp::Named("tret") = tret,
                            Rcpp::Named("serr") = std::string(&serr[0]));
}

static llvm::Type* get_type(llvm::LLVMContext& context)
	{
		return llvm::Type::getIntNTy(context, 2);
	}

static llvm::Type* get_type(llvm::LLVMContext& context)
	{
		return llvm::Type::getIntNTy(context, 4);
	}

inline auto avg(T a, T b)
	{
		//return (a >> 1) + (b >> 1) + ((a | b) & 1);

		value_t<typename T::type> result;
		llvm::Instruction::CastOps cast_op = llvm::Instruction::BitCast;
		if (result.is_sint)
			cast_op = llvm::Instruction::SExt;
		if (result.is_uint)
			cast_op = llvm::Instruction::ZExt;
		llvm::Type* cast_t = m_ir->getIntNTy(result.esize * 2);
		if (result.is_vector != 0)
			cast_t = llvm::VectorType::get(cast_t, result.is_vector);

		const auto axt = m_ir->CreateCast(cast_op, a.eval(m_ir), cast_t);
		const auto bxt = m_ir->CreateCast(cast_op, b.eval(m_ir), cast_t);
		const auto cxt = llvm::ConstantInt::get(cast_t, 1, false);
		const auto abc = m_ir->CreateAdd(m_ir->CreateAdd(axt, bxt), cxt);
		result.value = m_ir->CreateTrunc(m_ir->CreateLShr(abc, 1), result.get_type(m_context));
		return result;
	}

auto build(Args... args)
	{
		using value_type = std::remove_extent_t<T>;
		const value_type values[]{static_cast<value_type>(args)...};
		static_assert(sizeof(T) / sizeof(value_type) == sizeof...(Args), "build: unexpected number of arguments");
		value_t<T> result;
		result.value = llvm::ConstantDataVector::get(m_context, values);
		return result;
	}

value_t<u8[16]> pshufb(T1 a, T2 b)
	{
		value_t<u8[16]> result;

		const auto data0 = a.eval(m_ir);
		const auto index = b.eval(m_ir);
		const auto zeros = llvm::ConstantAggregateZero::get(get_type<u8[16]>());

		if (auto c = llvm::dyn_cast<llvm::Constant>(index))
		{
			// Convert PSHUFB index back to LLVM vector shuffle mask
			v128 mask{};

			const auto cv = llvm::dyn_cast<llvm::ConstantDataVector>(c);

			if (cv)
			{
				for (u32 i = 0; i < 16; i++)
				{
					const u64 b = cv->getElementAsInteger(i);
					mask._u8[i] = b < 128 ? b % 16 : 16;
				}
			}

			if (cv || llvm::isa<llvm::ConstantAggregateZero>(c))
			{
				result.value = llvm::ConstantDataVector::get(m_context, llvm::makeArrayRef((const u8*)mask._bytes, 16));
				result.value = m_ir->CreateZExt(result.value, get_type<u32[16]>());
				result.value = m_ir->CreateShuffleVector(data0, zeros, result.value);
				return result;
			}
		}

		if (m_use_ssse3)
		{
			result.value = m_ir->CreateCall(get_intrinsic(llvm::Intrinsic::x86_ssse3_pshuf_b_128), {data0, index});
		}
		else
		{
			// Emulate PSHUFB (TODO)
			const auto mask = m_ir->CreateAnd(index, 0xf);
			const auto loop = llvm::BasicBlock::Create(m_context, "", m_ir->GetInsertBlock()->getParent());
			const auto next = llvm::BasicBlock::Create(m_context, "", m_ir->GetInsertBlock()->getParent());
			const auto prev = m_ir->GetInsertBlock();

			m_ir->CreateBr(loop);
			m_ir->SetInsertPoint(loop);
			const auto i = m_ir->CreatePHI(get_type<u32>(), 2);
			const auto v = m_ir->CreatePHI(get_type<u8[16]>(), 2);
			i->addIncoming(m_ir->getInt32(0), prev);
			i->addIncoming(m_ir->CreateAdd(i, m_ir->getInt32(1)), loop);
			v->addIncoming(zeros, prev);
			result.value = m_ir->CreateInsertElement(v, m_ir->CreateExtractElement(data0, m_ir->CreateExtractElement(mask, i)), i);
			v->addIncoming(result.value, loop);
			m_ir->CreateCondBr(m_ir->CreateICmpULT(i, m_ir->getInt32(16)), loop, next);
			m_ir->SetInsertPoint(next);
			result.value = m_ir->CreateSelect(m_ir->CreateICmpSLT(index, zeros), zeros, result.value);
		}

		return result;
	}

