get jsonObject() {
    return this._jsonObject;
  }

  /**
   * @return {!Object} The JSON data representing this mode. It's a fragment of a fixture's JSON data.
   */
get jsonObject() {
    return this._jsonObject;
  }

  /**
   * @typedef {'keyOnly'|'defaultOnly'|'switchedOnly'|'all'} SwitchingChannelBehavior
   */

  /**
   * @param {!string} chKey The channel key to search for.
   * @param {!SwitchingChannelBehavior} [where='all'] Define which channels to include in the search.
   * @return {!boolean} Whether this SwitchingChannel contains the given channel key.
   */
usesChannelKey(chKey, where='all') {
    if (where === 'keyOnly') {
      return this.key === chKey;
    }

    if (where === 'defaultOnly') {
      return this.defaultChannel.key === chKey;
    }

    if (where === 'switchedOnly') {
      return this.switchToChannelKeys.includes(chKey);
    }

    return this.switchToChannelKeys.includes(chKey) || this.key === chKey;
  }

/**
 * Checks that fixture key, name and shortName are unique.
 * @param {?UniqueValues} [uniqueValues=null] Values that have to be unique are checked and all new occurences are appended.
 */
function checkFixIdentifierUniqueness(uniqueValues) {
  // test is called for a single fixture, e.g. when importing
  if (uniqueValues === null) {
    return;
  }

  const manKey = fixture.manufacturer.key;

  // fixture.key
  if (!(manKey in uniqueValues.fixKeysInMan)) {
    uniqueValues.fixKeysInMan[manKey] = new Set();
  }
  module.exports.checkUniqueness(
    uniqueValues.fixKeysInMan[manKey],
    fixture.key,
    `Fixture key '${fixture.key}' is not unique in manufacturer ${manKey} (test is not case-sensitive).`
  );

  // fixture.name
  if (!(manKey in uniqueValues.fixNamesInMan)) {
    uniqueValues.fixNamesInMan[manKey] = new Set();
  }
  module.exports.checkUniqueness(
    uniqueValues.fixNamesInMan[manKey],
    fixture.name,
    `Fixture name '${fixture.name}' is not unique in manufacturer ${manKey} (test is not case-sensitive).`
  );

  // fixture.shortName
  module.exports.checkUniqueness(
    uniqueValues.fixShortNames,
    fixture.shortName,
    `Fixture shortName '${fixture.shortName}' is not unique (test is not case-sensitive).`
  );
}

/**
 * Check that a fixture's meta block is valid.
 * @param {!Meta} meta The fixture's Meta object.
 */
function checkMeta(meta) {
  if (meta.lastModifyDate < meta.createDate) {
    result.errors.push('meta.lastModifyDate is earlier than meta.createDate.');
  }
}

/**
 * Get the highest possible DMX value for each fineness up to the specified one.
 * E.g. fineness=2 -> [255, 65535, 16777215]
 * @param {!number} fineness The least used fineness in a mode of a channel.
 * @return {!number[]} Possible end values, sorted ascending.
 */
function getPossibleEndValues(fineness) {
  let values = [];
  for (let i = 0; i <= fineness; i++) {
    values.push(Math.pow(256, i+1)-1);
  }
  return values;
}

function arraysEqual(a, b) {
  if (a === b) {
    return true;
  }

  if (a == null || b == null || a.length !== b.length) {
    return false;
  }

  return a.every((val, index) => val === b[index]);
}

function saveLaunchFiles(saveLauchFile, configuration ){
  if (!saveLauchFile) return
  //let lConfiguration = configuration.replace(' sim ', ' trade ')
  let lFilenameNix = new String().concat('./gen.',configuration.selector.toLowerCase(),'.sh')
  let lFinenamewin32 = new String().concat('./gen.',configuration.selector.toLowerCase(),'.bat')
  delete configuration.generateLaunch
  delete configuration.backtester_generation

  let bestOverallCommand = generateCommandParams(configuration)
  let lastFitnessLevel = -9999.0
  // get prior fitness level nix
  if (fs.existsSync(lFilenameNix) )
  {
    let lFileCont = fs.readFileSync(lFilenameNix,{encoding:'utf8',flag:'r'})
    let lines = lFileCont.split('\n')
    if (lines.length > 2) 
      if (lines[1].includes('fitness='))
      {
        let th = lines[1].split('=')
        lastFitnessLevel = th[1]
      }
  }
  // get prior firness level win32
  if (fs.existsSync(lFinenamewin32) )
  {
    let lFileCont = fs.readFileSync(lFinenamewin32,{encoding:'utf8',flag:'r'})
    let lines = lFileCont.split('\n')
    if (lines.length > 1) 
      if (lines[1].includes('fitness='))
      {
        let th = lines[1].split('=')
        lastFitnessLevel = th[1]
      }
  }

  //write Nix Version
  let lNixContents = '#!/bin/bash\n'.concat('#fitness=',configuration.fitness,'\n','./zenbot.sh trade ', bestOverallCommand,'\n')
  let lWin32Contents = '@echo off\n'.concat('rem fitness=',configuration.fitness,'\n','./zenbot.bat trade ', bestOverallCommand,'\n')

  if (Number(configuration.fitness) > Number(lastFitnessLevel))
  {
    fs.writeFileSync(lFilenameNix, lNixContents)
    fs.writeFileSync(lFinenamewin32, lWin32Contents)
    fs.chmodSync(lFilenameNix,777)
    fs.chmodSync(lFinenamewin32,777)
  }
}

