/**
 *  Style a parent component so that upon hovering over one of its children, that child is isolated
 *  from the non-hovered children.
 *
 *  When hovering over a ComponentWithIsolationHoverStyles' children, the hovered child will
 *  display a `childHoveredStyle` and all other elements will display a `childIgnoredStyle`,
 *  with a transition specified by `transitionStyle`.
 *
 *  Styling a parent component with this function disables pointer-events on the parent component.
 *
 *  Inspired by Sarah Drasner's example from SVG Animations: https://codepen.io/sdras/details/qOdWEP.
 */
(
  ParentComponent,
  childHoveredStyle,
  childIgnoredStyle,
  transitionStyle=css`transition: all .5s ease-out;`
) => (
  styled(ParentComponent)`
    pointer-events: none;
    & > * {
      pointer-events: auto;
      ${transitionStyle}
    }

    &:hover > * {
      ${childIgnoredStyle}
    }

    &:hover > *:hover {
      ${childHoveredStyle}
    }
  `
)

(state = initialState, action) => {
  switch (action.type) {
    case FETCH_REFRESH_TOKEN_SUCCEEDED: {
      const { refreshToken } = action.payload;
      return {
        ...state,
        refreshToken,
        fetchingRefreshToken: false
      };
    }

    case FETCH_ACCESS_TOKEN_SUCCEEDED: {
      const { accessToken } = action.payload;
      return {
        ...state,
        accessToken,
        fetchingAccessToken: false
      };
    }

    case FETCH_REFRESH_TOKEN_STARTED:
      return {
        ...state,
        fetchingRefreshToken: true
      };

    case FETCH_ACCESS_TOKEN_STARTED:
      return {
        ...state,
        fetchingAccessToken: true
      };

    case USER_LOGGED_OUT:
      return {
        ...state,
        accessToken: null,
        refreshToken: null
      };

    default:
      return state;
  }
}

(state = initialState, action) => {
  switch(action.type) {
    case FETCH_PLAYLISTS_SUCCEEDED: {
      return {
        playlists: action.payload.playlists,
        fetchingPlaylists: false
      };
    }

    case FETCH_PLAYLISTS_STARTED:
      return {
        ...state,
        fetchingPlaylists: true
      };

    case FETCH_PLAYLIST_SUCCEEDED: {
      const { playlists } = state;
      return {
        playlists: [action.payload.playlist, ...playlists],
        fetchingPlaylists: false
      };
    }

    case FETCH_PLAYLIST_STARTED:
      return {
        ...state,
        fetchingPlaylists: true
      };

    default:
      return state;
  }
}

(state = initialState, action) => {
  switch(action.type) {
    case SOUFFLE_STARTED:
      return { ...state, souffleing: true };

    case SOUFFLE_SUCCEEDED:
      return { ...state, souffleing: false };

    case SOUFFLE_BY_UPDATED:
      return { ...state, souffleBy: action.payload.souffleBy};

    default:
      return state;
  }
}

