          from={colors.lightGreen}
          to={colors.yellow}
          id="gradient" />
        <g fill="url(#gradient)">
          <Spring reset native from={{ t: 0 }} to={{ t: 1 }} onRest={this.goNext}>
            {({ t }) => <animated.path d={t.interpolate(interpolator)} />}
          </Spring>
        </g>
      </svg>
    );
  }

