static int
zil_prt_rec_write_cb(void *data, size_t len, void *unused)
{
	char *cdata = data;
	int i;

	for (i = 0; i < len; i++) {
		if (isprint(*cdata))
			(void) printf("%c ", *cdata);
		else
			(void) printf("%2X", *cdata);
		cdata++;
	}
	return (0);
}

