/* This function loads the J21 rate coeff file into the (global function) data arrays.
 * very similar to load_treecool TODO: generalize this
 * Format of the treecool table:
    alpha, Gamma_HI, Gamma_HeI, Gamma_HeII,  Qdot_HI, Qdot_HeI, Qdot_HeII,
    where 'Gamma' is the photoionization rate and 'Qdot' is the photoheating rate.
    The Gamma's are in units of s^-1, and the Qdot's are in units of erg s^-1.
*/
static void
load_J21coeffs(const char * J21CoeffFile)
{
    FILE * fd = fopen(J21CoeffFile, "r");
    if(!fd)
        endrun(456, "Could not open rate coefficients file at: '%s'\n", J21CoeffFile);

    /*Find size of file*/
    NJ21Coeffs = 0;
    do
    {
        char buffer[1024];
        char * retval = fgets(buffer, 1024, fd);
        /*Happens on end of file*/
        if(!retval)
            break;
        retval = strtok(buffer, " \t");
        /*Discard comments*/
        if(!retval || retval[0] == '#')
            continue;
        NJ21Coeffs++;
    }
    while(1);
    rewind(fd);

    MPI_Bcast(&(NJ21Coeffs), 1, MPI_INT, 0, MPI_COMM_WORLD);

    if(NJ21Coeffs<= 2)
        endrun(1, "Photon background contains: %d entries, not enough.\n", NJ21Coeffs);

    /*Allocate memory for the photon background table.*/
    Gamma_alpha = mymalloc("J21CoeffTable", 7 * NJ21Coeffs * sizeof(double));
    G_HI_coeff.ydata = Gamma_alpha + NJ21Coeffs;
    G_HeI_coeff.ydata = Gamma_alpha + 2 * NJ21Coeffs;
    G_HeII_coeff.ydata = Gamma_alpha + 3 * NJ21Coeffs;
    Eps_HI_coeff.ydata = Gamma_alpha + 4 * NJ21Coeffs;
    Eps_HeI_coeff.ydata = Gamma_alpha + 5 * NJ21Coeffs;
    Eps_HeII_coeff.ydata = Gamma_alpha + 6 * NJ21Coeffs;

    int ThisTask;
    MPI_Comm_rank(MPI_COMM_WORLD, &ThisTask);
    if(ThisTask == 0)
    {
        int i = 0;
        while(i < NJ21Coeffs)
        {
            char buffer[1024];
            char * saveptr;
            char * line = fgets(buffer, 1024, fd);
            /*Happens on end of file*/
            if(!line)
                break;
            char * retval = strtok_r(line, " \t", &saveptr);
            if(!retval || retval[0] == '#')
                continue;
            Gamma_alpha[i] = atof(retval);
            /*Get the rest*/
            G_HI_coeff.ydata[i]   = load_tree_value(&saveptr);
            G_HeI_coeff.ydata[i]  = load_tree_value(&saveptr);
            G_HeII_coeff.ydata[i] = load_tree_value(&saveptr);
            Eps_HI_coeff.ydata[i]     = load_tree_value(&saveptr)+ CoolingParams.HydrogenHeatAmp;
            Eps_HeI_coeff.ydata[i]    = load_tree_value(&saveptr);
            Eps_HeII_coeff.ydata[i]   = load_tree_value(&saveptr);
            i++;
        }

        fclose(fd);
    }

    /*Broadcast data to other processors*/
    MPI_Bcast(Gamma_alpha, 7 * NJ21Coeffs, MPI_DOUBLE, 0, MPI_COMM_WORLD);
    /*Initialize the UVB redshift interpolation: reticulate the splines*/
    init_itp_type(Gamma_alpha, &G_HI_coeff, NJ21Coeffs);
    init_itp_type(Gamma_alpha, &G_HeI_coeff, NJ21Coeffs);
    init_itp_type(Gamma_alpha, &G_HeII_coeff, NJ21Coeffs);
    init_itp_type(Gamma_alpha, &Eps_HI_coeff, NJ21Coeffs);
    init_itp_type(Gamma_alpha, &Eps_HeI_coeff, NJ21Coeffs);
    init_itp_type(Gamma_alpha, &Eps_HeII_coeff, NJ21Coeffs);

    message(0, "Read %d lines alpha = %g - %g, GHI %g - %g from file %s\n", NJ21Coeffs, Gamma_alpha[0], Gamma_alpha[NJ21Coeffs-1], G_HI_coeff.ydata[0], G_HI_coeff.ydata[NJ21Coeffs-1], J21CoeffFile);
}

/*Get photo ionization rate coeff*/
/*TODO(jdavies): this is very similar to get_photo_rate, and only one is used, find a way to combine*/
/*would need to change z to log(1+z) input in photorate and remove 10^x*/
static double
get_photorate_coeff(double alpha, struct itp_type * Gamma_tab)
{
    double photo_rate;
    if (alpha >= Gamma_alpha[NJ21Coeffs - 1])
        return 0;
    else if (alpha < Gamma_alpha[0])
        photo_rate = Gamma_tab->ydata[0];
    else {
        photo_rate = gsl_interp_eval(Gamma_tab->intp, Gamma_alpha, Gamma_tab->ydata, alpha, NULL);
    }
    //pow 10 here because the treecool load does log10
    return pow(10,photo_rate) * CoolingParams.PhotoIonizeFactor;
}

/* gets J21==1 rates from interpolation tables*/
/*TODO(jdavies): combine with get_global_UVBG somehow*/
struct J21_coeffs get_J21_coeffs(double alpha)
{
    struct J21_coeffs J21toUV;
    J21toUV.gJH0 = get_photorate_coeff(alpha, &G_HI_coeff);
    J21toUV.gJHe0 = get_photorate_coeff(alpha, &G_HeI_coeff);
    J21toUV.gJHep = get_photorate_coeff(alpha, &G_HeII_coeff);

    J21toUV.epsH0 = get_photorate_coeff(alpha, &Eps_HI_coeff);
    J21toUV.epsHe0 = get_photorate_coeff(alpha, &Eps_HeI_coeff);
    J21toUV.epsHep = get_photorate_coeff(alpha, &Eps_HeII_coeff);
    return J21toUV;
}

//set the parameters we need for the excursion set option
void set_uvf_params(ParameterSet * ps){
    int ThisTask;
    MPI_Comm_rank(MPI_COMM_WORLD, &ThisTask);
    if(ThisTask==0)
    {
        uvf_params.ExcursionSetReionOn = param_get_int(ps,"ExcursionSetReionOn");
        uvf_params.ExcursionSetZStop = param_get_double(ps,"ExcursionSetZStop");
        uvf_params.AlphaUV = param_get_double(ps,"AlphaUV");
    }

    MPI_Bcast(&uvf_params, sizeof(struct UVFparams), MPI_BYTE, 0, MPI_COMM_WORLD);
    return;
}

static struct UVBG get_local_UVBG_from_J21(double redshift, double J21, double zreion) {
    struct UVBG uvbg = {0};

    // N.B. J21 must be in units of 1e-21 erg s-1 Hz-1 (proper cm)-2 sr-1
    uvbg.J_UV = J21;
    uvbg.zreion = zreion;

    //interpolators in cooling_rates.c should now be rate coeffs
    //it seems a bit wasteful to calculate this for every particle
    //but the global uv does an interpolation every time and this allows
    //for future inhomogeneous alpha
    //if this becomes a bottleneck we can set the coeffs globally
    struct J21_coeffs J21toUV = get_J21_coeffs(uvf_params.AlphaUV);

    uvbg.gJH0   = J21toUV.gJH0 * J21; // s-1
    uvbg.epsH0  = J21toUV.epsH0 * J21 * 1.60218e-12;  // erg s-1
    uvbg.gJHe0  = J21toUV.gJHe0 * J21; // s-1
    uvbg.epsHe0 = J21toUV.epsHe0 * J21 * 1.60218e-12;  // erg s-1

    /*Since the excursion set only finds HII (& HeII) bubbles, and HeII -> HeIII
     * heating is taken care of by the qso_lightup model, there is never a case where we need these rates */
    /* NOTE: this means that the excursion set will be switched off before helium reionisation
     * and global rates must be used, otherwise helium will not ionise or heat */
    /* the excursion set (so far) only includes stellar ionising radiation, so
     * this is equivalent to the assumption that stars do not doubly ionise helium
     * which will need to change if we decide to add QSO radiation to the excursion set (i.e Qin et al. 2017, DRAGONS X)*/
    uvbg.gJHep = 0.;
    uvbg.epsHep = 0.;

    uvbg.self_shield_dens = get_self_shield_dens(redshift, &uvbg);

    return uvbg;
}

//switch function that decides whether to use excursion set or global UV background
/*TODO: Better continuity, if the z_reion tables provided finish after ExcursionSetZStop, particles could rapidly recombine.
 * also if helium reion starts before the excursion set finishes, flash reionisations occur as we switch to global*/
struct UVBG get_local_UVBG(double redshift, const struct UVBG * const GlobalUVBG, const double * const Pos, const double * const PosOffset, double J21, double zreion)
{
    if(uvf_params.ExcursionSetReionOn && (redshift > uvf_params.ExcursionSetZStop))
    {
        return get_local_UVBG_from_J21(redshift,J21,zreion);
    }
    else
    {
        return get_local_UVBG_from_global(redshift,GlobalUVBG,Pos,PosOffset);
    }
}

/* TODO: It would be a good idea to generalise this to arbitrary fof/particle properties */
static void fof_set_escapefraction(struct FOFGroups * fof, const int NgroupsExt, struct fof_particle_list * HaloLabel)
{
    int i = 0;
    #pragma omp parallel for
    for(i = 0; i < PartManager->NumPart; i++){
        if(P[i].Type == 0){
            SPHP(i).EscapeFraction = 0.;
        }
        if(P[i].Type == 4){
            STARP(i).EscapeFraction = 0.;	/* will mark particles that are not in any group */
        }
    }

    int start = 0;
    for(i = 0; i < NgroupsExt; i++)
    {
        /* find the first particle */
        for(;start < PartManager->NumPart; start++) {
            if(HaloLabel[start].MinID >= fof->Group[i].base.MinID) break;
        }
        /* add particles */
        for(;start < PartManager->NumPart; start++) {
            if(HaloLabel[start].MinID != fof->Group[i].base.MinID) {
                break;
            }
            int pi = HaloLabel[start].Pindex;

            /* putting halo mass in escape fraction for now, converted before uvbg calculation */
            //TODO: switch this off for gas particles if we are smoothing the star formation rate
            if(P[pi].Type == 0){
                SPHP(pi).EscapeFraction = fof->Group[i].Mass;
            }
            else if(P[pi].Type == 4){
                STARP(pi).EscapeFraction = fof->Group[i].Mass;
            }
        }
    }
}

/* initialise one set of regions with custom iterator 
 * this is the same as petapm_force_init with a custom iterator 
 * (and no CPS definition since it's called multiple times)*/
PetaPMRegion *
petapm_reion_init(
        PetaPM * pm,
        petapm_prepare_func prepare,
        pm_iterator iterator,
        PetaPMParticleStruct * pstruct,
        int * Nregions,
        void * userdata) {

    *Nregions = 0;
    PetaPMRegion * regions = prepare(pm, pstruct, userdata, Nregions);
    pm_init_regions(pm, regions, *Nregions);

    walltime_measure("/PMreion/Misc");
    pm_iterate(pm, iterator, regions, *Nregions);
    walltime_measure("/PMreion/cic");

    layout_prepare(pm, &pm->priv->layout, pm->priv->meshbuf, regions, *Nregions, pm->comm);

    walltime_measure("/PMreion/comm");
    return regions;
}

/* differences from force c2r (why I think I need this separate)
 * radius loop (could do this with long list of same function + global R)
 * I'm pretty sure I need a third function type (reion loop) with all three grids
 * ,after c2r but iteration over the grid, instead of particles */
void
petapm_reion_c2r(PetaPM * pm_mass, PetaPM * pm_star, PetaPM * pm_sfr,
        pfft_complex * mass_unfiltered, pfft_complex * star_unfiltered, pfft_complex * sfr_unfiltered,
        PetaPMRegion * regions,
        const int Nregions,
        PetaPMFunctions * functions,
        petapm_reion_func reion_loop,
        double R_max, double R_min, double R_delta, int use_sfr)
{
    PetaPMFunctions * f = functions;
    double R = fmin(R_max,pm_mass->BoxSize);
    int last_step = 0;
    int f_count = 0;
    petapm_transfer_func transfer = f->transfer;
    petapm_readout_func readout = f->readout;

    /* TODO: seriously re-think the allocation ordering in this function */
    double * mass_real = (double * ) mymalloc2("mass_real", pm_mass->priv->fftsize * sizeof(double));

    //TODO: add CellLengthFactor for lowres (>1Mpc, see old find_HII_bubbles function)
    while(!last_step) {
        f_count++;
        //The last step will be unfiltered
        if(R/R_delta < R_min || R/R_delta < (pm_mass->CellSize) || f_count > MAX_R_ITERATIONS)
        {
            last_step = 1;
            R = pm_mass->CellSize;
        }

        //NOTE: The PetaPM structs for reionisation use the G variable for filter radius in order to use
        //the transfer functions correctly
        pm_mass->G = R;
        pm_star->G = R;
        if(use_sfr)pm_sfr->G = R;

        //TODO: maybe allocate and free these outside the loop
        pfft_complex * mass_filtered = (pfft_complex *) mymalloc("mass_filtered", pm_mass->priv->fftsize * sizeof(double));
        pfft_complex * star_filtered = (pfft_complex *) mymalloc("star_filtered", pm_star->priv->fftsize * sizeof(double));
        pfft_complex * sfr_filtered;
        if(use_sfr){
            sfr_filtered = (pfft_complex *) mymalloc("sfr_filtered", pm_sfr->priv->fftsize * sizeof(double));
        }

        /* apply the filtering at this radius */
        /*We want the last step to be unfiltered,
         *  calling apply transfer with NULL should just copy the grids */

        transfer = last_step ? NULL : f->transfer;

        pm_apply_transfer_function(pm_mass, mass_unfiltered, mass_filtered, transfer);
        pm_apply_transfer_function(pm_star, star_unfiltered, star_filtered, transfer);
        if(use_sfr){
            pm_apply_transfer_function(pm_sfr, sfr_unfiltered, sfr_filtered, transfer);
        }
        walltime_measure("/PMreion/calc");

        double * star_real = (double * ) mymalloc2("star_real", pm_star->priv->fftsize * sizeof(double));
        //dummy pointer if SFR is not used
        double * sfr_real;
        if(use_sfr){
            sfr_real = (double * ) mymalloc2("sfr_real", pm_sfr->priv->fftsize * sizeof(double));
        }
        /* back to real space */
        pfft_execute_dft_c2r(pm_mass->priv->plan_back, mass_filtered, mass_real);
        pfft_execute_dft_c2r(pm_star->priv->plan_back, star_filtered, star_real);
        if(use_sfr){
            pfft_execute_dft_c2r(pm_sfr->priv->plan_back, sfr_filtered, sfr_real);
        }
        walltime_measure("/PMreion/c2r");

        if(use_sfr){
            myfree(sfr_filtered);
        }
        myfree(star_filtered);
        myfree(mass_filtered);

        /* the reion loop calculates the J21 and stores it,
         * for now the mass_real grid will be reused to hold J21
         * on the last filtering step*/
        reion_loop(pm_mass,pm_star,pm_sfr,mass_real,star_real,sfr_real,last_step);

        /* since we don't need to readout star and sfr grids...*/
        /* on the last step, the mass grid is populated with J21 and read out*/
        if(use_sfr){
            myfree(sfr_real);
        }
        myfree(star_real);

        R = R / R_delta;
    }
    //J21 grid is exchanged to pm_mass buffer and freed
    layout_build_and_exchange_cells_to_local(pm_mass, &pm_mass->priv->layout, pm_mass->priv->meshbuf, mass_real);
    walltime_measure("/PMreion/comm");
    //J21 read out to particles
    pm_iterate(pm_mass, readout, regions, Nregions);
    walltime_measure("/PMreion/readout");
}

/* We need a slightly different flow for reionisation, so I 
 * will define these here instead of messing with the force functions.
 * The c2r function is the same, however we need a new function, reion_loop
 * to run over all three filtered grids, after the inverse transform.
 * The c2r function itself is also different since we need to apply the
 * transfer (filter) function on all three grids and run reion_loop before any readout.*/
void petapm_reion(PetaPM * pm_mass, PetaPM * pm_star, PetaPM * pm_sfr,
        petapm_prepare_func prepare,
        PetaPMGlobalFunctions * global_functions, //petapm_transfer_func global_transfer,
        PetaPMFunctions * functions,
        PetaPMParticleStruct * pstruct,
        PetaPMReionPartStruct * rstruct,
        petapm_reion_func reion_loop,
        double R_max, double R_min, double R_delta, int use_sfr,
        void * userdata) {

    //assigning CPS here due to three sets of regions
    CPS = pstruct;
    CPS_R = rstruct;

    /* initialise regions for each grid
     * NOTE: these regions should be identical except for the grid buffer */
    int Nregions_mass, Nregions_star, Nregions_sfr;
    PetaPMRegion * regions_mass = petapm_reion_init(pm_mass, prepare, put_particle_to_mesh, pstruct, &Nregions_mass, userdata);
    PetaPMRegion * regions_star = petapm_reion_init(pm_star, prepare, put_star_to_mesh, pstruct, &Nregions_star, userdata);
    PetaPMRegion * regions_sfr;
    if(use_sfr){
        regions_sfr = petapm_reion_init(pm_sfr, prepare, put_sfr_to_mesh, pstruct, &Nregions_sfr, userdata);
    }

    walltime_measure("/PMreion/comm2");

    //using force r2c since this part can be done independently
    pfft_complex * mass_unfiltered = petapm_force_r2c(pm_mass, global_functions);
    pfft_complex * star_unfiltered = petapm_force_r2c(pm_star, global_functions);
    pfft_complex * sfr_unfiltered;
    if(use_sfr){
        sfr_unfiltered = petapm_force_r2c(pm_sfr, global_functions);
    }

    //need custom reion_c2r to implement the 3 grid c2r and readout
    //the readout is only performed on the mass grid so for now I only pass in regions/Nregions for mass
    if(functions)
        petapm_reion_c2r(pm_mass, pm_star, pm_sfr,
               mass_unfiltered, star_unfiltered, sfr_unfiltered,
               regions_mass, Nregions_mass, functions, reion_loop,
               R_max, R_min, R_delta, use_sfr);

    //free everything in the correct order
    if(use_sfr){
        myfree(sfr_unfiltered);
    }
    myfree(star_unfiltered);
    myfree(mass_unfiltered);

    if(CPS->RegionInd)
        myfree(CPS->RegionInd);

    if(use_sfr){
        myfree(regions_sfr);
    }
    myfree(regions_star);
    myfree(regions_mass);

    if(use_sfr){
        petapm_force_finish(pm_sfr);
    }
    petapm_force_finish(pm_star);
    petapm_force_finish(pm_mass);
}

//escape fraction scaled GSM
static void put_star_to_mesh(PetaPM * pm, int i, double * mesh, double weight) {
    if(INACTIVE(i) || *TYPE(i) != 4)
        return;
    double Mass = *MASS(i);
    double fesc = *FESC(i);
#pragma omp atomic update
    mesh[0] += weight * Mass * fesc;
}

//escape fraciton scaled SFR
static void put_sfr_to_mesh(PetaPM * pm, int i, double * mesh, double weight) {
    if(INACTIVE(i) || *TYPE(i) != 0)
        return;
    double Sfr = *SFR(i);
    double fesc = *FESCSPH(i);
#pragma omp atomic update
    mesh[0] += weight * Sfr * fesc;
}

