def test_star_broadcast():
    core.PATH_STAR = True
    val = {'a': [1, 2, 3]}
    assert glom(val, Path.from_text('a.*').path_t + 1) == [2, 3, 4]
    val = {'a': [{'b': [{'c': 1}, {'c': 2}, {'c': 3}]}]}
    assert glom(val, Path.from_text('**.c').path_t + 1) == [2, 3, 4]
    core.PATH_STAR = False

def __init__(self, *args, **kwargs):
        self.name = kwargs.pop('name', '')
        self.debug = kwargs.pop('debug', None)
        super().__init__()
        for _ in range(8):
            self.append({'id': None, 'type': None})

def as_table(self):
        colnames = list(ACA_CATALOG_DTYPES)
        colnames.remove('idx')
        rows = []
        for row in self:
            out = {}
            for name in ACA_CATALOG_DTYPES:
                try:
                    out[name] = row[name]
                except KeyError:
                    pass
            rows.append(out)
        return ACACatalogTable(rows)[colnames]

def __repr__(self):
        out = '\n'.join([self.name, str(self.as_table()), ''])
        return out

def _merge_cats_debug(cat_debug, tbl, message):
    if cat_debug and len(tbl) > 0:
        print('*' * 80)
        print(f'Adding {message}')
        print('*' * 80)

def __set__(self, instance, value):
        if isinstance(value, Table):
            colnames = ['coord0', 'coord1', 'coord_type', 'mag', 'function']
            if not set(colnames) <= set(value.colnames):
                raise ValueError(f'monitors input table must have {", ".join(colnames)} columns')
        else:
            value = np.asarray(value)
            if value.ndim != 2 or value.shape[1] != 5:
                raise ValueError('monitors input must have shape (N, 5)')
            out = Table()
            out['coord0'] = value[:, 0].astype(np.float64)
            out['coord1'] = value[:, 1].astype(np.float64)
            out['coord_type'] = value[:, 2].astype(np.uint8)
            out['mag'] = value[:, 3].astype(np.float64)
            out['function'] = value[:, 4].astype(np.uint8)
            value = out

            if np.any(out['coord_type'] < 0) or np.any(out['coord_type'] > 2):
                raise ValueError('monitors coord type must be 0, 1, or 2')

            if np.any(out['function'] < 0) or np.any(out['function'] > 3):
                raise ValueError('monitors function must be 0, 1, 2, or 3')

        instance.meta[self.name] = value

def pformat(self, *args, **kwargs):
        self._set_formats()
        return super().pformat(*args, **kwargs)

def pprint(self, *args, **kwargs):
        self._set_formats()
        return super().pprint(*args, **kwargs)

def t_ccd(self):
        # For fids use the guide CCD temperature
        return self.t_ccd_guide

def get_starcheck_obs_kwargs(filename):
    """
    Parse the starcheck.txt file to get keyword arg dicts for get_aca_catalog()

    :param filename: file name of starcheck.txt in load products
    :returns: dict (by obsid) of kwargs for get_aca_catalog()

    """
    delim = "==================================================================================== "
    with open(filename, 'r') as fh:
        text = fh.read()
    chunks = text.split(delim)
    outs = {}
    for chunk in chunks:
        if "No star catalog for obsid" in chunk:
            continue
        try:
            out = get_kwargs_from_starcheck_text(chunk, include_cat=True)

        except ValueError:
            continue
        else:
            outs[out['obsid']] = out

    return outs

