                                10,
                                "#ffad00",  // 10 to 100
                                100,
                                "#ff0006",  // 100 to 1000
                                1000,
                                "#ff00ef"  // 1000+
                            ],
                            "circle-radius": [
                                "step",
                                ["get", "point_count"],
                                12,  // 0 to 10
                                10,
                                14,  // 10 to 100
                                100,
                                16,  // 100 to 1000
                                1000,
                                18  // 1000+
                            ]
                        }
                    });

                    map.addLayer({
                        id: "sounds-cluster-labels",
