  it('basic beforeSave requireUserKey as admin', async function (done) {
    Parse.Cloud.beforeSave(Parse.User, () => {}, {
      fields: {
        admin: {
          default: false,
          constant: true,
        },
      },
    });
    Parse.Cloud.define(
      'secureFunction',
      () => {
        return "Here's all the secure data!";
      },
      {
        requireUserKeys: {
          admin: {
            options: true,
            error: 'Unauthorized.',
          },
        },
      }
    );
