      await Parse.Cloud.run('secureFunction');
      fail('function should only be available to admin users');
    } catch (error) {
      expect(error.code).toEqual(Parse.Error.VALIDATION_ERROR);
      expect(error.message).toEqual('Unauthorized.');
    }
    done();
  }

