def __lt__(self, other: "Project") -> bool:
        if self.online:
            return self.num_stars < other.num_stars
        else:
            return self.name < other.name

def header(cls) -> str:
        return (
            f"| {'Name':{cls.NAME}} | CI | OS | Notes |\n"
            f"|{'':-^{cls.NAME+2  }}|----|----|:------|"
        )

def table_row(self) -> str:
        notes = self.notes.replace('\n', ' ')
        return f"| {self.namelink: <{self.NAME}} | {self.ci_icons} | {self.os_icons} | {notes} |"

def info(self) -> str:
        days = (datetime.utcnow() - self.pushed_at).days
        return f"<!-- {self.name}: {self.num_stars}, last pushed {days} days ago -->"

def str_projects(
    config: List[Dict[str, Any]], *, online: bool = True, auth: Optional[str] = None
) -> str:
    io = StringIO()
    print = functools.partial(builtins.print, file=io)

    if online:
        for icon in ICONS:
            fetch_icon(icon)

    github = Github(auth) if online else None

    projects = sorted((Project(item, github) for item in config), reverse=online)

    print(Project.header())
    for project in projects:
        print(project.table_row())

    print()
    for project in projects:
        print(project.links())

    print()
    for icon in ICONS:
        print(f"[{icon} icon]: {path_for_icon(icon).as_posix()}")

    print()
    for project in projects:
        print(project.info())

    return io.getvalue()

//NewRepoCmd configures the repo manage command
func NewRepoCmd(ctx context.Context, dockerCli command.Cli) *cobra.Command {
	cmd := &cobra.Command{
		Use:  "repo",
		Long: "Manage repositories",
		Args: cli.NoArgs,
		RunE: command.ShowHelp(dockerCli.Err()),
	}
	cmd.AddCommand(
		newListCmd(ctx, dockerCli),
		newRmCmd(ctx, dockerCli),
	)
	return cmd
}

func(r hub.Repository) string {
			if r.LastUpdated.Nanosecond() == 0 {
				return ""
			}
			return fmt.Sprintf("%s ago", units.HumanDuration(time.Since(r.LastUpdated)))
		}

func newListCmd(ctx context.Context, dockerCli command.Cli) *cobra.Command {
	cmd := &cobra.Command{
		Use:   "ls",
		Short: "List all the repositories",
		Args:  cli.NoArgs,
		RunE: func(_ *cobra.Command, args []string) error {
			return runList(ctx, dockerCli)
		},
	}
	return cmd
}

func(_ *cobra.Command, args []string) error {
			return runList(ctx, dockerCli)
		}

func runList(ctx context.Context, dockerCli command.Cli) error {
	authResolver := func(hub *registry.IndexInfo) types.AuthConfig {
		return command.ResolveAuthConfig(ctx, dockerCli, hub)
	}
	client, err := hub.NewClient(authResolver)
	if err != nil {
		return err
	}
	repositories, err := client.GetRepositories()
	if err != nil {
		return err
	}

	w := tabwriter.NewWriter(os.Stdout, 20, 1, 3, ' ', 0)
	var headers []string
	for _, column := range defaultColumns {
		headers = append(headers, column.header)
	}
	fmt.Fprintln(w, strings.Join(headers, "\t"))

	for _, repository := range repositories {
		var values []string
		for _, column := range defaultColumns {
			values = append(values, column.value(repository))
		}
		fmt.Fprintln(w, strings.Join(values, "\t"))
	}
	return w.Flush()
}

func(hub *registry.IndexInfo) types.AuthConfig {
		return command.ResolveAuthConfig(ctx, dockerCli, hub)
	}

func newRmCmd(ctx context.Context, dockerCli command.Cli) *cobra.Command {
	var opts rmOptions
	cmd := &cobra.Command{
		Use:   "rm [OPTIONS] REPOSITORY",
		Short: "Delete a repository",
		Args:  cli.ExactArgs(1),
		RunE: func(_ *cobra.Command, args []string) error {
			return runRm(ctx, dockerCli, opts, args[0])
		},
	}
	cmd.Flags().BoolVar(&opts.force, "force", false, "Force deletion of the repository")
	return cmd
}

func(_ *cobra.Command, args []string) error {
			return runRm(ctx, dockerCli, opts, args[0])
		}

func runRm(ctx context.Context, dockerCli command.Cli, opts rmOptions, repository string) error {
	ref, err := reference.Parse(repository)
	if err != nil {
		return err
	}
	namedRef, ok := ref.(reference.Named)
	if !ok {
		return fmt.Errorf("invalid reference: repository not specified")
	}

	if !opts.force {
		fmt.Println("Please type the name of your repository to confirm deletion:", namedRef.Name())
		reader := bufio.NewReader(os.Stdin)
		input, _ := reader.ReadString('\n')
		input = strings.ToLower(strings.TrimSpace(input))
		if input != namedRef.Name() {
			return fmt.Errorf("%q differs from your repository name, deletion aborted", input)
		}
	}

	authResolver := func(hub *registry.IndexInfo) types.AuthConfig {
		return command.ResolveAuthConfig(ctx, dockerCli, hub)
	}
	client, err := hub.NewClient(authResolver)
	if err != nil {
		return err
	}
	if err := client.RemoveRepository(namedRef.Name()); err != nil {
		return err
	}
	fmt.Println("Deleted", repository)
	return nil
}

func(hub *registry.IndexInfo) types.AuthConfig {
		return command.ResolveAuthConfig(ctx, dockerCli, hub)
	}

//GetRepositories lists all the repositories a user can access
func (h *Client) GetRepositories() ([]Repository, error) {
	u, err := url.Parse(h.domain + fmt.Sprintf(RepositoriesURL, h.user))
	if err != nil {
		return nil, err
	}
	q := url.Values{}
	q.Add("page_size", fmt.Sprintf("%v", itemsPerPage))
	q.Add("page", "1")
	q.Add("ordering", "last_updated")
	u.RawQuery = q.Encode()

	repos, next, err := h.getRepositoriesPage(u.String())
	if err != nil {
		return nil, err
	}

	for next != "" {
		pageRepos, n, err := h.getRepositoriesPage(next)
		if err != nil {
			return nil, err
		}
		next = n
		repos = append(repos, pageRepos...)
	}

	return repos, nil
}

func (h *Client) getRepositoriesPage(url string) ([]Repository, string, error) {
	req, err := http.NewRequest("GET", url, nil)
	if err != nil {
		return nil, "", err
	}
	req.Header["Authorization"] = []string{fmt.Sprintf("Bearer %s", h.token)}
	response, err := doRequest(req)
	if err != nil {
		return nil, "", err
	}
	var hubResponse hubRepositoryResponse
	if err := json.Unmarshal(response, &hubResponse); err != nil {
		return nil, "", err
	}
	var repos []Repository
	for _, result := range hubResponse.Results {
		repo := Repository{
			Name:        result.Name,
			Description: result.Description,
			LastUpdated: result.LastUpdated,
			PullCount:   result.PullCount,
			StarCount:   result.StarCount,
			IsPrivate:   result.IsPrivate,
		}
		repos = append(repos, repo)
	}
	return repos, hubResponse.Next, nil
}

function initStars() {
  var stars = 800
  var starElem = document.getElementById('stars')
  console.log(starElem)
  var r = 500

  for (var i = 0; i < stars; i++) {
    var star = document.createElement('div')
    star.className = 'star'
    starElem.appendChild(star)
  }

  var allStars = document.getElementsByClassName('star')
  for (let cur of allStars) {
    var s = 0.2 + Math.random()
    var curR = r + Math.random() * 1800

    cur.style.transformOrigin = '0 0 ' + curR + 'px'
    cur.style.transform =
      'translate3d(0,0,-' +
      curR +
      'px) rotateY(' +
      Math.random() * 360 +
      'deg) rotateX(' +
      Math.random() * -50 +
      'deg) scale(' +
      s +
      ',' +
      s +
      ')'
  }
}

() => {
    	const lastPoint = {x:this.x,y:this.y};
    	//Move the particle periodically
    	this.radians += this.velocity;

    	//Drag Effect
    	this.lastMouse.x += (mouse.x - this.lastMouse.x)* 0.05;
    	this.lastMouse.y += (mouse.y - this.lastMouse.y)* 0.05;
    	//circular motion
    	this.x = this.lastMouse.x + Math.cos(this.radians) * this.distanceFromCenter;
    	this.y = this.lastMouse.y + Math.sin(this.radians) * this.distanceFromCenter;

    	this.draw(lastPoint);
    }

