        reviews.add(review2);

        doReturn(Optional.of(book))
                .when(bookRepository)
                .findById(1L);

        doReturn(book)
                .when(bookRepository)
                .save(book);

        doReturn(reviews)
                .when(reviewRepository)
                .findByBook(1L);

        Book new_book = bookService.calculateStars(1L, 3, Strategy.UPDATE, 5);

        assert new_book.getStars() == 3;
    }

