@Override
    public void tryHit(final float dt){
        if (passedTime * 2 > time && isHit()) {
            float signAcc = passedTime - time;
            if (Config.isFixFrameOffset()) {
                signAcc += (float) hitOffsetToPreviousFrame() / 1000f;
            }
            final float acc = Math.abs(signAcc);
            //Log.i("note-ini", "signAcc: " + signAcc);
            if (acc <= GameHelper.getDifficultyHelper().hitWindowFor50(GameHelper.getDifficulty())) {
                playSound();
            }
            listener.registerAccuracy(signAcc);
            passedTime = -1;
            // Remove circle and register hit in update thread
            float finalSignAcc = signAcc;
            SyncTaskManager.getInstance().run(() -> {
                HitCircle.this.listener
                        .onCircleHit(id, finalSignAcc, pos, endsCombo, (byte) 0, color);
                removeFromScene();
            });

        }
    }

@Override
    public void tryHit(final float dt){
        if (startHit == false) // If we didn't get start hit(click)
        {
            if (isHit() && -passedTime < GameHelper.getDifficultyHelper().hitWindowFor50(GameHelper.getDifficulty())) // if
            // we
            // clicked
            {
                listener.registerAccuracy(passedTime);
                startHit = true;
                Utils.playHitSound(listener, soundId[0], sampleSet[0], addition[0]);
                ticksGot++;
                firstHitAccuracy = (int) (passedTime * 1000);
                listener.onSliderHit(id, 30, null, path.points.get(0),
                        false, color, GameObjectListener.SLIDER_START);
            }
            if (passedTime < 0) // we at approach time
            {
                if (startHit == true) {
                    approachCircle.setAlpha(0);
                }
            }
        }
    }

