def create_pie_plot(self, labels, values, title, colors=None):
        fig = go.Figure()
        if colors:
            fig.add_trace(go.Pie(labels=labels, values=values, marker={'colors': colors}))
        else:
            fig.add_trace(go.Pie(labels=labels, values=values))

        fig.update_layout(
