async (e, setShow) => {
    e.preventDefault();
    const { ratings: { rating, feedback } } = this.state;
    const {
      showAlert, rateAccommodation, accommodation, GetSingleAccommodation,
    } = this.props;

    await this.setState({
      error: {
        status: false,
        heading: '',
        message: '',
      },
    });

    if (rating <= 3 && feedback === '') {
      await this.setState({
        error: {
          status: true,
          heading: 'Invalid Rating',
          message: 'Please supply feedback for ratings under a 4',
        },
      });
      return showAlert();
    }

    const payload = {
      accommodationId: accommodation.id,
      rating,
      ...(rating <= 3 && { feedback }),
      ...((rating > 3 && feedback !== '') && { feedback }),
    };

    await rateAccommodation(payload, setShow);
    await GetSingleAccommodation(accommodation.slug);
  }

(state = initialState, action) => {
  switch (action.type) {
    case RATE_ACCOMMODATION:
      return {
        ...state,
        data: action.payload,
        status: 'success',
        dataError: '',
      };
    case RATE_ACCOMMODATION_ERROR:
      return {
        ...state,
        dataError: action.payload,
        data: '',
        status: 'error',
      };
    default:
      return {
        ...state,
      };
  }
}

