@VisibleForTesting
    static void setupMethods(PrivateMethodAccessor accessor) {
        //Note: Multiple of these can succeed.
        Pair<Class, Method> nativeImpl = accessor.getPrivateMethod(NATIVE_CLASS, "isActionButton");
        sNativeClassRef = nativeImpl.first;
        sNativeIsActionButton = nativeImpl.second;

        Pair<Class, Method> androidXImpl =  accessor.getPrivateMethod(ANDROIDX_CLASS, "isActionButton");
        sAndroidXClassRef = androidXImpl.first;
        sAndroidXIsActionButton = androidXImpl.second;
    }

@CheckResult
    private static Pair<Class, Method> getPrivateMethodHandleSystemErrors(String className, String methodName) {
        Method action = null;
        Class<?> menuItemImpl = null;
        try {
            //We know this won't always work, we'll log if this isn't the case.
            menuItemImpl = Class.forName(className);
            action = menuItemImpl.getDeclaredMethod(methodName);
            action.setAccessible(true);
            Timber.d("Setup ActionBarOverflow: %s", className);
        } catch (Exception | NoSuchFieldError | NoSuchMethodError ignoreAndLogEx) {
            //See: #5806. MenuItemImpl;->isActionButton is on the light greylist
            //https://developer.android.com/distribute/best-practices/develop/restrictions-non-sdk-interfaces#results-of-keeping-non-sdk
            Timber.d(ignoreAndLogEx, "Failed to handle: %s", className);
        }

        return new Pair<>(menuItemImpl, action);
    }

    /**
     * Check if an item is showing (not in the overflow menu).
     *
     * @param item
     *            the MenuItem.
     * @return {@code true} if the MenuItem is visible on the ActionBar. {@code false} if not. {@code null if unknown}
     */
public static @Nullable Boolean isActionButton(MenuItem item) {
        if (sNativeClassRef != null && sNativeClassRef.isInstance(item)) {
            return tryInvokeMethod(item, sNativeIsActionButton);
        } else if (sAndroidXClassRef != null && sAndroidXClassRef.isInstance(item)) {
            return tryInvokeMethod(item, sAndroidXIsActionButton);
        } else {
            Timber.w("Unhandled ActionBar class: %s", item.getClass().getName());
            return null;
        }
    }

private static Boolean tryInvokeMethod(MenuItem item, Method method) {
        try {
            return (boolean) method.invoke(item, (Object[]) null);
        } catch (Exception  | NoSuchFieldError | NoSuchMethodError ex) {
            Timber.w(ex, "Error handling ActionBar class: %s", item.getClass().getName());
            return null;
        }
    }

@VisibleForTesting(otherwise = VisibleForTesting.NONE)
    static boolean hasUsableMethod() {
        return  sNativeIsActionButton != null ||
                sAndroidXIsActionButton != null;

    }

@CheckResult
    @VisibleForTesting(otherwise = VisibleForTesting.NONE)
    static Pair<Class, Method> getPrivateMethodOnlyHandleExceptions(String className, String methodName) {
        Method action = null;
        Class<?> menuItemImpl = null;
        try {
            menuItemImpl = Class.forName(className);
            action = menuItemImpl.getDeclaredMethod(methodName);
            action.setAccessible(true);
            Timber.d("Setup ActionBarOverflow: %s", className);
        } catch (Exception ignoreAndLogEx) {
            Timber.d(ignoreAndLogEx, "Failed to handle: %s", className);
        }

        return new Pair<>(menuItemImpl, action);
    }

def get_layer_type(self):
        """
        Recursively go till the top until layer is not reached
        """
        if isinstance(self.parent, common.Layer.Layer):
            return self.parent.get_type()
        return self.parent.get_layer_type()

def get_loop(self):
        """
        Returns whether the bline is looped or not
        """
        loop = False
        if "loop" in self.bline.keys():
            v = self.bline.attrib["loop"]
            if v == "true":
                loop = True
        return loop

def extract_entries(self, entry_list):
        """
        Stores the entries in a list
        """
        for entry in self.bline:
            # Assuming it's child is always composite for now
            entry_list.append({})
            if entry[0].tag == "composite":
                element = entry[0]
            else:
                element = entry
            for param in element:
                tag = param.tag
                if tag == "animated":   # For dynamic list
                    tag = param.attrib["type"]
                entry_list[-1][tag] = common.Param.Param(param, element)
            if entry[0].tag == "composite":
                entry_list[-1]["composite"] = element

def get_len(self):
        """
        Returns the number of entries
        """
        return len(self.entry_list)

def set_entry(self, itr, entry, tag="vector"):
        """
        Sets the entry at itr to val
        """
        for param in entry:
            self.entry_list[itr][tag] = common.Param.Param(param, entry)

def __init__(self, canvas):
        """
        """
        if isinstance(canvas, Param):
            self.canvas = canvas.get()[0]
            # If canvas is derived from a parameter store that parameter also
            self.parent_param = canvas
        else:
            self.canvas = canvas
        self.defs = {}
        self.extract_defs(self.defs)
        self.layers = []
        self.extract_layers(self.layers)
        self.bones = {}
        self.extract_bones(self.bones)
        self.set_name()

def set_name(self):
        """
        Sets the name of the canvas
        """
        found = False
        for child in self.canvas:
            if child.tag == "name":
                self.name = child.text
                found = True
        if not found:
            self.name = settings.CANVAS_NAME + str(settings.canvas_count.inc())

def extract_defs(self, defs_dict):
        """
        Will store all the defs with there id's as there keys
        """
        for child in self.canvas:
            if child.tag == "defs":
                defs = child

                for child in defs:
                    key = child.attrib["id"]
                    defs_dict[key] = child

def extract_layers(self, layer_list):
        """
        Will store all the layers in a list
        """
        for child in self.canvas:
            if child.tag == "layer":
                layer_list.append(Layer(child, self))

def extract_bones(self, bones_dict):
        """
        Will store all the bones in a dictionary
        """
        for chld in self.canvas:
            if chld.tag == "bones":
                bones = chld

                for child in bones:
                    key = child.attrib["guid"]
                    bones_dict[key] = Param(child, Param(bones, self))

def get_num_layers(self):
        """
        Returns the number of layers in the canvas
        """
        return len(self.layers)

def set_group_params(self):
        """
        If the current layer is group, it sets the immediate children parameters
        as group_children=1. This is needed in convert methods like
        radial_composite and bone_link
        """
        typ = self.get_type()
        if typ in settings.GROUP_LAYER or typ in settings.PRE_COMP_LAYER:
            for param in self.params.values():
                param.is_group_child = True

def extract_params(self, params):
        """
        Will extract the parameters from the layer and store in params
        """
        for child in self.layer:
            if child.tag == "param":
                key = child.attrib["name"]
                params[key] = Param(child, self)
        self.set_group_params()

def get_param(self, *keys):
        """
        Given a key, this will return the address of the child corresponding to
        it
        If multiple keys are given, it will return the key found first
        """
        for key in keys:
            if key in self.params.keys():
                return self.params[key]
        return Param(None, None)
        #raise KeyError("No parameter %s in Layer %s", key, self.get_type())

def set_description(self):
        """
        Sets the layer description if given, otherwise the default description
        is set
        """
        if "desc" in self.layer.keys():
            self.description = self.layer.attrib["desc"]
        else:
            # Set the default name
            if self.get_type() in settings.SHAPE_LAYER:
                desc = settings.LAYER_SHAPE_NAME
            elif self.get_type() in set.union(settings.SOLID_LAYER, settings.SHAPE_SOLID_LAYER):
                desc = settings.LAYER_SOLID_NAME
            elif self.get_type() in settings.IMAGE_LAYER:
                desc = settings.LAYER_IMAGE_NAME
            elif self.get_type() in set.union(settings.PRE_COMP_LAYER, settings.GROUP_LAYER):
                desc = settings.LAYER_PRECOMP_NAME
            else:
                desc = settings.UNKNOWN_LAYER
            desc += str(settings.layer_count.inc())
            self.description = desc

def add_offset(self):
        """
        Inserts necassary offset in the positions of the layers if they lie inside
        another composition of Lottie
        """
        # This if condition is not applicable for group, rotate, precomp... layers
        if not settings.INSIDE_PRECOMP:
            return

        update_dict = []
        compare = {"center", "origin", "point1", "point2", "tl", "br"}
        for key in compare:
            param = self.get_param(key)
            if param.get() is not None:
                update_dict.append(param)

        for param in update_dict:
            param.add_offset()

def get_layer_type(self):
        """
        Recursively go till the top until layer is not reached
        """
        if isinstance(self.parent, common.Layer.Layer):
            return self.parent.get_type()
        return self.parent.get_layer_type()

def get_layer(self):
        """
        Recursively find the layer
        """
        if isinstance(self.parent, common.Layer.Layer):
            return self.parent
        return self.parent.get_layer()

def get_canvas(self):
        """
        Recursively find the canvas
        """
        if isinstance(self.parent, common.Canvas.Canvas):
            return self.parent
        return self.parent.get_canvas()

def append_same_key(self, key, child):
        """
        Helps append in the dict if same key is already present
        """
        val = Param(child, self)

        if self.is_group_child:
            val.is_group_child = True

        if isinstance(self.subparams[key], list):
            self.subparams[key].append(val)
        else:
            prev = self.subparams[key]
            self.subparams[key] = [prev, val]

def extract_subparams(self):
        """
        Extracts the subparameters of this parameter and stores with there tag
        as the key
        """
        if self.SUBPARAMS_EXTRACTED:
            return
        self.SUBPARAMS_EXTRACTED = 1
        self.subparams.clear()
        for child in self.param:
            key = child.tag 
            if key in self.subparams.keys():
                self.append_same_key(key, child)
            else:
                self.subparams[key] = Param(child, self)

                if self.is_group_child:
                    self.subparams[key].is_group_child = True

def called_by(self, dic):
        """
        Checks if this function's ancestor are in this dictionary
        """
        for it in inspect.stack():
            if it[3] in dic:
                return True
        return False

def gen_path(self, anim_type="real", idx=0):
        """
        Generates the path for this parameter over time depending on the
        animation type of this parameter
        """
        self.path = {}
        if anim_type in {"real", "bool"}:
            gen_value_Keyframed(self.path, self.param[0], idx)
        else:
            gen_properties_multi_dimensional_keyframed(self.path, self.param[0], idx)

def get_single_value(self, frame):
        """
        Returns the value of some parameter which is not a convert method
        """
        if self.param[0].attrib["type"] == "bool":  # No need of lottie format path here
            return get_bool_at_frame(self.param[0], frame)

        if not self.path:   # Empty dictionary
            raise KeyError("Please calculate the path of this parameter before getting value at a frame")
        return get_vector_at_frame(self.path, frame)

def waypoint_at_frame(anim, frame):
    """
    Returns true if a waypoint is present at 'frame'
    """
    for waypoint in anim:
        fr = get_frame(waypoint)
        if fr == frame:
            return True
    return False

def modify_bool_animation(anim):
    """
    Inserts waypoints at such frames so that the animation is similar to that in
    lottie
    """
    i = 0
    while i < len(anim):
        cur_fr = get_frame(anim[i])
        val_now = get_bool_at_frame(anim, cur_fr)
        # Check at one frame less and one frame more: only cases
        if cur_fr - 1 >= settings.lottie_format["ip"] and not waypoint_at_frame(anim, cur_fr-1):
            val_before = get_bool_at_frame(anim, cur_fr - 1)
            if val_now != val_before:
                new = copy.deepcopy(anim[i])
                new.attrib["time"] = str((cur_fr - 1)/settings.lottie_format["fr"]) + "s"
                if val_before:
                    new[0].attrib["value"] = "true"
                else:
                    new[0].attrib["value"] = "false"
                anim.insert(i, new)
                i += 1
        if cur_fr + 1 <= settings.lottie_format["op"] and not waypoint_at_frame(anim, cur_fr + 1):
            val_after = get_bool_at_frame(anim, cur_fr + 1)
            if val_after != val_now:
                new = copy.deepcopy(anim[i])
                new.attrib["time"] = str((cur_fr + 1)/settings.lottie_format["fr"]) + "s"
                if val_after:
                    new[0].attrib["value"] = "true"
                else:
                    new[0].attrib["value"] = "false"
                anim.insert(i+1, new)
                i += 1

        i += 1

    # Make the animation constant
    for waypoint in anim:
        waypoint.attrib["before"] = waypoint.attrib["after"] = "constant"

/**
 * Renders an "nyc bus stats" style summary of a route and direction.
 *
 * @param {any} props
 */
function InfoScoreCard(props) {

  const {
    grades,
    gradeName,
    hideRating,
    title,
    largeValue,
    smallValue,
    bottomContent,
    popoverContent,
  } = props;

  const useStyles = makeStyles(theme => ({
    popover: {
        padding: theme.spacing(2),
      },
  }));

  const classes = useStyles();

  const [anchorEl, setAnchorEl] = useState(null);

  function handleClick(event) {
    setAnchorEl(event.currentTarget);
  }

  function handleClose() {
    setAnchorEl(null);
  }

  const cardStyle = (grades, gradeName) => {
    return {
      background:
        grades
          ? quartileBackgroundColor(grades[gradeName] / 100.0)
          : 'gray',
      color:
        grades
          ? quartileForegroundColor(grades[gradeName] / 100.0)
          : 'black',
      margin: 4
    }
  };


  const rating = grades ? Math.max(Math.round(grades[gradeName] / 10.0) / 2.0, 0.5) : 0;

  return (
    <Fragment>
      <Grid item xs component={Paper} style={cardStyle(grades, gradeName)}>
        <Box display="flex" flexDirection="column" justifyContent="flex-start" height="100%">                  
          <Typography variant="overline">
            {title}
          </Typography>

          <Box flexGrow={1}> {/* middle area takes all possible height */}

            <Typography variant="h3" display="inline">
              {largeValue}  
            </Typography>

            <Typography variant="h5" display="inline">
              {smallValue}
            </Typography>

            { hideRating ? null : <Rating
              readOnly
              size="small"
              value={rating}
              precision={0.5}
              />}
          </Box>
          <Box display="flex" justifyContent="space-between" alignItems="flex-end" pt={2}>
            {bottomContent}
            <IconButton size='small' onClick={handleClick} ><InfoIcon fontSize='small'/></IconButton>                  
          </Box>
        </Box>
      </Grid>

      <Popover
        open={Boolean(anchorEl)}
        anchorEl={anchorEl}
        onClose={handleClose}
        anchorOrigin={{
          vertical: 'bottom',
          horizontal: 'center',
        }}
        transformOrigin={{
          vertical: 'top',
          horizontal: 'center',
        }}
      >
        <div className={classes.popover}>
          {popoverContent}
        </div>
      </Popover>  
    </Fragment>     
  )      
}

