def comment(self, item_id: int) -> ControllerResponse:
        assert self.item_reviewed_field != "reviewed_item"  # Reviewed item not set"
        comment_fields = {field: val for (field, val) in self.request_fields.items()
                          if field in Comment.field_names()}
        comment_fields['author'] = self.author
        comment_fields.update({self.item_reviewed_field: self.model.objects.get(pk=item_id)})
        comment = self.comment_model(**comment_fields)
        comment.save()
        return ControllerResponse(status_text='Retrieved', obj=comment)

def render_stream_view(self) -> HttpResponse:
        if self.request.user.is_authenticated:
            return UserPostStreamView.as_view()(self.request)
        else:
            return GuestPostStreamView.as_view()(self.request)

def retrieve_all(self) -> ControllerResponse:
        all_items = super().retrieve_all().obj
        for item in all_items:
            if item.author == self.author:
                item.hidden = True
        return ControllerResponse(status_text='Retrieved', obj=all_items)

def retrieve_all_following(self) -> ControllerResponse:
        posts = []
        for followee in self.author.user.following.all():
            posts.extend(Author.objects.get(user=followee).post_set.all())
        return ControllerResponse(status_text='Retrieved posts from followees', obj=list(posts))

def update_post(self, pk: int) -> ControllerResponse:
        obj = self.find_by_id(pk)
        if obj.author == self.author:
            return super().update(obj)
        else:
            return ControllerResponseForbidden()

def delete_post(self, pk: int) -> ControllerResponse:
        obj = self.find_by_id(pk)
        if obj.author == self.author:
            return self.delete(obj)
        else:
            return ControllerResponseForbidden()

def rate(self, pk: int):
        item_reviewed = self.model.objects.get(pk=pk)
        if self.author == item_reviewed.author:
            return ControllerResponseForbidden()
        rating_score = int(self.request_fields['rating_score'])
        rating_fields = {'author': self.request_fields['author']}
        if self.model == Comment:
            rating_fields['reviewed_comment'] = item_reviewed
        elif self.model == Recipe:
            rating_fields['reviewed_recipe'] = item_reviewed
        elif self.model == Post:
            rating_fields['reviewed_post'] = item_reviewed
        try:
            rating = Rating.objects.get(**rating_fields)
            rating.old_rating_value = rating.rating_value
        except Rating.DoesNotExist:
            rating = Rating(**rating_fields)
        rating.rating_value = rating_score
        rating.save()
        item_reviewed.aggregate_rating.add_rating(rating, update=hasattr(rating, 'old_rating_value'))
        return ControllerResponse(status_text='Rated', obj=item_reviewed.aggregate_rating)

