(state = { articlesData: {} }, action) => {
  switch (action.type) {
    case GET_ARTICLES:
      return { ...state, articles: action.articlesData };
    case ARTICLES_ERROR:
      normalStats.push(action.error);
      return { ...state, error: normalStats };
    default:
      return state;
  }
}

(state = { searchData: {} }, action) => {
  switch (action.type) {
    case SEARCH_ARTICLE:
      return { ...state, articles: action.searchData, searchFailed: false };
    case SEARCH_ERROR:
      return { ...state, searchFailed: true };
    default:
      return state;
  }
}

