def __get__(self, instance, owner):
        if instance is None:
            # When called without an instance, return self to allow access
            # to descriptor attributes.
            return self
        else:
            return getattr(instance, self.alias)

def __set_name__(self, owner, name):
        if owner.__name__.endswith('Table'):
            self.alias = name + '_' + owner.__name__[:-5].lower()
            owner.allowed_kwargs.add(name)
        else:
            raise ValueError('can only be used in classes named *Table')

public boolean hasPageStreamingMethods() {
    for (MethodConfig methodConfig : getMethodConfigs()) {
      if (methodConfig.isPageStreaming()) {
        return true;
      }
    }
    return false;
  }

public boolean hasBundlingMethods() {
    for (MethodConfig methodConfig : getMethodConfigs()) {
      if (methodConfig.isBundling()) {
        return true;
      }
    }
    return false;
  }

public boolean hasGrpcStreamingMethods() {
    for (MethodConfig methodConfig : getMethodConfigs()) {
