    /**
     * Generates an array corresponding to the trophy distribution according
     * to the ranking array given as parameter.
     * @param ranking The sorted ranking array corresponding to the stars that each player
     *                earned
     * @return Returns the trophy array
     */
public static Integer[] generateTrophiesFromRanking(Integer[] ranking) {
        Integer[] trophies = new Integer[ranking.length];
        trophies[0] = MAX_RANK;
        for(int i = 1; i < trophies.length; ++i) {
            if(ranking[i-1].intValue() == ranking[i].intValue()) {
                trophies[i] = trophies[i-1];
            } else {
                trophies[i] = MAX_RANK - DELTA_RANK * i;
            }
        }

        return trophies;
    }

    /**
     * Generates an array corresponding to the final position distribution according
     * to the ranking array given as parameter.
     * @param ranking The sorted ranking array corresponding to the stars that each player
     *                earned
     * @return Returns the position array
     */
public static Integer[] generatePositionsFromRanking(Integer[] ranking) {
        Integer[] positions = new Integer[ranking.length];
        positions[0] = 1;
        for(int i = 1; i < positions.length; ++i) {
            if(ranking[i-1].intValue() == ranking[i].intValue()) {
                positions[i] = positions[i-1];
            } else {
                positions[i] = i + 1;
            }
        }

        return positions;
    }

    /**
     * Returns a string array with the sign of the number in front of this latter. In other words
     * the number 10 becomes +10.
     * @param list List of the numbers
     * @return A list of number with the respective sign
     */
public static String[] addSignToNumber(Integer[] list) {
        String[] numbersWithSign = new String[list.length];

        for(int i = 0; i < numbersWithSign.length; ++i) {
            numbersWithSign[i] = list[i] > 0 ? "+" + String.valueOf(list[i])
                                                    : String.valueOf(list[i]);
        }

        return numbersWithSign;
    }

@Test
    public void testGenerateTrophiesFromRanking() {
        Integer[] ranking = new Integer[] {5, 5, 4, 2, 0};

        Integer[] trophies = RankingUtils.generateTrophiesFromRanking(ranking);
        Integer[] result = new Integer[] {10, 10, 0, -5, -10};
        assertThat(trophies, is(result));

        ranking = new Integer[] {5, 5, 5, 5, 5};

        trophies = RankingUtils.generateTrophiesFromRanking(ranking);
        result = new Integer[] {10, 10, 10, 10, 10};

        assertThat(trophies, is(result));
    }

@Test
    public void testGeneratePositionsFromRanking() {
        Integer[] ranking = new Integer[] {5, 5, 4, 2, 0};

        Integer[] trophies = RankingUtils.generatePositionsFromRanking(ranking);
        Integer[] result = new Integer[] {1, 1, 3, 4, 5};
        assertThat(trophies, is(result));
    }

@Test
    public void testAddSignToNumbers() {
        Integer[] input = new Integer[] {10, 10, 0, -5, -10};
        String[] expectedOutput = new String[] {"+10", "+10", "0", "-5", "-10"};

        assertThat(RankingUtils.addSignToNumber(input), is(expectedOutput));
    }

