    const {
      handleRating, ratingInfo, slug, getArticle, prevUserRating,
    } = this.props;

    if (prevUserRating) return;
    const ratingData = {
      article: slug,
      rating,
    };
    await handleRating(ratingData);
    getArticle(slug);
    if (ratingInfo.error) {
      M.toast({
