		if (/\bo-table\b/.test(el.getAttribute('data-o-component'))) {
			return new OTable(el);
		}
		const tableEls = Array.from(el.querySelectorAll('[data-o-component~="o-table"]'));
		return tableEls.map(el => {
			return new OTable(el);
