function(FolderSyncService, Account, AccountCollection, Folder, Message,
	State) {

	describe('FolderSyncService', function() {
		var server;

		beforeEach(function() {
			State.accounts = new AccountCollection();
			server = sinon.fakeServer.create();
		});

		afterEach(function() {
			State.accounts = new AccountCollection();
			server.restore();
		});

		it('syncs the sync token of a single folder', function(done) {
			var account = new Account({
				accountId: 15
			});
			var folder = new Folder({
				id: 'SU5CT1g=',
				syncToken: 'oldToken',
				account: account
			});
			folder.addMessage(new Message({
				id: 123
			}));
			folder.addMessage(new Message({
				id: 124
			}));

			var syncing = FolderSyncService.syncFolder(folder);

			expect(server.requests.length).toBe(1);
			server.requests[0].respond(
				200,
				{
					'Content-Type': 'application/json'
				},
				JSON.stringify({
					token: 'newToken',
					newMessages: [
						{
							id: 125
						}
					],
					changedMessages: [],
					vanishedMessages: []
				})
				);

			syncing.then(function() {
				expect(folder.messages.pluck('id')).toEqual([123, 124, 125]);
				done();
			}).catch(function(e) {
				console.error(e);
				done.fail(e);
			});
		});

		it('syncs new messages in a single folder', function(done) {
			var account = new Account({
				accountId: 15
			});
			var folder = new Folder({
				id: 'SU5CT1g=',
				syncToken: 'oldToken',
				account: account
			});
			folder.addMessage(new Message({
				id: 123
			}));
			folder.addMessage(new Message({
				id: 124
			}));

			var syncing = FolderSyncService.syncFolder(folder);

			expect(server.requests.length).toBe(1);
			server.requests[0].respond(
				200,
				{
					'Content-Type': 'application/json'
				},
				JSON.stringify({
					token: 'newToken',
					newMessages: [
						{
							id: 125
						}
					],
					changedMessages: [],
					vanishedMessages: []
				})
				);

			syncing.then(function() {
				expect(folder.messages.pluck('id')).toEqual([123, 124, 125]);
				done();
			}).catch(function(e) {
				console.error(e);
				done.fail(e);
			});
		});

		it('syncs changed messages in a single folder', function(done) {
			var account = new Account({
				accountId: 15
			});
			var folder = new Folder({
				id: 'SU5CT1g=',
				syncToken: 'oldToken',
				account: account
			});
			folder.addMessage(new Message({
				id: 123,
				subject: 'old subject'
			}));
			folder.addMessage(new Message({
				id: 124
			}));

			var syncing = FolderSyncService.syncFolder(folder);

			expect(server.requests.length).toBe(1);
			server.requests[0].respond(
				200,
				{
					'Content-Type': 'application/json'
				},
				JSON.stringify({
					token: 'newToken',
					newMessages: [],
					changedMessages: [
						{
							id: 123,
							subject: 'new subject'
						}
					],
					vanishedMessages: []
				})
				);

			syncing.then(function() {
				expect(folder.messages.get(123).
					get('subject')).toEqual('new subject');
				done();
			}).catch(function(e) {
				console.error(e);
				done.fail(e);
			});
		});

		it('syncs vanished messages in a single folder', function(done) {
			var account = new Account({
				accountId: 15
			});
