def main(args):
    all_seg_ids = np.loadtxt(args.seg_list_file, delimiter=" ",dtype='S2')
    if args.apply_cuts is True:
        apply_selection(args, all_seg_ids)
    else:
        # No selection cuts applied. Writes entire input catalog to selected galaxies file
        for seg in all_seg_ids:
            for f, filt in enumerate(args.filter_names):
                cat_name = args.main_path + seg + '/' + filt + '_with_pstamp.fits'
                cat[f] = Table.read(cat_name, format= 'fits')
                new_cat_name = args.main_path + seg + '/' + filt + '_selected.fits'
                cat[f].write(new_cat_name, format='fits', overwrite=True) 
    #Saves catalog in a format that can be read by galsim
    get_in_galsim.make_all(args)

def div_pixels(seg_map, num):
    """Get pixels that belong to image, other objects, background from
    segmentation map
    """
    s = seg_map.shape
    xs = range(s[0])
    ys = range(s[1])
    bl = []
    oth = {}
    oth_segs = []
    im = []
    check = 0
    for x in xs:
        for y in ys:
            if seg_map[x, y] == 0:
                # background pixel
                bl.append([x, y])
            elif seg_map[x, y] == int(num) + 1:
                # image pixel
                im.append([x, y])
            else:
                # other object
                if oth.has_key(str(seg_map[x, y])):
                    oth[str(seg_map[x, y])].append([x, y])
                else:
                    oth[str(seg_map[x, y])] = [[x, y]]
                    oth_segs.append(str(seg_map[x, y]))
    if seg_map[s[0] / 2, s[1] / 2] != int(num) + 1:
        check = 1
    return im, bl, oth, oth_segs, check

def get_avg_around_pix(x0, y0, arr):
    """Returns average values of pixels around (x0,y0) in arr"""
    x, y = [x0], [y0]
    if x0 > 0:
        x.append(x0 - 1)
    if arr.shape[0] - 1 > x0:
        x.append(x0 + 1)
    if y0 > 0:
        y.append(y0 - 1)
    if arr.shape[1] - 1 > y0:
        y.append(y0 + 1)
    neighb = [arr[i][j] for i in x for j in y]
    avg = np.mean(neighb)
    return avg

def select_good_stars(catalog, nstars=25):
    """Return indices of nstars with the highest SNR in catalog."""
    dtype = [('snr', float), ('index',int)]
    values = np.array([(-np.inf,-1)], dtype=dtype)
    for i in range(catalog.nrows):
        if (catalog['IS_STAR'][i] == 1) and (catalog['IN_MASK'][i] == 0):
            values = np.append(values, np.array([(catalog['SNR'][i],
                                                catalog['NUMBER'][i])],dtype=dtype))
    best_stars = np.sort(values, order='snr')[-nstars:]['index']
    return best_stars

def get_closest_tt(x0, y0, tt_table, dist=200.):    
    x = tt_table.T[0]
    y = tt_table.T[1]
    d = ((x-x0)**2+(y-y0)**2)**0.5 
    best = np.argmin(d)
    if (abs(x0-x[best]) < dist and abs(y0-y[best]) < dist):
        return [x[best],y[best]]
    else:
        return False

def set_col_any(arr, val, buff, set_to):
    """Set the column value to set_to that are within buff of any non zero value in arr"""
    s = arr.shape
    for i in range(s[1]):
        temp = arr[:,i]
        if val:
            q, = np.where(temp==val)
        else:
            q, = np.where(temp!=0)
        d = np.array([range(j-buff,j+buff+1) for j in q])
        d = d.reshape(1,d.size)[0]
        d = d[np.where((d>=0) &(d<s[0]))]
        if len(d) != 0: 
            temp[d]= set_to
        arr[:,i]=temp
    return arr

