def __init__(self,args):
        self.file_name = args.file_name.replace('seg_id', args.seg_id)
        self.seg_id = args.seg_id
        self.filters = args.filter_names
        self.out_path = args.out_path
        self.tt_file_path = args.tt_file_path       
        self.focus = args.focus
        if args.file_path[-1] != '/':
            self.file_path = args.file_path+'/'
        else:
            self.file_path = args.file_path
        self.data_files = {}
        for i in range(len(self.filters)):
            filter1 = self.filters[i]
            self.data_files[filter1] = self.file_path + filter1 + '/' + self.file_name.replace('filter', filter1)
        self.tt_file_name = {}
        for focus in self.focus:
            self.tt_file_name[focus] = args.tt_file_name.replace('focus', 'f'+str(focus))

def split_for_natural_sort(s):
    """
    split a string *s* for natural sort.
    """
    return tuple((int(y) if y.isdigit() else y for y in re.split(r'(\d+)', s)))

def evaluate_expression(expression, catalog_instance):
    """
    evaluate a numexpr expression on a GCR catalog
    """
    quantities_needed = set(ne.necompiler.precompile(expression)[-1])
    if not catalog_instance.has_quantities(quantities_needed):
        raise KeyError("Not all quantities needed exist")
    return ne.evaluate(expression,
                       local_dict=catalog_instance.get_quantities(quantities_needed),
                       global_dict={})

def postQualify()  = if (!(postQualifiedWith contains trueOwner)) {
      postQualifiedWith ::= trueOwner
      modifyName(s => s"$s(in $trueOwner)")
    }

def isSyntheticWarnable(sym: Symbol) = (
          sym.isDefaultGetter 
        )

def unusedTerms = {
          val all = defnTrees.toList.filter(v => isUnusedTerm(v.symbol))

          // filter out setters if already warning for getter, indicated by position.
          // also documentary names in patterns.
          all.filterNot(v =>
              v.symbol.isSetter && all.exists(g => g.symbol.isGetter && g.symbol.pos.point == v.symbol.pos.point)
           || atBounds.exists(x => v.symbol.pos.point == x.pos.point)
          ).sortBy(treepos)
        }

def isImplementation(m: Symbol): Boolean = {
            val opc = new overridingPairs.Cursor(classOf(m))
            opc.iterator.exists(pair => pair.low == m)
          }

def isConvention(p: Symbol): Boolean = {
            (p.name.decoded == "args" && p.owner.isMethod && p.owner.name.decoded == "main") ||
            (p.tpe =:= typeOf[scala.Predef.DummyImplicit])
          }

def warnable(s: Symbol) = (
               (settings.warnUnusedParams || s.isImplicit)
            && !isImplementation(s.owner)
            && !isConvention(s)
          )

// RunAndPipe runs the given command, and logs the process to the given writer
func RunAndPipe(dir string, env []string, writer io.Writer, commandWords ...string) error {
	if len(commandWords) == 1 {
		var err error
		commandWords, err = ParseCommand(commandWords[0])
		if err != nil {
			return err
		}
	}
	cmd := exec.Command(commandWords[0], commandWords[1:]...)
	cmd.Dir = dir
	cmd.Env = append(os.Environ(), env...)
	cmd.Stdout = writer
	cmd.Stderr = writer
	PrintBanner(writer)
	if err := cmd.Run(); err != nil {
		return errors.Wrapf(err, "Error running '%s'", strings.Join(commandWords, " "))
	}
	PrintBanner(writer)
	return nil
}

// PrintBanner prints a banner separator
func PrintBanner(writer io.Writer) {
	separator := strings.Repeat("*", 80)
	fmt.Fprintf(writer, "%s\n", separator)
}

// Helper: Run the C compiler and capture stderr
static std::pair<int, std::string> runCC45(const std::string& cCode) {
    // Write C code to temp file
    std::ofstream c_file("/tmp/test_struct_temp.c");
    c_file << cCode;
    c_file.close();

    // Run cc45 and capture stderr only
    int ret = system("./bin/cc45 /tmp/test_struct_temp.c -o /tmp/test_struct_temp.s 2>/tmp/test_struct_stderr.txt >/dev/null");

    // Read captured stderr
    std::string stderr_content;
    std::ifstream stderr_file("/tmp/test_struct_stderr.txt");
    if (stderr_file) {
        std::stringstream buffer;
        buffer << stderr_file.rdbuf();
        stderr_content = buffer.str();
        stderr_file.close();
    }

    return {ret, stderr_content};
}

