			if tc.agentEnv != "" {
				t.Setenv("AGENT_ENV", tc.agentEnv)
			}
			if tc.piCodingAgent != "" {
				t.Setenv("PI_CODING_AGENT", tc.piCodingAgent)
			}

			resp, err := handleDetect()
