			assert.Equal(t, tc.wantDetected, resp.Detected, tc.failurePrevented)
			if tc.wantReason != "" {
				assert.Equal(t, tc.wantReason, resp.Reason, tc.failurePrevented)
			}
		}

def _apply_bmm_dot_dtype_requirements(_lowering: AtenLowering, node: Node) -> Lowering:
    """Handle bmm.dtype by stripping the ScalarType arg and reusing bmm_lowering."""
    node.args = tuple(a for a in node.args if isinstance(a, Node))
    return apply_dot_requirements(bmm_lowering, node)

/// Validates `arr` per the conventions in IREECPUEnums.td. Used inside an
/// `assert()` at the end of `getMmaIntrinsicsForTargetConfig` so it only
/// runs in debug builds — it constructs `DataTiledMMAAttr` instances to
/// inspect tile shapes/types, which would be too expensive to do
/// unconditionally on every cost-model query.
///
/// Conditions:
///   1. Strictly increasing in enum value (subsumes "no duplicates" and
///      rules out misordered pairs).
///   2. By the bit-0 convention from IREECPUEnums.td, every M↔N-swapped
///      entry (bit 0 set) is immediately preceded by its natural sibling
///      (`prev == v ^ 1`).
///   3. For each (natural, swapped) sibling pair, the swapped entry's
///      tile type has M↔N exchanged and LHS↔RHS element types exchanged
///      vs the natural's; K and ACC element type are unchanged.
///   4. A natural entry without a swapped sibling (singleton) must be
///      self-symmetric: square shape AND identical LHS/RHS element types
///      — otherwise the swapped orientation would be a distinct operation
///      and the array would be incomplete.
///
/// The type-polymorphic generic-scalar 1×1×1 family is square and
/// type-polymorphic, so it satisfies (4) vacuously. We skip the
/// `DataTiledMMAAttr`-based extraction for it (passing null element types
/// to the attr would invalidate the resulting vector types).
static bool isMmaIntrinsicArrayValid(MLIRContext *ctx,
                                     ArrayRef<IREE::CPU::MMAIntrinsic> arr) {
  using IREE::CPU::DataTiledMMAAttr;
  using IREE::CPU::MMAIntrinsic;

  // Conventions (1) and (2): order, strict increase, swap-pair structure.
  if (!arr.empty() && (static_cast<uint32_t>(arr[0]) & 1) != 0) {
    return false;
  }
  for (size_t i = 1; i < arr.size(); ++i) {
    uint32_t v = static_cast<uint32_t>(arr[i]);
    uint32_t prev = static_cast<uint32_t>(arr[i - 1]);
    if (prev >= v) {
      return false;
    }
    if ((v & 1) != 0 && prev != (v ^ 1)) {
      return false;
    }
  }

  // For (3) and (4) we need shape + element types from `DataTiledMMAAttr`.
  auto getShapeAndTypes = [&](MMAIntrinsic intr) {
    auto attr = DataTiledMMAAttr::get(ctx, intr, /*intrinsics_m=*/1,
                                      /*intrinsics_n=*/1, /*intrinsics_k=*/1,
                                      /*lhs_type=*/Type(),
                                      /*rhs_type=*/Type(),
                                      /*acc_type=*/Type());
    SmallVector<VectorType> tiles;
    attr.getUndistributedTileTypes(tiles);
    assert(tiles.size() == 3);
    return std::make_tuple(tiles[0].getShape()[0],     // M (LHS dim 0)
                           tiles[1].getShape()[0],     // N (RHS dim 0)
                           tiles[0].getShape()[1],     // K (LHS dim 1)
                           tiles[0].getElementType(),  // LHS elem
                           tiles[1].getElementType(),  // RHS elem
                           tiles[2].getElementType()); // ACC elem
  };

  for (size_t i = 0; i < arr.size(); ++i) {
    if ((static_cast<uint32_t>(arr[i]) & 1) != 0) {
      continue; // swapped entry — checked when we hit its natural sibling.
    }
    if (IREE::CPU::isGenericScalar(arr[i])) {
      continue; // type-polymorphic 1×1×1: vacuously valid.
    }
    auto [mn, nn, kn, lhsn, rhsn, accn] = getShapeAndTypes(arr[i]);
    bool hasSibling =
        (i + 1 < arr.size()) && (static_cast<uint32_t>(arr[i + 1]) ==
                                 (static_cast<uint32_t>(arr[i]) | 1));
    if (hasSibling) {
      auto [ms, ns, ks, lhss, rhss, accs] = getShapeAndTypes(arr[i + 1]);
      // Condition (3): siblings have M↔N and LHS↔RHS exchanged; K and ACC
      // element type are unchanged.
      if (ms != nn || ns != mn || ks != kn) {
        return false;
      }
      if (lhss != rhsn || rhss != lhsn || accs != accn) {
        return false;
      }
    } else {
      // Condition (4): singleton — must be self-symmetric.
      if (mn != nn || lhsn != rhsn) {
        return false;
      }
    }
  }
  return true;
}

/**
 * Check whether the process with the given PID is a LightNVR instance.
 *
 * On Linux we inspect /proc/<pid>/comm which contains the executable name
 * (up to 15 characters, as set by the kernel).  A lightnvr process will
 * always have "lightnvr" there.
 *
 * This prevents false positives on container restart: after a container is
 * stopped and started again the PID namespace is reused from 1, so the PID
 * that was recorded in the PID file from the previous run may now belong to
 * a completely unrelated process (e.g. a shell, go2rtc, or a system daemon).
 * Killing that unrelated process would crash the container.
 *
 * Returns true  if the process is (or may be) a LightNVR instance.
 * Returns false if we can positively confirm it is NOT LightNVR (stale PID).
 */
static bool is_lightnvr_process(pid_t pid) {
#ifdef __linux__
    char path[64];
    snprintf(path, sizeof(path), "/proc/%d/comm", (int)pid);
    FILE *fp = fopen(path, "r");
    if (!fp) {
        /* Cannot read comm – be conservative and assume it might be lightnvr. */
        return true;
    }
    char comm[32] = {0};
    bool ok = (fgets(comm, sizeof(comm), fp) != NULL);
    fclose(fp);
    if (!ok) {
        return true;
    }
    comm[strcspn(comm, "\n")] = '\0';
    /* The kernel truncates comm to TASK_COMM_LEN-1 (15) characters, so
     * "lightnvr" (8 chars) is always preserved in full. */
    return strcmp(comm, "lightnvr") == 0;
#else
    /* On non-Linux platforms we cannot easily inspect the process name,
     * so conservatively assume it might be lightnvr. */
    (void)pid;
    return true;
#endif
}

public FormDraftController(FormDraftService draftService, CaseRepository caseRepository) {
    this.draftService = draftService;
    this.caseRepository = caseRepository;
  }

@GetMapping("/{caseId}/forms/{formId}/draft")
  @PreAuthorize("isAuthenticated()")
  @Transactional(readOnly = true)
  public ResponseEntity<ApiResponse<FormDraftDto>> get(
      @PathVariable UUID caseId,
      @PathVariable String formId,
      @AuthenticationPrincipal WksUserPrincipal actor) {
    requireCaseExists(caseId);
    Optional<FormDraft> found = draftService.findDraft(caseId, formId, actor.id());
    return found
        .map(d -> ResponseEntity.ok(ApiResponse.success(FormDraftDto.from(d))))
        .orElseGet(() -> ResponseEntity.<ApiResponse<FormDraftDto>>notFound().build());
  }

@PutMapping("/{caseId}/forms/{formId}/draft")
  @PreAuthorize("isAuthenticated()")
  @Transactional
  public ResponseEntity<ApiResponse<FormDraftDto>> put(
      @PathVariable UUID caseId,
      @PathVariable String formId,
      @Valid @RequestBody SaveDraftRequest body,
      @AuthenticationPrincipal WksUserPrincipal actor) {
    requireCaseExists(caseId);
    FormDraft saved =
        draftService.saveDraft(
            caseId,
            formId,
            actor.id(),
            body.payload(),
            body.scrollY(),
            body.sectionExpanded(),
            body.caseTypeVersionAtSave());
    return ResponseEntity.ok(ApiResponse.success(FormDraftDto.from(saved)));
  }

@DeleteMapping("/{caseId}/forms/{formId}/draft")
  @PreAuthorize("isAuthenticated()")
  @Transactional
  public ResponseEntity<Void> delete(
      @PathVariable UUID caseId,
      @PathVariable String formId,
      @AuthenticationPrincipal WksUserPrincipal actor) {
    requireCaseExists(caseId);
    draftService.deleteDraft(caseId, formId, actor.id());
    return ResponseEntity.noContent().build();
  }

private void requireCaseExists(UUID caseId) {
    Case existing =
        caseRepository
            .findById(caseId)
            .orElseThrow(() -> new WksNotFoundException("Case " + caseId + " not found"));
    // referenced solely to confirm the row exists; assignee/RBAC checks live elsewhere.
    if (existing == null) {
      throw new WksNotFoundException("Case " + caseId + " not found");
    }
  }

