func TestComposition_AnyOfAll(t *testing.T) {
	// Stop if (score >= 100 AND score <= 200) OR score >= 500
	// With score = 150: first All fires (100<=150<=200), Any should stop.
	c := Any(
		All(ScoreThreshold(100.0, false), ScoreThreshold(200.0, true)),
		ScoreThreshold(500.0, false),
	)
	if !c.ShouldStop(0, 150.0) {
		t.Fatal("AnyOfAll: expected stop at score=150 (100<=150<=200)")
	}
	if c.ShouldStop(0, 300.0) {
		t.Fatal("AnyOfAll: 300 fails the All group and doesn't meet 500 threshold, should not stop")
	}
	if !c.ShouldStop(0, 600.0) {
		t.Fatal("AnyOfAll: expected stop at score=600 (>=500)")
	}
}

// recordStats collects per-generation statistics into g.Statistics when the
// collector is non-nil.
func (g *Generation[T]) recordStats(generation int) {
	if g.Statistics == nil {
		return
	}
	scores := make([]float64, len(g.Individuals))
	karvas := make([]string, len(g.Individuals))
	for i, ind := range g.Individuals {
		scores[i] = ind.Score
		karvas[i] = ind.Genome.KarvaString()
	}
	s := statistics.Record(generation, scores, karvas, g.MinimizeScore)
	g.Statistics.Append(s)
}

// --- Statistics integration tests ---

func TestEvolve_Statistics_CollectedEachGeneration(t *testing.T) {
	// Statistics.History must have exactly one entry per evaluated generation.
	const iters = 5
	sf := func(core.Genome[int]) float64 { return 0.5 } // never triggers default stop
	g := newTestGeneration(t, 17, sf)
	col := &statistics.Collector{}
	g.Statistics = col
	g.Evolve(iters)
	// iters loop entries + 1 final evaluation = iters+1
	want := iters + 1
	if len(col.History) != want {
		t.Fatalf("Statistics.History len=%d, want %d", len(col.History), want)
	}
}

