func TestEvolve_Statistics_GenerationIndicesAscending(t *testing.T) {
	// Generation indices in the history must increase monotonically.
	const iters = 8
	sf := func(core.Genome[int]) float64 { return 0.1 }
	g := newTestGeneration(t, 21, sf)
	col := &statistics.Collector{}
	g.Statistics = col
	g.Evolve(iters)

	for i := 1; i < len(col.History); i++ {
		if col.History[i].Generation <= col.History[i-1].Generation {
			t.Errorf("History[%d].Generation=%d not > History[%d].Generation=%d",
				i, col.History[i].Generation, i-1, col.History[i-1].Generation)
		}
	}
}

func TestEvolve_Statistics_BestScoreNonDecreasing(t *testing.T) {
	// With elitism, the best score must never decrease across generations
	// when maximizing.
	const iters = 10
	sf := func(g core.Genome[int]) float64 {
		return float64(len(g.KarvaString()))
	}
	gen := newTestGeneration(t, 23, sf)
	col := &statistics.Collector{}
	gen.Statistics = col
	gen.Evolve(iters)

	for i := 1; i < len(col.History); i++ {
		if col.History[i].BestScore < col.History[i-1].BestScore {
			t.Errorf("BestScore decreased at generation %d: %v < %v",
				col.History[i].Generation,
				col.History[i].BestScore,
				col.History[i-1].BestScore)
		}
	}
}

func(g core.Genome[int]) float64 {
		return float64(len(g.KarvaString()))
	}

func TestEvolve_Statistics_DiversityInRange(t *testing.T) {
	// Diversity must always be in [0, 1].
	const iters = 10
	sf := func(core.Genome[int]) float64 { return 1.0 }
	g := newTestGeneration(t, 25, sf)
	col := &statistics.Collector{}
	g.Statistics = col
	g.Evolve(iters)

	for _, s := range col.History {
		if s.Diversity < 0 || s.Diversity > 1 {
			t.Errorf("Diversity=%v out of [0,1] at generation %d", s.Diversity, s.Generation)
		}
	}
}

func TestEvolve_Statistics_EarlyStop_HistoryStopsAtStop(t *testing.T) {
	// When Evolve stops early (StopFunc returns true), the history must contain
	// entries only up to and including the stopping generation.
	stopGen := 4
	callCount := 0
	sf := func(core.Genome[int]) float64 { return 0.5 }
	g := newTestGeneration(t, 27, sf)
	col := &statistics.Collector{}
	g.Statistics = col
	g.StopFunc = func(Individual[int]) bool {
		callCount++
		return callCount >= stopGen
	}
	g.Evolve(100)
	// StopFunc is called after statistics are recorded, so we expect exactly
	// stopGen entries (one per iteration until stop).
	if len(col.History) != stopGen {
		t.Fatalf("Statistics.History len=%d, want %d (stopGen)", len(col.History), stopGen)
	}
}

func(Individual[int]) bool {
		callCount++
		return callCount >= stopGen
	}

// Record computes per-generation statistics from the given scores and optional
// Karva-string representations.
//
// generation is the zero-based generation index.
// scores must be non-empty; all scores contribute to BestScore, WorstScore,
// and MeanScore.
// karvaStrings may be nil or empty, in which case Diversity is 0.
// minimize controls whether "best" means lowest (true) or highest (false).
//
// Record does not modify any internal state; it returns the computed Stats
// directly. Use Collector.Append to accumulate results over time.
func Record(generation int, scores []float64, karvaStrings []string, minimize bool) Stats {
	if len(scores) == 0 {
		return Stats{Generation: generation}
	}

	best := scores[0]
	worst := scores[0]
	sum := scores[0]
	for _, s := range scores[1:] {
		sum += s
		if minimize {
			if s < best {
				best = s
			}
			if s > worst {
				worst = s
			}
		} else {
			if s > best {
				best = s
			}
			if s < worst {
				worst = s
			}
		}
	}
	mean := sum / float64(len(scores))

	diversity := 0.0
	if len(karvaStrings) > 0 {
		seen := make(map[string]struct{}, len(karvaStrings))
		for _, k := range karvaStrings {
			seen[k] = struct{}{}
		}
		diversity = float64(len(seen)) / float64(len(karvaStrings))
	}

	return Stats{
		Generation: generation,
		BestScore:  best,
		WorstScore: worst,
		MeanScore:  mean,
		Diversity:  diversity,
	}
}

// Append adds s to the collector's History.
func (c *Collector) Append(s Stats) {
	c.History = append(c.History, s)
}

// Last returns the most recently appended Stats. If History is empty, Last
// returns the zero Stats value.
func (c *Collector) Last() Stats {
	if len(c.History) == 0 {
		return Stats{}
	}
	return c.History[len(c.History)-1]
}

// --- Record tests ---

func TestRecord_EmptyScores(t *testing.T) {
	s := Record(0, nil, nil, false)
	if s.Generation != 0 {
		t.Errorf("Generation=%d, want 0", s.Generation)
	}
	if s.BestScore != 0 || s.WorstScore != 0 || s.MeanScore != 0 || s.Diversity != 0 {
		t.Errorf("non-zero stats for empty scores: %+v", s)
	}
}

func TestRecord_SingleScore_Maximize(t *testing.T) {
	s := Record(3, []float64{7.5}, nil, false)
	if s.Generation != 3 {
		t.Errorf("Generation=%d, want 3", s.Generation)
	}
	if s.BestScore != 7.5 {
		t.Errorf("BestScore=%v, want 7.5", s.BestScore)
	}
	if s.WorstScore != 7.5 {
		t.Errorf("WorstScore=%v, want 7.5", s.WorstScore)
	}
	if s.MeanScore != 7.5 {
		t.Errorf("MeanScore=%v, want 7.5", s.MeanScore)
	}
	if s.Diversity != 0 {
		t.Errorf("Diversity=%v, want 0 (no karva strings)", s.Diversity)
	}
}

func TestRecord_Maximize_BestWorstMean(t *testing.T) {
	scores := []float64{1.0, 5.0, 3.0, 2.0, 4.0}
	s := Record(1, scores, nil, false)
	if s.BestScore != 5.0 {
		t.Errorf("BestScore=%v, want 5.0", s.BestScore)
	}
	if s.WorstScore != 1.0 {
		t.Errorf("WorstScore=%v, want 1.0", s.WorstScore)
	}
	wantMean := (1.0 + 5.0 + 3.0 + 2.0 + 4.0) / 5.0
	if math.Abs(s.MeanScore-wantMean) > 1e-9 {
		t.Errorf("MeanScore=%v, want %v", s.MeanScore, wantMean)
	}
}

func TestRecord_Minimize_BestWorstMean(t *testing.T) {
	scores := []float64{1.0, 5.0, 3.0, 2.0, 4.0}
	s := Record(2, scores, nil, true)
	if s.BestScore != 1.0 {
		t.Errorf("BestScore=%v, want 1.0 (minimize)", s.BestScore)
	}
	if s.WorstScore != 5.0 {
		t.Errorf("WorstScore=%v, want 5.0 (minimize)", s.WorstScore)
	}
	wantMean := (1.0 + 5.0 + 3.0 + 2.0 + 4.0) / 5.0
	if math.Abs(s.MeanScore-wantMean) > 1e-9 {
		t.Errorf("MeanScore=%v, want %v", s.MeanScore, wantMean)
	}
}

func TestRecord_NegativeScores(t *testing.T) {
	scores := []float64{-5.0, -2.0, -8.0, -1.0}
	s := Record(0, scores, nil, false)
	if s.BestScore != -1.0 {
		t.Errorf("BestScore=%v, want -1.0", s.BestScore)
	}
	if s.WorstScore != -8.0 {
		t.Errorf("WorstScore=%v, want -8.0", s.WorstScore)
	}
}

func TestRecord_AllEqualScores(t *testing.T) {
	scores := []float64{3.0, 3.0, 3.0}
	s := Record(0, scores, nil, false)
	if s.BestScore != 3.0 {
		t.Errorf("BestScore=%v, want 3.0", s.BestScore)
	}
	if s.WorstScore != 3.0 {
		t.Errorf("WorstScore=%v, want 3.0", s.WorstScore)
	}
	if s.MeanScore != 3.0 {
		t.Errorf("MeanScore=%v, want 3.0", s.MeanScore)
	}
}

func TestRecord_GenerationIndex(t *testing.T) {
	for _, gen := range []int{0, 1, 42, 999} {
		s := Record(gen, []float64{1.0}, nil, false)
		if s.Generation != gen {
			t.Errorf("gen=%d: Stats.Generation=%d, want %d", gen, s.Generation, gen)
		}
	}
}

// --- Diversity tests ---

func TestRecord_Diversity_AllUnique(t *testing.T) {
	karvas := []string{"a|b", "c|d", "e|f", "g|h"}
	s := Record(0, []float64{1, 2, 3, 4}, karvas, false)
	if s.Diversity != 1.0 {
		t.Errorf("Diversity=%v, want 1.0 (all unique)", s.Diversity)
	}
}

func TestRecord_Diversity_AllIdentical(t *testing.T) {
	karvas := []string{"a|b", "a|b", "a|b"}
	s := Record(0, []float64{1, 2, 3}, karvas, false)
	wantDiv := 1.0 / 3.0
	if math.Abs(s.Diversity-wantDiv) > 1e-9 {
		t.Errorf("Diversity=%v, want %v (all identical)", s.Diversity, wantDiv)
	}
}

func TestRecord_Diversity_Mixed(t *testing.T) {
	// 4 karva strings, 3 unique → diversity = 3/4
	karvas := []string{"a", "b", "a", "c"}
	s := Record(0, []float64{1, 2, 3, 4}, karvas, false)
	wantDiv := 3.0 / 4.0
	if math.Abs(s.Diversity-wantDiv) > 1e-9 {
		t.Errorf("Diversity=%v, want %v", s.Diversity, wantDiv)
	}
}

func TestRecord_Diversity_NilKarvaStrings(t *testing.T) {
	s := Record(0, []float64{1, 2, 3}, nil, false)
	if s.Diversity != 0 {
		t.Errorf("Diversity=%v, want 0 (nil karva strings)", s.Diversity)
	}
}

func TestRecord_Diversity_EmptyKarvaStrings(t *testing.T) {
	s := Record(0, []float64{1, 2, 3}, []string{}, false)
	if s.Diversity != 0 {
		t.Errorf("Diversity=%v, want 0 (empty karva strings)", s.Diversity)
	}
}

// --- Collector tests ---

func TestCollector_AppendAndHistory(t *testing.T) {
	col := &Collector{}
	if len(col.History) != 0 {
		t.Fatalf("new Collector has non-empty history: %d entries", len(col.History))
	}

	s0 := Record(0, []float64{1, 2, 3}, nil, false)
	s1 := Record(1, []float64{4, 5, 6}, nil, false)
	col.Append(s0)
	col.Append(s1)

	if len(col.History) != 2 {
		t.Fatalf("History len=%d, want 2", len(col.History))
	}
	if col.History[0].Generation != 0 {
		t.Errorf("History[0].Generation=%d, want 0", col.History[0].Generation)
	}
	if col.History[1].Generation != 1 {
		t.Errorf("History[1].Generation=%d, want 1", col.History[1].Generation)
	}
}

func TestCollector_Last_EmptyHistory(t *testing.T) {
	col := &Collector{}
	last := col.Last()
	if last != (Stats{}) {
		t.Errorf("Last() on empty Collector=%+v, want zero Stats", last)
	}
}

func TestCollector_Last_ReturnsNewest(t *testing.T) {
	col := &Collector{}
	col.Append(Record(0, []float64{1.0}, nil, false))
	col.Append(Record(1, []float64{2.0}, nil, false))
	col.Append(Record(2, []float64{9.0}, nil, false))

	last := col.Last()
	if last.Generation != 2 {
		t.Errorf("Last().Generation=%d, want 2", last.Generation)
	}
	if last.BestScore != 9.0 {
		t.Errorf("Last().BestScore=%v, want 9.0", last.BestScore)
	}
}

func TestCollector_OrderPreserved(t *testing.T) {
	col := &Collector{}
	for i := 0; i < 10; i++ {
		col.Append(Record(i, []float64{float64(i)}, nil, false))
	}
	for i, s := range col.History {
		if s.Generation != i {
			t.Errorf("History[%d].Generation=%d, want %d", i, s.Generation, i)
		}
	}
}

func TestExtractSafeOutputLabels_IncludesLabelCommand(t *testing.T) {
	data := &workflow.WorkflowData{
		SafeOutputs: &workflow.SafeOutputsConfig{
			CreateIssues: &workflow.CreateIssuesConfig{
				Labels:        []string{"bug"},
				AllowedLabels: []string{"triage"},
			},
			AddLabels: &workflow.AddLabelsConfig{
				Allowed: []string{"automation"},
			},
		},
		LabelCommand: []string{"deploy"},
	}

	got := extractSafeOutputLabels(data)
	want := []string{"bug", "triage", "automation", "deploy"}

	if len(got) != len(want) {
		t.Fatalf("expected %d labels, got %d: %v", len(want), len(got), got)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("expected labels %v, got %v", want, got)
		}
	}
}

func TestExtractSafeOutputLabels_DeduplicatesAcrossSources(t *testing.T) {
	data := &workflow.WorkflowData{
		SafeOutputs: &workflow.SafeOutputsConfig{
			CreatePullRequests: &workflow.CreatePullRequestsConfig{
				Labels: []string{"deploy"},
			},
		},
		LabelCommand: []string{"deploy"},
	}

	got := extractSafeOutputLabels(data)
	if len(got) != 1 || got[0] != "deploy" {
		t.Fatalf("expected deduplicated labels [deploy], got %v", got)
	}
}

() => {
  const state = {
    manifest: null,
    summary: null,
    charts: null,
    pages: [],
    developers: new Map(),
    index: [],
    filtered: [],
    rendered: 0,
    pageSize: 30,
  };

  const el = (id) => document.getElementById(id);

  const escapeHtml = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' }[c]));

  const qs = new URLSearchParams(location.search);
  ["q","location","language","skill","sort","minStars","minForks"].forEach((k) => {
    if (qs.has(k) && el(k)) el(k).value = qs.get(k);
  });

  const saveQuery = () => {
    const params = new URLSearchParams();
    ["q","location","language","skill","sort","minStars","minForks"].forEach((k) => {
      const v = el(k)?.value?.trim();
      if (v) params.set(k, v);
    });
    history.replaceState(null, "", `${location.pathname}?${params.toString()}`);
  };

  const fetchJson = (p, options = {}) =>
    fetch(p, { cache: options.cache || "default" }).then((r) => {
      if (!r.ok) throw new Error(`Failed to load ${p} (HTTP ${r.status})`);
      return r.json();
    });
  const versioned = (p) => {
    const v = state.manifest?.version;
    return v ? `${p}?v=${encodeURIComponent(v)}` : p;
  };

  const loadManifest = async () => {
    state.manifest = await fetchJson('/data/web/manifest.json', { cache: "no-cache" });
    state.summary = await fetchJson(versioned(`/data/web/${state.manifest.stats_summary}`));
    state.charts = await fetchJson(versioned(`/data/web/${state.manifest.charts}`));
    state.index = (await fetchJson(versioned(`/data/web/${state.manifest.search_index}`))).items || [];
    el('meta').textContent = `Last updated: ${state.summary.generated_at || 'N/A'} · Developers: ${state.summary.total_developers || 0}`;
    renderCharts();
    await ensurePage(1);
    applyFilters();
  };

  const ensurePage = async (num) => {
    if (state.pages[num]) return;
    const file = state.manifest.directory_index[num - 1];
    if (!file) return;
    const payload = await fetchJson(versioned(`/data/web/${file}`));
    state.pages[num] = payload.developers || [];
    for (const d of state.pages[num]) state.developers.set(d.login, d);
  };

  const sortedIds = async () => {
    const sortBy = el('sort').value || 'activity';
    const data = await fetchJson(versioned(`/data/web/${state.manifest.sorted_indexes}`));
    return data[sortBy] || [];
  };

  const matches = (idx) => {
    const q = el('q').value.trim().toLowerCase();
    const location = el('location').value.trim().toLowerCase();
    const language = el('language').value.trim().toLowerCase();
    const skill = el('skill').value.trim().toLowerCase();
    const minStars = Number(el('minStars').value || 0);
    const minForks = Number(el('minForks').value || 0);

    if (q && !(idx.tokens || []).some((t) => t.includes(q))) return false;
    if (location && !String(idx.location || '').toLowerCase().includes(location)) return false;
    if (language && !(idx.languages || []).some((l) => l.toLowerCase().includes(language))) return false;
    if (skill) {
      const pool = [...(idx.skills || []), ...(idx.expertise_tags || [])].map((x) => String(x).toLowerCase());
      if (!pool.some((x) => x.includes(skill))) return false;
    }
    if ((idx.stars || 0) < minStars) return false;
    if ((idx.forks || 0) < minForks) return false;
    return true;
  };

  const hydrateFor = async (logins) => {
    const need = logins.filter((l) => !state.developers.has(l));
    let n = 1;
    while (need.length && state.manifest.directory_index[n - 1]) {
      await ensurePage(n++);
      for (let i = need.length - 1; i >= 0; i--) if (state.developers.has(need[i])) need.splice(i, 1);
    }
  };

  const applyFilters = async () => {
    saveQuery();
    const order = await sortedIds();
    const byId = new Map(state.index.map((i) => [i.id, i]));
    state.filtered = order.filter((id) => byId.has(id)).map((id) => byId.get(id)).filter(matches).map((i) => i.id);
    state.rendered = 0;
    el('results').innerHTML = '';
    el('count').textContent = `${state.filtered.length} matching developers`;
    await renderMore();
  };

  const card = (d) => {
    const skills = (d.skills || []).slice(0, 6).join(', ') || 'N/A';
    const langs = (d.primary_languages || d.languages || []).slice(0, 5).join(', ') || 'N/A';
    const repos = (d.top_repositories || []).slice(0, 3)
      .map((r) => `<li><a href="${escapeHtml(r.url || '#')}" rel="noopener">${escapeHtml(r.name || 'repo')}</a> ⭐${r.stargazers_count || 0}</li>`)
      .join('');
    return `<article class="card"><h3><a href="/developers/${encodeURIComponent(d.login)}/">${escapeHtml(d.login)}</a></h3>
      <p class="muted">${escapeHtml(d.name || '')} · ${escapeHtml(d.location || 'Unknown')}</p>
      <p>Followers: ${d.followers || 0} · Stars: ${d.recent_repo_stars_sum || 0} · Forks: ${d.repo_forks_sum || 0}</p>
      <p>Languages: ${escapeHtml(langs)}</p>
      <p>Skills: ${escapeHtml(skills)}</p>
      <ul>${repos || '<li>No repo summary</li>'}</ul></article>`;
  };

  const renderMore = async () => {
    const next = state.filtered.slice(state.rendered, state.rendered + state.pageSize);
    await hydrateFor(next);
    const html = next.map((id) => state.developers.get(id)).filter(Boolean).map(card).join('');
    el('results').insertAdjacentHTML('beforeend', html);
    state.rendered += next.length;
    el('loadMore').style.display = state.rendered < state.filtered.length ? 'block' : 'none';
  };

  const renderList = (target, items, fmt) => {
    const root = el(target);
    root.innerHTML = (items || []).map(fmt).join('') || '<li>No data available.</li>';
  };

  const renderCharts = () => {
    renderList('timeline', state.charts.timeline, (x) => `<li>${escapeHtml(x.date)}: ${x.total_contributions} contributions, ${x.developers} developers</li>`);
    renderList('topLanguages', state.summary.language_leaderboard, (x) => `<li>${escapeHtml(x.language)} (${x.developers} developers)</li>`);
    renderList('topLocations', state.summary.location_leaderboard, (x) => `<li>${escapeHtml(x.location)} (${x.developers} developers)</li>`);
    renderList('risingRepos', state.charts.rising_repositories, (x) => `<li><a href="${escapeHtml(x.url || '#')}" rel="noopener">${escapeHtml(x.repository)}</a> +${x.stars_growth} stars</li>`);
  };

  el('filters').addEventListener('input', () => applyFilters());
  el('loadMore').addEventListener('click', () => renderMore());

  loadManifest().catch((e) => {
    console.error(e);
    el('meta').textContent = 'Failed to load live data bundle.';
  });
}

