      <p class="muted">${escapeHtml(d.name || '')} · ${escapeHtml(d.location || 'Unknown')}</p>
      <p>Followers: ${d.followers || 0} · Stars: ${d.recent_repo_stars_sum || 0} · Forks: ${d.repo_forks_sum || 0}</p>
      <p>Languages: ${escapeHtml(langs)}</p>
      <p>Skills: ${escapeHtml(skills)}</p>
      <ul>${repos || '<li>No repo summary</li>'}</ul></article>`;
  }

async () => {
    const next = state.filtered.slice(state.rendered, state.rendered + state.pageSize);
    await hydrateFor(next);
    const html = next.map((id) => state.developers.get(id)).filter(Boolean).map(card).join('');
    el('results').insertAdjacentHTML('beforeend', html);
    state.rendered += next.length;
    el('loadMore').style.display = state.rendered < state.filtered.length ? 'block' : 'none';
  }

(target, items, fmt) => {
    const root = el(target);
    root.innerHTML = (items || []).map(fmt).join('') || '<li>No data available.</li>';
  }

() => {
    renderList('timeline', state.charts.timeline, (x) => `<li>${escapeHtml(x.date)}: ${x.total_contributions} contributions, ${x.developers} developers</li>`);
    renderList('topLanguages', state.summary.language_leaderboard, (x) => `<li>${escapeHtml(x.language)} (${x.developers} developers)</li>`);
    renderList('topLocations', state.summary.location_leaderboard, (x) => `<li>${escapeHtml(x.location)} (${x.developers} developers)</li>`);
    renderList('risingRepos', state.charts.rising_repositories, (x) => `<li><a href="${escapeHtml(x.url || '#')}" rel="noopener">${escapeHtml(x.repository)}</a> +${x.stars_growth} stars</li>`);
  }

(e) => {
    console.error(e);
    el('meta').textContent = 'Failed to load live data bundle.';
  }

def _load_json(path, default):
    if not os.path.exists(path):
        return default
    try:
        with open(path, "r", encoding="utf-8") as f:
            return json.load(f)
    except (json.JSONDecodeError, OSError, TypeError):
        return default

def _parse_iso(dt_str):
    if not dt_str:
        return None
    normalized = dt_str.replace("Z", "+00:00")
    try:
        dt = datetime.fromisoformat(normalized)
        if dt.tzinfo is None:
            return dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(timezone.utc)
    except ValueError:
        return None

def _update_rate_stats(headers):
    remaining = headers.get("X-RateLimit-Remaining")
    used = headers.get("X-RateLimit-Used")
    try:
        if remaining is not None:
            rem_int = int(remaining)
            prev = API_STATS["remaining_min"]
            API_STATS["remaining_min"] = rem_int if prev is None else min(prev, rem_int)
    except (TypeError, ValueError):
        pass
    try:
        if used is not None:
            API_STATS["used"] = max(API_STATS["used"], int(used))
    except (TypeError, ValueError):
        pass

def load_site_url():
    cfg_path = os.path.join(ROOT, "_config.yml")
    if not os.path.exists(cfg_path):
        return ""
    try:
        with open(cfg_path, "r", encoding="utf-8") as f:
            for line in f:
                if line.strip().startswith("url:"):
                    return line.split(":", 1)[1].strip().strip('"').strip("'")
    except OSError:
        return ""
    return ""

def get_user(login, cache=None):
    return gh_get(
        f"https://api.github.com/users/{login}",
        cache=cache,
        cache_key=f"user:{_normalize_login(login)}",
    )

def _tokenize(*parts):
    text = " ".join(_clean_text(p).lower() for p in parts if p)
    # Keep token chars commonly found in developer terms (c++, c#, node.js, ci-cd) and
    # drop 1-char tokens to reduce noisy matches in the client-side search index.
    return sorted({t for t in re.split(r"[^a-z0-9+#.\-]+", text) if len(t) > 1})

def _choose_last_active(user, repo_summary):
    times = [_parse_iso(user.get("updated_at")), _parse_iso(repo_summary.get("last_repo_activity_at"))]
    valid = [t for t in times if t is not None]
    if not valid:
        return None
    return max(valid).isoformat().replace("+00:00", "Z")

def _load_previous_automated():
    prev = _load_json(AUTOMATED_PATH, {})
    if not isinstance(prev, dict):
        return {}
    return prev

def _should_refresh_developer(login, previous_map, now, cfg, full_refresh=False):
    if full_refresh:
        return True
    prev = previous_map.get(_normalize_login(login))
    if not prev:
        return True
    ttl_hours = int(cfg.get("incremental_ttl_hours", 24))
    stamp = _parse_iso(prev.get("last_collected_at") or prev.get("fetched_at") or prev.get("last_active_at"))
    if stamp is None:
        return True
    return now - stamp > timedelta(hours=ttl_hours)

def _merge_candidates(search_logins, manual_logins, max_candidates):
    seen = set()
    merged = []
    for login in list(manual_logins) + list(search_logins):
        if not login:
            continue
        norm = _normalize_login(login)
        if norm in seen:
            continue
        seen.add(norm)
        merged.append(login)
        if len(merged) >= max_candidates:
            break
    return merged

def _compute_growth(current_devs, previous_devs):
    prev_map = {_normalize_login(d.get("login")): d for d in previous_devs}
    for dev in current_devs:
        prev = prev_map.get(_normalize_login(dev.get("login")), {})
        dev["followers_growth"] = int(dev.get("followers", 0) or 0) - int(prev.get("followers", dev.get("followers", 0)) or 0)
        dev["stars_growth"] = int(dev.get("recent_repo_stars_sum", 0) or 0) - int(prev.get("recent_repo_stars_sum", dev.get("recent_repo_stars_sum", 0)) or 0)

def _load_activity_timeline(limit=30):
    timeline = []
    files = sorted(glob.glob(os.path.join(DATA_DIR, "????-??-??.json")), reverse=True)[:limit]
    for path in reversed(files):
        payload = _load_json(path, {})
        if not isinstance(payload, dict):
            continue
        devs = payload.get("developers", []) or []
        if not devs:
            continue
        total_contribs = sum(int(d.get("recent_total_contributions", 0) or 0) for d in devs)
        avg_score = sum(float(d.get("composite_score", 0) or 0) for d in devs) / len(devs)
        timeline.append(
            {
                "date": payload.get("run_date") or os.path.basename(path).replace(".json", ""),
                "developers": len(devs),
                "total_contributions": total_contribs,
                "average_score": round(avg_score, 6),
            }
        )
    return timeline

def _build_aggregates(scored, previous_devs, timeline):
    language_stats = {}
    location_stats = {}
    prev_repo_stars = {}

    for dev in previous_devs:
        for repo in dev.get("top_repositories", []) or []:
            full_name = repo.get("full_name") or repo.get("name")
            if full_name:
                prev_repo_stars[full_name.lower()] = int(repo.get("stargazers_count", 0) or 0)

    rising_repos = []
    for dev in scored:
        location = _clean_text(dev.get("location") or "Unknown")
        location_stats[location] = location_stats.get(location, 0) + 1

        for lang in dev.get("primary_languages", []) or []:
            block = language_stats.setdefault(lang, {"developers": 0, "stars": 0})
            block["developers"] += 1
            block["stars"] += int(dev.get("recent_repo_stars_sum", 0) or 0)

        for repo in dev.get("top_repositories", []) or []:
            full_name = repo.get("full_name") or repo.get("name")
            if not full_name:
                continue
            old = prev_repo_stars.get(full_name.lower(), 0)
            current = int(repo.get("stargazers_count", 0) or 0)
            growth = current - old
            if growth > 0:
                rising_repos.append(
                    {
                        "repository": full_name,
                        "url": repo.get("url"),
                        "owner": dev.get("login"),
                        "stars_growth": growth,
                        "stars": current,
                    }
                )

    language_leaderboard = [
        {"language": lang, **stats}
        for lang, stats in sorted(
            language_stats.items(), key=lambda i: (i[1]["developers"], i[1]["stars"], i[0].lower()), reverse=True
        )
    ]
    location_leaderboard = [
        {"location": loc, "developers": count}
        for loc, count in sorted(location_stats.items(), key=lambda i: (i[1], i[0].lower()), reverse=True)
    ]
    rising_repos.sort(key=lambda r: (r["stars_growth"], r["stars"]), reverse=True)

    return {
        "language_leaderboard": language_leaderboard[:30],
        "location_leaderboard": location_leaderboard[:30],
        "rising_repositories": rising_repos[:50],
        "activity_timeline": timeline,
    }

def validate_duplicate_usernames(data_dir):
    users_path = data_dir / "users.json"
    automated_path = data_dir / "automated.json"

    users = []
    automated = []

    if users_path.exists():
        try:
            with open(users_path, "r", encoding="utf-8") as f:
                payload = json.load(f)
                users = payload if isinstance(payload, list) else []
        except Exception:
            users = []

    if automated_path.exists():
        try:
            with open(automated_path, "r", encoding="utf-8") as f:
                payload = json.load(f)
                automated = payload.get("developers", []) if isinstance(payload, dict) else []
        except Exception:
            automated = []

    all_ids = {}
    ok = True

    for entry in users:
        username = _norm_username(entry.get("github_username") or entry.get("login"))
        if not username:
            continue
        all_ids.setdefault(username, []).append("users.json")

    for entry in automated:
        username = _norm_username(entry.get("login") or entry.get("github_username"))
        if not username:
            continue
        all_ids.setdefault(username, []).append("automated.json")

    for username, sources in all_ids.items():
        if sources.count("users.json") > 1:
            print(f"Duplicate username in users.json: {username}")
            ok = False
        if sources.count("automated.json") > 1:
            print(f"Duplicate username in automated.json: {username}")
            ok = False

    return ok

def test_validate_duplicate_usernames(tmp_path):
    data_dir = tmp_path
    users = [
        {"github_username": "Foo.Bar"},
        {"github_username": "foo-bar"},
    ]
    automated = {
        "developers": [
            {"login": "x"},
            {"login": "X"},
        ]
    }
    (data_dir / "users.json").write_text(json.dumps(users), encoding="utf-8")
    (data_dir / "automated.json").write_text(json.dumps(automated), encoding="utf-8")

    assert validate_data.validate_duplicate_usernames(data_dir) is False

